window.WORD_AI_EXAMPLE_LIBRARY = {"source":"DeepSeek one-time offline generation with a separate review pass","model":"deepseek-v4-pro","generatedAt":"2026-08-08T14:00:01.415906+00:00","entries":{"curriculum":{"examples":[{"sentence":"Although the curriculum was designed to meet national standards, it failed to address the specific needs of local communities.","translation":"尽管该课程旨在符合国家标准，但未能满足当地社区的具体需求。"},{"sentence":"The school introduced a new curriculum that emphasizes project-based learning, which has significantly improved student engagement.","translation":"学校引入了一门强调项目式学习的新课程，这显著提高了学生的参与度。"},{"sentence":"Because the curriculum includes mandatory internships, students gain practical experience before entering the job market.","translation":"由于课程包含强制性实习，学生在进入就业市场前获得了实践经验。"},{"sentence":"Educators must regularly update the curriculum to incorporate emerging technologies, thereby ensuring that graduates remain competitive.","translation":"教育工作者必须定期更新课程以纳入新兴技术，从而确保毕业生保持竞争力。"},{"sentence":"While the curriculum offers a wide range of electives, it still lacks sufficient courses on environmental sustainability.","translation":"虽然该课程提供了广泛的选修课，但在环境可持续性方面仍然缺乏足够的课程。"}]},"poison":{"examples":[{"sentence":"The illegal dumping of toxic chemicals into the river has turned the water into a deadly poison that threatens local wildlife.","translation":"非法向河流倾倒有毒化学品已将河水变成威胁当地野生动物的致命毒药。"},{"sentence":"Although the plant has medicinal properties, its leaves contain a potent poison that can cause paralysis if ingested.","translation":"尽管这种植物具有药用特性，但其叶子含有一种强效毒药，如果摄入会导致瘫痪。"},{"sentence":"The spread of fake news acts as a social poison, which undermines democratic processes and polarizes communities.","translation":"假新闻的传播起着社会毒药的作用，它破坏民主进程并使社区两极分化。"},{"sentence":"Because the poison was slow-acting, the victim did not realize they had been exposed until symptoms appeared days later.","translation":"由于毒药是慢性的，受害者直到几天后出现症状才意识到自己已经接触了毒药。"},{"sentence":"Strict safety protocols in laboratories prevent accidental exposure to poison, thereby protecting researchers from harm.","translation":"实验室的严格安全规程防止意外接触毒药，从而保护研究人员免受伤害。"}]},"farewell":{"examples":[{"sentence":"The professor's farewell lecture, which covered his lifelong research, was attended by scholars from around the world.","translation":"教授的告别讲座涵盖了他毕生的研究，吸引了来自世界各地的学者参加。"},{"sentence":"Although the farewell party was bittersweet, it provided an opportunity to reflect on shared achievements.","translation":"尽管告别派对苦乐参半，但它提供了一个反思共同成就的机会。"},{"sentence":"She composed a farewell message that expressed gratitude for the mentorship she had received over the years.","translation":"她撰写了一封告别信，表达了对多年来所获指导的感激之情。"},{"sentence":"Because the CEO's farewell speech emphasized innovation, it inspired employees to pursue bold ideas.","translation":"由于首席执行官的告别演讲强调了创新，它激励员工追求大胆的想法。"},{"sentence":"The retiring ambassador's farewell dinner was a formal event that celebrated decades of diplomatic service.","translation":"即将退休的大使的告别晚宴是一场正式活动，庆祝了数十年的外交服务。"}]},"vegetable":{"examples":[{"sentence":"Although vegetable consumption is essential for health, many people fail to meet the recommended daily intake.","translation":"尽管蔬菜摄入对健康至关重要，但许多人未能达到推荐的每日摄入量。"},{"sentence":"The community vegetable garden, which was established last year, has improved access to fresh produce in the neighborhood.","translation":"去年建立的社区菜园改善了附近居民获得新鲜农产品的机会。"},{"sentence":"Because vegetable prices are volatile, governments often implement policies to stabilize the market.","translation":"由于蔬菜价格波动，政府经常实施政策以稳定市场。"},{"sentence":"Research shows that a diet rich in vegetable fiber can reduce the risk of heart disease, thereby promoting longevity.","translation":"研究表明，富含蔬菜纤维的饮食可以降低心脏病风险，从而促进长寿。"},{"sentence":"While vegetable farming is labor-intensive, technological advances such as automated harvesting are increasing efficiency.","translation":"尽管蔬菜种植是劳动密集型的，但自动化收割等技术进步正在提高效率。"}]},"rose":{"examples":[{"sentence":"Although the rose is often associated with romance, it also carries deep cultural significance in religious ceremonies.","translation":"尽管玫瑰常与浪漫联系在一起，但它在宗教仪式中也具有深厚的文化意义。"},{"sentence":"The rose, which requires careful pruning and ample sunlight, thrives best in temperate climates with well-drained soil.","translation":"玫瑰需要精心修剪和充足的阳光，在温带气候和排水良好的土壤中生长得最好。"},{"sentence":"Because the rose has a complex genetic makeup, breeders can create varieties with unique colors and fragrances.","translation":"由于玫瑰具有复杂的基因构成，育种者可以培育出具有独特色彩和香气的品种。"},{"sentence":"When the rose garden is in full bloom, it attracts not only tourists but also local photographers seeking the perfect shot.","translation":"当玫瑰园盛开时，它不仅吸引游客，还吸引当地摄影师寻找完美的镜头。"},{"sentence":"The rose industry, which spans from cultivation to perfume production, contributes significantly to the economy of several countries.","translation":"玫瑰产业从种植到香水生产，对多个国家的经济做出了重大贡献。"}]},"protest":{"examples":[{"sentence":"Although the protest was initially ignored by the media, it eventually gained widespread attention through social media platforms.","translation":"尽管抗议最初被媒体忽视，但最终通过社交媒体平台获得了广泛关注。"},{"sentence":"The protest, which was organized by environmental activists, aimed to raise awareness about the dangers of deforestation.","translation":"这场由环保活动人士组织的抗议，旨在提高人们对森林砍伐危险的认识。"},{"sentence":"Because the protest remained nonviolent, it garnered sympathy from the public and put pressure on the authorities to negotiate.","translation":"由于抗议保持非暴力，它赢得了公众的同情，并向当局施加了谈判的压力。"},{"sentence":"When a protest is suppressed without dialogue, it often leads to deeper social divisions and long-term unrest.","translation":"当抗议在没有对话的情况下被镇压时，往往会导致更深的社会分裂和长期动荡。"},{"sentence":"The right to peaceful protest is a cornerstone of democracy, which allows citizens to express dissent without fear of retaliation.","translation":"和平抗议的权利是民主的基石，它允许公民表达异议而不必担心报复。"}]},"emergency":{"examples":[{"sentence":"Because the emergency alarm malfunctioned, the building evacuation was delayed, which increased the risk to occupants.","translation":"由于紧急警报失灵，大楼疏散被延误，这增加了住户的风险。"},{"sentence":"The government declared a state of emergency after the earthquake, thereby mobilizing additional rescue resources.","translation":"地震后政府宣布进入紧急状态，从而调动了额外的救援资源。"},{"sentence":"Although the emergency room was understaffed, the medical team managed to treat all critical patients efficiently.","translation":"尽管急诊室人手不足，医疗团队还是高效地救治了所有危重病人。"},{"sentence":"When a chemical spill occurs, the emergency response team must follow strict protocols to contain the hazard.","translation":"当化学品泄漏发生时，应急响应小组必须遵循严格的规程来控制危害。"},{"sentence":"The airline crew is trained to handle any in-flight emergency, which ensures passenger safety at all times.","translation":"机组人员接受过处理任何飞行中紧急情况的训练，这确保了乘客在任何时候的安全。"}]},"old":{"examples":[{"sentence":"Although the old are often stereotyped as frail, many maintain active lifestyles well into their eighties.","translation":"尽管老年人常被刻板地认为是虚弱的，但许多人直到八十多岁仍保持积极的生活方式。"},{"sentence":"Because the old have witnessed significant historical changes, their oral histories provide invaluable insights for younger generations.","translation":"由于老年人见证了重大的历史变迁，他们的口述历史为年轻一代提供了宝贵的见解。"},{"sentence":"The old, who may face social isolation, benefit greatly from community programs that encourage intergenerational interaction.","translation":"可能面临社会孤立的老年人，从鼓励代际互动的社区项目中受益匪浅。"},{"sentence":"When societies invest in healthcare for the old, they not only improve quality of life but also reduce long-term medical costs.","translation":"当社会投资于老年人的医疗保健时，他们不仅提高了生活质量，还降低了长期的医疗成本。"},{"sentence":"While the old are often respected for their wisdom, their potential to contribute to the workforce is frequently underestimated.","translation":"虽然老年人常因其智慧而受到尊重，但他们为劳动力做出贡献的潜力却经常被低估。"}]},"defect":{"examples":[{"sentence":"Although the product had a minor defect, the company issued a full refund to ensure customer satisfaction.","translation":"尽管该产品有一个小缺陷，但公司为了确保客户满意度发放了全额退款。"},{"sentence":"A design defect in the engine, which was overlooked during testing, led to a costly recall.","translation":"发动机的一个设计缺陷在测试中被忽视，导致了一次代价高昂的召回。"},{"sentence":"Because the defect was detected early, the team was able to fix it without delaying the project.","translation":"由于缺陷被及早发现，团队得以在不延误项目的情况下修复它。"},{"sentence":"The researcher emphasized that every theory has a defect that must be addressed through further study.","translation":"该研究人员强调，每一种理论都有一个必须通过进一步研究来解决的缺陷。"},{"sentence":"While the software's defect was not critical, it still affected user experience and required an update.","translation":"虽然该软件的缺陷并不严重，但它仍然影响了用户体验并需要更新。"}]},"newspaper":{"examples":[{"sentence":"Because the newspaper provides reliable information, it remains a trusted source for many readers.","translation":"由于该报纸提供可靠的信息，它仍然是许多读者信赖的来源。"},{"sentence":"A well-written newspaper editorial, which presents balanced arguments, can influence public policy.","translation":"一篇写得好的报纸社论，呈现了平衡的论点，可以影响公共政策。"},{"sentence":"Although online news is instant, a printed newspaper offers a depth of analysis that digital formats often lack.","translation":"尽管在线新闻是即时的，但印刷报纸提供了数字格式通常缺乏的深度分析。"},{"sentence":"The newspaper article exposed corruption, thereby prompting a government investigation.","translation":"该报纸文章揭露了腐败，从而促使政府展开调查。"},{"sentence":"When the newspaper published the story, it sparked a nationwide debate on education reform.","translation":"当该报纸发表这篇报道时，它引发了一场关于教育改革的全国性辩论。"}]},"ninety":{"examples":[{"sentence":"Because ninety percent of the students passed the exam, the school considered the new teaching method a success.","translation":"由于百分之九十的学生通过了考试，学校认为新的教学方法是成功的。"},{"sentence":"The survey revealed that ninety out of one hundred respondents preferred the updated design, which was more user-friendly.","translation":"调查显示，一百名受访者中有九十人更喜欢更新后的设计，因为它更便于使用。"},{"sentence":"Although the marathon was ninety kilometers long, the experienced runner completed it without excessive fatigue.","translation":"尽管马拉松长达九十公里，但这位经验丰富的跑步者没有过度疲劳就完成了。"},{"sentence":"The company invested ninety million dollars in research, thereby developing a groundbreaking technology.","translation":"该公司投资了九千万美元用于研究，从而开发出一项突破性技术。"},{"sentence":"When the temperature reached ninety degrees, the cooling system activated automatically to ensure a comfortable environment.","translation":"当温度达到九十度时，冷却系统自动启动，以确保舒适的环境。"}]},"muscular":{"examples":[{"sentence":"Although a muscular physique is often admired, it requires consistent training and proper nutrition to maintain.","translation":"尽管肌肉发达的体格常受人羡慕，但需要持续的训练和适当的营养来维持。"},{"sentence":"The heart is a muscular organ that pumps blood throughout the body, thereby sustaining life.","translation":"心脏是一个肌肉发达的器官，它将血液泵送到全身，从而维持生命。"},{"sentence":"Because muscular strength declines with age, older adults should engage in resistance exercises to preserve mobility.","translation":"由于肌肉力量随年龄增长而下降，老年人应进行抗阻运动以保持活动能力。"},{"sentence":"A balanced diet provides the protein necessary for repairing muscular tissue, which is damaged during intense workouts.","translation":"均衡的饮食提供修复肌肉组织所需的蛋白质，这些组织在高强度锻炼中受损。"},{"sentence":"When designing a fitness program, it is important to include exercises that target all major muscular groups to ensure balanced development.","translation":"在设计健身计划时，重要的是要包括针对所有主要肌肉群的练习，以确保均衡发展。"}]},"reasonable":{"examples":[{"sentence":"A reasonable approach to urban planning balances economic growth with environmental protection, thereby ensuring sustainable development.","translation":"合理的城市规划方法在经济增长与环境保护之间取得平衡，从而确保可持续发展。"},{"sentence":"Although the proposal seemed ambitious, the committee found it reasonable after reviewing the detailed budget.","translation":"尽管该提案看似雄心勃勃，委员会在审查详细预算后认为它是合理的。"},{"sentence":"Setting reasonable deadlines allows teams to maintain high-quality output without experiencing burnout.","translation":"设定合理的截止日期能让团队保持高质量产出，而不会感到精疲力竭。"},{"sentence":"Consumers are more likely to remain loyal to brands that offer reasonable prices and transparent policies.","translation":"消费者更可能忠于那些提供合理价格和透明政策的品牌。"},{"sentence":"In academic debates, participants should present reasonable arguments supported by evidence rather than resorting to emotional appeals.","translation":"在学术辩论中，参与者应提出有证据支持的合理论点，而不是诉诸情感诉求。"}]},"decent":{"examples":[{"sentence":"Although the starting salary was modest, the company offered a decent benefits package that included health insurance and paid leave.","translation":"虽然起薪不高，但公司提供了包括医疗保险和带薪休假在内的优厚福利待遇。"},{"sentence":"Because the restaurant maintained a decent standard of hygiene, it quickly gained a loyal customer base despite its simple decor.","translation":"由于餐厅保持了良好的卫生标准，尽管装修简朴，它还是迅速赢得了忠实的顾客群。"},{"sentence":"When attending a formal dinner, it is essential to wear decent attire, which shows respect for the host and other guests.","translation":"参加正式晚宴时，穿着得体的服装至关重要，这体现了对主人和其他宾客的尊重。"},{"sentence":"The government should ensure that all citizens have access to decent housing, as this is a fundamental human right that underpins social stability.","translation":"政府应确保所有公民都能获得体面的住房，因为这是一项基本人权，是社会稳定的基础。"},{"sentence":"While the film received mixed reviews, the lead actor delivered a decent performance that earned him a nomination for best actor.","translation":"尽管这部电影评价褒贬不一，但男主角的表演相当不错，为他赢得了最佳男主角提名。"}]},"science":{"examples":[{"sentence":"Advances in medical science have significantly increased life expectancy, which in turn poses challenges for pension systems worldwide.","translation":"医学的进步显著提高了预期寿命，这反过来又给全球的养老金体系带来了挑战。"},{"sentence":"Although science provides powerful tools for understanding nature, it cannot answer every philosophical question about human existence.","translation":"尽管科学为理解自然提供了强大的工具，但它无法回答关于人类存在的所有哲学问题。"},{"sentence":"Because computer science graduates are in high demand, many universities have expanded their programs to meet the needs of the tech industry.","translation":"由于计算机科学专业的毕业生需求量很大，许多大学扩大了课程规模以满足科技行业的需求。"},{"sentence":"Environmental science plays a crucial role in developing sustainable solutions, thereby helping to mitigate the effects of climate change.","translation":"环境科学在制定可持续解决方案中发挥着关键作用，从而有助于减轻气候变化的影响。"},{"sentence":"Public trust in science depends on transparent communication, which ensures that research findings are accurately conveyed to the public.","translation":"公众对科学的信任取决于透明的沟通，这确保了研究成果能准确地传达给公众。"}]},"compassion":{"examples":[{"sentence":"Although the judge was known for her strict rulings, she often showed compassion toward first-time offenders.","translation":"尽管这位法官以严厉的判决著称，但她经常对初犯者表现出同情。"},{"sentence":"Because he had experienced poverty himself, his compassion for the underprivileged was deep and genuine.","translation":"因为他自己经历过贫困，他对弱势群体的同情是深切而真诚的。"},{"sentence":"The organization's mission is to provide aid with compassion, ensuring that every recipient is treated with dignity.","translation":"该组织的使命是带着同情心提供援助，确保每位受助者都得到有尊严的对待。"},{"sentence":"While some argue that compassion has no place in business, many successful leaders prove that empathy can drive innovation.","translation":"虽然有人认为同情心在商业中没有立足之地，但许多成功的领导者证明，同理心可以推动创新。"},{"sentence":"Her compassion for animals led her to establish a shelter that rescues and rehabilitates injured wildlife.","translation":"她对动物的同情心促使她建立了一个收容所，用于救助和康复受伤的野生动物。"}]},"effect":{"examples":[{"sentence":"Although the medication was intended to relieve pain, its side effect caused severe drowsiness in many patients.","translation":"尽管这种药物旨在缓解疼痛，但其副作用导致许多患者严重嗜睡。"},{"sentence":"Because the new regulation took effect immediately, companies had to adapt their practices without delay.","translation":"因为新规定立即生效，公司不得不立即调整其做法。"},{"sentence":"The butterfly effect suggests that small changes in initial conditions can have a profound effect on complex systems.","translation":"蝴蝶效应表明，初始条件的微小变化会对复杂系统产生深远影响。"},{"sentence":"To ensure the policy had the desired effect, the government conducted a thorough review after its first year of implementation.","translation":"为了确保政策达到预期效果，政府在实施第一年后进行了彻底审查。"},{"sentence":"While the economic sanctions were meant to pressure the regime, their effect on ordinary citizens was devastating.","translation":"虽然经济制裁旨在向该政权施压，但它们对普通公民的影响却是毁灭性的。"}]},"stall":{"examples":[{"sentence":"Although the market stall sold fresh produce, it struggled to compete with larger supermarkets that offered lower prices.","translation":"尽管市场摊位出售新鲜农产品，但它难以与提供更低价格的大型超市竞争。"},{"sentence":"When the engine began to stall on the highway, the driver carefully steered the vehicle to the emergency lane.","translation":"当发动机在高速公路上开始熄火时，司机小心地将车转向应急车道。"},{"sentence":"Economic reforms are essential to prevent a stall in growth, which could lead to higher unemployment and social unrest.","translation":"经济改革对于防止增长停滞至关重要，这可能导致更高的失业率和社会动荡。"},{"sentence":"The negotiators used a deliberate stall tactic, thereby buying time to consult with their respective governments.","translation":"谈判者故意使用拖延战术，从而争取时间与各自政府协商。"},{"sentence":"Because the horse refused to enter the stall, the groom had to coax it with a bucket of oats.","translation":"因为马拒绝进入马厩，马夫不得不用一桶燕麦哄它。"}]},"steak":{"examples":[{"sentence":"Although the steak was cooked to perfection, the accompanying sauce lacked the depth of flavor we had anticipated.","translation":"尽管牛排烹制得恰到好处，但搭配的酱汁却缺乏我们预期的风味层次。"},{"sentence":"Because the chef selected a prime cut of steak, the dish required only minimal seasoning to highlight its natural richness.","translation":"由于厨师选用了上等牛排，这道菜只需极少的调味就能突出其天然的浓郁风味。"},{"sentence":"The restaurant's signature steak, which is dry-aged for thirty days, attracts diners from across the city.","translation":"这家餐厅的招牌牛排经过三十天干式熟成，吸引了全市各地的食客。"},{"sentence":"When preparing steak at home, many cooks overlook the importance of letting the meat rest before slicing.","translation":"在家烹制牛排时，许多厨师忽视了切肉前让肉静置的重要性。"},{"sentence":"A perfectly grilled steak can serve as the centerpiece of a celebratory meal, provided that it is paired with suitable side dishes.","translation":"一块烤得恰到好处的牛排可以成为庆祝餐的核心，前提是搭配了合适的配菜。"}]},"danger":{"examples":[{"sentence":"Because the dam showed signs of structural weakness, engineers warned that the downstream villages were in imminent danger.","translation":"由于大坝出现了结构薄弱的迹象，工程师警告下游村庄面临迫在眉睫的危险。"},{"sentence":"Although the species was once abundant, it now faces the danger of extinction due to habitat loss and poaching.","translation":"尽管该物种曾经数量众多，但由于栖息地丧失和偷猎，它现在面临灭绝的危险。"},{"sentence":"The researcher emphasized that ignoring early warning signals can place entire communities in grave danger.","translation":"研究人员强调，忽视早期预警信号可能使整个社区陷入严重危险。"},{"sentence":"While the new technology offers significant benefits, it also introduces the danger of unprecedented privacy violations.","translation":"虽然新技术带来了显著的好处，但它也带来了前所未有的隐私侵犯危险。"},{"sentence":"Public health officials must communicate the danger of infectious diseases clearly so that citizens take appropriate precautions.","translation":"公共卫生官员必须清楚地传达传染病的危险，以便公民采取适当的预防措施。"}]},"prepare":{"examples":[{"sentence":"To prepare for the upcoming conference, the team compiled a comprehensive report that synthesized recent findings.","translation":"为筹备即将到来的会议，团队编写了一份综合报告，汇总了近期研究成果。"},{"sentence":"Although the students had only two weeks to prepare, they delivered a presentation that impressed the entire faculty.","translation":"尽管学生们只有两周时间准备，但他们的演讲给全体教员留下了深刻印象。"},{"sentence":"The government must prepare contingency plans that address both economic downturns and natural disasters.","translation":"政府必须制定应急计划，以应对经济衰退和自然灾害。"},{"sentence":"Because the experiment requires precise conditions, the laboratory technicians need to prepare the equipment well in advance.","translation":"由于实验需要精确的条件，实验室技术人员需要提前准备好设备。"},{"sentence":"Universities should prepare students not only for their first job but also for a lifetime of adaptive learning.","translation":"大学不仅应让学生为第一份工作做好准备，还应为他们终身的适应性学习做好准备。"}]},"magnetic":{"examples":[{"sentence":"Although the material is not naturally magnetic, scientists can induce magnetism through a process of controlled exposure to strong fields.","translation":"尽管这种材料并非天然具有磁性，但科学家可以通过受控暴露于强磁场的过程来诱导磁性。"},{"sentence":"The magnetic resonance imaging technique, which relies on powerful magnets, has revolutionized medical diagnostics by providing detailed internal views.","translation":"磁共振成像技术依赖于强大的磁体，通过提供详细的内部视图，彻底改变了医学诊断。"},{"sentence":"Because her magnetic charm captivated audiences worldwide, the actress became a cultural icon within a remarkably short time.","translation":"由于她那富有吸引力的魅力迷住了全世界的观众，这位女演员在极短的时间内成为了文化偶像。"},{"sentence":"Engineers designed a magnetic levitation train that reduces friction, thereby achieving speeds far beyond those of conventional rail systems.","translation":"工程师设计了一种磁悬浮列车，它减少了摩擦，从而实现了远超传统铁路系统的速度。"},{"sentence":"While magnetic fields are invisible to the naked eye, their effects on charged particles can be observed in laboratory experiments.","translation":"虽然磁场肉眼不可见，但它们对带电粒子的影响可以在实验室实验中观察到。"}]},"campaign":{"examples":[{"sentence":"The presidential campaign, which lasted nearly two years, exhausted both candidates but ultimately engaged millions of voters.","translation":"这场持续了近两年的总统竞选活动让两位候选人都筋疲力尽，但最终吸引了数百万选民。"},{"sentence":"Because the anti-smoking campaign used graphic images of diseased lungs, it significantly reduced tobacco use among teenagers.","translation":"由于反吸烟运动使用了病变肺部的图像，它显著减少了青少年吸烟。"},{"sentence":"A well-funded marketing campaign can create brand loyalty, even when the product itself is not markedly superior to its competitors.","translation":"一场资金充足的营销活动可以建立品牌忠诚度，即使产品本身并不明显优于竞争对手。"},{"sentence":"The military campaign succeeded not only through superior firepower but also through the strategic use of local terrain.","translation":"这场军事战役的成功不仅依靠优势火力，还依靠对当地地形的战略利用。"},{"sentence":"Although the environmental campaign faced strong opposition from industry lobbyists, it eventually led to stricter pollution regulations.","translation":"尽管这场环保运动面临行业说客的强烈反对，但它最终导致了更严格的污染法规。"}]},"detail":{"examples":[{"sentence":"The researcher described the experimental procedure in such detail that even a novice could replicate it.","translation":"研究人员如此详细地描述了实验步骤，以至于新手也能复制。"},{"sentence":"Because the architect paid meticulous attention to detail, the building harmonizes with its historic surroundings.","translation":"因为建筑师对细节一丝不苟，这座建筑与历史环境融为一体。"},{"sentence":"A policy that overlooks a single crucial detail can undermine the entire reform effort.","translation":"一项忽视单个关键细节的政策可能破坏整个改革努力。"},{"sentence":"Although the report summarized the findings, the appendix provided the supporting data in exhaustive detail.","translation":"尽管报告总结了发现，附录却以详尽的细节提供了支撑数据。"},{"sentence":"To write a persuasive proposal, one must substantiate every claim with concrete detail rather than vague assertions.","translation":"要写出有说服力的提案，必须用具体细节而非模糊断言来证实每个主张。"}]},"tongue":{"examples":[{"sentence":"Although English is not her mother tongue, she delivers academic presentations with remarkable fluency.","translation":"尽管英语不是她的母语，她仍能以非凡的流利度进行学术演讲。"},{"sentence":"A slip of the tongue during the interview, which revealed confidential information, cost him the job opportunity.","translation":"面试中的一次口误泄露了机密信息，使他失去了工作机会。"},{"sentence":"Because the indigenous tongue is no longer taught at home, linguists fear it will vanish within a generation.","translation":"因为这种土著语言不再在家中教授，语言学家担心它将在一代人之内消失。"},{"sentence":"The diplomat's sharp tongue, while effective in debate, often alienates potential allies.","translation":"这位外交官的尖刻言辞虽然在辩论中有效，却常常疏远潜在盟友。"},{"sentence":"To master a foreign tongue, learners must immerse themselves in authentic contexts rather than relying solely on textbooks.","translation":"要掌握一门外语，学习者必须沉浸在真实语境中，而不是仅仅依赖教科书。"}]},"chop":{"examples":[{"sentence":"The chef demonstrated how to chop vegetables uniformly so that they would cook at the same rate and enhance the dish's presentation.","translation":"厨师演示了如何将蔬菜切得大小均匀，以便它们能以相同的速度烹熟并提升菜肴的品相。"},{"sentence":"Because the butcher prepared the chop with precision, the cut retained its tenderness and cooked evenly on the grill.","translation":"由于屠夫精准地处理了这块排骨，切块保持了嫩度，并在烤架上均匀受热。"},{"sentence":"Although a chop is often considered a simple cut of meat, its quality depends on the animal's diet and the aging process.","translation":"尽管排骨常被视为一种简单的肉块，但其品质取决于动物的饮食和熟成过程。"},{"sentence":"The recipe instructed the cook to chop the herbs finely, which released their essential oils and intensified the sauce's flavor.","translation":"食谱指导厨师将香草切碎，这样能释放其精油并增强酱汁的风味。"},{"sentence":"When preparing a stir-fry, it is essential to chop all ingredients beforehand to ensure that the cooking process remains swift and controlled.","translation":"在准备炒菜时，提前将所有食材切好至关重要，以确保烹饪过程迅速且可控。"}]},"lumber":{"examples":[{"sentence":"Sustainable forestry practices ensure that lumber production does not irreversibly damage ecosystems.","translation":"可持续的林业实践确保木材生产不会对生态系统造成不可逆转的损害。"},{"sentence":"Because the construction industry relies heavily on imported lumber, it is vulnerable to global trade policy fluctuations.","translation":"由于建筑业严重依赖进口木材，它容易受到全球贸易政策波动的影响。"},{"sentence":"Using reclaimed lumber in building projects can significantly reduce the demand for virgin timber, thereby conserving forests.","translation":"在建筑项目中使用再生木材可以显著减少对原始木材的需求，从而保护森林。"},{"sentence":"Although steel frames offer greater durability, many architects prefer lumber for its aesthetic warmth and lower carbon footprint.","translation":"尽管钢框架提供更高的耐用性，但许多建筑师更喜欢木材，因为它具有美学上的温暖感和较低的碳足迹。"},{"sentence":"The lumber industry must adapt to stricter environmental regulations if it hopes to maintain long-term profitability.","translation":"木材行业如果希望保持长期盈利，就必须适应更严格的环境法规。"}]},"prior":{"examples":[{"sentence":"Although she had no prior experience in management, she quickly adapted to the leadership role.","translation":"尽管她之前没有管理经验，但她很快适应了领导角色。"},{"sentence":"The court ruled that the prior contract was void because it violated public policy.","translation":"法院裁定先前的合同无效，因为它违反了公共政策。"},{"sentence":"Prior to the experiment, all participants were required to sign a consent form to ensure ethical compliance.","translation":"在实验之前，所有参与者都必须签署同意书，以确保符合伦理规范。"},{"sentence":"The professor emphasized that prior knowledge of calculus is a prerequisite for this advanced physics course.","translation":"教授强调，先前的微积分知识是这门高级物理课程的先决条件。"},{"sentence":"Because the company failed to disclose prior safety violations, it faced severe penalties from the regulator.","translation":"由于该公司未能披露先前的安全违规行为，它面临监管机构的严厉处罚。"}]},"equation":{"examples":[{"sentence":"When solving a quadratic equation, one must consider both positive and negative roots to ensure accuracy.","translation":"在解二次方程时，必须考虑正根和负根以确保准确性。"},{"sentence":"The economist incorporated inflation into the equation, thereby improving the model's predictive power.","translation":"经济学家将通货膨胀纳入方程，从而提高了模型的预测能力。"},{"sentence":"Although the equation is mathematically elegant, its real-world application requires careful calibration.","translation":"尽管该方程在数学上很优雅，但其实际应用需要仔细校准。"},{"sentence":"The chemical equation must be balanced, which means that the number of atoms on each side is equal.","translation":"化学方程式必须配平，这意味着每一边的原子数相等。"},{"sentence":"Because the equation omitted a key variable, the results were misleading and had to be revised.","translation":"由于方程遗漏了一个关键变量，结果具有误导性，不得不进行修正。"}]},"waiter":{"examples":[{"sentence":"The waiter who served our table remained remarkably composed even when the restaurant became crowded.","translation":"那位为我们这桌服务的服务员即使在餐厅变得拥挤时也保持着非凡的镇定。"},{"sentence":"Although the waiter had little formal education, his ability to handle difficult customers impressed the manager.","translation":"尽管这位服务员没受过多少正规教育，但他处理难缠顾客的能力给经理留下了深刻印象。"},{"sentence":"The waiter recommended a dish that was not on the menu, which turned out to be the highlight of the meal.","translation":"服务员推荐了一道菜单上没有的菜，结果成了那顿饭的亮点。"},{"sentence":"A skilled waiter can anticipate guests' needs before they are expressed, thereby enhancing the overall dining experience.","translation":"一个熟练的服务员能在客人表达之前预见到他们的需求，从而提升整体用餐体验。"},{"sentence":"The waiter discreetly informed the host that one of the guests had a food allergy, ensuring a safe dining experience.","translation":"服务员谨慎地告知主人其中一位客人有食物过敏，从而确保了安全的用餐体验。"}]},"two":{"examples":[{"sentence":"Although the two proposals share a common goal, they differ significantly in their implementation strategies.","translation":"尽管这两项提案有共同的目标，但它们在实施策略上存在显著差异。"},{"sentence":"The study compared two groups of participants, one of which received the experimental treatment while the other served as a control.","translation":"该研究比较了两组参与者，其中一组接受实验处理，而另一组作为对照。"},{"sentence":"Because the two variables are highly correlated, researchers must control for one when analyzing the other.","translation":"由于这两个变量高度相关，研究人员在分析其中一个时必须控制另一个。"},{"sentence":"The policy aims to address two critical issues, namely environmental degradation and economic inequality, through integrated measures.","translation":"该政策旨在通过综合措施解决两个关键问题，即环境退化和经济不平等。"},{"sentence":"When two cultures interact over an extended period, they often influence each other's language and customs.","translation":"当两种文化长期互动时，它们常常会影响彼此的语言和习俗。"}]},"paper":{"examples":[{"sentence":"Although the paper was published in a prestigious journal, several peers questioned the validity of its methodology.","translation":"尽管这篇论文发表在一家知名期刊上，但几位同行质疑其研究方法的有效性。"},{"sentence":"The policy paper argues that investing in early childhood education yields substantial long-term economic benefits.","translation":"这份政策文件认为，投资于儿童早期教育能带来可观的长期经济效益。"},{"sentence":"Because the paper relied on outdated data, the committee requested a supplementary analysis before making a decision.","translation":"由于该论文依赖过时的数据，委员会要求进行补充分析后再做决定。"},{"sentence":"She submitted a paper that not only challenged conventional theories but also proposed a novel framework for future research.","translation":"她提交了一篇论文，不仅挑战了传统理论，还为未来的研究提出了一个新颖的框架。"},{"sentence":"The professor distributed a paper outlining the key arguments of her latest research, which sparked a lively debate among the students.","translation":"教授分发了一篇概述她最新研究关键论点的论文，这在学生中引发了热烈的讨论。"}]},"migrate":{"examples":[{"sentence":"Although many birds migrate to warmer regions when winter approaches, some species have adapted to endure the cold.","translation":"尽管许多鸟类在冬季来临时迁徙到更温暖的地区，但有些物种已经适应了忍受寒冷。"},{"sentence":"Rural populations often migrate to urban centers because they seek better employment opportunities and improved living standards.","translation":"农村人口经常迁移到城市中心，因为他们寻求更好的就业机会和更高的生活水平。"},{"sentence":"Some fish species migrate upstream to spawn, a journey that demands immense energy and exposes them to predators.","translation":"一些鱼类逆流而上迁徙产卵，这段旅程需要巨大的能量，并使它们暴露于捕食者面前。"},{"sentence":"As climate patterns shift, certain animal populations are forced to migrate toward cooler habitats, which may disrupt existing ecosystems.","translation":"随着气候模式的变化，某些动物种群被迫迁徙到更凉爽的栖息地，这可能会破坏现有的生态系统。"},{"sentence":"Highly skilled professionals may migrate to countries that offer more advanced research facilities, thereby contributing to a brain drain in their home nations.","translation":"高技能专业人员可能会迁移到提供更先进研究设施的国家，从而导致其祖国的人才流失。"}]},"six":{"examples":[{"sentence":"The committee, which consists of six experts, will review the proposal before the deadline to ensure a thorough evaluation.","translation":"由六位专家组成的委员会将在截止日期前审查该提案，以确保进行彻底的评估。"},{"sentence":"After six months of intensive training, the team demonstrated a significant improvement in performance, which impressed the management.","translation":"经过六个月的强化训练，该团队在表现上显示出显著提升，这给管理层留下了深刻印象。"},{"sentence":"Because the project required diverse skills, the manager assembled a group of six specialists from different fields, thereby enhancing the team's capability.","translation":"由于项目需要多样化的技能，经理组建了一个由来自不同领域的六位专家组成的小组，从而增强了团队的能力。"},{"sentence":"The survey found that six out of ten respondents preferred online learning to traditional classroom instruction, which indicates a shift in educational preferences.","translation":"调查发现，十分之六的受访者更喜欢在线学习而非传统课堂教学，这表明教育偏好的转变。"},{"sentence":"Although the course lasts only six weeks, it covers a comprehensive range of topics in environmental science, thereby providing a solid foundation for further study.","translation":"尽管该课程仅持续六周，但它涵盖了环境科学领域的广泛主题，从而为进一步学习奠定了坚实的基础。"}]},"reassure":{"examples":[{"sentence":"The detailed safety report helped reassure the public that the new technology posed no significant risk, which was crucial for its acceptance.","translation":"详细的安全报告有助于让公众放心，新技术不会构成重大风险，这对于它的接受至关重要。"},{"sentence":"To reassure investors, the company released a transparent financial statement outlining its recovery plan, thereby restoring confidence in the market.","translation":"为了让投资者安心，公司发布了一份透明的财务报表，概述了其复苏计划，从而恢复了市场信心。"},{"sentence":"The teacher's calm explanation served to reassure the students who were anxious about the upcoming exam, because it clarified the difficult concepts.","translation":"老师冷静的解释让那些对即将到来的考试感到焦虑的学生安心，因为它澄清了难懂的概念。"},{"sentence":"Although the initial results were disappointing, the researcher tried to reassure the team that the methodology was sound, which helped maintain morale.","translation":"尽管初步结果令人失望，但研究员试图让团队放心，方法是可靠的，这有助于保持士气。"},{"sentence":"Regular communication from the leadership can reassure employees during periods of organizational change, thereby reducing uncertainty and resistance.","translation":"在组织变革期间，领导层的定期沟通可以让员工安心，从而减少不确定性和阻力。"}]},"trade":{"examples":[{"sentence":"Although international trade can stimulate economic growth, it may also lead to job displacement in certain sectors if workers lack retraining opportunities.","translation":"尽管国际贸易可以刺激经济增长，但如果工人缺乏再培训机会，它也可能导致某些行业的失业。"},{"sentence":"The expansion of e-commerce has transformed retail trade, enabling small businesses to reach global markets without the need for physical storefronts.","translation":"电子商务的扩张改变了零售贸易，使小企业无需实体店面就能进入全球市场。"},{"sentence":"Because trade agreements often reduce tariffs and harmonize regulations, they can lower consumer prices and increase product variety.","translation":"由于贸易协定通常会降低关税并协调法规，它们可以降低消费者价格并增加产品种类。"},{"sentence":"The historical Silk Road facilitated not only the exchange of goods but also the spread of ideas, thereby enriching civilizations through trade.","translation":"历史上的丝绸之路不仅促进了商品交换，还传播了思想，从而通过贸易丰富了文明。"},{"sentence":"While free trade is generally beneficial, governments may impose trade barriers to protect national security or infant industries from foreign competition.","translation":"尽管自由贸易通常是有益的，但政府可能会设置贸易壁垒，以保护国家安全或新兴产业免受外国竞争。"}]},"depress":{"examples":[{"sentence":"Persistent economic uncertainty can depress consumer spending, which in turn slows overall growth.","translation":"持续的经济不确定性会抑制消费者支出，进而减缓整体增长。"},{"sentence":"When policymakers depress interest rates too aggressively, they risk fueling asset bubbles that may later burst.","translation":"当政策制定者过于激进地压低利率时，他们可能助长资产泡沫，这些泡沫随后可能破裂。"},{"sentence":"Excessive screen time can depress academic performance, because it reduces the hours available for focused study.","translation":"过度使用屏幕会降低学业表现，因为它减少了可用于专注学习的时间。"},{"sentence":"Although the medication is effective, it may temporarily depress the patient's appetite, requiring nutritional monitoring.","translation":"尽管这种药物有效，但它可能暂时抑制患者的食欲，需要营养监测。"},{"sentence":"A prolonged drought will depress crop yields, thereby threatening food security in the region.","translation":"长期干旱将压低作物产量，从而威胁该地区的粮食安全。"}]},"death":{"examples":[{"sentence":"Although the death of a loved one is deeply painful, it often prompts survivors to cherish their remaining relationships more fully.","translation":"尽管亲人的离世令人深感痛苦，但它常常促使生者更充分地珍惜余下的关系。"},{"sentence":"Because the death penalty remains a controversial issue, many nations have abolished it in favor of life imprisonment.","translation":"由于死刑仍然是一个有争议的问题，许多国家已废除死刑而改用终身监禁。"},{"sentence":"When a species faces the threat of death due to habitat loss, conservationists must coordinate international efforts to protect it.","translation":"当一个物种因栖息地丧失而面临灭绝的威胁时，自然保护主义者必须协调国际努力来保护它。"},{"sentence":"The death of traditional bookstores, which has accelerated in the digital age, reflects a broader shift in consumer behavior.","translation":"传统书店的消亡在数字时代加速，这反映了消费者行为更广泛的转变。"},{"sentence":"If policymakers ignore the social determinants of death, such as poverty and inequality, public health outcomes will remain stagnant.","translation":"如果政策制定者忽视死亡的社会决定因素，如贫困和不平等，公共卫生结果将停滞不前。"}]},"missionary":{"examples":[{"sentence":"Although the missionary faced cultural barriers, his dedication to education led to the establishment of several rural schools.","translation":"尽管这位传教士面临文化障碍，但他对教育的奉献促成了几所乡村学校的建立。"},{"sentence":"Because missionary hospitals often provided the only available healthcare, they gained trust even among skeptical local populations.","translation":"由于教会医院常常提供唯一可及的医疗保健，它们甚至赢得了持怀疑态度的当地居民的信任。"},{"sentence":"When a missionary documented indigenous languages, he inadvertently preserved cultural knowledge that would otherwise have been lost.","translation":"当一位传教士记录土著语言时，他无意中保存了原本会失传的文化知识。"},{"sentence":"The missionary movement, which peaked in the 19th century, left a complex legacy of both humanitarian aid and cultural disruption.","translation":"在19世纪达到顶峰的传教运动，留下了人道主义援助和文化破坏的复杂遗产。"},{"sentence":"If modern NGOs adopt a missionary zeal without cultural sensitivity, their interventions may do more harm than good.","translation":"如果现代非政府组织采取传教士般的热忱而缺乏文化敏感性，他们的干预可能弊大于利。"}]},"coordinate":{"examples":[{"sentence":"To ensure a seamless product launch, the marketing and engineering teams must coordinate their timelines and resources effectively.","translation":"为了确保产品顺利发布，营销和工程团队必须有效协调他们的时间表和资源。"},{"sentence":"Although international relief efforts are well-intentioned, they often fail unless agencies coordinate their activities on the ground.","translation":"尽管国际救援努力是善意的，但除非各机构在实地协调活动，否则它们常常失败。"},{"sentence":"Because the human brain must coordinate countless neural signals, even minor disruptions can lead to significant cognitive impairments.","translation":"由于人脑必须协调无数神经信号，即使是微小的干扰也可能导致严重的认知障碍。"},{"sentence":"The new traffic management system uses AI to coordinate signal timings, thereby reducing congestion during peak hours.","translation":"新的交通管理系统使用人工智能协调信号配时，从而减少高峰时段的拥堵。"},{"sentence":"When diplomats coordinate their positions before a summit, they increase the likelihood of reaching a binding international agreement.","translation":"当外交官在峰会前协调立场时，他们增加了达成有约束力的国际协议的可能性。"}]},"chef":{"examples":[{"sentence":"Because the executive chef emphasized rigorous training, the restaurant maintained its Michelin star for five consecutive years.","translation":"由于行政主厨强调严格培训，这家餐厅连续五年保持了米其林星级。"},{"sentence":"The head chef redesigned the menu to incorporate locally sourced ingredients, thereby supporting regional farmers.","translation":"主厨重新设计了菜单以融入当地采购的食材，从而支持了区域农民。"},{"sentence":"A skilled chef must balance creativity with consistency when developing new dishes that appeal to diverse palates.","translation":"一位技艺娴熟的厨师在开发吸引不同口味的新菜品时，必须平衡创意与一致性。"},{"sentence":"The chef, who had trained in Paris, introduced innovative techniques that transformed the kitchen's workflow.","translation":"那位在巴黎受训的厨师引入了创新技术，改变了厨房的工作流程。"},{"sentence":"In response to dietary trends, the chef developed a plant-based tasting menu that attracted a wider clientele.","translation":"为了应对饮食趋势，厨师开发了一套植物性品尝菜单，吸引了更广泛的顾客。"}]},"sleeve":{"examples":[{"sentence":"Although the sleeve of his jacket was torn, he continued to wear it because it held sentimental value.","translation":"尽管他的夹克袖子破了，但他继续穿着，因为它具有情感价值。"},{"sentence":"The mechanic used a metal sleeve to reinforce the worn shaft, thereby extending the machine's lifespan.","translation":"机械师使用金属套管加固磨损的轴，从而延长了机器的使用寿命。"},{"sentence":"When the tailor shortened the sleeve, she ensured that the cuff still fit comfortably around the wrist.","translation":"裁缝在缩短袖子时，确保袖口仍能舒适地贴合手腕。"},{"sentence":"Because the protective sleeve was missing, the electrical wires were exposed to moisture and eventually short-circuited.","translation":"由于保护套管缺失，电线暴露在潮湿环境中，最终短路。"},{"sentence":"The designer added a lace trim to the sleeve, which gave the dress a more elegant appearance.","translation":"设计师在袖子上添加了蕾丝边，使裙子外观更加优雅。"}]},"quota":{"examples":[{"sentence":"Because the government set a strict quota on carbon emissions, factories had to adopt cleaner technologies to comply.","translation":"由于政府对碳排放设定了严格的配额，工厂不得不采用更清洁的技术以遵守规定。"},{"sentence":"The sales team exceeded their monthly quota by 20 percent, which earned them a substantial bonus.","translation":"销售团队超额完成了月度配额20%，这为他们赢得了可观的奖金。"},{"sentence":"When the import quota on textiles was lifted, the market was flooded with cheaper foreign products, thereby challenging local manufacturers.","translation":"当纺织品进口配额取消时，市场上充斥着更便宜的外国产品，从而对本地制造商构成挑战。"},{"sentence":"Although the university's admission quota for international students is limited, it attracts applicants from over 50 countries each year.","translation":"尽管该大学对国际学生的招生配额有限，但每年仍吸引来自50多个国家的申请者。"},{"sentence":"To ensure fairness, the organization allocated a quota of seats for representatives from each region.","translation":"为了确保公平，该组织为每个地区的代表分配了席位配额。"}]},"hungry":{"examples":[{"sentence":"Although the country has made economic progress, many rural families still go hungry during the dry season.","translation":"尽管该国取得了经济进步，但许多农村家庭在旱季仍然挨饿。"},{"sentence":"A hungry mind, which constantly seeks new challenges, is essential for innovation in any field.","translation":"一个渴望知识、不断寻求新挑战的头脑，对于任何领域的创新都至关重要。"},{"sentence":"Because the children were hungry, the teacher decided to start the lunch break earlier than usual.","translation":"因为孩子们饿了，老师决定比平时提前开始午休。"},{"sentence":"The organization's mission is to ensure that no child goes to bed hungry in the community.","translation":"该组织的使命是确保社区里没有孩子饿着肚子上床睡觉。"},{"sentence":"If the government does not address food insecurity, the number of hungry citizens will continue to rise.","translation":"如果政府不解决粮食不安全问题，饥饿公民的数量将继续上升。"}]},"golf":{"examples":[{"sentence":"Although golf is often perceived as a leisurely sport, it requires significant physical stamina and mental focus.","translation":"尽管高尔夫常被视为一项休闲运动，但它需要相当的体力和精神专注。"},{"sentence":"The charity golf tournament, which attracted numerous celebrities, raised substantial funds for children's education.","translation":"那场吸引了众多名人的慈善高尔夫锦标赛，为儿童教育筹集了大量资金。"},{"sentence":"Because the golf course was designed by a renowned architect, it offers a challenging yet enjoyable experience.","translation":"由于该高尔夫球场由一位著名建筑师设计，它提供了富有挑战性却又令人愉悦的体验。"},{"sentence":"Learning to play golf not only improves one's physical health but also cultivates patience and strategic thinking.","translation":"学习打高尔夫不仅能改善身体健康，还能培养耐心和战略思维。"},{"sentence":"When the company relocated its headquarters, the proximity to a golf course was a factor in the decision.","translation":"当公司搬迁总部时，靠近高尔夫球场是决策中的一个因素。"}]},"parasite":{"examples":[{"sentence":"A parasite that depends entirely on its host for survival often evolves to minimize harm, since killing the host would eliminate its own habitat.","translation":"完全依赖宿主生存的寄生虫通常会进化到尽量减少伤害，因为杀死宿主会消除其自身的栖息地。"},{"sentence":"In many ecosystems, a parasite can regulate host populations, thereby contributing to overall biodiversity and stability.","translation":"在许多生态系统中，寄生虫可以调节宿主种群，从而促进整体生物多样性和稳定性。"},{"sentence":"Although a parasite is often viewed as purely destructive, its presence can drive host species to develop stronger immune defenses over generations.","translation":"尽管寄生虫通常被视为纯粹具有破坏性，但它的存在可以促使宿主物种在世代中发展出更强的免疫防御。"},{"sentence":"Researchers study the malaria parasite in order to identify vulnerabilities that could lead to more effective treatments.","translation":"研究人员研究疟疾寄生虫，以确定可能导致更有效治疗方法的弱点。"},{"sentence":"When a parasite infects a keystone species, the ripple effects can alter the entire food web, demonstrating the interconnectedness of ecological communities.","translation":"当寄生虫感染关键物种时，连锁反应可以改变整个食物网，表明生态群落的相互关联性。"}]},"beyond":{"examples":[{"sentence":"The complexity of climate models is beyond the grasp of most non-specialists, which underscores the need for effective science communication.","translation":"气候模型的复杂性超出了大多数非专业人士的理解范围，这凸显了有效科学传播的必要性。"},{"sentence":"Although the policy aims to reduce inequality, its long-term effects remain beyond our current ability to predict with certainty.","translation":"尽管该政策旨在减少不平等，但其长期影响仍超出了我们目前能够确切预测的能力。"},{"sentence":"The value of a liberal arts education extends beyond immediate job preparation, fostering critical thinking that benefits society as a whole.","translation":"文科教育的价值超出了直接的职业准备，它培养的批判性思维有益于整个社会。"},{"sentence":"Because the ethical implications of artificial intelligence go beyond technical considerations, interdisciplinary collaboration is essential for responsible development.","translation":"由于人工智能的伦理影响超出了技术考量，跨学科合作对于负责任的发展至关重要。"},{"sentence":"The historical significance of the Silk Road lies beyond mere trade, as it facilitated cultural exchange that shaped civilizations across continents.","translation":"丝绸之路的历史意义不仅在于贸易，因为它促进了文化交融，塑造了各大洲的文明。"}]},"adult":{"examples":[{"sentence":"An adult who pursues higher education later in life often brings valuable experience to the classroom, which enriches discussions.","translation":"一个在以后的生活中追求高等教育的成年人通常会为课堂带来宝贵的经验，从而丰富讨论。"},{"sentence":"Because an adult's brain continues to develop until the mid-twenties, decision-making skills may still be maturing during early adulthood.","translation":"由于成年人的大脑会持续发育到二十五岁左右，决策能力在成年早期可能仍在成熟。"},{"sentence":"When an adult assumes caregiving responsibilities for aging parents, it can create significant emotional and financial strain.","translation":"当一个成年人承担起照顾年迈父母的责任时，可能会造成巨大的情感和经济压力。"},{"sentence":"An adult who volunteers in the community not only contributes to social welfare but also gains a sense of purpose.","translation":"一个在社区做志愿者的成年人不仅为社会福利做出贡献，而且获得了目标感。"},{"sentence":"Although an adult is legally independent, many still rely on family networks for emotional support and practical advice.","translation":"尽管成年人在法律上是独立的，但许多人仍然依赖家庭网络获得情感支持和实际建议。"}]},"organ":{"examples":[{"sentence":"Although the liver is a resilient organ, excessive alcohol consumption can cause irreversible damage over time.","translation":"尽管肝脏是一个有复原能力的器官，但长期过量饮酒仍会造成不可逆的损伤。"},{"sentence":"Because the heart is a muscular organ, regular aerobic exercise strengthens its pumping efficiency.","translation":"由于心脏是一个肌肉器官，有规律的有氧运动能增强其泵血效率。"},{"sentence":"A free press serves as an indispensable organ of public scrutiny, which helps to hold governments accountable.","translation":"新闻自由是公众监督不可或缺的机构，这有助于让政府负起责任。"},{"sentence":"The Security Council is the principal organ of the United Nations, thereby bearing the primary responsibility for maintaining international peace.","translation":"安全理事会是联合国的主要机关，因此承担着维护国际和平的首要责任。"},{"sentence":"When the organ in the cathedral began to play, the resonant chords filled the vast nave with solemn grandeur.","translation":"当大教堂里的风琴开始演奏时，共鸣的和弦使整个宽阔的中殿充满了庄严宏伟的气氛。"}]},"sovereign":{"examples":[{"sentence":"A sovereign state possesses the exclusive right to govern its territory without external interference.","translation":"主权国家拥有不受外部干涉、独立治理其领土的专属权利。"},{"sentence":"Although the monarch remains the ceremonial head of state, actual sovereign power now rests with the elected parliament.","translation":"尽管君主仍是礼仪上的国家元首，但实际的主权权力现在属于民选议会。"},{"sentence":"The treaty explicitly recognizes each nation's sovereign authority over its natural resources, thereby preventing unilateral exploitation.","translation":"该条约明确承认每个国家对其自然资源拥有主权权力，从而防止了单方面开采。"},{"sentence":"In a constitutional monarchy, the sovereign reigns but does not rule, because executive decisions are made by the government.","translation":"在君主立宪制中，君主统而不治，因为行政决策由政府做出。"},{"sentence":"By pooling their sovereign rights in certain areas, member states can achieve collective goals that none could accomplish alone.","translation":"通过在某些领域集中行使主权权利，成员国可以实现任何一国单独无法完成的集体目标。"}]},"day":{"examples":[{"sentence":"Although the storm raged throughout the day, the rescue team continued their search without hesitation.","translation":"尽管暴风雨肆虐了一整天，救援队仍毫不犹豫地继续搜寻。"},{"sentence":"Because the conference was postponed by one day, we had extra time to refine our presentation.","translation":"因为会议推迟了一天，我们有额外的时间来完善我们的演示。"},{"sentence":"The new policy, which takes effect next month, will reduce the work day by one hour.","translation":"新政策将于下个月生效，将工作日缩短一小时。"},{"sentence":"While some people prefer to exercise in the morning, others find that evening workouts better suit their day.","translation":"虽然有些人喜欢在早上锻炼，但其他人发现晚上锻炼更适合他们的一天。"},{"sentence":"If we do not act now, the day will come when these resources are depleted beyond recovery.","translation":"如果我们现在不采取行动，这些资源枯竭到无法恢复的那一天将会到来。"}]},"slow":{"examples":[{"sentence":"Although the internet connection was slow, we managed to complete the video conference without major interruptions.","translation":"尽管网络连接很慢，我们还是设法完成了视频会议，没有出现重大中断。"},{"sentence":"Because the recovery process has been slow, investors are becoming increasingly cautious about future prospects.","translation":"由于复苏过程缓慢，投资者对未来前景变得越来越谨慎。"},{"sentence":"The government implemented new measures to slow the spread of the virus, which had been accelerating rapidly.","translation":"政府实施了新措施来减缓病毒的传播，此前病毒一直在迅速加速传播。"},{"sentence":"While a slow and steady approach may seem tedious, it often leads to more sustainable long-term results.","translation":"虽然缓慢而稳定的方法可能看起来乏味，但它通常会带来更可持续的长期结果。"},{"sentence":"The committee's slow decision-making process frustrated many stakeholders, thereby delaying the project's launch.","translation":"委员会缓慢的决策过程让许多利益相关者感到沮丧，从而推迟了项目的启动。"}]},"big":{"examples":[{"sentence":"Addressing climate change is a big challenge that requires coordinated international effort.","translation":"应对气候变化是一项需要国际协调努力的重大挑战。"},{"sentence":"Although the initial investment seems big, the long-term savings justify the expense.","translation":"尽管初始投资看似巨大，但长期的节省证明这笔花费是合理的。"},{"sentence":"The government's decision had a big impact on small businesses, many of which struggled to adapt.","translation":"政府的决定对小企业产生了巨大影响，其中许多企业难以适应。"},{"sentence":"A big data analysis can reveal patterns that traditional methods might overlook.","translation":"大数据分析可以揭示传统方法可能忽略的模式。"},{"sentence":"She played a big role in shaping the company's diversity policy, which improved employee satisfaction.","translation":"她在制定公司的多元化政策中发挥了重要作用，从而提高了员工满意度。"}]},"race":{"examples":[{"sentence":"Although the company claims to hire without regard to race, its workforce lacks diversity.","translation":"尽管该公司声称不分种族雇用人，但其员工队伍缺乏多样性。"},{"sentence":"Because the annual boat race attracts international teams, it significantly boosts local tourism.","translation":"由于一年一度的划船比赛吸引了国际队伍，它极大地促进了当地旅游业。"},{"sentence":"The race to develop a vaccine, which involved unprecedented global collaboration, ultimately saved millions of lives.","translation":"开发疫苗的竞赛涉及前所未有的全球合作，最终挽救了数百万人的生命。"},{"sentence":"Legislation that prohibits discrimination on the basis of race has been instrumental in promoting social equality.","translation":"禁止基于种族的歧视的立法在促进社会平等方面发挥了重要作用。"},{"sentence":"While the marathon is a grueling race, participants often describe it as a transformative experience.","translation":"虽然马拉松是一项艰苦的比赛，但参与者常将其描述为一次脱胎换骨的经历。"}]},"ride":{"examples":[{"sentence":"Although the bus ride from the airport takes only fifteen minutes, it can feel longer during rush hour.","translation":"虽然从机场坐公车只需十五分钟，但在高峰时段会感觉更长。"},{"sentence":"The bumpy ride through the countryside, which offered breathtaking views, was an unforgettable part of the trip.","translation":"穿越乡村的颠簸旅程展现了壮丽的景色，是旅行中难忘的一部分。"},{"sentence":"Because the amusement park ride reaches extreme speeds, it is not recommended for individuals with heart conditions.","translation":"由于游乐园的游乐设施达到极高的速度，不建议心脏病患者乘坐。"},{"sentence":"A short bike ride to work not only reduces carbon emissions but also improves cardiovascular health.","translation":"骑自行车短途上班不仅能减少碳排放，还能改善心血管健康。"},{"sentence":"The politician's rapid ride to power, which was fueled by charisma and strategic alliances, surprised many analysts.","translation":"这位政客的迅速掌权是由个人魅力和战略联盟推动的，令许多分析人士感到意外。"}]},"dangerous":{"examples":[{"sentence":"Because prolonged exposure to high levels of air pollution is dangerous to respiratory health, many cities have introduced stricter emission standards.","translation":"由于长期暴露在高水平空气污染中对呼吸系统健康是危险的，许多城市已经引入了更严格的排放标准。"},{"sentence":"While nuclear energy offers a low-carbon alternative, the disposal of radioactive waste remains a dangerous challenge that requires long-term planning.","translation":"尽管核能提供了一种低碳替代方案，但放射性废物的处置仍然是一个危险的挑战，需要长期规划。"},{"sentence":"The spread of misinformation online can create a dangerous environment in which public trust in science and institutions is steadily eroded.","translation":"网上错误信息的传播可能造成一种危险的环境，使公众对科学和机构的信任逐渐被侵蚀。"},{"sentence":"It is dangerous to assume that economic growth alone will resolve deep-seated social inequalities without targeted policy interventions.","translation":"假设仅靠经济增长就能在没有针对性政策干预的情况下解决根深蒂固的社会不平等是危险的。"},{"sentence":"When safety protocols are ignored, even routine laboratory procedures can become dangerous, leading to accidents that are entirely preventable.","translation":"当安全规程被忽视时，即使是常规的实验室操作也可能变得危险，导致完全可以预防的事故。"}]},"plead":{"examples":[{"sentence":"Although the defendant decided to plead guilty to the lesser charge, his lawyer continued to argue for a reduced sentence based on mitigating circumstances.","translation":"尽管被告决定对较轻的指控认罪，但他的律师继续基于减轻情节恳求减刑。"},{"sentence":"Environmental activists plead with world leaders to take immediate action on climate change, because the window for preventing catastrophic outcomes is rapidly closing.","translation":"环保活动人士恳求世界领导人立即对气候变化采取行动，因为防止灾难性后果的窗口期正在迅速关闭。"},{"sentence":"When the journalist was asked to reveal her source, she chose to plead the Fifth Amendment rather than compromise her ethical obligations.","translation":"当记者被要求透露她的消息来源时，她选择援引第五修正案，而不是违背她的道德义务。"},{"sentence":"The charity organization continues to plead for donations, as the ongoing crisis has left thousands of families without access to clean water and shelter.","translation":"该慈善组织继续恳求捐款，因为持续的危机使成千上万的家庭无法获得清洁水和住所。"},{"sentence":"Rather than plead for an extension without justification, the student submitted a detailed plan outlining how she would complete the remaining work on time.","translation":"该学生没有在没有理由的情况下恳求延期，而是提交了一份详细的计划，概述了她将如何按时完成剩余的工作。"}]},"forever":{"examples":[{"sentence":"Although the treaty was signed decades ago, its principles remain forever relevant to international diplomacy.","translation":"尽管该条约是几十年前签署的，但其原则对国际外交永远具有现实意义。"},{"sentence":"Because the artist's masterpiece was destroyed in the fire, a priceless cultural treasure is lost forever.","translation":"因为这位艺术家的杰作在火灾中被毁，一件无价的文化瑰宝永远消失了。"},{"sentence":"When a language dies, a unique worldview vanishes forever, which impoverishes human intellectual diversity.","translation":"当一种语言消亡时，一种独特的世界观就永远消失，这使人类智力多样性变得贫乏。"},{"sentence":"The invention of the internet has forever changed how we access information, thereby reshaping education and commerce.","translation":"互联网的发明永远改变了我们获取信息的方式，从而重塑了教育和商业。"},{"sentence":"Unless we take decisive action now, the damage to the ecosystem may last forever, threatening future generations.","translation":"除非我们现在采取果断行动，否则对生态系统的破坏可能永远持续，威胁到后代。"}]},"dead":{"examples":[{"sentence":"Although the patient was declared clinically dead, the medical team continued resuscitation efforts for another thirty minutes.","translation":"尽管病人被宣布临床死亡，但医疗团队又继续进行了三十分钟的抢救。"},{"sentence":"Because the volcano is considered dead, the surrounding area has been deemed safe for residential development.","translation":"因为这座火山被认为是死火山，周边地区已被视为可安全进行住宅开发。"},{"sentence":"When the negotiations reached a dead end, both parties agreed to bring in a mediator to facilitate a compromise.","translation":"当谈判陷入僵局时，双方同意引入调解人以促成妥协。"},{"sentence":"The ancient city, now dead for centuries, still offers valuable insights into early urban planning through its ruins.","translation":"这座古城已死寂数百年，但其废墟仍为早期城市规划提供了宝贵的见解。"},{"sentence":"If the battery is completely dead, the device will not respond even when connected to a power source, which indicates a need for replacement.","translation":"如果电池完全没电，即使连接电源设备也不会响应，这表明需要更换电池。"}]},"switch":{"examples":[{"sentence":"Although the initial investment is high, many households are choosing to switch to solar energy to reduce long-term costs.","translation":"尽管初始投资很高，但许多家庭为了降低长期成本正选择转向太阳能。"},{"sentence":"Because the software was prone to crashes, the company decided to switch to a more stable platform, which improved productivity.","translation":"因为该软件容易崩溃，公司决定转换到一个更稳定的平台，从而提高了生产力。"},{"sentence":"When the professor noticed the students' confusion, she made a quick switch to a more interactive teaching method.","translation":"当教授注意到学生的困惑时，她迅速转换到一种更具互动性的教学方法。"},{"sentence":"The sudden switch in consumer preferences forced the industry to rethink its marketing strategies, thereby accelerating innovation.","translation":"消费者偏好的突然转变迫使该行业重新思考其营销策略，从而加速了创新。"},{"sentence":"To ensure safety, the system is designed to automatically switch to backup power if the main supply fails.","translation":"为了确保安全，该系统设计为在主电源故障时自动切换到备用电源。"}]},"jeans":{"examples":[{"sentence":"Although jeans are often criticized for their casual appearance, they remain a versatile garment that can be dressed up with a blazer.","translation":"尽管牛仔裤常因其休闲外观而受到批评，但它仍然是一种百搭的服装，搭配西装外套可以显得正式。"},{"sentence":"Because jeans are made from durable denim, they are ideal for outdoor activities that require both comfort and resilience.","translation":"由于牛仔裤由耐用的牛仔布制成，它们非常适合需要舒适和韧性的户外活动。"},{"sentence":"While jeans were once exclusively worn by miners and cowboys, they have now become a symbol of democratic fashion worldwide.","translation":"虽然牛仔裤曾经只有矿工和牛仔穿，但现在它们已成为全球民主时尚的象征。"},{"sentence":"The fashion industry, which constantly reinvents classic items, has introduced eco-friendly jeans made from organic cotton to reduce environmental impact.","translation":"时尚行业不断重塑经典单品，推出了由有机棉制成的环保牛仔裤，以减少对环境的影响。"},{"sentence":"When choosing jeans for a professional setting, one should opt for darker washes and avoid distressed styles to maintain a polished look.","translation":"在为职业场合选择牛仔裤时，应选择深色水洗并避免破洞款式，以保持整洁的外观。"}]},"intact":{"examples":[{"sentence":"Despite the severe earthquake, the historic library remained largely intact, preserving centuries of knowledge.","translation":"尽管发生了强烈地震，这座历史悠久的图书馆基本保持完好，保存了几个世纪的知识。"},{"sentence":"The research team ensured that the original data stayed intact throughout the complex analysis process.","translation":"研究团队确保原始数据在复杂的分析过程中保持完整。"},{"sentence":"Because the capsule was designed to withstand extreme pressure, its contents were recovered intact from the ocean floor.","translation":"由于密封舱的设计能承受极端压力，其内部物品从海底被打捞上来时完好无损。"},{"sentence":"The legal framework must remain intact if we are to maintain public trust in the judicial system.","translation":"如果我们要维持公众对司法体系的信任，法律框架必须保持完整。"},{"sentence":"Even after the merger, the company's core values were kept intact, which reassured long-term employees.","translation":"即使在合并之后，公司的核心价值观仍得以保留，这让老员工感到安心。"}]},"thrill":{"examples":[{"sentence":"Although the thrill of winning the competition was immense, she remained focused on her long-term academic goals.","translation":"尽管赢得比赛的激动是巨大的，但她仍然专注于自己的长期学术目标。"},{"sentence":"The thrill that comes from solving a complex mathematical problem can motivate students to pursue advanced studies.","translation":"解决复杂数学问题所带来的激动可以激励学生追求更高层次的学习。"},{"sentence":"While the thrill of traveling to new countries is undeniable, it is the cultural immersion that truly enriches one's perspective.","translation":"尽管前往新国家旅行的激动不可否认，但真正丰富个人视野的是文化沉浸。"},{"sentence":"Because the thrill of discovery drives scientific progress, researchers often dedicate their lives to exploring the unknown.","translation":"因为发现的激动推动着科学进步，研究人员常常毕生致力于探索未知。"},{"sentence":"The thrill of performing on stage, which many actors describe as addictive, requires years of rigorous training to achieve.","translation":"许多演员描述为令人上瘾的舞台表演的激动，需要多年的严格训练才能实现。"}]},"glamor":{"examples":[{"sentence":"Although the glamor of the fashion industry attracts many young people, the work behind the scenes is often tedious and demanding.","translation":"尽管时尚产业的魅力吸引了许多年轻人，但幕后的工作往往是乏味且要求高的。"},{"sentence":"The glamor associated with being a published author can overshadow the years of rejection and revision that precede success.","translation":"与成为出版作家相关的魅力可能掩盖了成功之前多年的拒绝和修改。"},{"sentence":"While the glamor of a high-profile career is appealing, it is the sense of purpose that sustains long-term job satisfaction.","translation":"尽管高调职业的魅力很吸引人，但维持长期工作满意度的是使命感。"},{"sentence":"Because the glamor of social media influencers is carefully curated, it often presents an unrealistic standard of living.","translation":"因为社交媒体网红的魅力是精心策划的，它常常呈现出一种不切实际的生活标准。"},{"sentence":"The glamor of studying at an Ivy League university, which many students aspire to, comes with intense academic pressure.","translation":"许多学生向往的在常春藤盟校学习的魅力，伴随着巨大的学业压力。"}]},"shoot":{"examples":[{"sentence":"When the director decided to shoot the film in a single continuous take, the actors had to rehearse for months to ensure perfection.","translation":"当导演决定用一个连续的长镜头拍摄电影时，演员们不得不排练数月以确保完美。"},{"sentence":"Although the photographer wanted to shoot the wildlife in its natural habitat, the dense forest made it difficult to get clear shots.","translation":"尽管摄影师想在自然栖息地拍摄野生动物，但茂密的森林使得获取清晰镜头变得困难。"},{"sentence":"Because the documentary crew needed to shoot in a war zone, they underwent extensive safety training before deployment.","translation":"因为纪录片摄制组需要在战区拍摄，他们在部署前接受了广泛的安全培训。"},{"sentence":"The new plant began to shoot fresh green leaves, which indicated that the soil conditions were finally optimal for growth.","translation":"新植物开始长出鲜绿的叶子，这表明土壤条件终于达到了最佳生长状态。"},{"sentence":"While the basketball player attempted to shoot from the three-point line, the defender leaped to block the ball.","translation":"当篮球运动员试图从三分线投篮时，防守队员跳起封盖。"}]},"format":{"examples":[{"sentence":"The professor required that all essays follow a consistent format, which included a title page and numbered sections.","translation":"教授要求所有论文遵循一致的格式，其中包括标题页和编号章节。"},{"sentence":"Because the data were presented in a clear tabular format, readers could quickly identify the key trends.","translation":"由于数据以清晰的表格形式呈现，读者能够迅速识别关键趋势。"},{"sentence":"The conference adopted a hybrid format so that both in-person and remote participants could engage fully.","translation":"会议采用了混合形式，以便现场和远程参与者都能充分参与。"},{"sentence":"Although the report retained its traditional structure, the new digital format allowed for interactive charts and embedded videos.","translation":"尽管报告保留了传统结构，但新的数字格式允许使用交互式图表和嵌入视频。"},{"sentence":"To ensure compatibility across devices, the team standardized the file format before distributing the materials.","translation":"为确保跨设备兼容性，团队在分发材料前统一了文件格式。"}]},"patch":{"examples":[{"sentence":"Although the garden was mostly barren, a vibrant patch of wildflowers thrived in the corner, which attracted numerous bees.","translation":"尽管花园大部分荒芜，但角落里一片生机勃勃的野花却茁壮成长，吸引了许多蜜蜂。"},{"sentence":"The city has designated a small patch of land near the river as a protected wetland, thereby preserving local biodiversity.","translation":"市政府已将河边一小块土地划为受保护的湿地，从而维护了当地的生物多样性。"},{"sentence":"After the software update, a critical security patch was applied to prevent unauthorized access, which had been a major concern.","translation":"软件更新后，应用了一个关键的安全补丁以防止未经授权的访问，这一直是一个主要问题。"},{"sentence":"The researcher spent months developing a patch to fix the flaw in the algorithm, because it had caused inconsistent results.","translation":"研究人员花了数月时间开发一个补丁来修复算法中的缺陷，因为它导致了结果不一致。"},{"sentence":"In the vast desert, even a tiny patch of shade provided by a rock can offer crucial relief, while the sun remains scorching.","translation":"在广阔的沙漠中，即使是岩石提供的一小片阴凉也能提供至关重要的缓解，而太阳依然灼热。"}]},"cop":{"examples":[{"sentence":"The cop who patrols our neighborhood has earned widespread trust through consistent community engagement.","translation":"在我们社区巡逻的那位警官通过持续的社区互动赢得了广泛信任。"},{"sentence":"A veteran cop can often de-escalate a tense situation without resorting to force.","translation":"一位经验丰富的警官通常能够在不诉诸武力的情况下缓和紧张局面。"},{"sentence":"Because the cop had received advanced training in crisis intervention, he successfully persuaded the distressed individual to seek help.","translation":"由于那位警官接受过危机干预的高级培训，他成功说服了那名痛苦的人寻求帮助。"},{"sentence":"Although the cop faced intense public scrutiny, she maintained her professionalism and followed proper procedure.","translation":"尽管那位警官面临强烈的公众监督，她仍保持了专业精神并遵循了正当程序。"},{"sentence":"The cop who testified in court provided crucial evidence that led to a just verdict.","translation":"在法庭上作证的那位警官提供了关键证据，促成了公正的判决。"}]},"tolerant":{"examples":[{"sentence":"Although a tolerant attitude toward dissent is essential for democracy, it must be balanced against the need to maintain public order.","translation":"尽管对异议持宽容态度对民主至关重要，但必须与维护公共秩序的需要相平衡。"},{"sentence":"Because the new cultivar is tolerant of saline soil, it can thrive in coastal regions where other crops fail.","translation":"由于这种新品种能耐盐碱土壤，它能在其他作物无法生长的沿海地区茁壮成长。"},{"sentence":"A leader who is tolerant of diverse opinions fosters an inclusive environment, which in turn enhances team creativity.","translation":"一个能宽容不同意见的领导者会营造包容的环境，这反过来又提高了团队的创造力。"},{"sentence":"While some plants are tolerant of drought, they still require occasional watering to survive prolonged dry spells.","translation":"虽然有些植物耐旱，但它们仍需要偶尔浇水以度过长时间的干旱期。"},{"sentence":"Through education that promotes critical thinking, societies can become more tolerant of cultural differences.","translation":"通过促进批判性思维的教育，社会可以对文化差异变得更加宽容。"}]},"it":{"examples":[{"sentence":"When evaluating a new policy, it is essential to consider both its short-term costs and its long-term benefits.","translation":"在评估新政策时，必须同时考虑其短期成本和长期收益。"},{"sentence":"Although it may seem counterintuitive, investing in preventive healthcare often reduces overall medical expenditure.","translation":"尽管看似有悖直觉，但投资于预防性医疗通常能降低总体医疗支出。"},{"sentence":"It is widely acknowledged that early childhood education lays the foundation for lifelong learning and social development.","translation":"人们普遍认为，幼儿教育为终身学习和社会发展奠定了基础。"},{"sentence":"Because it requires interdisciplinary collaboration, tackling climate change demands a fundamental shift in how we organize research.","translation":"由于需要跨学科合作，应对气候变化要求我们从根本上改变组织研究的方式。"},{"sentence":"Once a scientific theory gains widespread acceptance, it can shape public policy for decades, even if subsequent evidence challenges its assumptions.","translation":"一旦科学理论获得广泛接受，它就能影响公共政策数十年，即使后来的证据质疑其假设。"}]},"rhythm":{"examples":[{"sentence":"Although the rhythm of urban life can be exhausting, many people find it stimulating and full of opportunity.","translation":"尽管城市生活的节奏可能令人疲惫，但许多人觉得它充满刺激和机遇。"},{"sentence":"Because a steady rhythm in writing enhances readability, skilled authors vary sentence length to create a natural flow.","translation":"由于稳定的节奏能增强可读性，熟练的作者会变化句子长度以创造自然的流畅感。"},{"sentence":"The circadian rhythm, which regulates sleep and alertness, can be disrupted by irregular work schedules.","translation":"调节睡眠和警觉性的昼夜节律可能因不规律的工作时间表而被打乱。"},{"sentence":"When learning a musical instrument, students must internalize the rhythm before they can play expressively.","translation":"学习乐器时，学生必须先内化节奏，然后才能富有表现力地演奏。"},{"sentence":"The rhythm of the seasons, which has governed agricultural cycles for millennia, is now shifting due to climate change.","translation":"数千年来支配农业周期的季节节奏，现在正因气候变化而改变。"}]},"various":{"examples":[{"sentence":"Although various factors contribute to economic growth, investment in education remains one of the most critical.","translation":"尽管各种因素促进经济增长，但教育投资仍然是最关键的之一。"},{"sentence":"Because the library subscribes to various academic journals, researchers can access a wide range of current studies.","translation":"由于图书馆订阅了各种学术期刊，研究人员可以获取广泛的当前研究。"},{"sentence":"The committee considered various proposals, which ranged from incremental reforms to radical restructuring, before reaching a decision.","translation":"委员会考虑了各种提案，从渐进式改革到彻底重组，然后才做出决定。"},{"sentence":"When designing a survey, it is important to include participants from various backgrounds to ensure representative results.","translation":"设计调查时，重要的是纳入各种背景的参与者，以确保结果具有代表性。"},{"sentence":"The museum's collection includes artifacts from various civilizations, thereby offering visitors a comprehensive view of human history.","translation":"博物馆的藏品包括来自各种文明的文物，从而为参观者提供了人类历史的全面视角。"}]},"restless":{"examples":[{"sentence":"Although the patient was physically exhausted, a restless anxiety prevented her from falling asleep before the surgery.","translation":"尽管病人身体疲惫，但一种焦躁不安的情绪使她在手术前无法入睡。"},{"sentence":"When employees lack challenging tasks, they often become restless and disengaged, which ultimately reduces overall productivity.","translation":"当员工缺乏具有挑战性的任务时，他们往往会变得焦躁和懈怠，这最终会降低整体生产力。"},{"sentence":"The restless crowd began to disperse only after the organizer announced that the delayed performance would start within ten minutes.","translation":"直到组织者宣布延迟的演出将在十分钟内开始后，焦躁的人群才开始散去。"},{"sentence":"Because the novel's protagonist is a restless spirit who cannot settle in one place, the narrative unfolds across five different countries.","translation":"因为小说的主人公是一个无法在一个地方安顿下来的不安分灵魂，所以故事在五个不同的国家展开。"},{"sentence":"A restless night spent worrying about the upcoming exam can impair cognitive performance, which is why sleep hygiene is crucial for students.","translation":"因担心即将到来的考试而辗转难眠的一夜会损害认知表现，这就是为什么睡眠卫生对学生至关重要。"}]},"prosperous":{"examples":[{"sentence":"Although the nation faced severe economic downturns, its commitment to innovation ultimately created a prosperous and resilient economy.","translation":"尽管该国面临严重的经济衰退，但其对创新的承诺最终创造了繁荣而有韧性的经济。"},{"sentence":"A prosperous society requires not only material wealth but also strong social cohesion, which fosters trust and cooperation among citizens.","translation":"一个繁荣的社会不仅需要物质财富，还需要强大的社会凝聚力，这能促进公民之间的信任与合作。"},{"sentence":"Because the government invested heavily in education and infrastructure, the once-struggling region became a prosperous hub for international trade.","translation":"由于政府大力投资教育和基础设施，这个曾经挣扎的地区成为了国际贸易的繁荣中心。"},{"sentence":"While some cities rely on a single industry, truly prosperous urban centers diversify their economies to ensure long-term stability.","translation":"虽然一些城市依赖单一产业，但真正繁荣的城市中心会实现经济多元化，以确保长期稳定。"},{"sentence":"The entrepreneur's decision to prioritize sustainable practices attracted ethical investors, thereby making the business both environmentally friendly and prosperous.","translation":"这位企业家优先考虑可持续实践的决定吸引了道德投资者，从而使企业既环保又繁荣。"}]},"proposition":{"examples":[{"sentence":"The central proposition of the theory is that economic growth depends primarily on technological innovation.","translation":"该理论的核心主张是，经济增长主要取决于技术创新。"},{"sentence":"Before we accept the proposition that all students benefit from smaller classes, we must examine the empirical evidence.","translation":"在我们接受所有学生都能从小班教学中受益这一主张之前，我们必须审视实证证据。"},{"sentence":"His research challenges the long-held proposition that bilingualism confuses children's cognitive development.","translation":"他的研究挑战了长期以来认为双语会混淆儿童认知发展的主张。"},{"sentence":"The business proposition involved a partnership that would expand our distribution network into three new regions.","translation":"这项商业提议涉及一项合作，将把我们的分销网络扩展到三个新地区。"},{"sentence":"In formal logic, a proposition is a statement that can be either true or false, but not both simultaneously.","translation":"在形式逻辑中，命题是一个可以为真或为假的陈述，但不能同时为真和假。"}]},"satellite":{"examples":[{"sentence":"Although satellite technology was once prohibitively expensive, it has now become accessible to many developing nations.","translation":"尽管卫星技术曾经昂贵得令人望而却步，但现在许多发展中国家已经能够使用它。"},{"sentence":"Because satellite imagery provides real-time data, emergency responders can coordinate relief efforts more effectively after natural disasters.","translation":"由于卫星图像提供实时数据，紧急救援人员可以在自然灾害后更有效地协调救援工作。"},{"sentence":"The satellite, which was launched last year, monitors ocean temperatures to help scientists predict El Niño events.","translation":"去年发射的那颗卫星监测海洋温度，以帮助科学家预测厄尔尼诺现象。"},{"sentence":"While satellite navigation systems are widely used, their signals can be disrupted by solar storms or intentional jamming.","translation":"虽然卫星导航系统被广泛使用，但其信号可能被太阳风暴或故意干扰所中断。"},{"sentence":"Governments invest in satellite programs to ensure national security, thereby gaining a strategic advantage in global affairs.","translation":"政府投资卫星项目以确保国家安全，从而在全球事务中获得战略优势。"}]},"companion":{"examples":[{"sentence":"A loyal companion can alleviate the stress of academic life, which often leads to burnout among graduate students.","translation":"一个忠诚的伴侣可以缓解学业压力，这种压力常常导致研究生精疲力竭。"},{"sentence":"Because a travel companion shares both costs and experiences, the journey becomes more affordable and memorable.","translation":"因为旅伴分担费用和经历，旅程变得更加实惠和难忘。"},{"sentence":"The elderly woman adopted a dog as a companion, thereby reducing her feelings of isolation and improving her daily routine.","translation":"那位老妇人收养了一只狗作为伴侣，从而减少了孤独感并改善了日常生活。"},{"sentence":"Although a study companion can enhance productivity, choosing someone with a compatible schedule is essential for success.","translation":"虽然学习伙伴可以提高效率，但选择一个时间安排相合的人对成功至关重要。"},{"sentence":"In many classic novels, the protagonist's companion serves as a moral compass, which highlights the central themes of the story.","translation":"在许多经典小说中，主人公的伴侣充当道德指南，这突出了故事的中心主题。"}]},"monument":{"examples":[{"sentence":"Although the monument was erected to honor a single leader, it has become a symbol of national unity.","translation":"尽管这座纪念碑是为纪念一位领袖而建，但它已成为民族团结的象征。"},{"sentence":"The ancient monument, which was discovered by archaeologists in 1922, provides valuable insights into early urban planning.","translation":"这座于1922年被考古学家发现的古老纪念碑，为早期城市规划提供了宝贵的见解。"},{"sentence":"Because the monument attracts thousands of tourists annually, the local economy has experienced significant growth.","translation":"由于这座纪念碑每年吸引成千上万的游客，当地经济实现了显著增长。"},{"sentence":"The decision to preserve the monument rather than replace it with a modern structure reflects a deep respect for cultural heritage.","translation":"决定保留这座纪念碑而非用现代建筑取而代之，体现了对文化遗产的深深敬意。"},{"sentence":"While the monument commemorates a tragic event, it also serves as a reminder of the resilience of the human spirit.","translation":"尽管这座纪念碑纪念的是一场悲剧事件，但它也提醒人们人类精神的坚韧。"}]},"statue":{"examples":[{"sentence":"The statue of the university's founder, which stands in the central plaza, serves as a reminder of the institution's enduring values.","translation":"矗立在中央广场的大学创始人雕像，提醒着人们这所机构经久不衰的价值观。"},{"sentence":"Because the ancient statue was carved from a single block of marble, it has survived for over two millennia.","translation":"由于这座古代雕像由一整块大理石雕刻而成，它已经存世超过两千年。"},{"sentence":"Although the bronze statue commemorates a controversial historical figure, it remains a protected cultural artifact.","translation":"尽管这座铜像纪念的是一位有争议的历史人物，但它仍是一件受保护的文化文物。"},{"sentence":"The statue, which was commissioned by the city council, aims to honor the contributions of local healthcare workers.","translation":"这座由市议会委托制作的雕像，旨在表彰当地医护人员的贡献。"},{"sentence":"When the statue was unveiled, the community gathered to reflect on the shared history it represents.","translation":"当雕像揭幕时，社区聚集在一起，反思它所代表的共同历史。"}]},"modify":{"examples":[{"sentence":"To improve fuel efficiency, engineers must modify the engine design without compromising safety standards.","translation":"为了提高燃油效率，工程师必须修改发动机设计，同时不降低安全标准。"},{"sentence":"Because the policy failed to address income inequality, lawmakers decided to modify its key provisions.","translation":"由于该政策未能解决收入不平等问题，立法者决定修改其关键条款。"},{"sentence":"Although the software update will modify the user interface, the core functionality remains unchanged.","translation":"尽管软件更新将修改用户界面，但核心功能保持不变。"},{"sentence":"Researchers often modify their hypotheses when new evidence contradicts the original assumptions.","translation":"当新证据与原始假设相矛盾时，研究人员通常会修改他们的假设。"},{"sentence":"The architect decided to modify the building's layout so that it would better accommodate natural light.","translation":"建筑师决定修改建筑的布局，以便更好地利用自然光。"}]},"texture":{"examples":[{"sentence":"Although the texture of the silk appears delicate, it is surprisingly durable when woven tightly.","translation":"尽管丝绸的质地看起来精致，但当紧密编织时，它却出奇地耐用。"},{"sentence":"The chef emphasized that the texture of the sauce, which should be velvety smooth, is crucial to the dish's success.","translation":"厨师强调，酱汁的质地应该如丝绒般顺滑，这对菜品的成功至关重要。"},{"sentence":"Because the texture of the soil affects water retention, farmers must choose crops that suit the local conditions.","translation":"由于土壤的质地影响保水性，农民必须选择适合当地条件的作物。"},{"sentence":"The texture of the ancient pottery, characterized by its coarse grit, indicates that it was used for cooking rather than storage.","translation":"古代陶器的质地以其粗糙的砂砾为特征，表明它是用于烹饪而非储存。"},{"sentence":"When designing a user interface, developers should consider the visual texture of elements to ensure a pleasant user experience.","translation":"在设计用户界面时，开发者应考虑元素的视觉质感，以确保愉悦的用户体验。"}]},"although":{"examples":[{"sentence":"Although online education offers flexibility, it requires strong self-discipline to complete courses successfully.","translation":"尽管在线教育提供了灵活性，但要成功完成课程需要很强的自律性。"},{"sentence":"Although the new policy aims to reduce pollution, its economic impact remains a subject of debate.","translation":"尽管新政策旨在减少污染，但其经济影响仍然是一个争论的话题。"},{"sentence":"Although artificial intelligence can process vast amounts of data, human judgment is still essential for ethical decisions.","translation":"尽管人工智能可以处理海量数据，但人类的判断对于伦理决策仍然至关重要。"},{"sentence":"Although many countries have adopted renewable energy, fossil fuels continue to dominate the global energy mix.","translation":"尽管许多国家已采用可再生能源，但化石燃料仍在全球能源结构中占主导地位。"},{"sentence":"Although the experiment did not yield the expected results, it provided valuable insights for future research.","translation":"尽管实验没有产生预期的结果，但它为未来的研究提供了宝贵的见解。"}]},"certify":{"examples":[{"sentence":"Although the laboratory must certify the purity of the compound, the process requires rigorous testing to ensure accuracy.","translation":"尽管实验室必须证明该化合物的纯度，但这一过程需要严格测试以确保准确性。"},{"sentence":"Because the board needs to certify the candidate's qualifications, they will review her credentials thoroughly before making a decision.","translation":"因为董事会需要证明候选人的资格，他们将在做出决定前彻底审查她的资历。"},{"sentence":"When an auditor is called to certify the accounts, any discrepancies must be resolved through careful examination.","translation":"当审计师被请来证明账目时，任何差异都必须通过仔细检查来解决。"},{"sentence":"If the agency fails to certify the safety of the new drug, it cannot be marketed to the public.","translation":"如果该机构未能证明新药的安全性，它就不能向公众销售。"},{"sentence":"Universities often certify language proficiency through standardized tests, which provide an objective measure of a student's abilities.","translation":"大学通常通过标准化考试来证明语言能力，这为学生的能力提供了客观的衡量标准。"}]},"liquor":{"examples":[{"sentence":"Although moderate consumption of liquor may have some social benefits, excessive drinking leads to severe health issues.","translation":"尽管适量饮用烈酒可能有一些社交好处，但过度饮酒会导致严重的健康问题。"},{"sentence":"Because the government regulates the sale of liquor strictly, underage purchasing is significantly reduced.","translation":"因为政府严格监管烈酒的销售，未成年人购买的情况显著减少。"},{"sentence":"When people consume liquor in excess, their judgment becomes impaired, which can result in dangerous behavior.","translation":"当人们过量饮用烈酒时，他们的判断力会受损，这可能导致危险行为。"},{"sentence":"If a country imposes high taxes on liquor, it can generate revenue while discouraging heavy drinking.","translation":"如果一个国家对烈酒征收高额税收，它可以在抑制过度饮酒的同时增加收入。"},{"sentence":"The cultural significance of liquor varies across societies, with some viewing it as a ceremonial drink rather than a casual beverage.","translation":"烈酒的文化意义因社会而异，有些社会将其视为礼仪饮品而非休闲饮料。"}]},"code":{"examples":[{"sentence":"Developers must write clean code so that their programs remain maintainable over time.","translation":"开发人员必须编写清晰的代码，以便程序长期保持可维护性。"},{"sentence":"Because the building did not comply with the fire code, the authorities ordered immediate renovations.","translation":"由于该建筑不符合消防法规，当局下令立即进行翻修。"},{"sentence":"The genetic code determines how organisms develop, which explains why certain traits are inherited.","translation":"遗传密码决定了生物体的发育方式，这解释了为什么某些特征会被遗传。"},{"sentence":"Although the algorithm is efficient, the underlying code requires thorough documentation for future reference.","translation":"尽管算法高效，但底层代码需要详尽的文档以供将来参考。"},{"sentence":"A uniform code of conduct helps organizations foster a culture of integrity, provided that it is consistently enforced.","translation":"统一的行为准则有助于组织培养诚信文化，前提是它得到一贯的执行。"}]},"conquer":{"examples":[{"sentence":"Although the initial obstacles seemed daunting, she managed to conquer her fear of public speaking through consistent practice.","translation":"尽管最初的障碍令人生畏，她通过持续练习克服了对公开演讲的恐惧。"},{"sentence":"Because the team adopted a collaborative approach, they were able to conquer the complex project ahead of schedule.","translation":"由于团队采用了协作方法，他们得以提前完成这个复杂的项目。"},{"sentence":"While many explorers attempted to conquer the uncharted territory, only those with meticulous preparation succeeded.","translation":"虽然许多探险家试图征服这片未知领域，但只有那些精心准备的人成功了。"},{"sentence":"If we fail to conquer our reliance on fossil fuels, the environmental consequences will become irreversible.","translation":"如果我们不能克服对化石燃料的依赖，环境后果将变得不可逆转。"},{"sentence":"Through rigorous training and mental discipline, athletes can conquer physical limitations that once seemed insurmountable.","translation":"通过严格的训练和心理自律，运动员可以克服曾经看似无法逾越的身体极限。"}]},"likely":{"examples":[{"sentence":"Because the new policy addresses key concerns, it is likely to gain widespread support among the population.","translation":"由于新政策解决了关键问题，它很可能获得民众的广泛支持。"},{"sentence":"Although the experiment yielded promising results, the findings are likely to be challenged by peer review.","translation":"尽管实验取得了有希望的结果，但这些发现很可能受到同行评审的质疑。"},{"sentence":"If the government invests in renewable energy, the country is likely to achieve carbon neutrality by 2050.","translation":"如果政府投资可再生能源，该国很可能在2050年前实现碳中和。"},{"sentence":"Students who participate in extracurricular activities are more likely to develop leadership skills, which benefit their future careers.","translation":"参加课外活动的学生更有可能培养领导能力，这对他们未来的职业有益。"},{"sentence":"While the economic forecast remains uncertain, a moderate recovery is likely to occur in the next quarter.","translation":"尽管经济预测仍不确定，但下个季度很可能出现温和复苏。"}]},"nobody":{"examples":[{"sentence":"Although the company advertised the position widely, nobody with the required expertise applied for the job.","translation":"尽管公司广泛宣传了这个职位，但没有人具备所需的专业知识来申请这份工作。"},{"sentence":"Because the evidence was inconclusive, nobody could determine the exact cause of the system failure.","translation":"由于证据不确凿，没有人能确定系统故障的确切原因。"},{"sentence":"When the new regulation was implemented, nobody anticipated the widespread disruption it would cause.","translation":"当新规定实施时，没有人预料到它会引发广泛的混乱。"},{"sentence":"Despite the team's thorough investigation, nobody was able to identify the source of the data breach.","translation":"尽管团队进行了彻底调查，但没有人能够确定数据泄露的来源。"},{"sentence":"In a society that values conformity, nobody dares to challenge the prevailing norms without facing criticism.","translation":"在一个重视一致性的社会中，没有人敢于挑战主流规范而不面临批评。"}]},"verse":{"examples":[{"sentence":"Although modern free verse often abandons traditional rhyme schemes, it still employs vivid imagery to convey complex emotions.","translation":"尽管现代自由诗常常摒弃传统的押韵格式，但它仍然运用生动的意象来传达复杂的情感。"},{"sentence":"Because classical Chinese verse is rich in allusions, readers must be familiar with historical contexts to fully appreciate its depth.","translation":"由于中国古典诗歌富含典故，读者必须熟悉历史背景才能充分领略其深度。"},{"sentence":"The poet's use of blank verse, which mimics natural speech patterns, allowed for a more intimate and conversational tone.","translation":"诗人使用无韵诗，模仿自然的语言模式，营造出更亲切、更对话式的语气。"},{"sentence":"While memorizing verse can enhance cognitive abilities, its primary value lies in fostering an appreciation for linguistic beauty.","translation":"虽然背诵诗歌可以增强认知能力，但其主要价值在于培养对语言之美的欣赏。"},{"sentence":"Epic verse, which often recounts the heroic deeds of a culture, serves as a vital link between generations and preserves collective memory.","translation":"史诗常常叙述一个文化的英雄事迹，是连接世代、保存集体记忆的重要纽带。"}]},"cheer":{"examples":[{"sentence":"Although the team faced a series of defeats, the coach's unwavering optimism brought cheer to the players and renewed their determination.","translation":"尽管球队遭遇了一连串的失败，教练坚定不移的乐观精神给队员们带来了振奋，并重新点燃了他们的决心。"},{"sentence":"The charity event spread cheer throughout the community, because it provided essential support to families in need during the holiday season.","translation":"慈善活动在整个社区传播了欢乐，因为它在节日期间为有需要的家庭提供了必要的支持。"},{"sentence":"When the long-awaited rain finally arrived, the farmers' faces were filled with cheer, which reflected their relief after months of drought.","translation":"当期盼已久的雨水终于降临时，农民们的脸上洋溢着愉快，这反映了他们数月干旱后的宽慰。"},{"sentence":"The festive decorations and lively music created an atmosphere of cheer, thereby attracting more visitors to the annual cultural fair.","translation":"节日的装饰和欢快的音乐营造了一种欢乐的氛围，从而吸引了更多游客参加年度文化博览会。"},{"sentence":"Despite the challenging circumstances, the volunteers managed to bring cheer to the elderly residents through their weekly visits and heartfelt conversations.","translation":"尽管环境艰难，志愿者们通过每周的探访和真诚的交谈，设法给老年居民带来了愉快。"}]},"loosen":{"examples":[{"sentence":"To ensure a smooth recovery, the physical therapist recommended exercises that gradually loosen the stiff joints without causing additional pain.","translation":"为了确保顺利康复，物理治疗师推荐了一些能逐渐放松僵硬关节而不会引起额外疼痛的练习。"},{"sentence":"Because the strict regulations hindered innovation, the government decided to loosen the rules, which allowed startups to experiment with new technologies.","translation":"由于严格的法规阻碍了创新，政府决定放松规定，这使得初创公司能够试验新技术。"},{"sentence":"When the negotiations reached a deadlock, the mediator suggested a break to loosen the tension, thereby creating a more constructive atmosphere.","translation":"当谈判陷入僵局时，调解员建议休息一下以放松紧张情绪，从而营造了更具建设性的氛围。"},{"sentence":"Although the company traditionally maintained a rigid hierarchy, the new CEO sought to loosen the structure, which encouraged more open communication.","translation":"尽管公司传统上保持着严格的等级制度，新任首席执行官试图放松这一结构，这鼓励了更开放的沟通。"},{"sentence":"The central bank's decision to loosen monetary policy was aimed at stimulating economic growth, rather than merely controlling inflation.","translation":"中央银行放松货币政策的决定旨在刺激经济增长，而不仅仅是控制通货膨胀。"}]},"alphabet":{"examples":[{"sentence":"Although the English alphabet consists of only 26 letters, it can represent a vast array of sounds through various combinations, which makes it remarkably versatile.","translation":"尽管英语字母表仅由26个字母组成，但它能通过各种组合表示大量的声音，这使其非常灵活。"},{"sentence":"Learning the alphabet is a critical milestone in early childhood education, because it lays the foundation for reading and writing skills that are essential for academic success.","translation":"学习字母表是幼儿教育中的一个关键里程碑，因为它为阅读和写作技能奠定了基础，这些技能对学业成功至关重要。"},{"sentence":"The development of the phonetic alphabet by the Phoenicians greatly influenced later writing systems, thereby facilitating trade and cultural exchange across the Mediterranean.","translation":"腓尼基人发明的音标字母极大地影响了后来的书写系统，从而促进了地中海地区的贸易和文化交流。"},{"sentence":"When linguists study ancient inscriptions, they often begin by identifying the alphabet used, which helps them decipher the language and understand the civilization.","translation":"当语言学家研究古代铭文时，他们通常从识别所使用的字母表开始，这有助于他们破译语言并理解该文明。"},{"sentence":"In computer programming, sorting strings alphabetically relies on the order of characters in the alphabet, which ensures consistent and predictable data organization.","translation":"在计算机编程中，按字母顺序对字符串进行排序依赖于字母表中字符的顺序，这确保了数据组织的一致性和可预测性。"}]},"dig":{"examples":[{"sentence":"Although the ground was frozen, the workers had to dig a trench to repair the broken water pipe.","translation":"尽管地面结冰了，工人们还是得挖一条沟来修理破裂的水管。"},{"sentence":"To ensure the stability of the building, engineers must dig deep foundations that reach the bedrock.","translation":"为了确保建筑的稳定性，工程师必须挖掘深达基岩的地基。"},{"sentence":"Archaeologists dig carefully at the site, using brushes rather than shovels to avoid damaging artifacts.","translation":"考古学家在现场小心挖掘，使用刷子而不是铲子，以避免损坏文物。"},{"sentence":"Because the soil was contaminated, the team had to dig out and replace several tons of earth.","translation":"由于土壤受到污染，团队不得不挖出并更换数吨泥土。"},{"sentence":"When planting trees, it is essential to dig a hole that is twice as wide as the root ball.","translation":"种树时，挖一个比根团宽一倍的坑是至关重要的。"}]},"tonight":{"examples":[{"sentence":"Because the deadline is tomorrow, the team will work late tonight to finalize the report.","translation":"由于截止日期是明天，团队今晚将加班以完成报告。"},{"sentence":"The professor will deliver a lecture tonight that explores the ethical implications of artificial intelligence.","translation":"教授今晚将发表一场演讲，探讨人工智能的伦理影响。"},{"sentence":"If the weather remains clear, the observatory will open tonight for a public stargazing event.","translation":"如果天气保持晴朗，天文台今晚将向公众开放观星活动。"},{"sentence":"Although the conference begins tomorrow, a welcome reception will be held tonight for early arrivals.","translation":"虽然会议明天才开始，但今晚将为提前到达者举行欢迎招待会。"},{"sentence":"The negotiators hope to reach an agreement tonight, thereby avoiding further delays in the peace process.","translation":"谈判代表希望今晚达成协议，从而避免和平进程的进一步拖延。"}]},"shallow":{"examples":[{"sentence":"A shallow understanding of historical context often leads policymakers to repeat past mistakes rather than learn from them.","translation":"对历史背景的肤浅理解常常导致决策者重蹈覆辙，而非从中吸取教训。"},{"sentence":"Because the river becomes dangerously shallow during the dry season, cargo vessels must reduce their loads to avoid running aground.","translation":"由于这条河在旱季会变得危险地浅，货船必须减少载重以避免搁浅。"},{"sentence":"Although social media can foster connection, its emphasis on brief, shallow interactions may undermine the development of deep, meaningful relationships.","translation":"尽管社交媒体可以促进联系，但它对简短、肤浅互动的强调可能会损害深厚、有意义关系的发展。"},{"sentence":"Critics argue that the report offers only a shallow analysis of the economic trends, ignoring the underlying structural factors that drive long-term growth.","translation":"批评者认为，该报告仅对经济趋势进行了肤浅的分析，忽视了驱动长期增长的深层结构性因素。"},{"sentence":"Marine biologists discovered that the shallow coastal waters, rich in nutrients, serve as vital nurseries for numerous fish species.","translation":"海洋生物学家发现，营养丰富的浅海沿岸水域是众多鱼类的重要育苗场。"}]},"frequent":{"examples":[{"sentence":"Although frequent team meetings can disrupt individual workflow, they are essential for maintaining alignment on complex projects.","translation":"尽管频繁的团队会议可能打断个人工作流程，但它们对于在复杂项目中保持一致至关重要。"},{"sentence":"Because frequent data backups minimize the risk of permanent loss, companies invest heavily in automated backup systems.","translation":"由于频繁的数据备份能最大限度地降低永久丢失的风险，公司大力投资于自动化备份系统。"},{"sentence":"Frequent exposure to high levels of noise, which is common in urban environments, has been linked to increased stress and cardiovascular problems.","translation":"频繁暴露于高水平噪音中，这在城市环境中很常见，已被证实与压力增加和心血管问题有关。"},{"sentence":"While frequent international travel broadens one's perspective, it can also lead to cultural fatigue and a sense of rootlessness.","translation":"虽然频繁的国际旅行能拓宽视野，但它也可能导致文化疲劳和无根感。"},{"sentence":"Frequent policy changes in the education sector often create uncertainty, thereby hindering long-term planning by schools and teachers.","translation":"教育部门频繁的政策变动常常造成不确定性，从而阻碍学校和教师的长期规划。"}]},"desolate":{"examples":[{"sentence":"The desolate landscape of the former industrial zone, which was abandoned decades ago, now serves as a stark reminder of economic decline.","translation":"几十年前被废弃的前工业区的荒凉景观，如今成为经济衰退的鲜明提醒。"},{"sentence":"Because the remote village became desolate after the earthquake, the government implemented a relocation program to ensure the safety of its residents.","translation":"由于地震后这个偏远村庄变得荒凉，政府实施了搬迁计划以确保居民的安全。"},{"sentence":"Although the desert appears desolate, it supports a unique ecosystem that has adapted to extreme conditions over millennia.","translation":"尽管沙漠看似荒凉，但它支撑着一个独特的生态系统，该系统数千年来已适应了极端条件。"},{"sentence":"The once-bustling market square lay desolate, with empty stalls and scattered debris that testified to years of neglect.","translation":"曾经熙熙攘攘的市场广场一片荒凉，空荡荡的摊位和散落的碎片见证了多年的疏于管理。"},{"sentence":"When the mining company departed, it left behind a desolate terrain scarred by open pits, which posed environmental hazards for decades.","translation":"当矿业公司离开时，它留下了一片被露天矿坑破坏的荒凉地带，这在几十年里都构成了环境危害。"}]},"him":{"examples":[{"sentence":"Although the professor initially doubted his theory, she later acknowledged that she had underestimated him.","translation":"尽管这位教授最初怀疑他的理论，但她后来承认自己低估了他。"},{"sentence":"The manager assigned the most challenging project to him because she believed in his ability to deliver results.","translation":"经理把最具挑战性的项目交给了他，因为她相信他有能力交付成果。"},{"sentence":"When the community faced a crisis, many residents turned to him for guidance and support.","translation":"当社区面临危机时，许多居民向他寻求指导和支持。"},{"sentence":"His colleagues respected him not only for his expertise but also for his willingness to mentor younger staff.","translation":"他的同事们尊重他，不仅因为他的专业知识，还因为他愿意指导年轻员工。"},{"sentence":"The scholarship enabled him to pursue advanced studies abroad, which profoundly shaped his career.","translation":"这项奖学金使他能够出国深造，这深刻地塑造了他的职业生涯。"}]},"soup":{"examples":[{"sentence":"Although the soup appeared plain, its rich flavor came from a slow-simmered broth that required hours of preparation.","translation":"尽管这汤看起来很普通，但其浓郁的风味来自慢炖的高汤，需要数小时的准备。"},{"sentence":"The nutritionist recommended consuming vegetable soup before meals, which helps control appetite and promotes healthier eating habits.","translation":"营养学家建议餐前喝蔬菜汤，这有助于控制食欲并促进更健康的饮食习惯。"},{"sentence":"Because the soup kitchen relies on donations, the community organized a fundraiser to ensure it could continue serving the homeless.","translation":"由于施粥所依赖捐赠，社区组织了一场筹款活动，以确保它能继续为无家可归者服务。"},{"sentence":"The chef demonstrated how to make a clear soup that retains the natural essence of the ingredients, thereby enhancing the dining experience.","translation":"厨师演示了如何制作一道保留食材天然精华的清汤，从而提升了用餐体验。"},{"sentence":"In many cultures, sharing a pot of soup symbolizes hospitality and strengthens social bonds, which is why it is often served at gatherings.","translation":"在许多文化中，分享一锅汤象征着好客并加强了社会纽带，这就是为什么它常在聚会上供应。"}]},"contradict":{"examples":[{"sentence":"The latest experimental results contradict the long-held assumption, which necessitates a fundamental revision of the theoretical framework.","translation":"最新的实验结果与长期以来的假设相矛盾，这需要对理论框架进行根本性的修订。"},{"sentence":"Although the two witnesses' accounts appear to contradict each other, they may simply reflect different perspectives on the same event.","translation":"尽管两位证人的叙述似乎相互矛盾，但它们可能只是反映了对同一事件的不同视角。"},{"sentence":"His public statements often contradict his private actions, thereby eroding the trust that his constituents have placed in him.","translation":"他的公开声明常常与他的私人行为相矛盾，从而削弱了选民对他的信任。"},{"sentence":"When new data contradict established theories, scientists must carefully reassess their hypotheses rather than dismiss the evidence outright.","translation":"当新数据与既定理论相矛盾时，科学家必须仔细重新评估他们的假设，而不是直接否定证据。"},{"sentence":"The findings of the investigation contradict the initial report, which raises serious questions about the integrity of the original inquiry.","translation":"调查结果与最初的报告相矛盾，这引发了人们对原始调查完整性的严重质疑。"}]},"luxury":{"examples":[{"sentence":"Although owning a private jet is often seen as the ultimate luxury, it also entails significant environmental costs.","translation":"尽管拥有私人飞机常被视为终极奢侈，但它也带来了巨大的环境代价。"},{"sentence":"Because affordable housing is scarce in many cities, having a spare bedroom has become an unattainable luxury for most young professionals.","translation":"由于许多城市经济适用房稀缺，拥有一间备用卧室对大多数年轻专业人士来说已成为一种无法企及的奢侈。"},{"sentence":"While some people consider organic food a needless luxury, others argue that it is a necessary investment in long-term health.","translation":"尽管有些人认为有机食品是不必要的奢侈，但另一些人则主张这是对长期健康的必要投资。"},{"sentence":"The luxury of free time, which previous generations took for granted, is increasingly rare in today's hyper-connected society.","translation":"前几代人视为理所当然的空闲时间这种奢侈，在当今高度互联的社会中日益罕见。"},{"sentence":"If we continue to treat water as an infinite luxury rather than a finite resource, severe shortages will become inevitable.","translation":"如果我们继续将水视为无限的奢侈而非有限的资源，严重的短缺将不可避免。"}]},"task":{"examples":[{"sentence":"Because the task of drafting a comprehensive climate policy requires interdisciplinary expertise, governments must consult scientists and economists alike.","translation":"由于起草全面的气候政策这一任务需要跨学科专业知识，政府必须同时咨询科学家和经济学家。"},{"sentence":"Although the task of learning a new language can be daunting, consistent practice over time yields remarkable progress.","translation":"尽管学习一门新语言的任务可能令人生畏，但长期坚持练习会带来显著进步。"},{"sentence":"The task of reducing income inequality, which has plagued many nations for decades, demands bold fiscal reforms.","translation":"减少收入不平等这一困扰许多国家数十年的任务，需要大胆的财政改革。"},{"sentence":"When a team is assigned a complex task, clear communication becomes essential to ensure that all members understand their roles.","translation":"当一个团队被分配一项复杂任务时，清晰的沟通对于确保所有成员理解自己的角色至关重要。"},{"sentence":"Rather than viewing the task of writing a thesis as a burden, students should see it as an opportunity to contribute original knowledge.","translation":"与其将撰写论文的任务视为负担，学生应将其看作贡献原创知识的机会。"}]},"unity":{"examples":[{"sentence":"Although the committee members held diverse opinions, they achieved unity through a shared commitment to the organization's mission.","translation":"尽管委员会成员持有不同意见，但他们通过对组织使命的共同承诺实现了团结。"},{"sentence":"The unity of the team was strengthened when they overcame a series of unexpected challenges that threatened the project's deadline.","translation":"当团队克服了一系列威胁项目截止日期的意外挑战时，他们的团结得到了加强。"},{"sentence":"Because national unity is essential for economic development, governments often promote policies that foster social cohesion.","translation":"由于国家团结对经济发展至关重要，政府经常推行促进社会凝聚力的政策。"},{"sentence":"The success of the peace negotiations depended on the unity of the participating nations, which allowed them to present a coherent strategy.","translation":"和平谈判的成功取决于参与国的团结，这使他们能够提出连贯的战略。"},{"sentence":"In times of crisis, the unity of a community can be a decisive factor in ensuring that recovery efforts are effective and inclusive.","translation":"在危机时期，社区的团结可能是确保恢复工作有效且包容的决定性因素。"}]},"rather":{"examples":[{"sentence":"Rather than focusing solely on economic growth, policymakers should consider environmental sustainability to ensure long-term prosperity.","translation":"政策制定者不应只关注经济增长，而应考虑环境可持续性，以确保长期繁荣。"},{"sentence":"The new software did not simplify the process; rather, it introduced complexities that required additional training for the staff.","translation":"新软件并没有简化流程；相反，它带来了复杂性，需要对员工进行额外培训。"},{"sentence":"Many consumers would rather purchase eco-friendly products, even if they are more expensive, because they value environmental protection.","translation":"许多消费者宁愿购买环保产品，即使它们更贵，因为他们重视环境保护。"},{"sentence":"The experiment produced rather surprising results, which challenged the established theory and opened new avenues for research.","translation":"实验产生了相当令人惊讶的结果，这挑战了既定理论，并为研究开辟了新途径。"},{"sentence":"While some people prefer traditional classroom learning, others would rather engage in online courses that offer greater flexibility.","translation":"虽然有些人喜欢传统的课堂学习，但另一些人宁愿参加提供更大灵活性的在线课程。"}]},"steel":{"examples":[{"sentence":"Because steel is both durable and recyclable, it remains a fundamental material in sustainable construction projects worldwide.","translation":"由于钢材既耐用又可回收，它仍然是全球可持续建筑项目中的基础材料。"},{"sentence":"The automotive industry has increasingly adopted high-strength steel to reduce vehicle weight, thereby improving fuel efficiency.","translation":"汽车行业越来越多地采用高强度钢材来减轻车辆重量，从而提高燃油效率。"},{"sentence":"Although steel production is energy-intensive, technological innovations have significantly reduced its carbon footprint in recent years.","translation":"尽管钢铁生产是能源密集型的，但近年来技术创新已显著减少了其碳足迹。"},{"sentence":"The bridge's design relied on a steel framework, which provided the necessary support to withstand strong winds and heavy traffic.","translation":"这座桥的设计依赖于钢框架，它提供了必要的支撑，以承受强风和繁忙的交通。"},{"sentence":"When global demand for steel declined, many manufacturers diversified their products to maintain profitability during the economic downturn.","translation":"当全球钢材需求下降时，许多制造商通过多样化产品来在经济低迷时期保持盈利能力。"}]},"surge":{"examples":[{"sentence":"Although the surge in housing prices has made homeownership difficult for many, it has also increased the wealth of existing homeowners.","translation":"尽管房价的飙升使许多人难以拥有住房，但它也增加了现有房主的财富。"},{"sentence":"A surge in cyberattacks has prompted companies to invest heavily in cybersecurity, thereby reducing the risk of data breaches.","translation":"网络攻击的激增促使公司大力投资网络安全，从而降低了数据泄露的风险。"},{"sentence":"Because the surge in demand for electric vehicles is driven by environmental concerns, governments are offering incentives to accelerate adoption.","translation":"由于对电动汽车需求的激增是由环境问题驱动的，政府正在提供激励措施以加速普及。"},{"sentence":"The surge of misinformation on social media platforms has led to widespread confusion, which undermines public trust in institutions.","translation":"社交媒体平台上错误信息的激增导致了广泛的混乱，这削弱了公众对机构的信任。"},{"sentence":"When a surge in unemployment occurs during a recession, policymakers often respond with stimulus packages to boost the economy.","translation":"当经济衰退期间失业率激增时，政策制定者通常会以刺激计划来提振经济。"}]},"attitude":{"examples":[{"sentence":"A positive attitude toward failure, which views setbacks as learning opportunities, is essential for long-term success in any field.","translation":"对失败的积极态度，即将挫折视为学习机会，对于任何领域的长期成功都至关重要。"},{"sentence":"Although a competitive attitude can drive innovation, it may also create a toxic work environment if not balanced with collaboration.","translation":"尽管竞争态度可以推动创新，但如果不与协作相平衡，也可能造成有害的工作环境。"},{"sentence":"The government's attitude toward foreign investment has shifted dramatically, thereby attracting more multinational corporations to the region.","translation":"政府对外国投资的态度发生了巨大转变，从而吸引了更多跨国公司来到该地区。"},{"sentence":"Because a teacher's attitude toward students can influence their motivation, educators must cultivate an encouraging and supportive demeanor.","translation":"由于教师对学生的态度会影响他们的积极性，教育者必须培养鼓励和支持的风范。"},{"sentence":"Adopting a proactive attitude when dealing with conflicts, rather than avoiding them, often leads to more sustainable resolutions.","translation":"在处理冲突时采取积极主动的态度，而不是回避，通常会带来更可持续的解决方案。"}]},"earthquake":{"examples":[{"sentence":"Although modern engineering has greatly improved structural resilience, a powerful earthquake can still devastate unprepared communities.","translation":"尽管现代工程大大提高了结构的韧性，但一场强烈的地震仍能摧毁没有准备的社区。"},{"sentence":"Because tectonic stress accumulates over decades, the region faces a high probability of a major earthquake within the next thirty years.","translation":"由于构造应力积累了几十年，该地区在未来三十年内发生大地震的可能性很高。"},{"sentence":"When an earthquake strikes beneath the ocean floor, it often triggers a tsunami that travels across entire ocean basins.","translation":"当地震发生在海底时，通常会引发海啸，横跨整个海洋盆地。"},{"sentence":"The government implemented strict building codes after the 2008 earthquake, thereby reducing casualties in subsequent seismic events.","translation":"政府在2008年地震后实施了严格的建筑规范，从而减少了后续地震事件中的伤亡。"},{"sentence":"While scientists cannot predict the exact moment of an earthquake, they can identify high-risk zones through geological surveys.","translation":"虽然科学家无法预测地震的确切时刻，但他们可以通过地质调查确定高风险区域。"}]},"tin":{"examples":[{"sentence":"Although tin is often associated with cans, its most critical application lies in soldering electronic components onto circuit boards.","translation":"尽管锡常与罐头联系在一起，但其最关键的用途在于将电子元件焊接到电路板上。"},{"sentence":"Because pure tin can transform into a brittle nonmetallic form at low temperatures, alloying it with other metals prevents this structural failure.","translation":"由于纯锡在低温下会转变为脆性的非金属形态，将其与其他金属制成合金可防止这种结构失效。"},{"sentence":"The ancient bronze alloy, which combined copper with tin, revolutionized toolmaking and warfare during the Bronze Age.","translation":"古代青铜合金将铜与锡结合，在青铜时代彻底改变了工具制造和战争方式。"},{"sentence":"When tin is electroplated onto steel, it creates a corrosion-resistant surface that is safe for food contact and easy to recycle.","translation":"当锡被电镀到钢上时，会形成耐腐蚀的表面，既安全接触食品又易于回收。"},{"sentence":"Global tin reserves are concentrated in a few countries, which makes the supply chain vulnerable to geopolitical disruptions.","translation":"全球锡储量集中在少数几个国家，这使得供应链容易受到地缘政治干扰的影响。"}]},"flood":{"examples":[{"sentence":"Although levees provide some protection, a catastrophic flood can still breach them and inundate entire neighborhoods.","translation":"尽管堤坝提供了一定的保护，但灾难性的洪水仍可能将其冲垮并淹没整个街区。"},{"sentence":"Because climate change intensifies the hydrological cycle, many regions now experience more frequent and severe flood events.","translation":"由于气候变化加剧了水文循环，许多地区现在经历了更频繁和更严重的洪水事件。"},{"sentence":"When a river flood coincides with a high tide, the resulting storm surge can push water far inland, causing unprecedented damage.","translation":"当河流洪水与高潮同时发生时，由此产生的风暴潮会将水推向内陆深处，造成前所未有的破坏。"},{"sentence":"The government invested in a sophisticated flood forecasting system, which uses real-time data to issue early warnings to vulnerable communities.","translation":"政府投资了一套先进的洪水预报系统，该系统利用实时数据向脆弱社区发布预警。"},{"sentence":"Rather than relying solely on structural defenses, the city adopted a flood management strategy that includes wetland restoration and floodplain zoning.","translation":"该城市没有仅仅依赖结构性防御，而是采取了一种洪水管理策略，包括湿地恢复和洪泛区分区。"}]},"handy":{"examples":[{"sentence":"Although the campus is large, having a folding bicycle is a handy solution that allows students to move between classes quickly.","translation":"尽管校园很大，拥有一辆折叠自行车是一个便利的解决方案，能让学生快速地在课间移动。"},{"sentence":"Because the laboratory is equipped with a handy digital microscope, researchers can capture and share high-resolution images without complex setups.","translation":"由于实验室配备了便利的数码显微镜，研究人员无需复杂设置即可捕获并分享高分辨率图像。"},{"sentence":"When conducting fieldwork in remote areas, a multi-tool proves handy, as it combines several essential functions into one compact device.","translation":"在偏远地区进行实地考察时，多功能工具显得非常便利，因为它将多种基本功能集于一个紧凑的装置。"},{"sentence":"The new citation plugin is particularly handy for graduate students, which automatically formats references according to the required style guide.","translation":"新的引文插件对研究生特别方便，它能根据要求的格式指南自动格式化参考文献。"},{"sentence":"Keeping a small notebook handy during seminars is a simple yet effective strategy to capture spontaneous ideas that might otherwise be forgotten.","translation":"在研讨会上随身携带一个小笔记本是一个简单而有效的策略，以捕捉那些否则可能被遗忘的即兴想法。"}]},"amplify":{"examples":[{"sentence":"To amplify the faint electrical signals from the sensor, the team used a low-noise amplifier that minimized interference.","translation":"为了放大传感器发出的微弱电信号，团队使用了一种低噪声放大器，以尽量减少干扰。"},{"sentence":"The professor decided to amplify the key points of her lecture with real-world examples, which made the material more accessible to students.","translation":"教授决定用现实世界的例子来详细阐述她讲座的要点，这使学生更容易理解材料。"},{"sentence":"While social media can amplify public awareness of social issues, it can also spread misinformation if not properly monitored.","translation":"虽然社交媒体可以放大公众对社会问题的认识，但如果监管不当，它也会传播错误信息。"},{"sentence":"The new marketing strategy was designed to amplify the brand's visibility through targeted online campaigns, thereby attracting a larger customer base.","translation":"新的营销策略旨在通过有针对性的在线活动来扩大品牌知名度，从而吸引更大的客户群。"},{"sentence":"When presenting the data, the researcher chose to amplify the most significant trends rather than covering every detail, which helped the audience focus on the main findings.","translation":"在展示数据时，研究人员选择详细说明最重要的趋势，而不是涵盖每个细节，这有助于听众关注主要发现。"}]},"tomb":{"examples":[{"sentence":"Archaeologists were astonished when they entered the ancient tomb, which contained a wealth of artifacts that shed light on early trade routes.","translation":"考古学家进入古墓时感到惊讶，里面藏有大量文物，揭示了早期贸易路线。"},{"sentence":"The tomb of the unknown soldier, which is guarded day and night, symbolizes the nation's gratitude for those who sacrificed their lives.","translation":"日夜守卫的无名战士墓象征着国家对那些牺牲生命的人的感激之情。"},{"sentence":"Because the tomb was constructed with advanced engineering techniques, it remained intact despite centuries of earthquakes.","translation":"由于这座陵墓采用了先进的工程技术建造，尽管经历了几个世纪的地震，它仍然完好无损。"},{"sentence":"The inscriptions on the tomb provided historians with crucial evidence about the political structure of the dynasty, which had been previously misunderstood.","translation":"墓碑上的铭文为历史学家提供了关于该朝代政治结构的关键证据，此前这一直被误解。"},{"sentence":"Although the tomb had been looted in antiquity, the remaining fragments of pottery allowed researchers to reconstruct the burial rituals of that era.","translation":"尽管这座墓穴在古代被盗过，但剩余的陶器碎片使研究人员得以重建那个时代的埋葬仪式。"}]},"longitude":{"examples":[{"sentence":"Although early sailors struggled to determine longitude accurately, the invention of the marine chronometer revolutionized navigation.","translation":"尽管早期水手难以准确测定经度，但航海天文钟的发明彻底改变了导航。"},{"sentence":"The prime meridian, which passes through Greenwich, serves as the zero-degree reference line for measuring longitude.","translation":"穿过格林威治的本初子午线是测量经度的零度参考线。"},{"sentence":"Because the Earth rotates 15 degrees of longitude per hour, time zones are based on longitudinal divisions.","translation":"由于地球每小时自转15度经度，时区是基于经度划分的。"},{"sentence":"While latitude determines climate zones, longitude affects local time and communication schedules across the globe.","translation":"虽然纬度决定气候带，但经度影响全球各地的地方时间和通信安排。"},{"sentence":"The explorer recorded the island's longitude in his logbook to ensure future voyagers could locate it precisely.","translation":"探险家将岛屿的经度记录在航海日志中，以确保未来的航海者能够精确定位它。"}]},"lie":{"examples":[{"sentence":"When a public figure tells a deliberate lie to protect their reputation, the long-term damage to their credibility often outweighs any short-term benefit.","translation":"当公众人物为维护声誉而故意说谎时，对其信誉的长期损害往往超过任何短期利益。"},{"sentence":"Although the witness initially believed her testimony was harmless, the court later proved that it was a lie which had obstructed the course of justice.","translation":"尽管证人最初认为她的证词无害，但法庭后来证明那是一个妨碍司法公正的谎言。"},{"sentence":"A lie repeated often enough can begin to feel like truth, which is why critical thinking must be cultivated from an early age.","translation":"一个被重复多次的谎言会开始让人感觉像真理，这就是为什么必须从小培养批判性思维。"},{"sentence":"The politician's claim that he had never met the lobbyist turned out to be a lie, leading to a formal investigation into his conduct.","translation":"那位政治家声称从未见过该说客，结果这是一个谎言，导致对其行为展开正式调查。"},{"sentence":"Because a single lie can unravel years of trust, professionals in fields such as journalism and law are held to exceptionally high standards of honesty.","translation":"因为一个谎言就可能瓦解多年建立的信任，新闻和法律等领域的专业人士被要求遵守极高的诚信标准。"}]},"circular":{"examples":[{"sentence":"The architect designed a circular courtyard that not only maximizes natural light but also encourages informal interaction among residents.","translation":"建筑师设计了一个圆形庭院，不仅最大限度地引入自然光，还鼓励居民之间的非正式交流。"},{"sentence":"Because the argument relies on a circular definition, it fails to provide any independent evidence for the claim it attempts to support.","translation":"由于该论证依赖于循环定义，它未能为其试图支持的论点提供任何独立的证据。"},{"sentence":"The committee adopted a circular seating arrangement to symbolize equality among members, thereby fostering more open and democratic discussions.","translation":"委员会采用了圆形座位安排，以象征成员之间的平等，从而促进更开放和民主的讨论。"},{"sentence":"In many traditional cultures, the circular shape represents unity and eternity, which explains its frequent use in ceremonial art and architecture.","translation":"在许多传统文化中，圆形代表团结和永恒，这解释了它在仪式艺术和建筑中的频繁使用。"},{"sentence":"The researcher pointed out that the economic model was based on circular reasoning, as it assumed the very outcome it was supposed to predict.","translation":"研究人员指出，该经济模型基于循环推理，因为它假设了它本应预测的结果。"}]},"one":{"examples":[{"sentence":"Although one might assume that talent alone guarantees success, sustained effort and resilience often prove more decisive in the long run.","translation":"尽管人们可能认为仅凭天赋就能保证成功，但长期来看，持续的努力和韧性往往更具决定性。"},{"sentence":"One effective strategy for improving public health is to promote preventive care, which reduces the burden on hospitals and enhances overall well-being.","translation":"改善公共卫生的一个有效策略是推广预防性护理，这能减轻医院负担并提升整体福祉。"},{"sentence":"Because one poorly designed policy can have far-reaching economic consequences, lawmakers must carefully evaluate potential impacts before implementation.","translation":"因为一项设计不当的政策可能产生深远的经济后果，立法者在实施前必须仔细评估潜在影响。"},{"sentence":"When one considers the rapid advancement of artificial intelligence, it becomes clear that ethical guidelines must evolve to address emerging challenges.","translation":"当人们考虑到人工智能的快速发展时，显然伦理准则必须演变以应对新出现的挑战。"},{"sentence":"One of the most significant benefits of studying abroad is the opportunity to develop intercultural competence, which is highly valued in today's globalized workforce.","translation":"出国留学最显著的好处之一是有机会培养跨文化能力，这在当今全球化的劳动力中备受重视。"}]},"plane":{"examples":[{"sentence":"Although the plane was delayed by heavy fog, the passengers remained calm and patient throughout the wait.","translation":"尽管飞机因大雾延误，乘客们在等待期间始终保持冷静和耐心。"},{"sentence":"The carpenter used a sharp tool to plane the rough board, which ensured a smooth surface for the furniture.","translation":"木匠用锋利的工具刨平粗糙的木板，从而确保家具表面光滑。"},{"sentence":"In mathematics, a plane is a flat surface that extends infinitely, which serves as a fundamental concept in geometry.","translation":"在数学中，平面是一个无限延伸的平坦表面，这是几何学中的一个基本概念。"},{"sentence":"Because the pilot skillfully navigated the plane through the storm, all passengers arrived safely at their destination.","translation":"由于飞行员熟练地驾驶飞机穿越暴风雨，所有乘客都安全抵达目的地。"},{"sentence":"The architect used a laser plane to ensure the floor was perfectly level, thereby avoiding structural issues later.","translation":"建筑师使用激光平面仪确保地板完全水平，从而避免日后出现结构问题。"}]},"photo":{"examples":[{"sentence":"Although the photo was taken decades ago, it still vividly captures the joy of that family reunion.","translation":"尽管这张照片是几十年前拍的，但它仍然生动地捕捉到了那次家庭团聚的欢乐。"},{"sentence":"The journalist submitted a compelling photo of the rescue operation, which later appeared on the front page.","translation":"记者提交了一张救援行动的引人注目的照片，这张照片后来登上了头版。"},{"sentence":"Because the original photo had faded, the archivist used digital restoration to preserve its historical details.","translation":"由于原始照片已经褪色，档案管理员使用数字修复来保存其历史细节。"},{"sentence":"A well-composed photo can convey complex emotions, whereas a poorly taken one may fail to engage viewers.","translation":"一张构图精良的照片可以传达复杂的情感，而一张拍得不好的照片可能无法吸引观众。"},{"sentence":"The museum displayed a rare photo of the scientist at work, which provided insight into her daily research routine.","translation":"博物馆展出了一张这位科学家工作的罕见照片，这让我们得以了解她的日常研究流程。"}]},"view":{"examples":[{"sentence":"From a policy perspective, the government's view that renewable energy subsidies should be gradually reduced has sparked considerable debate among economists.","translation":"从政策角度来看，政府认为可再生能源补贴应逐步减少的观点在经济学家中引发了大量争论。"},{"sentence":"Although many people hold the view that technology isolates individuals, it can actually foster meaningful connections when used thoughtfully.","translation":"尽管许多人认为科技使人孤立，但如果使用得当，它实际上可以促进有意义的联系。"},{"sentence":"The researcher's view, which is grounded in extensive empirical evidence, challenges the conventional assumption that economic growth always leads to greater happiness.","translation":"这位研究者的观点基于大量的实证证据，挑战了经济增长总能带来更大幸福这一传统假设。"},{"sentence":"In view of the mounting environmental pressures, urban planners are increasingly adopting designs that integrate green spaces into high-density areas.","translation":"鉴于日益加剧的环境压力，城市规划者越来越多地采用将绿地融入高密度区域的设计。"},{"sentence":"A panoramic view of the city from the hilltop not only reveals its architectural grandeur but also underscores the stark contrast between affluent and impoverished neighborhoods.","translation":"从山顶俯瞰城市的全景不仅展现了其建筑的宏伟，也凸显了富裕社区与贫困社区之间的鲜明对比。"}]},"farther":{"examples":[{"sentence":"Although the research station is located farther from the coast than originally planned, its proximity to deep-sea vents enables unique biological studies.","translation":"尽管研究站的位置比原计划离海岸更远，但它靠近深海热泉，使得独特的生物学研究成为可能。"},{"sentence":"Because the new highway bypasses the town, commuters must now drive farther to reach the city center, which has increased fuel consumption.","translation":"由于新高速公路绕过了小镇，通勤者现在必须开车更远才能到达市中心，这增加了燃油消耗。"},{"sentence":"When resources are depleted locally, fishing fleets venture farther into international waters, thereby raising concerns about overfishing and maritime disputes.","translation":"当本地资源枯竭时，渔船队会冒险进入更远的国际水域，从而引发对过度捕捞和海事争端的担忧。"},{"sentence":"The telescope can detect galaxies farther away than any previous instrument, which allows astronomers to study the early universe in unprecedented detail.","translation":"这台望远镜能探测到比以往任何仪器都更远的星系，这使得天文学家能够以前所未有的细节研究早期宇宙。"},{"sentence":"If the desert continues to expand, farmers will be compelled to relocate farther from their ancestral lands, a trend that threatens cultural heritage.","translation":"如果沙漠继续扩张，农民将被迫迁移到离祖传土地更远的地方，这一趋势威胁着文化遗产。"}]},"philosopher":{"examples":[{"sentence":"The philosopher Immanuel Kant argued that moral actions must be guided by universal principles, which he called the categorical imperative.","translation":"哲学家伊曼努尔·康德认为，道德行为必须由他称之为绝对命令的普遍原则指导。"},{"sentence":"Although she faced personal hardships, she remained a philosopher at heart, always seeking wisdom rather than material comfort.","translation":"尽管她面临个人困难，她内心仍是一位哲人，总是寻求智慧而非物质舒适。"},{"sentence":"The ancient philosopher Confucius emphasized the importance of social harmony, which continues to influence East Asian cultures today.","translation":"古代哲学家孔子强调社会和谐的重要性，这至今仍影响着东亚文化。"},{"sentence":"Because the philosopher questioned the very foundations of knowledge, his work sparked debates that reshaped modern epistemology.","translation":"因为这位哲学家质疑知识的基础，他的工作引发了重塑现代认识论的辩论。"},{"sentence":"A true philosopher does not merely accept conventional beliefs but critically examines them, thereby advancing human understanding.","translation":"真正的哲学家不仅仅接受传统信仰，而是批判性地审视它们，从而推动人类理解。"}]},"canteen":{"examples":[{"sentence":"Although the canteen is often crowded during lunchtime, it remains the most convenient place for students to grab a quick meal.","translation":"尽管食堂在午餐时间经常拥挤，但它仍然是学生们快速用餐最方便的地方。"},{"sentence":"The new canteen, which features a variety of international cuisines, has significantly improved employee satisfaction with workplace dining.","translation":"新食堂提供多种国际美食，显著提高了员工对工作餐的满意度。"},{"sentence":"Because the canteen uses locally sourced ingredients, it not only supports regional farmers but also reduces its carbon footprint.","translation":"由于食堂使用当地采购的食材，它不仅支持了地区农民，还减少了碳足迹。"},{"sentence":"When the company relocated to a larger office, the spacious canteen became a hub for informal meetings and creative brainstorming.","translation":"当公司搬迁到更大的办公室时，宽敞的食堂成为了非正式会议和创意头脑风暴的中心。"},{"sentence":"The hospital canteen operates 24 hours a day, thereby ensuring that night-shift staff always have access to hot meals.","translation":"医院食堂全天24小时营业，从而确保夜班工作人员总能吃到热饭。"}]},"mutual":{"examples":[{"sentence":"Although they come from different cultural backgrounds, their mutual passion for environmental protection has forged a strong bond between them.","translation":"尽管他们来自不同的文化背景，但对环境保护的共同热情在他们之间建立了牢固的纽带。"},{"sentence":"The treaty was signed because both nations recognized the mutual benefits of reducing trade barriers and fostering economic cooperation.","translation":"该条约得以签署，是因为两国都认识到减少贸易壁垒和促进经济合作的互惠互利。"},{"sentence":"In a successful team, mutual accountability ensures that every member takes responsibility for the project's outcome, rather than blaming others.","translation":"在一个成功的团队中，相互问责确保每个成员对项目结果负责，而不是指责他人。"},{"sentence":"The partnership, which is built on mutual respect and shared values, has enabled the two organizations to tackle complex social issues effectively.","translation":"这种建立在相互尊重和共同价值观基础上的伙伴关系，使两个组织能够有效应对复杂的社会问题。"},{"sentence":"When countries engage in cultural exchanges, they develop a deeper mutual understanding that can prevent conflicts and promote peace.","translation":"当各国进行文化交流时，他们会加深相互理解，从而预防冲突、促进和平。"}]},"land":{"examples":[{"sentence":"Because land is a scarce resource in urban areas, city planners must design high-density housing to accommodate growing populations.","translation":"由于土地在城市地区是一种稀缺资源，城市规划者必须设计高密度住房以容纳不断增长的人口。"},{"sentence":"The farmer decided to sell his land, which had been in the family for generations, to a developer who promised to preserve the orchard.","translation":"这位农民决定卖掉他家世代拥有的土地，卖给一个承诺保留果园的开发商。"},{"sentence":"Although the pilot faced strong crosswinds, she managed to land the aircraft smoothly, thereby avoiding any injuries to the passengers.","translation":"尽管飞行员遇到了强烈的侧风，她还是设法平稳着陆，从而避免了乘客受伤。"},{"sentence":"Investing in agricultural land can yield substantial returns, provided that investors understand the risks associated with climate change and market fluctuations.","translation":"投资农业用地可以产生可观的回报，前提是投资者了解与气候变化和市场波动相关的风险。"},{"sentence":"The government reclaimed the contaminated land and transformed it into a public park, thereby improving the quality of life for nearby residents.","translation":"政府回收了受污染的土地，并将其改造成公园，从而改善了附近居民的生活质量。"}]},"threshold":{"examples":[{"sentence":"Although the exact threshold for toxicity varies among individuals, prolonged exposure to the chemical poses a serious health risk.","translation":"尽管毒性的确切阈值因人而异，但长期接触这种化学物质会构成严重的健康风险。"},{"sentence":"Because the company's revenue fell below the contractual threshold, the partnership agreement was automatically terminated.","translation":"由于公司的收入低于合同规定的门槛，合作协议自动终止。"},{"sentence":"When a stimulus crosses the sensory threshold, it becomes consciously perceptible, which is a fundamental principle in psychology.","translation":"当刺激超过感觉阈值时，它就会变得有意识地可感知，这是心理学的一个基本原理。"},{"sentence":"The new law lowers the threshold for obtaining a business license, thereby encouraging more entrepreneurs to enter the market.","translation":"新法律降低了获得营业执照的门槛，从而鼓励更多企业家进入市场。"},{"sentence":"If global temperatures rise beyond a critical threshold, the resulting climate feedback loops could become irreversible.","translation":"如果全球气温超过临界阈值，由此产生的气候反馈循环可能变得不可逆转。"}]},"eliminate":{"examples":[{"sentence":"To eliminate errors in the final report, the team implemented a rigorous peer-review process that involved multiple rounds of editing.","translation":"为了消除最终报告中的错误，团队实施了一个严格的同行评审过程，涉及多轮编辑。"},{"sentence":"Although it is impossible to eliminate all risks, a comprehensive safety protocol can significantly reduce the likelihood of accidents.","translation":"尽管不可能消除所有风险，但全面的安全规程可以显著降低事故的可能性。"},{"sentence":"The new filtration system can eliminate contaminants from drinking water, which ensures that the supply meets health standards.","translation":"新的过滤系统可以消除饮用水中的污染物，从而确保供水符合健康标准。"},{"sentence":"Because the invasive species threatened the native ecosystem, authorities decided to eliminate it through a targeted eradication program.","translation":"由于入侵物种威胁到本地生态系统，当局决定通过有针对性的根除计划来消除它。"},{"sentence":"Automation can eliminate repetitive manual tasks, thereby allowing employees to focus on more creative and strategic work.","translation":"自动化可以消除重复的手工任务，从而使员工能够专注于更具创造性和战略性的工作。"}]},"millimeter":{"examples":[{"sentence":"Although the component was designed with millimeter precision, thermal expansion during operation caused a slight but critical misalignment.","translation":"尽管该部件以毫米级精度设计，但运行中的热膨胀导致了轻微却关键的错位。"},{"sentence":"Because the microscope can resolve details down to a fraction of a millimeter, it has become indispensable for cellular biology research.","translation":"由于该显微镜能分辨小至几分之一毫米的细节，它已成为细胞生物学研究不可或缺的工具。"},{"sentence":"The engineer insisted on measuring every weld to the nearest millimeter, which ensured the bridge met all safety standards.","translation":"工程师坚持将每条焊缝测量到最接近的毫米，这确保了桥梁符合所有安全标准。"},{"sentence":"While a millimeter may seem negligible in daily life, in semiconductor manufacturing such a deviation can render an entire chip defective.","translation":"虽然一毫米在日常生活中看似微不足道，但在半导体制造中，这样的偏差可能使整个芯片报废。"},{"sentence":"The artist carved the jade with millimeter accuracy, thereby transforming a rough stone into an exquisite sculpture that captivated collectors.","translation":"艺术家以毫米级的精度雕刻玉石，从而将一块粗糙的石头变成了一件令收藏家着迷的精美雕塑。"}]},"geometry":{"examples":[{"sentence":"Although geometry originated in ancient land measurement, it now underpins fields as diverse as robotics and cosmology.","translation":"尽管几何学起源于古代的土地测量，但它现在支撑着从机器人学到宇宙学等众多领域。"},{"sentence":"Engineers rely on the geometry of bridge trusses to distribute weight efficiently, thereby preventing structural failure.","translation":"工程师依靠桥梁桁架的几何形状来有效分配重量，从而防止结构失效。"},{"sentence":"Because the geometry of snowflakes reveals underlying molecular symmetry, scientists study them to understand crystal formation.","translation":"由于雪花的几何形状揭示了潜在的分子对称性，科学家研究它们以理解晶体形成。"},{"sentence":"The artist used projective geometry to create a mural that appears three-dimensional when viewed from a specific angle.","translation":"这位艺术家运用射影几何学创作了一幅壁画，从特定角度观看时呈现出三维效果。"},{"sentence":"While Euclidean geometry assumes flat surfaces, Riemannian geometry describes curved spaces, which is essential for modern physics.","translation":"欧几里得几何学假设平面，而黎曼几何学描述弯曲空间，这对现代物理学至关重要。"}]},"refute":{"examples":[{"sentence":"Although the initial findings seemed conclusive, the peer review process allowed experts to refute the methodology, which ultimately strengthened the research.","translation":"尽管初步发现似乎确凿，但同行评审过程使专家能够反驳该方法，这最终加强了研究。"},{"sentence":"To refute the widespread misconception, the scientist published a paper that presented clear evidence from multiple independent studies.","translation":"为了反驳这一普遍误解，这位科学家发表了一篇论文，其中提供了来自多项独立研究的明确证据。"},{"sentence":"Because the defendant could not refute the forensic evidence, the jury reached a unanimous guilty verdict within hours.","translation":"由于被告无法反驳法医证据，陪审团在数小时内达成了一致的有罪判决。"},{"sentence":"The professor encouraged students to refute established theories, thereby fostering a culture of critical thinking and intellectual growth.","translation":"教授鼓励学生反驳既有理论，从而培养批判性思维和智力成长的文化。"},{"sentence":"While it is tempting to refute opposing views with emotional appeals, a logical argument that relies on verifiable data is far more persuasive.","translation":"虽然用情感诉求来反驳对立观点很诱人，但依赖可验证数据的逻辑论证更具说服力。"}]},"drug":{"examples":[{"sentence":"Because the new drug targets a specific protein, it minimizes side effects while effectively treating the chronic condition.","translation":"由于这种新药针对一种特定蛋白质，它在有效治疗慢性病的同时最大限度地减少了副作用。"},{"sentence":"The government launched a campaign to combat drug abuse, which not only educates the public but also provides rehabilitation services.","translation":"政府发起了一场打击药物滥用的运动，该运动不仅教育公众，还提供康复服务。"},{"sentence":"Although the drug showed promise in early trials, further testing revealed unforeseen complications that delayed its approval.","translation":"尽管该药物在早期试验中显示出希望，但进一步测试揭示了不可预见的并发症，推迟了其批准。"},{"sentence":"To ensure patient safety, the regulatory agency requires that every new drug undergo rigorous clinical trials before it can be marketed.","translation":"为了确保患者安全，监管机构要求每种新药在上市前都必须经过严格的临床试验。"},{"sentence":"The rise of antibiotic-resistant bacteria has spurred research into novel drug therapies, which may revolutionize modern medicine.","translation":"抗生素耐药细菌的增加刺激了对新型药物疗法的研究，这可能会彻底改变现代医学。"}]},"scenery":{"examples":[{"sentence":"While the urban skyline has its own charm, the natural scenery of the countryside offers a tranquility that city life cannot replicate.","translation":"虽然城市天际线有其自身的魅力，但乡村的自然风景提供了一种城市生活无法复制的宁静。"},{"sentence":"The national park's diverse scenery, which ranges from lush forests to arid deserts, attracts researchers and tourists alike.","translation":"国家公园多样的风景，从茂密的森林到干旱的沙漠，吸引了研究人员和游客。"},{"sentence":"Because the scenery along the route is so stunning, the train journey is often considered a highlight of the trip rather than a mere transfer.","translation":"由于沿途的风景如此迷人，火车之旅通常被视为旅行的亮点，而不仅仅是中转。"},{"sentence":"The film's breathtaking scenery was not created digitally but captured on location, thereby lending authenticity to the narrative.","translation":"电影中令人叹为观止的风景不是数字制作的，而是在实地拍摄的，从而为叙事增添了真实性。"},{"sentence":"To preserve the pristine scenery for future generations, the local community implemented strict regulations that limit commercial development.","translation":"为了为后代保护原始风景，当地社区实施了严格的法规，限制商业开发。"}]},"policeman":{"examples":[{"sentence":"Because the policeman on duty noticed the suspicious vehicle, a major theft was prevented before it could occur.","translation":"由于值班警察注意到了可疑车辆，一起重大盗窃案在发生前就被阻止了。"},{"sentence":"Although the policeman was off duty, he intervened to stop the fight, thereby preventing serious injuries.","translation":"尽管那名警察不当班，他还是介入制止了斗殴，从而防止了严重伤害。"},{"sentence":"The policeman who patrols the park has built strong relationships with local families, which enhances community safety.","translation":"在公园巡逻的那名警察与当地家庭建立了牢固的关系，这增强了社区安全。"},{"sentence":"When a child goes missing, the first step is to contact a policeman, who can quickly initiate a search operation.","translation":"当儿童失踪时，第一步是联系警察，他们能迅速启动搜寻行动。"},{"sentence":"A policeman must remain calm under pressure, because his decisions can have life-or-death consequences in critical situations.","translation":"警察在压力下必须保持冷静，因为在危急情况下他的决定可能关乎生死。"}]},"resolute":{"examples":[{"sentence":"Although the team faced numerous setbacks, their resolute determination to succeed kept them working late into the night.","translation":"尽管团队面临无数挫折，他们坚定的成功决心使他们工作到深夜。"},{"sentence":"Because the leader was resolute in her decision to cut costs, the company survived the economic downturn while competitors failed.","translation":"由于领导在削减成本的决定上坚定不移，公司在经济衰退中幸存下来，而竞争对手却失败了。"},{"sentence":"A resolute commitment to environmental protection, which includes reducing carbon emissions, is essential for sustainable development.","translation":"对环境保护的坚定承诺，包括减少碳排放，对于可持续发展至关重要。"},{"sentence":"When faced with ethical dilemmas, a resolute individual chooses integrity over personal gain, thereby earning long-term trust.","translation":"面对道德困境时，坚定的人选择诚信而非个人利益，从而赢得长期信任。"},{"sentence":"To ensure the reform's success, the government must take resolute action against corruption, rather than merely issuing warnings.","translation":"为确保改革成功，政府必须对腐败采取坚决行动，而不仅仅是发出警告。"}]},"outskirts":{"examples":[{"sentence":"Although the outskirts lack the convenience of downtown amenities, they offer a tranquility that many families find invaluable.","translation":"尽管郊区缺乏市中心的便利设施，但它们提供了一种许多家庭认为无价的宁静。"},{"sentence":"Because the new industrial park was developed on the outskirts, it attracted businesses seeking lower operational costs.","translation":"由于新的工业园区建在郊区，它吸引了寻求更低运营成本的企业。"},{"sentence":"The outskirts of the city have seen rapid population growth, which has placed strain on existing infrastructure.","translation":"城市郊区经历了快速的人口增长，这给现有基础设施带来了压力。"},{"sentence":"While the outskirts provide more affordable housing, residents often face longer commutes to urban employment centers.","translation":"虽然郊区提供了更实惠的住房，但居民通常面临到城市就业中心更长的通勤时间。"},{"sentence":"The government plans to extend the metro line to the outskirts, thereby improving connectivity for suburban communities.","translation":"政府计划将地铁线路延伸至郊区，从而改善郊区社区的连通性。"}]},"rent":{"examples":[{"sentence":"Although the rent for this apartment is relatively high, its convenient location near the university makes it a popular choice among students.","translation":"尽管这间公寓的租金相对较高，但它靠近大学的便利位置使其成为学生们的热门选择。"},{"sentence":"Because the landlord failed to maintain the property, the tenants decided to withhold the rent until the necessary repairs were completed.","translation":"因为房东未能维护房产，租户决定扣留租金，直到必要的维修完成。"},{"sentence":"The sudden increase in rent, which was not communicated in advance, caused significant financial strain for the family.","translation":"租金突然上涨，且未提前通知，给这个家庭带来了巨大的经济压力。"},{"sentence":"When you rent a car in a foreign country, it is essential to understand the local traffic laws to avoid fines.","translation":"当你在国外租车时，了解当地的交通法规以避免罚款是至关重要的。"},{"sentence":"The company decided to rent additional office space rather than purchase a new building, thereby preserving capital for other investments.","translation":"公司决定租用额外的办公空间，而不是购买新楼，从而为其他投资保留了资金。"}]},"magnet":{"examples":[{"sentence":"Although the city is small, its vibrant arts scene has become a magnet for creative professionals from around the world.","translation":"尽管这座城市很小，但其充满活力的艺术氛围已成为吸引世界各地创意专业人士的磁铁。"},{"sentence":"The new research institute, which offers state-of-the-art facilities, acts as a magnet for top scientists seeking to advance their work.","translation":"这个提供尖端设施的新研究所，像磁铁一样吸引着寻求推进工作的顶尖科学家。"},{"sentence":"Because the region's low tax rates serve as a magnet for businesses, its economy has grown rapidly over the past decade.","translation":"由于该地区的低税率像磁铁一样吸引着企业，其经济在过去十年中迅速增长。"},{"sentence":"A prestigious university can be a magnet that draws ambitious students, thereby enriching the local community with fresh talent.","translation":"一所名牌大学可以成为吸引雄心勃勃的学生的磁铁，从而为当地社区注入新的人才。"},{"sentence":"While natural beauty alone may not suffice, the coastal town has become a magnet for retirees seeking a peaceful lifestyle.","translation":"虽然仅凭自然美景可能不够，但这个沿海小镇已成为寻求宁静生活方式的退休人员的向往之地。"}]},"species":{"examples":[{"sentence":"Although many species have vanished due to human activity, conservation programs can still prevent further losses.","translation":"尽管许多物种因人类活动而消失，但保护计划仍能防止进一步的损失。"},{"sentence":"Because invasive species often lack natural predators, they can rapidly dominate new environments.","translation":"由于入侵物种通常缺乏天敌，它们能迅速在新环境中占据主导地位。"},{"sentence":"When a keystone species is removed, the entire ecosystem may collapse, which demonstrates the interconnectedness of nature.","translation":"当关键物种被移除时，整个生态系统可能崩溃，这表明了自然的相互关联性。"},{"sentence":"Scientists classify organisms into distinct species based on genetic differences, thereby refining our understanding of biodiversity.","translation":"科学家根据遗传差异将生物划分为不同的物种，从而完善了我们对生物多样性的理解。"},{"sentence":"Protecting endangered species is not only a moral obligation but also essential for maintaining ecological balance.","translation":"保护濒危物种不仅是一种道德义务，而且对于维持生态平衡至关重要。"}]},"contend":{"examples":[{"sentence":"Although many scholars contend that technology improves education, others argue that it can be a distraction.","translation":"尽管许多学者认为技术改善了教育，但其他人则认为它可能分散注意力。"},{"sentence":"Because startups must contend with limited funding, they often rely on innovative strategies to survive.","translation":"由于初创公司必须应对有限的资金，它们通常依靠创新策略来生存。"},{"sentence":"When athletes contend for a championship, they must maintain peak physical condition, which requires rigorous training.","translation":"当运动员为冠军而竞争时，他们必须保持最佳身体状态，这需要严格的训练。"},{"sentence":"Governments contend with the dilemma of allocating resources between healthcare and education, thereby facing difficult trade-offs.","translation":"政府应对在医疗和教育之间分配资源的困境，从而面临艰难的权衡。"},{"sentence":"Some critics contend that globalization exacerbates inequality, whereas proponents highlight its economic benefits.","translation":"一些批评者认为全球化加剧了不平等，而支持者则强调其经济效益。"}]},"dilemma":{"examples":[{"sentence":"Although the dilemma of choosing between career and family is common, flexible work policies can help alleviate it.","translation":"尽管在事业和家庭之间选择的困境很常见，但灵活的工作政策有助于缓解这一困境。"},{"sentence":"Because the ethical dilemma involved conflicting values, the committee struggled to reach a consensus.","translation":"由于这一伦理困境涉及相互冲突的价值观，委员会难以达成共识。"},{"sentence":"When faced with the dilemma of preserving nature or promoting development, policymakers must consider long-term consequences.","translation":"当面临保护自然还是促进发展的困境时，决策者必须考虑长期后果。"},{"sentence":"The prisoner's dilemma illustrates how rational individuals might not cooperate, even when it is in their best interest to do so.","translation":"囚徒困境说明了理性的个体可能不会合作，即使合作符合他们的最佳利益。"},{"sentence":"Many students face the dilemma of pursuing a passion versus choosing a stable career, which can cause significant stress.","translation":"许多学生面临追求激情还是选择稳定职业的困境，这可能导致巨大的压力。"}]},"bulk":{"examples":[{"sentence":"The bulk of the evidence suggests that early intervention significantly improves long-term outcomes.","translation":"大量证据表明，早期干预能显著改善长期效果。"},{"sentence":"Because the bulk of the funding comes from public sources, transparency in allocation is essential.","translation":"由于大部分资金来自公共来源，分配的透明度至关重要。"},{"sentence":"Although the bulk of the population supports the reform, a vocal minority continues to oppose it.","translation":"尽管大多数人口支持这项改革，但仍有少数人高声反对。"},{"sentence":"The bulk of the research focuses on renewable energy, which is critical for sustainable development.","translation":"大部分研究集中在可再生能源上，这对可持续发展至关重要。"},{"sentence":"In order to reduce costs, the company decided to purchase materials in bulk rather than in small quantities.","translation":"为了降低成本，公司决定批量采购材料，而不是小量购买。"}]},"though":{"examples":[{"sentence":"Although the new policy is controversial, it has led to measurable improvements in public health, though some critics remain unconvinced.","translation":"尽管新政策存在争议，但它已带来公共卫生方面可衡量的改善，不过一些批评者仍不信服。"},{"sentence":"The initial investment is high; the long-term savings, though, justify the expenditure when considering the total cost of ownership.","translation":"初期投资很高；然而，从总拥有成本来看，长期节省的费用证明了这笔支出的合理性。"},{"sentence":"The experiment failed to confirm the hypothesis, though the data revealed an unexpected pattern that warrants further investigation.","translation":"实验未能证实该假设，不过数据揭示了一个值得进一步研究的新模式。"},{"sentence":"Online learning offers flexibility, though it requires a high degree of self-discipline, which many students find challenging to maintain.","translation":"在线学习提供了灵活性，不过它需要高度的自律，而许多学生发现这很难保持。"},{"sentence":"The proposal was accepted, though several committee members expressed reservations about its feasibility, thereby delaying the implementation phase.","translation":"该提案被接受了，不过几位委员会成员对其可行性表示了保留意见，从而推迟了实施阶段。"}]},"convenient":{"examples":[{"sentence":"While online banking is convenient, it exposes users to cybersecurity risks that cannot be ignored, which necessitates robust protective measures.","translation":"虽然网上银行很方便，但它让用户面临不可忽视的网络安全风险，这就需要强有力的保护措施。"},{"sentence":"A convenient location near public transport can significantly increase a property's market value, because it reduces commuting time for residents.","translation":"靠近公共交通的便利位置可以显著提高房产的市场价值，因为它减少了居民的通勤时间。"},{"sentence":"It is convenient to attribute the problem solely to a lack of funding, but the underlying causes are more complex, thereby requiring a multifaceted solution.","translation":"将问题仅仅归咎于资金不足是很省事的，但根本原因更为复杂，因此需要多方面的解决方案。"},{"sentence":"The new software provides a convenient interface that allows researchers to analyze data without extensive coding, which accelerates the research process.","translation":"新软件提供了一个方便的界面，使研究人员无需大量编程即可分析数据，从而加快了研究进程。"},{"sentence":"Although the meeting time was convenient for most participants, a few had to rearrange their schedules, which highlights the challenge of coordinating large groups.","translation":"尽管会议时间对大多数参与者来说很方便，但仍有少数人不得不重新安排日程，这凸显了协调大群体的挑战。"}]},"device":{"examples":[{"sentence":"The new tracking device, which uses satellite technology, can locate lost hikers in remote areas.","translation":"这种新型追踪设备利用卫星技术，可以在偏远地区定位迷路的徒步旅行者。"},{"sentence":"Although the device was designed for industrial use, it has found applications in medical research.","translation":"尽管该设备是为工业用途设计的，但已在医学研究中得到应用。"},{"sentence":"Because the security device malfunctioned, the building was left vulnerable to unauthorized access.","translation":"由于安全装置发生故障，大楼容易遭受未经授权的进入。"},{"sentence":"Engineers developed a portable device that converts plastic waste into usable fuel, thereby addressing pollution and energy needs.","translation":"工程师开发了一种便携式装置，可将塑料废物转化为可用燃料，从而解决污染和能源需求。"},{"sentence":"When using any electronic device, it is important to follow the manufacturer's safety instructions.","translation":"使用任何电子设备时，遵循制造商的安全说明非常重要。"}]},"proof":{"examples":[{"sentence":"The researcher presented compelling proof that the new drug significantly reduces recovery time.","translation":"研究人员提供了令人信服的证据，证明这种新药能显著缩短康复时间。"},{"sentence":"Without concrete proof, the committee refused to accept the allegations of misconduct.","translation":"由于缺乏确凿证据，委员会拒绝接受有关不当行为的指控。"},{"sentence":"Historical records offer ample proof that early civilizations engaged in long-distance trade.","translation":"历史记录提供了充分的证据，表明早期文明曾进行远距离贸易。"},{"sentence":"The sudden drop in crime rates served as proof that the new policy was effective.","translation":"犯罪率的突然下降证明了新政策的有效性。"},{"sentence":"Although anecdotal accounts are suggestive, they do not constitute scientific proof.","translation":"尽管轶事叙述具有启发性，但它们并不构成科学证据。"}]},"cake":{"examples":[{"sentence":"Although the cake was elaborately decorated, its flavor was disappointingly bland.","translation":"尽管蛋糕装饰精美，但味道却平淡得令人失望。"},{"sentence":"Because the cake contained a high proportion of butter, it had an exceptionally rich texture.","translation":"由于蛋糕含有大量黄油，所以口感格外浓郁。"},{"sentence":"The baker demonstrated how to fold egg whites into the batter, which ensures the cake rises properly.","translation":"烘焙师演示了如何将蛋白拌入面糊，这能确保蛋糕充分膨胀。"},{"sentence":"While the cake was baking, the kitchen filled with the comforting aroma of vanilla and caramel.","translation":"蛋糕烘烤时，厨房里弥漫着香草和焦糖的怡人香气。"},{"sentence":"If you substitute applesauce for oil, the cake will be lower in fat but still moist.","translation":"如果用苹果酱代替油，蛋糕的脂肪含量会更低，但仍然湿润。"}]},"plaster":{"examples":[{"sentence":"Although modern drywall is common, traditional plaster walls offer superior soundproofing and durability.","translation":"尽管现代石膏板很常见，但传统的灰泥墙具有更优越的隔音和耐久性。"},{"sentence":"Because the plaster had not fully cured, the painters had to wait before applying the final coat.","translation":"由于灰泥尚未完全固化，油漆工必须等待才能涂刷最后一道涂层。"},{"sentence":"The artisan applied a thin layer of plaster to the ceiling, which created a smooth and elegant finish.","translation":"工匠在天花板上涂了一层薄薄的灰泥，从而打造出光滑优雅的表面。"},{"sentence":"When the old plaster began to crumble, the homeowners decided to replace it with a more modern material.","translation":"当旧的灰泥开始碎裂时，房主决定用更现代的材料替换它。"},{"sentence":"The restoration expert used a special plaster that matches the historic composition to repair the fresco.","translation":"修复专家使用了一种与历史成分相匹配的特殊灰泥来修复壁画。"}]},"cage":{"examples":[{"sentence":"Although the cage was spacious and equipped with perches, the parrot still showed signs of psychological distress.","translation":"尽管笼子很宽敞并配有栖木，但这只鹦鹉仍然表现出心理困扰的迹象。"},{"sentence":"Because the cage had been improperly secured, the research monkey managed to escape and caused a brief alarm in the facility.","translation":"由于笼子没有妥善固定，研究用的猴子设法逃脱并在设施内引起了短暂的警报。"},{"sentence":"The zoo designed a naturalistic cage that mimicked the animal's wild habitat, thereby encouraging more natural behaviors.","translation":"动物园设计了一个模仿动物野生栖息地的自然主义笼子，从而鼓励了更自然的行为。"},{"sentence":"When the cage was finally opened after years of confinement, the lion hesitated before stepping out into the sanctuary.","translation":"当笼子在多年囚禁后终于被打开时，狮子犹豫了一下才踏入保护区。"},{"sentence":"The animal rights group argued that no cage, regardless of size, could provide a fulfilling life for a creature that roams vast distances in the wild.","translation":"动物权利组织认为，无论笼子多大，都无法为在野外漫游广阔距离的生物提供充实的生活。"}]},"academic":{"examples":[{"sentence":"Although she had a strong academic background in mathematics, she struggled to apply theoretical concepts to real-world engineering problems.","translation":"尽管她有扎实的数学学术背景，但她难以将理论概念应用于现实世界的工程问题。"},{"sentence":"The university's academic integrity policy requires that all sources be properly cited, which helps to prevent plagiarism.","translation":"大学的学术诚信政策要求所有来源都得到适当引用，这有助于防止剽窃。"},{"sentence":"Because academic journals often have lengthy peer-review processes, groundbreaking research can take months or even years to reach the public.","translation":"由于学术期刊通常有漫长的同行评审过程，突破性的研究可能需要数月甚至数年才能到达公众手中。"},{"sentence":"The conference brought together academic experts from diverse fields, thereby fostering interdisciplinary dialogue and collaboration.","translation":"会议汇集了来自不同领域的学术专家，从而促进了跨学科对话与合作。"},{"sentence":"While academic achievement is important, employers increasingly value practical skills and emotional intelligence in the workplace.","translation":"虽然学术成就很重要，但雇主越来越重视工作场所中的实践技能和情商。"}]},"used":{"examples":[{"sentence":"The laboratory purchased a used electron microscope to reduce equipment costs while maintaining research quality.","translation":"实验室购买了一台二手电子显微镜，以在维持研究质量的同时降低设备成本。"},{"sentence":"Because the used textbooks were carefully annotated by previous students, they provided valuable insights that new copies lacked.","translation":"由于这些二手教科书被之前的学生仔细标注过，它们提供了新书所缺乏的宝贵见解。"},{"sentence":"Although the used car had high mileage, its meticulous service record convinced the buyer of its reliability.","translation":"尽管这辆二手车里程数很高，但其详尽的保养记录使买家相信了它的可靠性。"},{"sentence":"The charity organization distributes used clothing to underprivileged communities, thereby reducing waste and supporting those in need.","translation":"该慈善组织将二手衣物分发给贫困社区，从而减少浪费并帮助有需要的人。"},{"sentence":"Researchers found that used cooking oil can be converted into biodiesel, offering a sustainable alternative to fossil fuels.","translation":"研究人员发现，使用过的食用油可以转化为生物柴油，为化石燃料提供了一种可持续的替代品。"}]},"spacious":{"examples":[{"sentence":"Although the apartment is not luxurious, its spacious layout allows the family to create distinct zones for work and relaxation.","translation":"尽管这套公寓并不豪华，但其宽敞的布局使这家人能够划分出明确的工作和休闲区域。"},{"sentence":"Because the conference hall is exceptionally spacious, it can accommodate large academic symposiums without feeling crowded.","translation":"由于会议厅格外宽敞，它可以容纳大型学术研讨会而不显得拥挤。"},{"sentence":"Urban planners argue that spacious public parks are essential for improving residents' mental well-being, which fosters community interaction.","translation":"城市规划者认为，宽敞的公共公园对于改善居民的心理健康至关重要，这促进了社区互动。"},{"sentence":"The museum's spacious galleries enable visitors to appreciate large-scale contemporary artworks from multiple perspectives, thereby enhancing their aesthetic experience.","translation":"博物馆宽敞的展厅使参观者能够从多个角度欣赏大型当代艺术作品，从而提升他们的审美体验。"},{"sentence":"The newly designed library features spacious reading areas that encourage students to engage in prolonged, focused study.","translation":"新设计的图书馆拥有宽敞的阅读区，鼓励学生进行长时间专注的学习。"}]},"burglar":{"examples":[{"sentence":"Because the burglar had carefully disabled the alarm, the police concluded that the crime was premeditated rather than opportunistic.","translation":"由于窃贼小心地破坏了警报器，警方断定这起犯罪是有预谋的而非机会性的。"},{"sentence":"Although the burglar wore a mask to conceal his face, a distinctive tattoo on his wrist led to his eventual arrest.","translation":"尽管窃贼戴着面具遮住了脸，但他手腕上一个独特的纹身最终导致了他的被捕。"},{"sentence":"Installing a comprehensive security system can deter a potential burglar from targeting residential properties, which reduces the risk of break-ins.","translation":"安装全面的安防系统可以阻止潜在的窃贼将住宅作为目标，这降低了入室盗窃的风险。"},{"sentence":"Forensic experts were able to identify the burglar by analyzing the faint fingerprints left on the shattered window pane, thereby providing crucial evidence.","translation":"法医专家通过分析破碎窗玻璃上留下的模糊指纹，成功确认了窃贼的身份，从而提供了关键证据。"},{"sentence":"The insurance company requires homeowners to report a burglary within 24 hours, even if the burglar took nothing of significant value, to ensure timely processing.","translation":"保险公司要求房主在24小时内报告入室盗窃，即使窃贼没有拿走任何贵重物品，以确保及时处理。"}]},"cousin":{"examples":[{"sentence":"My cousin, who works as a civil engineer, has contributed to several major infrastructure projects that improved regional connectivity.","translation":"我的表兄是一名土木工程师，曾参与多个改善区域连通性的重大基础设施项目。"},{"sentence":"Although my cousin and I pursued different academic disciplines, we often exchange ideas that enrich both our perspectives.","translation":"尽管我和表姐攻读不同的学科，但我们经常交流想法，从而丰富了彼此的视野。"},{"sentence":"A distant cousin, whom I had never met before, contacted me to share valuable genealogical records that clarified our family history.","translation":"一位素未谋面的远房表亲联系了我，分享了珍贵的家谱记录，厘清了我们的家族史。"},{"sentence":"My cousin decided to volunteer abroad after graduation, an experience that profoundly shaped her understanding of global health challenges.","translation":"我的表妹毕业后决定去海外做志愿者，这段经历深刻塑造了她对全球健康挑战的理解。"},{"sentence":"Because my cousin is fluent in three languages, she often serves as an informal interpreter at international conferences held in our city.","translation":"由于我的表姐精通三种语言，她经常在我们城市举办的国际会议上担任非正式口译员。"}]},"victory":{"examples":[{"sentence":"Although the team celebrated their victory, they recognized that consistent effort was the true key to success.","translation":"尽管团队庆祝了胜利，但他们认识到持续的努力才是成功的真正关键。"},{"sentence":"The general's strategic victory, which relied on careful intelligence gathering, turned the tide of the war.","translation":"将军依靠精心情报收集取得的战略胜利，扭转了战局。"},{"sentence":"Because the election victory was so narrow, the new government had to negotiate with opposition parties to pass legislation.","translation":"由于选举胜利如此微弱，新政府不得不与反对党谈判以通过立法。"},{"sentence":"A victory in the courtroom not only vindicated the defendant but also set a precedent for future cases.","translation":"法庭上的胜利不仅证明了被告的清白，也为未来的案件树立了先例。"},{"sentence":"While the victory brought temporary relief, the long-term consequences of the conflict remained unresolved.","translation":"虽然胜利带来了暂时的缓解，但冲突的长期后果仍未解决。"}]},"kindness":{"examples":[{"sentence":"Although kindness is often undervalued in competitive environments, it can foster collaboration and long-term trust among colleagues.","translation":"尽管善良在竞争环境中常被低估，但它能促进同事间的合作与长期信任。"},{"sentence":"The kindness that volunteers show to disaster victims not only alleviates immediate suffering but also helps rebuild a sense of community.","translation":"志愿者对灾民表现出的善良不仅减轻了眼前的痛苦，也有助于重建社区意识。"},{"sentence":"Because small acts of kindness can accumulate into significant social change, policymakers should encourage prosocial behavior through education.","translation":"因为微小的善举能累积成重大的社会变革，政策制定者应通过教育鼓励亲社会行为。"},{"sentence":"While professional success often depends on technical skills, the kindness with which one treats others can determine the quality of workplace relationships.","translation":"虽然职业成功常取决于技术能力，但待人接物的善良能决定职场关系的质量。"},{"sentence":"When leaders demonstrate genuine kindness, they inspire loyalty and motivation, thereby creating a more resilient organizational culture.","translation":"当领导者表现出真诚的善良时，他们会激发忠诚和动力，从而创造更具韧性的组织文化。"}]},"acknowledge":{"examples":[{"sentence":"Although it is difficult to acknowledge personal biases, doing so is essential for making fair and objective decisions in academic research.","translation":"尽管承认个人偏见很难，但这样做对于在学术研究中做出公正客观的决定至关重要。"},{"sentence":"Companies that acknowledge their environmental impact can build a positive reputation, which attracts environmentally conscious consumers.","translation":"承认自身环境影响的公司能建立良好声誉，从而吸引有环保意识的消费者。"},{"sentence":"Because the government failed to acknowledge the economic disparities, public discontent grew until reforms were finally implemented.","translation":"由于政府未能承认经济差距，公众不满情绪增长，直到最终实施改革。"},{"sentence":"To ensure a constructive dialogue, both parties must first acknowledge the validity of each other's concerns, rather than dismissing them outright.","translation":"为确保建设性对话，双方必须首先承认对方关切的合理性，而不是直接否定。"},{"sentence":"When historians acknowledge the contributions of marginalized groups, they provide a more accurate and inclusive account of the past.","translation":"当历史学家承认边缘群体的贡献时，他们提供了更准确、更具包容性的历史叙述。"}]},"execute":{"examples":[{"sentence":"Although the strategy was sound, the team failed to execute it because of insufficient training.","translation":"尽管策略是合理的，但由于培训不足，团队未能执行它。"},{"sentence":"To execute the project on time, the manager delegated tasks while monitoring progress closely.","translation":"为了按时执行项目，经理分配了任务，同时密切监控进展。"},{"sentence":"Because the software can execute commands rapidly, it significantly reduces the time required for data analysis.","translation":"由于该软件能快速执行命令，它显著减少了数据分析所需的时间。"},{"sentence":"The court decided to execute the sentence despite international appeals for clemency.","translation":"尽管国际社会呼吁宽大处理，法院仍决定执行判决。"},{"sentence":"When researchers execute experiments with precision, they ensure that the results are both valid and reliable.","translation":"当研究人员精确地执行实验时，他们确保结果既有效又可靠。"}]},"outbreak":{"examples":[{"sentence":"Although the outbreak was contained within weeks, its economic impact persisted for years.","translation":"尽管疫情在几周内得到控制，但其经济影响持续了多年。"},{"sentence":"Because the outbreak spread through airborne transmission, wearing masks became mandatory in public spaces.","translation":"由于疫情通过空气传播，在公共场所佩戴口罩成为强制要求。"},{"sentence":"The outbreak of protests, which began in the capital, quickly spread to other cities.","translation":"始于首都的抗议活动爆发后，迅速蔓延到其他城市。"},{"sentence":"When an outbreak of food poisoning occurred, the restaurant was temporarily closed for investigation.","translation":"当食物中毒事件爆发时，该餐厅被暂时关闭以接受调查。"},{"sentence":"Without rapid international cooperation, the outbreak could have escalated into a global pandemic.","translation":"如果没有迅速的国际合作，这次疫情可能升级为全球大流行。"}]},"literally":{"examples":[{"sentence":"When translating poetry, one should not render metaphors literally, as the beauty may be lost.","translation":"翻译诗歌时，不应直译隐喻，否则会失去美感。"},{"sentence":"Although the instruction was meant figuratively, he interpreted it literally and caused confusion.","translation":"尽管指示是比喻性的，他却按字面意思理解，造成了混乱。"},{"sentence":"The city was so silent at night that you could literally hear a pin drop.","translation":"夜晚的城市如此安静，你简直能听到针落地的声音。"},{"sentence":"Because the term is often used literally in scientific contexts, its figurative use can be misleading.","translation":"由于该术语在科学语境中常按字面使用，其比喻用法可能产生误导。"},{"sentence":"The novel's description of the famine was so vivid that readers could literally feel the hunger.","translation":"小说对饥荒的描述如此生动，读者简直能感受到饥饿。"}]},"on":{"examples":[{"sentence":"Although the flight was delayed on account of fog, the passengers remained remarkably calm.","translation":"尽管航班因雾延误，乘客们仍然非常冷静。"},{"sentence":"The committee decided to focus on renewable energy, which is crucial for sustainable development.","translation":"委员会决定聚焦于可再生能源，这对可持续发展至关重要。"},{"sentence":"On the one hand, technology enhances efficiency, while on the other hand, it may reduce face-to-face interaction.","translation":"一方面，技术提高了效率，而另一方面，它可能减少面对面的交流。"},{"sentence":"The new regulation was introduced on the premise that it would improve public safety.","translation":"新规的出台基于其将改善公共安全的前提。"},{"sentence":"On reflection, the researcher realized that the initial hypothesis was flawed, thereby revising the experimental design.","translation":"经过反思，研究者意识到最初的假设有缺陷，从而修改了实验设计。"}]},"skate":{"examples":[{"sentence":"Although the ice was thin, the children were eager to skate on the frozen pond.","translation":"尽管冰层很薄，孩子们还是渴望在结冰的池塘上滑冰。"},{"sentence":"Because she practiced diligently, her ability to skate improved remarkably within a few months.","translation":"由于她勤奋练习，她的滑冰能力在几个月内显著提高。"},{"sentence":"The new skate park, which was designed by a renowned architect, attracts visitors from neighboring cities.","translation":"由著名建筑师设计的新滑冰公园吸引了邻近城市的游客。"},{"sentence":"When the temperature drops below freezing, the lake becomes a perfect place to skate.","translation":"当气温降到冰点以下时，这个湖就成了滑冰的理想场所。"},{"sentence":"Learning to skate requires not only physical strength but also mental focus to maintain balance.","translation":"学习滑冰不仅需要体力，还需要集中注意力来保持平衡。"}]},"fireplace":{"examples":[{"sentence":"Because the fireplace was the only source of warmth, the family spent winter evenings gathered around it.","translation":"由于壁炉是唯一的取暖来源，家人在冬夜都围聚在它旁边。"},{"sentence":"The old inn, which features a massive stone fireplace, offers a cozy atmosphere for travelers.","translation":"那家老客栈有一个巨大的石砌壁炉，为旅客提供了舒适的氛围。"},{"sentence":"Although central heating is more efficient, many homeowners still install a fireplace for its aesthetic appeal.","translation":"尽管中央供暖更高效，许多房主仍安装壁炉以追求其美学吸引力。"},{"sentence":"When the power went out, the fireplace became essential for both heating and cooking.","translation":"停电时，壁炉对于取暖和做饭都变得至关重要。"},{"sentence":"Installing a modern fireplace can reduce energy bills while creating a focal point in the living room.","translation":"安装现代壁炉可以降低能源费用，同时在客厅中创造一个焦点。"}]},"fairly":{"examples":[{"sentence":"The new policy has been fairly implemented across all departments, which has significantly improved employee morale.","translation":"新政策在所有部门得到了公平的执行，这显著提高了员工的士气。"},{"sentence":"Although the initial results were fairly modest, the long-term benefits of the program became evident over time.","translation":"尽管最初的结果相当有限，但随着时间的推移，该计划的长期效益变得明显。"},{"sentence":"A fairly large proportion of students reported that the revised curriculum helped them develop critical thinking skills.","translation":"相当大比例的学生报告说，修订后的课程帮助他们培养了批判性思维能力。"},{"sentence":"Because the evaluation criteria were applied fairly, even those who did not advance accepted the outcome without resentment.","translation":"由于评估标准得到了公平的应用，即使是那些没有晋级的人也毫无怨言地接受了结果。"},{"sentence":"The research team adopted a fairly rigorous methodology to ensure that the findings would be reproducible.","translation":"研究团队采用了相当严谨的方法，以确保研究结果可重现。"}]},"rock":{"examples":[{"sentence":"The geologist explained that the layered rock formation provided crucial evidence of the region's volcanic past.","translation":"地质学家解释说，层状的岩石构造为该地区的火山历史提供了关键证据。"},{"sentence":"Because the foundation was built on solid rock, the ancient temple withstood centuries of earthquakes.","translation":"由于地基建在坚固的岩石上，这座古庙经受住了数个世纪的地震。"},{"sentence":"The climber carefully examined the rock face before selecting a route that minimized the risk of falling debris.","translation":"登山者仔细检查了岩壁，然后选择了一条将落石风险降至最低的路线。"},{"sentence":"Although rock music originated in the mid-20th century, its influence on global youth culture remains profound.","translation":"尽管摇滚乐起源于20世纪中期，但它对全球青年文化的影响依然深远。"},{"sentence":"The sculptor chose a massive block of marble, knowing that this particular rock would yield a masterpiece.","translation":"雕塑家选择了一块巨大的大理石，他知道这块特殊的岩石将造就一件杰作。"}]},"knock":{"examples":[{"sentence":"Although the knock on the door was faint, it startled the researcher who had been absorbed in analyzing data for hours.","translation":"尽管敲门声很轻，但它惊动了那位已经全神贯注分析数据数小时的研究员。"},{"sentence":"The mechanic identified a persistent knock in the engine, which indicated that a component needed immediate replacement.","translation":"机械师发现发动机中有持续的敲击声，这表明某个部件需要立即更换。"},{"sentence":"Because the knock at the window occurred late at night, the family hesitated before checking the source of the sound.","translation":"由于敲窗声发生在深夜，这家人犹豫了一下才去查看声音的来源。"},{"sentence":"A single knock on the conference table served as a signal to begin the negotiation, thereby focusing everyone's attention.","translation":"在会议桌上敲一下作为开始谈判的信号，从而集中了所有人的注意力。"},{"sentence":"When the unexpected knock interrupted the lecture, the professor paused to ensure that the visitor was not in distress.","translation":"当意外的敲门声打断了讲座时，教授暂停下来以确保来访者没有遇到困难。"}]},"adolescent":{"examples":[{"sentence":"Although adolescent learners often struggle with self-discipline, structured routines can help them build effective study habits.","translation":"尽管青少年学习者常常在自律方面有困难，但有规律的作息能帮助他们建立有效的学习习惯。"},{"sentence":"Because adolescent identity formation is influenced by social media, educators must teach critical digital literacy skills.","translation":"由于青少年身份认同的形成受到社交媒体影响，教育者必须教授批判性的数字素养技能。"},{"sentence":"Adolescent participation in community service, which fosters empathy and civic responsibility, should be encouraged by schools.","translation":"青少年参与社区服务能培养同理心和公民责任感，学校应予以鼓励。"},{"sentence":"When adolescent athletes receive proper nutritional guidance, their physical performance and overall health improve significantly.","translation":"当青少年运动员获得适当的营养指导时，他们的身体表现和整体健康会显著改善。"},{"sentence":"Adolescent sleep patterns shift biologically, thereby making early school start times detrimental to their academic performance.","translation":"青少年的睡眠模式在生理上发生变化，因此过早的上课时间对他们的学业表现有害。"}]},"stalk":{"examples":[{"sentence":"The plant's thick stalk, which stores water, enables it to survive prolonged droughts in arid regions.","translation":"这种植物粗壮的茎能储存水分，使其能在干旱地区长期存活。"},{"sentence":"Although the stalk appears fragile, it contains strong fibers that are used to make durable textiles.","translation":"尽管茎看起来很脆弱，但它含有强韧的纤维，可用于制造耐用的纺织品。"},{"sentence":"Farmers often remove the lower leaves from the stalk to ensure that nutrients are directed toward fruit development.","translation":"农民经常摘除茎下部的叶子，以确保养分输送到果实发育中。"},{"sentence":"Because the stalk is rich in cellulose, researchers are exploring its potential as a sustainable source of biofuel.","translation":"由于茎富含纤维素，研究人员正在探索其作为可持续生物燃料来源的潜力。"},{"sentence":"In some cultures, the dried stalk is carved into intricate patterns, thereby transforming agricultural waste into art.","translation":"在一些文化中，干燥的茎被雕刻成复杂的图案，从而将农业废弃物转化为艺术品。"}]},"criticism":{"examples":[{"sentence":"Constructive criticism, when delivered with respect, can motivate employees to improve their performance significantly.","translation":"建设性的批评，当以尊重的方式提出时，可以极大地激励员工改进他们的表现。"},{"sentence":"The researcher welcomed peer criticism because it helped refine the methodology before the study was published.","translation":"这位研究人员欢迎同行的批评，因为这有助于在研究发表前完善方法。"},{"sentence":"Although the artist received harsh criticism from traditionalists, her innovative style eventually gained widespread acclaim.","translation":"尽管这位艺术家受到了传统主义者的严厉批评，但她的创新风格最终获得了广泛的赞誉。"},{"sentence":"A culture that suppresses criticism stifles innovation, as employees become reluctant to point out flaws or suggest improvements.","translation":"压制批评的文化会扼杀创新，因为员工会不愿意指出缺陷或提出改进建议。"},{"sentence":"Literary criticism not only evaluates a work's aesthetic value but also examines its social and historical context.","translation":"文学批评不仅评价作品的美学价值，还审视其社会和历史背景。"}]},"later":{"examples":[{"sentence":"Although the initial experiment failed, the researchers later identified a critical variable that led to a breakthrough.","translation":"尽管最初的实验失败了，但研究人员后来发现了一个关键变量，从而取得了突破。"},{"sentence":"Students who master foundational concepts early often find that later coursework becomes more manageable.","translation":"早期掌握基础概念的学生通常会发现后来的课程变得更容易应对。"},{"sentence":"The company launched the product without sufficient testing, which later resulted in costly recalls.","translation":"该公司在未经充分测试的情况下推出了产品，后来导致了代价高昂的召回。"},{"sentence":"Because the committee postponed the decision until later, the project timeline was significantly delayed.","translation":"由于委员会将决定推迟到以后，项目时间表被严重延误。"},{"sentence":"If we invest in renewable energy now, we can mitigate environmental damage that might otherwise become irreversible later.","translation":"如果我们现在投资可再生能源，就可以减轻以后可能变得不可逆转的环境损害。"}]},"appreciate":{"examples":[{"sentence":"To fully appreciate the novel's depth, one must consider the historical context in which it was written.","translation":"要完全领会这部小说的深度，必须考虑其创作的历史背景。"},{"sentence":"Employees appreciate a supportive manager, as it creates a positive atmosphere that boosts productivity.","translation":"员工欣赏支持他们的经理，因为这能营造积极的氛围，从而提高生产力。"},{"sentence":"Although the policy was initially unpopular, many citizens came to appreciate its environmental benefits over time.","translation":"尽管该政策最初不受欢迎，但许多市民逐渐认识到它对环境的益处。"},{"sentence":"Investors appreciate assets that appreciate steadily, such as bonds, which provide reliable returns.","translation":"投资者青睐稳定增值的资产，例如债券，它们能提供可靠的回报。"},{"sentence":"We should appreciate the diversity of opinions in a team, because it leads to more innovative solutions.","translation":"我们应当珍视团队中意见的多样性，因为它能带来更具创新性的解决方案。"}]},"valley":{"examples":[{"sentence":"Although the valley was prone to flooding, the community built resilient infrastructure to protect their homes.","translation":"尽管这个山谷容易发生洪水，但社区建造了有韧性的基础设施来保护家园。"},{"sentence":"The valley, which is surrounded by towering mountains, remains inaccessible during the harsh winter months.","translation":"这个被高耸山脉环绕的山谷，在严冬月份仍然无法进入。"},{"sentence":"Because the valley's microclimate is ideal for viticulture, local wineries have gained international acclaim.","translation":"由于山谷的微气候非常适合葡萄种植，当地的酿酒厂获得了国际赞誉。"},{"sentence":"When explorers first entered the valley, they discovered a hidden civilization that had thrived for centuries.","translation":"当探险家首次进入山谷时，他们发现了一个繁荣了几个世纪的隐秘文明。"},{"sentence":"The river that meanders through the valley not only irrigates the fields but also generates hydroelectric power.","translation":"蜿蜒流过山谷的河流不仅灌溉了田地，还产生了水力发电。"}]},"gallop":{"examples":[{"sentence":"Although the horse began at a gentle trot, it soon broke into a full gallop across the meadow.","translation":"虽然马开始是小跑，但很快就在草地上全速疾驰起来。"},{"sentence":"Because technological change often proceeds at a gallop, policymakers must adapt regulations swiftly to avoid obsolescence.","translation":"因为技术变革常常飞速发展，政策制定者必须迅速调整法规以避免过时。"},{"sentence":"When the team realized the deadline was imminent, they worked at a gallop to finalize the presentation.","translation":"当团队意识到截止日期临近时，他们以极快的速度工作以完成演示文稿。"},{"sentence":"The narrative moves at a gallop, which ensures that readers remain captivated throughout the entire novel.","translation":"叙事以极快的节奏推进，这确保了读者在整个小说中保持着迷。"},{"sentence":"While the economy once expanded at a gallop, it has now settled into a more moderate and sustainable growth rate.","translation":"虽然经济曾经高速扩张，但现在已趋于更温和且可持续的增长率。"}]},"investment":{"examples":[{"sentence":"Although initial costs are high, investment in renewable energy yields substantial long-term environmental and economic benefits.","translation":"虽然初始成本很高，但对可再生能源的投资能带来巨大的长期环境和经济利益。"},{"sentence":"Because a diversified investment portfolio spreads risk, it is often recommended for conservative investors.","translation":"因为多元化的投资组合分散了风险，所以通常推荐给保守型投资者。"},{"sentence":"When governments prioritize investment in education, they lay the foundation for a more innovative and competitive workforce.","translation":"当政府优先投资教育时，他们为更具创新力和竞争力的劳动力奠定了基础。"},{"sentence":"The company's strategic investment in research and development, which focused on artificial intelligence, led to a breakthrough product.","translation":"公司对研发的战略投资，专注于人工智能，带来了一款突破性产品。"},{"sentence":"Foreign direct investment can stimulate economic growth, provided that the host country maintains a stable and transparent legal framework.","translation":"外国直接投资可以刺激经济增长，前提是东道国保持稳定透明的法律框架。"}]},"apply":{"examples":[{"sentence":"Although the deadline is approaching, you must apply for the scholarship before the end of this month.","translation":"尽管截止日期临近，你必须在本月底之前申请奖学金。"},{"sentence":"Because the new regulation does not apply to small businesses, many startups are exempt from the additional tax.","translation":"由于新规定不适用于小企业，许多初创公司免于缴纳额外税款。"},{"sentence":"When you apply the theory to real-world data, you will notice that the results are not always consistent.","translation":"当你将该理论应用于现实世界的数据时，你会注意到结果并不总是一致的。"},{"sentence":"If you apply for the position online, you will receive a confirmation email within 24 hours.","translation":"如果你在线申请该职位，你将在24小时内收到一封确认邮件。"},{"sentence":"Researchers apply advanced statistical methods to analyze the survey data, which ensures the accuracy of their findings.","translation":"研究人员应用先进的统计方法来分析调查数据，这确保了其研究结果的准确性。"}]},"poll":{"examples":[{"sentence":"Although the poll was conducted online, it accurately reflected the opinions of the younger demographic.","translation":"尽管这项民意调查是在线进行的，但它准确地反映了年轻人群的意见。"},{"sentence":"Because the poll results showed a sharp decline in public trust, the government decided to revise its communication strategy.","translation":"由于民意调查结果显示公众信任度急剧下降，政府决定修改其沟通策略。"},{"sentence":"When a poll indicates that most citizens support the new policy, lawmakers are more likely to pass it.","translation":"当一项民意调查表明大多数公民支持新政策时，立法者更有可能通过它。"},{"sentence":"The poll, which surveyed over 5,000 participants, revealed a significant gender gap in attitudes toward remote work.","translation":"这项对5000多名参与者进行的民意调查揭示了在远程工作态度上的显著性别差异。"},{"sentence":"If the poll's methodology is flawed, the results cannot be used to make reliable predictions about the election outcome.","translation":"如果民意调查的方法有缺陷，其结果就不能用于对选举结果做出可靠的预测。"}]},"retire":{"examples":[{"sentence":"Although he had planned to retire at 60, his dedication to the project led him to postpone his retirement.","translation":"尽管他原计划在60岁退休，但对项目的投入使他推迟了退休。"},{"sentence":"Because many senior engineers will retire within the next five years, the company is actively recruiting young talent.","translation":"由于许多资深工程师将在未来五年内退休，公司正在积极招聘年轻人才。"},{"sentence":"When employees retire, they often face challenges in adjusting to a new routine without the structure of work.","translation":"当员工退休时，他们常常面临在没有工作结构的情况下适应新日常的挑战。"},{"sentence":"The government's decision to raise the retirement age means that workers will have to retire later than previous generations.","translation":"政府提高退休年龄的决定意味着工人将不得不比前几代人更晚退休。"},{"sentence":"If you retire early, you need to ensure that your savings are sufficient to support your lifestyle for several decades.","translation":"如果你提前退休，你需要确保你的储蓄足以支撑几十年的生活方式。"}]},"convention":{"examples":[{"sentence":"Although the convention was originally scheduled for June, the organizers postponed it to ensure greater international participation.","translation":"尽管大会原定于六月举行，但组织者为了确保更多的国际参与而将其推迟。"},{"sentence":"The Geneva Convention establishes legal standards for humanitarian treatment during war, which many nations have ratified.","translation":"日内瓦公约确立了战争期间人道待遇的法律标准，许多国家已批准该公约。"},{"sentence":"Because academic convention requires rigorous peer review, groundbreaking studies often face delays before publication.","translation":"由于学术惯例要求严格的同行评审，突破性研究在发表前常常面临延迟。"},{"sentence":"By challenging the convention that only formal education confers expertise, the company hired self-taught programmers who excelled.","translation":"通过挑战只有正规教育才能赋予专业知识的传统观念，该公司聘用了表现出色的自学程序员。"},{"sentence":"While social convention dictates that we shake hands when meeting, some cultures prefer bowing as a sign of respect.","translation":"尽管社会惯例规定见面时握手，但有些文化更喜欢鞠躬以示尊重。"}]},"cereal":{"examples":[{"sentence":"Because cereal grains like wheat and rice are staple foods, their cultivation has shaped human civilization for millennia.","translation":"由于小麦和水稻等谷类作物是主食，它们的种植数千年来塑造了人类文明。"},{"sentence":"A bowl of fortified cereal, which contains essential vitamins, can help children meet their daily nutritional requirements.","translation":"一碗强化麦片含有必需维生素，可以帮助儿童满足每日营养需求。"},{"sentence":"Although cereal production has increased globally, climate change threatens yields through droughts and heatwaves.","translation":"尽管全球谷类产量有所增加，但气候变化通过干旱和热浪威胁着产量。"},{"sentence":"Farmers often rotate cereal crops with legumes to replenish soil nitrogen, thereby reducing the need for synthetic fertilizers.","translation":"农民经常将谷类作物与豆类轮作以补充土壤氮素，从而减少对合成肥料的需求。"},{"sentence":"The ancient Egyptians relied on cereal cultivation not only for food but also for brewing beer, which was a dietary staple.","translation":"古埃及人依赖谷类种植不仅为了食物，还为了酿造作为日常饮食的啤酒。"}]},"principle":{"examples":[{"sentence":"Although the principle of equality is enshrined in law, achieving it in practice requires sustained effort from all sectors of society.","translation":"尽管平等原则已载入法律，但在实践中实现它需要社会各界持续的努力。"},{"sentence":"The principle that every individual deserves respect, regardless of their background, is fundamental to a harmonious community.","translation":"无论背景如何，每个人都应受到尊重的原则是和谐社区的基础。"},{"sentence":"Because the principle of conservation of energy applies universally, perpetual motion machines are impossible to construct.","translation":"由于能量守恒原理普遍适用，永动机是不可能制造出来的。"},{"sentence":"When designing public policy, adhering to the principle of transparency helps to build trust between citizens and the government.","translation":"在设计公共政策时，坚持透明原则有助于建立公民与政府之间的信任。"},{"sentence":"The principle of non-interference in internal affairs is a cornerstone of international relations, which aims to preserve sovereignty.","translation":"不干涉内政原则是国际关系的基石，旨在维护主权。"}]},"noble":{"examples":[{"sentence":"Although the noble families of medieval Europe held significant power, their influence gradually waned with the rise of centralized states.","translation":"尽管中世纪欧洲的贵族家族拥有重大权力，但随着中央集权国家的兴起，他们的影响力逐渐减弱。"},{"sentence":"A noble act, such as donating a kidney to a stranger, demonstrates a profound commitment to altruism that transcends personal risk.","translation":"高尚的行为，如向陌生人捐献肾脏，体现了超越个人风险的深刻利他主义承诺。"},{"sentence":"Because the pursuit of knowledge is a noble endeavor, societies that invest in education tend to flourish over time.","translation":"由于追求知识是一项崇高的事业，投资于教育的社会往往会随着时间的推移而繁荣。"},{"sentence":"The noble gases, which are chemically inert, play a crucial role in lighting and welding due to their stability.","translation":"化学性质不活泼的稀有气体因其稳定性在照明和焊接中发挥着关键作用。"},{"sentence":"While the knight's intentions were noble, his rigid adherence to an outdated code of honor led to unnecessary conflict.","translation":"尽管骑士的意图是高尚的，但他对过时的荣誉准则的僵化遵守导致了不必要的冲突。"}]},"somewhere":{"examples":[{"sentence":"Although the ancient map indicated that the treasure was buried somewhere on the island, no one has yet discovered its exact location.","translation":"尽管古地图表明宝藏埋在岛上的某个地方，但至今无人发现其确切位置。"},{"sentence":"Because the noise level in the city center was unbearable, she decided to move somewhere quieter to improve her concentration.","translation":"由于市中心的噪音难以忍受，她决定搬到更安静的地方以提高注意力。"},{"sentence":"The missing file must be stored somewhere in the digital archive, which contains over a million documents from the past decade.","translation":"丢失的文件一定存储在数字档案的某个地方，该档案包含过去十年超过一百万份文件。"},{"sentence":"When the experiment failed to produce results, the researchers looked somewhere else for a more promising approach.","translation":"当实验未能产生结果时，研究人员在别处寻找更有前景的方法。"},{"sentence":"If you cannot find the book in the library, it might be placed somewhere on the shelves that are reserved for rare collections.","translation":"如果你在图书馆找不到那本书，它可能被放在为珍本保留的书架上的某个地方。"}]},"fair":{"examples":[{"sentence":"The annual trade fair, which attracts thousands of international exhibitors, provides a vital platform for networking and innovation.","translation":"一年一度的贸易展览会吸引了数千家国际参展商，为交流和创新提供了重要平台。"},{"sentence":"Because the job fair was well-organized, many graduates secured interviews with leading companies in their fields.","translation":"由于招聘会组织得当，许多毕业生获得了与所在领域顶尖公司的面试机会。"},{"sentence":"The book fair featured a special section on rare manuscripts, thereby drawing scholars from around the world.","translation":"书展设有珍稀手稿专区，从而吸引了世界各地的学者。"},{"sentence":"While the science fair encouraged creativity, it also emphasized the importance of practical applications in solving real-world problems.","translation":"科学博览会鼓励创造力的同时，也强调了实际应用在解决现实问题中的重要性。"},{"sentence":"The cultural fair not only showcased traditional arts but also offered workshops to ensure that these skills are passed on to younger generations.","translation":"文化展览会不仅展示了传统艺术，还举办了工作坊，以确保这些技艺传承给年轻一代。"}]},"bird":{"examples":[{"sentence":"The migratory bird returns to the same wetland each spring, which suggests a remarkable spatial memory.","translation":"这种候鸟每年春天都会回到同一片湿地，这表明它具有非凡的空间记忆。"},{"sentence":"Because the bird relies on a narrow range of seeds, habitat loss poses a serious threat to its survival.","translation":"由于这种鸟依赖少数几种种子，栖息地丧失对其生存构成了严重威胁。"},{"sentence":"Although the bird is small, its complex song serves both to attract mates and to defend territory.","translation":"尽管这种鸟体型很小，但其复杂的鸣叫既能吸引配偶，又能保卫领地。"},{"sentence":"Researchers have discovered that the bird adjusts its foraging strategy when food becomes scarce.","translation":"研究人员发现，当食物变得稀缺时，这种鸟会调整其觅食策略。"},{"sentence":"The bird constructs an elaborate nest from twigs and mud, which provides insulation against temperature extremes.","translation":"这种鸟用树枝和泥巴建造精巧的巢穴，以抵御极端温度。"}]},"sheet":{"examples":[{"sentence":"Although the sheet of paper was thin, it withstood the pressure of the printing press without tearing.","translation":"尽管这张纸很薄，但它承受住了印刷机的压力而没有撕裂。"},{"sentence":"The nurse changed the bed sheet daily to ensure a hygienic environment for the patient.","translation":"护士每天更换床单，以确保为病人提供卫生的环境。"},{"sentence":"Because the sheet of ice on the lake was dangerously thin, the authorities prohibited skating.","translation":"由于湖面上的冰层薄得危险，当局禁止了滑冰活动。"},{"sentence":"The accountant reviewed the balance sheet, which revealed a significant increase in liabilities.","translation":"会计审查了资产负债表，该表显示负债大幅增加。"},{"sentence":"When the sheet of metal is heated, it expands and becomes more malleable for shaping.","translation":"当金属薄板被加热时，它会膨胀并变得更易于塑形。"}]},"option":{"examples":[{"sentence":"Although online learning is a flexible option, it demands strong time-management skills to ensure academic success.","translation":"尽管在线学习是一种灵活的选择，但它需要强大的时间管理能力以确保学业成功。"},{"sentence":"When companies face budget cuts, offering voluntary redundancy is often a more humane option than compulsory layoffs.","translation":"当公司面临预算削减时，提供自愿离职通常是一种比强制裁员更人道的选择。"},{"sentence":"Because public transportation reduces carbon emissions, it is an environmentally responsible option that many cities are promoting.","translation":"由于公共交通减少碳排放，它是许多城市正在推广的一种对环境负责的选择。"},{"sentence":"The government introduced a tax incentive as an option to stimulate investment in underdeveloped regions, thereby creating jobs.","translation":"政府引入税收激励作为一种选择，以刺激对欠发达地区的投资，从而创造就业机会。"},{"sentence":"While studying abroad is an attractive option, students must consider the financial burden that it may impose on their families.","translation":"尽管出国留学是一个有吸引力的选择，但学生必须考虑它可能给家庭带来的经济负担。"}]},"awe":{"examples":[{"sentence":"The intricate design of the Gothic cathedral inspired a sense of awe that has attracted millions of visitors over the centuries.","translation":"哥特式大教堂的复杂设计激发了一种敬畏感，几个世纪以来吸引了数百万游客。"},{"sentence":"When astronauts first saw Earth from space, they were struck by an overwhelming awe that reshaped their perspective on humanity.","translation":"当宇航员首次从太空看到地球时，他们被一种压倒性的敬畏所震撼，这重塑了他们对人类的看法。"},{"sentence":"Although the documentary revealed the harsh realities of nature, it also evoked a profound awe for the resilience of wildlife.","translation":"尽管这部纪录片揭示了自然的严酷现实，但它也唤起了对野生动物韧性的深深敬畏。"},{"sentence":"The young pianist listened with awe as the maestro demonstrated a technique that took decades to perfect.","translation":"年轻的钢琴家怀着敬畏聆听大师展示一种花费数十年才完善的技术。"},{"sentence":"Because the ancient redwood forest has stood for millennia, it fills visitors with a timeless awe that words cannot fully capture.","translation":"由于古老的红杉林已经屹立了数千年，它让游客充满了一种言语无法完全捕捉的永恒敬畏。"}]},"yard":{"examples":[{"sentence":"The old factory yard, which had been abandoned for decades, was eventually transformed into a community garden.","translation":"那个废弃了几十年的旧工厂院子，最终被改造成了一个社区花园。"},{"sentence":"Because the construction yard was located near a residential area, the company had to implement strict noise-control measures.","translation":"由于施工场地靠近居民区，公司不得不实施严格的噪音控制措施。"},{"sentence":"Although the house itself was modest, the spacious yard provided ample room for children to play and for the family to host gatherings.","translation":"虽然房子本身不大，但宽敞的院子为孩子们玩耍和家庭聚会提供了充足的空间。"},{"sentence":"The freight yard operates around the clock to ensure that goods are transferred efficiently between trains and trucks.","translation":"货运站场昼夜不停地运转，以确保货物在火车和卡车之间高效转运。"},{"sentence":"A well-maintained yard not only enhances a property's curb appeal but also serves as a buffer against street noise.","translation":"一个精心维护的庭院不仅能提升房产的外观吸引力，还能起到缓冲街道噪音的作用。"}]},"would":{"examples":[{"sentence":"If governments invested more in renewable energy, carbon emissions would decline significantly over the next decade.","translation":"如果各国政府在可再生能源上投入更多，未来十年碳排放量将显著下降。"},{"sentence":"A well-designed curriculum would enable students to develop critical thinking skills that are essential for academic success.","translation":"精心设计的课程将使学生能够培养对学业成功至关重要的批判性思维能力。"},{"sentence":"Without consistent funding, many promising research projects would fail to reach their full potential.","translation":"如果没有持续的资金支持，许多有前景的研究项目将无法充分发挥其潜力。"},{"sentence":"Although the proposed policy is controversial, it would ultimately benefit communities that lack access to healthcare.","translation":"尽管这项拟议政策存在争议，但它最终将使缺乏医疗服务的社区受益。"},{"sentence":"Scholars who examine historical patterns would argue that economic inequality often leads to social unrest.","translation":"研究历史模式的学者会认为，经济不平等往往导致社会动荡。"}]},"frame":{"examples":[{"sentence":"Although the picture frame was inexpensive, it complemented the artwork so well that it appeared custom-made.","translation":"虽然这个画框不贵，但它与艺术品搭配得如此协调，看起来像是定制的。"},{"sentence":"The legal frame of the new policy, which was drafted after extensive consultation, aims to protect consumers from fraudulent practices.","translation":"新政策的法律框架经过广泛咨询后起草，旨在保护消费者免受欺诈行为。"},{"sentence":"Because his slender frame belied his strength, opponents often underestimated him in competitions.","translation":"因为他瘦削的体格掩盖了他的力量，对手在比赛中常常低估他。"},{"sentence":"To frame the issue in a more positive light, the spokesperson emphasized the potential benefits rather than the temporary setbacks.","translation":"为了以更积极的方式表述这个问题，发言人强调了潜在的好处而不是暂时的挫折。"},{"sentence":"The bicycle's lightweight frame, which is made of carbon fiber, allows for greater speed and maneuverability on rough terrain.","translation":"自行车的轻质车架由碳纤维制成，使其在崎岖地形上具有更高的速度和机动性。"}]},"chocolate":{"examples":[{"sentence":"Although chocolate is often associated with indulgence, its moderate consumption has been linked to a reduced risk of heart disease.","translation":"虽然巧克力常与放纵联系在一起，但适量食用与降低心脏病风险有关。"},{"sentence":"The chocolate fondue fountain, which was the centerpiece of the dessert table, attracted guests of all ages throughout the evening.","translation":"巧克力喷泉作为甜点桌的中心装饰，整个晚上吸引了各个年龄段的客人。"},{"sentence":"Because the recipe called for unsweetened chocolate, the baker had to adjust the sugar content to achieve the desired flavor.","translation":"因为食谱要求使用无糖巧克力，面包师不得不调整糖的含量以达到理想的风味。"},{"sentence":"When the chocolate is tempered correctly, it produces a glossy finish and a satisfying snap that indicates high quality.","translation":"当巧克力正确调温时，它会产生光泽的表面和令人满意的脆裂声，这表明其高品质。"},{"sentence":"The company's decision to source chocolate from sustainable farms not only improved its brand image but also supported local communities.","translation":"该公司从可持续农场采购巧克力的决定不仅改善了其品牌形象，还支持了当地社区。"}]},"lawn":{"examples":[{"sentence":"Although a well-kept lawn enhances curb appeal, it often demands significant water and chemical inputs that can harm the environment.","translation":"虽然精心维护的草坪能提升外观吸引力，但它通常需要大量的水和化学品，这可能对环境造成危害。"},{"sentence":"The expansive lawn in front of the library, which is shaded by ancient oak trees, provides a serene spot for reading on sunny afternoons.","translation":"图书馆前那片被古老橡树遮蔽的广阔草坪，为晴朗的午后提供了一个宁静的阅读场所。"},{"sentence":"Because the lawn was saturated after the heavy rain, the gardeners postponed the mowing until the ground had dried sufficiently.","translation":"因为大雨后草坪浸水，园丁们推迟了修剪，直到地面充分干燥。"},{"sentence":"When designing the park, the architects included a large central lawn to ensure that visitors had ample space for recreational activities.","translation":"在设计公园时，建筑师们包括了一个大型中央草坪，以确保游客有充足的空间进行娱乐活动。"},{"sentence":"The new homeowners replaced their traditional lawn with a drought-resistant landscape, thereby reducing their water bill by half.","translation":"新房主用耐旱景观取代了传统的草坪，从而将水费减少了一半。"}]},"purpose":{"examples":[{"sentence":"The primary purpose of higher education is to cultivate critical thinking rather than merely to transmit factual knowledge.","translation":"高等教育的主要目的是培养批判性思维，而不仅仅是传授事实性知识。"},{"sentence":"Although the committee was formed for a specific purpose, its scope gradually expanded to address broader social issues.","translation":"尽管该委员会是为特定目的而成立的，但其范围逐渐扩大到解决更广泛的社会问题。"},{"sentence":"A well-defined research purpose enables scholars to design methodologies that yield meaningful and replicable results.","translation":"明确的研究目的使学者能够设计出产生有意义且可复制结果的方法。"},{"sentence":"Governments often impose taxes not only to raise revenue but also for the purpose of discouraging harmful behaviors.","translation":"政府征税往往不仅是为了增加收入，还为了抑制有害行为。"},{"sentence":"Because the purpose of the initiative was poorly communicated, many participants misunderstood its long-term objectives.","translation":"由于该倡议的目的传达不清，许多参与者误解了其长期目标。"}]},"auxiliary":{"examples":[{"sentence":"Although the main generator failed, the auxiliary power system kept the hospital running without interruption.","translation":"虽然主发电机发生故障，但辅助电力系统使医院不间断地运行。"},{"sentence":"The research team used an auxiliary hypothesis to explain the unexpected results, which strengthened their overall argument.","translation":"研究团队使用了一个辅助假设来解释意外结果，这加强了他们的整体论证。"},{"sentence":"Because the primary cooling mechanism was insufficient, engineers installed an auxiliary unit to prevent overheating.","translation":"由于主冷却机制不足，工程师安装了一个辅助装置以防止过热。"},{"sentence":"In many organizations, auxiliary staff handle logistical tasks, thereby allowing specialists to focus on core responsibilities.","translation":"在许多组织中，辅助人员处理后勤任务，从而使专家能够专注于核心职责。"},{"sentence":"The spacecraft is equipped with an auxiliary communication channel that ensures contact even if the main system fails.","translation":"航天器配备了一个辅助通信信道，即使主系统发生故障也能确保联系。"}]},"vast":{"examples":[{"sentence":"Although the Sahara Desert is vast, its ecosystem remains fragile and susceptible to climate change.","translation":"尽管撒哈拉沙漠辽阔，其生态系统依然脆弱且易受气候变化影响。"},{"sentence":"The vast majority of scholars agree that early intervention is crucial, which justifies increased funding for preschool programs.","translation":"绝大多数学者认为早期干预至关重要，这为增加学前教育项目拨款提供了理由。"},{"sentence":"Because the universe is so vast, the probability of extraterrestrial life existing elsewhere seems plausible to many scientists.","translation":"由于宇宙如此浩瀚，许多科学家认为地外生命存在的可能性是合理的。"},{"sentence":"The company amassed a vast amount of consumer data, thereby enabling highly targeted advertising campaigns.","translation":"该公司积累了海量的消费者数据，从而实现了高度精准的广告投放。"},{"sentence":"While the library houses a vast collection of rare manuscripts, access is restricted to accredited researchers to ensure preservation.","translation":"尽管该图书馆藏有大量珍贵手稿，但仅限认证研究人员查阅以确保保存。"}]},"greedy":{"examples":[{"sentence":"Although ambition can drive progress, an excessively greedy pursuit of wealth may undermine social cohesion and ethical standards.","translation":"尽管雄心能推动进步，但对财富过度贪婪的追求可能破坏社会凝聚力和道德标准。"},{"sentence":"Corporations that prioritize short-term profits over environmental responsibility are often criticized for being greedy, which damages their long-term reputation.","translation":"那些将短期利润置于环境责任之上的企业常因贪婪而受到批评，这损害了它们的长期声誉。"},{"sentence":"The greedy exploitation of natural resources has led to irreversible ecological damage, thereby threatening the survival of numerous species.","translation":"对自然资源的贪婪开采已导致不可逆转的生态破坏，从而威胁到众多物种的生存。"},{"sentence":"Investors who are too greedy often ignore warning signs, which ultimately leads to significant financial losses and market instability.","translation":"过于贪婪的投资者常常忽视警示信号，最终导致重大的财务损失和市场不稳定。"},{"sentence":"A greedy algorithm may yield a locally optimal solution but fail to find the global optimum, which limits its applicability in complex problems.","translation":"贪婪算法可能产生局部最优解，但无法找到全局最优解，这限制了它在复杂问题中的适用性。"}]},"considerate":{"examples":[{"sentence":"A considerate colleague always shares relevant resources before a meeting, which helps everyone prepare more effectively.","translation":"一位体贴的同事总会在会议前分享相关资源，这有助于每个人更有效地做好准备。"},{"sentence":"Because the professor was considerate enough to extend the deadline during the campus-wide power outage, students could submit their work without penalty.","translation":"由于教授在全校停电期间体贴地延长了截止日期，学生们得以不受处罚地提交作业。"},{"sentence":"Designing public spaces that are considerate of elderly residents, such as by adding benches and ramps, fosters a more inclusive community.","translation":"设计体贴老年人的公共空间，例如增设长椅和坡道，有助于营造更具包容性的社区。"},{"sentence":"Although the policy was intended to be considerate of employees' family needs, its rigid scheduling requirements inadvertently created new burdens.","translation":"尽管该政策本意是体贴员工的家庭需求，但其僵化的排班要求无意中造成了新的负担。"},{"sentence":"It is considerate to mute your microphone during virtual meetings unless you are speaking, as background noise can distract other participants.","translation":"在虚拟会议中，除非你在发言，否则将麦克风静音是一种体贴的做法，因为背景噪音会分散其他参与者的注意力。"}]},"abrupt":{"examples":[{"sentence":"Although the policy shift was abrupt, the organization managed to adapt quickly because it had a robust contingency plan in place.","translation":"尽管政策转变很突然，但该组织由于制定了健全的应急计划，得以迅速适应。"},{"sentence":"The professor's abrupt departure from the lecture hall, which occurred without any explanation, left the students confused and concerned.","translation":"教授突然离开讲堂，没有任何解释，让学生们感到困惑和担忧。"},{"sentence":"When a leader makes an abrupt decision without consulting the team, it can undermine trust and morale within the organization.","translation":"当领导者未经团队协商就做出突然的决定时，可能会破坏组织内部的信任和士气。"},{"sentence":"The novel's abrupt shift in narrative perspective, while initially jarring, ultimately serves to highlight the protagonist's fragmented mental state.","translation":"小说叙事视角的突然转变，虽然起初令人不适，但最终有助于凸显主人公支离破碎的精神状态。"},{"sentence":"Because the economic downturn was so abrupt, many small businesses were unable to secure loans in time to prevent bankruptcy.","translation":"由于经济衰退如此突然，许多小企业未能及时获得贷款以防止破产。"}]},"agony":{"examples":[{"sentence":"The agony of losing a loved one can be compounded by unresolved guilt, which makes the grieving process even more challenging.","translation":"失去亲人的痛苦可能因未解决的愧疚感而加剧，这使得悲伤过程更具挑战性。"},{"sentence":"Although modern medicine can alleviate physical agony, the psychological torment of chronic illness often requires long-term therapy.","translation":"尽管现代医学可以减轻身体上的痛苦，但慢性病带来的心理折磨往往需要长期治疗。"},{"sentence":"The athlete endured the agony of a career-ending injury, yet she channeled her experience into mentoring young players, thereby finding a new purpose.","translation":"这位运动员忍受了终结职业生涯的伤痛，但她将自己的经历用于指导年轻球员，从而找到了新的目标。"},{"sentence":"When a society ignores the agony of marginalized groups, it risks fostering deep-seated resentment that can erupt into social unrest.","translation":"当一个社会忽视边缘群体的痛苦时，它就有可能助长根深蒂固的怨恨，这种怨恨可能爆发为社会动荡。"},{"sentence":"The agony of making ethical decisions in wartime is a recurring theme in literature, which forces readers to confront the complexities of human morality.","translation":"战时做出伦理决策的痛苦是文学中反复出现的主题，它迫使读者直面人类道德的复杂性。"}]},"club":{"examples":[{"sentence":"Although the astronomy club has limited funding, it provides students with access to high-quality telescopes for research.","translation":"尽管天文俱乐部资金有限，但它为学生提供了用于研究的高质量望远镜。"},{"sentence":"Because the film club screens classic movies every Friday, members develop a deeper appreciation for cinematic history.","translation":"由于电影俱乐部每周五放映经典电影，成员们对电影史有了更深的鉴赏力。"},{"sentence":"The robotics club, which collaborates with local engineering firms, gives students hands-on experience in designing automated systems.","translation":"机器人俱乐部与当地工程公司合作，为学生提供了设计自动化系统的实践经验。"},{"sentence":"When the hiking club organizes weekend excursions, participants not only improve their fitness but also explore remote natural landscapes.","translation":"当远足俱乐部组织周末短途旅行时，参与者不仅提高了体能，还探索了偏远的自然景观。"},{"sentence":"The chess club fosters strategic thinking through regular tournaments, thereby enhancing members' problem-solving abilities.","translation":"国际象棋俱乐部通过定期比赛培养战略思维，从而提高了成员解决问题的能力。"}]},"superb":{"examples":[{"sentence":"The architect's superb design integrates sustainable materials with modern aesthetics, thereby setting a new standard for eco-friendly buildings.","translation":"建筑师卓越的设计将可持续材料与现代美学相结合，从而为环保建筑设立了新标准。"},{"sentence":"Because the chef used superb culinary techniques, the simple ingredients were transformed into an exquisite dish.","translation":"由于厨师运用了高超的烹饪技巧，简单的食材被转化为一道精致的菜肴。"},{"sentence":"Although the novel has a complex plot, the author's superb storytelling keeps readers engaged until the final page.","translation":"尽管这部小说情节复杂，但作者高超的叙事技巧让读者一直读到最后一页。"},{"sentence":"The athlete's superb coordination and agility, which result from years of rigorous training, give her a competitive edge.","translation":"这位运动员出色的协调性和敏捷性源于多年的严格训练，这使她具有竞争优势。"},{"sentence":"When the company launched its superb customer service platform, client satisfaction rates increased dramatically within months.","translation":"当公司推出其卓越的客户服务平台时，客户满意度在几个月内大幅提升。"}]},"authority":{"examples":[{"sentence":"Although the professor is a leading authority on climate policy, her recommendations were not adopted by the government.","translation":"尽管这位教授是气候政策方面的权威，她的建议并未被政府采纳。"},{"sentence":"The local authority implemented a new recycling program, which significantly reduced waste in the community.","translation":"地方当局实施了一项新的回收计划，这显著减少了社区的垃圾。"},{"sentence":"Because the manager delegated authority to her team, they were able to make decisions quickly and efficiently.","translation":"因为经理将权力下放给她的团队，他们能够迅速而高效地做出决定。"},{"sentence":"When a government exceeds its legal authority, the judiciary must intervene to uphold the constitution.","translation":"当政府超越其法定权力时，司法机构必须介入以维护宪法。"},{"sentence":"Citing an authority on ancient history, the author argued that the artifact was much older than previously thought.","translation":"作者引用了一位古代史权威的观点，认为这件文物比之前认为的要古老得多。"}]},"ideology":{"examples":[{"sentence":"Although the ideology of consumerism drives economic growth, it often leads to unsustainable resource depletion.","translation":"尽管消费主义意识形态推动了经济增长，但它往往导致不可持续的资源枯竭。"},{"sentence":"When a society adopts an ideology that prioritizes collective welfare, it may implement policies that reduce individual freedoms.","translation":"当一个社会采用优先考虑集体福利的意识形态时，它可能会实施减少个人自由的政策。"},{"sentence":"Because the dominant ideology in the organization emphasized innovation, employees were encouraged to take risks without fear of failure.","translation":"由于该组织的主流意识形态强调创新，员工被鼓励冒险而不必担心失败。"},{"sentence":"The new curriculum was designed to challenge the prevailing ideology, which had long neglected the contributions of minority groups.","translation":"新课程旨在挑战长期以来忽视少数群体贡献的主流意识形态。"},{"sentence":"While the ideology of meritocracy promises equal opportunity, it can obscure systemic barriers that perpetuate inequality.","translation":"尽管精英主义的意识形态承诺机会平等，但它可能掩盖使不平等长期存在的系统性障碍。"}]},"take":{"examples":[{"sentence":"If we take a proactive approach to learning, we can acquire skills that are essential for career advancement.","translation":"如果我们采取主动的学习方法，就能获得对职业发展至关重要的技能。"},{"sentence":"Although the new policy will take effect next month, its impact on small businesses remains uncertain.","translation":"尽管新政策将于下个月生效，但其对小企业的影响仍不确定。"},{"sentence":"When researchers take ethical considerations into account, they ensure that their studies do not harm participants.","translation":"当研究人员考虑到伦理因素时，他们确保其研究不会伤害参与者。"},{"sentence":"Because the project will take considerable resources, we must prioritize tasks to stay within budget.","translation":"由于该项目将耗费大量资源，我们必须确定任务的优先顺序以保持在预算之内。"},{"sentence":"Students who take advantage of internship opportunities often gain practical experience that enhances their employability.","translation":"利用实习机会的学生往往能获得实践经验，从而提高他们的就业能力。"}]},"recollect":{"examples":[{"sentence":"When I recollect the challenges I faced during my first year of graduate school, I appreciate how much I have grown.","translation":"当我回忆起研究生第一年面临的挑战时，我感激自己的成长。"},{"sentence":"Although she could not recollect the exact source of the data, she was confident in the overall findings of the study.","translation":"尽管她无法回忆起数据的确切来源，但她对研究的总体发现充满信心。"},{"sentence":"If you try to recollect the key points from the lecture, you will find it easier to write a comprehensive summary.","translation":"如果你试着回忆讲座的要点，你会发现写一份全面的总结更容易。"},{"sentence":"Because the witness struggled to recollect the sequence of events, the lawyer presented photographic evidence to aid her memory.","translation":"由于证人难以回忆起事件的顺序，律师出示了照片证据来帮助她回忆。"},{"sentence":"The ability to recollect past experiences accurately is a skill that can be improved through regular practice and reflection.","translation":"准确回忆过去经历的能力是一种可以通过定期练习和反思来提高的技能。"}]},"bite":{"examples":[{"sentence":"A single mosquito bite can transmit diseases that pose serious public health risks.","translation":"一次蚊虫叮咬就能传播构成严重公共卫生风险的疾病。"},{"sentence":"Although the initial bite of economic reform may be painful, it often leads to long-term prosperity.","translation":"尽管经济改革最初的阵痛可能令人痛苦，但它通常会带来长期繁荣。"},{"sentence":"The researcher took a bite of the apple to demonstrate that it was safe for consumption.","translation":"研究人员咬了一口苹果，以证明它可以安全食用。"},{"sentence":"Because the frost had a sharp bite, farmers took extra measures to protect their crops.","translation":"由于严寒刺骨，农民们采取了额外措施来保护庄稼。"},{"sentence":"The editor's critique had a constructive bite that ultimately improved the manuscript.","translation":"编辑的批评具有建设性的尖锐，最终改进了稿件。"}]},"individual":{"examples":[{"sentence":"Although an individual may possess limited resources, collective action can amplify their impact on social issues.","translation":"尽管个人可能拥有有限的资源，但集体行动可以放大他们对社会问题的影响。"},{"sentence":"Because each individual contributes unique perspectives, diverse teams often produce more innovative solutions.","translation":"因为每个个体贡献独特的视角，多元化的团队往往能产生更具创新性的解决方案。"},{"sentence":"While society emphasizes conformity, the courage of an individual to challenge norms can lead to transformative progress.","translation":"虽然社会强调一致性，但个人挑战规范的勇气可以带来变革性的进步。"},{"sentence":"The policy was designed to protect the rights of every individual, thereby ensuring equal opportunities for all citizens.","translation":"该政策旨在保护每个个体的权利，从而确保所有公民的平等机会。"},{"sentence":"When an individual engages in lifelong learning, they are better equipped to adapt to rapid technological changes.","translation":"当个人进行终身学习时，他们能更好地适应快速的技术变革。"}]},"forget":{"examples":[{"sentence":"When designing public policy, we must not forget that vulnerable groups often face barriers that the majority does not encounter.","translation":"在制定公共政策时，我们绝不能忘记弱势群体常常面临多数人不会遇到的障碍。"},{"sentence":"Although the immediate crisis has passed, we should not forget the lessons it taught us about the fragility of global supply chains.","translation":"尽管眼前的危机已经过去，但我们不应忘记它给我们带来的关于全球供应链脆弱性的教训。"},{"sentence":"In the pursuit of efficiency, organizations sometimes forget that employee well-being is essential for long-term productivity.","translation":"在追求效率的过程中，组织有时会忘记员工福祉对于长期生产力至关重要。"},{"sentence":"Historians caution that societies which forget their past mistakes are more likely to repeat them in the future.","translation":"历史学家告诫说，忘记过去错误的社会更有可能在未来重蹈覆辙。"},{"sentence":"While focusing on academic achievement, educators should not forget to nurture students' creativity and critical thinking skills.","translation":"在关注学业成绩的同时，教育者不应忘记培养学生的创造力和批判性思维能力。"}]},"fox":{"examples":[{"sentence":"The red fox, which has adapted remarkably well to urban environments, can now be found in many cities across the world.","translation":"赤狐已经非常出色地适应了城市环境，如今在世界许多城市都能见到其踪迹。"},{"sentence":"Because the fox plays a crucial role in controlling rodent populations, its presence benefits agricultural ecosystems.","translation":"由于狐狸在控制啮齿动物数量方面起着关键作用，它的存在对农业生态系统有益。"},{"sentence":"Although the fox is often portrayed as cunning in folklore, its behavior is primarily driven by survival instincts rather than calculated deception.","translation":"尽管狐狸在民间传说中常被描绘成狡猾的形象，但其行为主要是由生存本能而非精心算计的欺骗所驱动。"},{"sentence":"The decline of the Arctic fox population, which is linked to climate change and competition from red foxes, has raised conservation concerns.","translation":"北极狐数量的下降与气候变化及来自赤狐的竞争有关，这引发了保护方面的担忧。"},{"sentence":"In many cultures, the fox symbolizes adaptability and intelligence, traits that are highly valued in rapidly changing societies.","translation":"在许多文化中，狐狸象征着适应能力和智慧，这些特质在快速变化的社会中备受推崇。"}]},"sequence":{"examples":[{"sentence":"Understanding the correct sequence of steps in the experiment is crucial, because even a minor deviation can compromise the results.","translation":"理解实验中步骤的正确顺序至关重要，因为即使微小的偏差也可能影响结果。"},{"sentence":"The historian argued that the sequence of economic reforms, rather than any single policy, led to the nation's rapid development.","translation":"这位历史学家认为，是一系列经济改革的顺序，而非任何单一政策，促成了该国的快速发展。"},{"sentence":"By analyzing the sequence of genes responsible for drought resistance, scientists hope to engineer crops that can thrive in arid regions.","translation":"通过分析负责抗旱性的基因序列，科学家们希望培育出能在干旱地区茁壮成长的作物。"},{"sentence":"Although the film's non-linear sequence of events initially confused viewers, it ultimately provided a deeper understanding of the protagonist's motives.","translation":"尽管影片非线性的事件顺序起初让观众感到困惑，但最终它使人们更深刻地理解了主角的动机。"},{"sentence":"The software automatically arranges the data into a logical sequence, which allows researchers to identify patterns more efficiently.","translation":"该软件自动将数据排列成逻辑顺序，使研究人员能够更有效地识别模式。"}]},"century":{"examples":[{"sentence":"Although the cathedral was built in the twelfth century, its foundations rest on a Roman temple that dates back even further.","translation":"尽管这座大教堂建于12世纪，但其地基却坐落在一座历史更久远的罗马神庙之上。"},{"sentence":"Because the Industrial Revolution transformed economies in the nineteenth century, it also reshaped social hierarchies and urban life.","translation":"由于工业革命在19世纪改变了经济，它也重塑了社会等级制度和城市生活。"},{"sentence":"The philosophical movements of the eighteenth century, which emphasized reason and individual rights, profoundly influenced modern political thought.","translation":"18世纪的哲学运动强调理性和个人权利，深刻影响了现代政治思想。"},{"sentence":"When we examine the twentieth century, we see that medical breakthroughs dramatically increased life expectancy worldwide.","translation":"当我们审视20世纪时，我们发现医学突破极大地提高了全球预期寿命。"},{"sentence":"The twenty-first century poses unprecedented challenges, such as climate change, that require global cooperation to address effectively.","translation":"21世纪带来了前所未有的挑战，如气候变化，需要全球合作才能有效应对。"}]},"scrap":{"examples":[{"sentence":"The detective found a scrap of fabric at the crime scene, which later became crucial evidence in the trial.","translation":"侦探在犯罪现场发现了一小块织物，后来成为审判中的关键证据。"},{"sentence":"Although she had only a scrap of experience in programming, she quickly learned through online courses.","translation":"虽然她只有一点编程经验，但她通过在线课程迅速学会了。"},{"sentence":"The company decided to scrap the outdated project rather than invest more resources into it.","translation":"公司决定废弃这个过时的项目，而不是投入更多资源。"},{"sentence":"He wrote the phone number on a scrap of paper, which he then accidentally threw away with the trash.","translation":"他把电话号码写在一张纸片上，然后不小心和垃圾一起扔掉了。"},{"sentence":"Without a scrap of evidence to support his claim, the argument was dismissed by the committee.","translation":"由于没有一丝证据支持他的主张，该论点被委员会驳回。"}]},"mischief":{"examples":[{"sentence":"Although the software glitch seemed minor, it caused considerable mischief to the company's database.","translation":"尽管这个软件故障看似微小，但它对公司的数据库造成了相当大的损害。"},{"sentence":"The new policy was implemented to prevent financial mischief, which had previously led to significant losses.","translation":"这项新政策是为了防止金融危害行为而实施的，这种行为此前曾导致重大损失。"},{"sentence":"Because the children were left unsupervised, their mischief resulted in a broken window and a flooded kitchen.","translation":"由于孩子们无人看管，他们的恶作剧导致了一扇窗户被打破和厨房被水淹。"},{"sentence":"The journalist's article exposed the political mischief that had undermined public trust in the election process.","translation":"这位记者的文章揭露了破坏公众对选举过程信任的政治危害行为。"},{"sentence":"While his colleagues appreciated his humor, his constant mischief during meetings often derailed important discussions.","translation":"尽管同事们欣赏他的幽默，但他在会议期间不断的恶作剧常常使重要讨论偏离正轨。"}]},"leap":{"examples":[{"sentence":"The leap in online sales, which was driven by the pandemic, has permanently changed consumer behavior.","translation":"由疫情推动的在线销售激增，永久性地改变了消费者行为。"},{"sentence":"While a leap in technology can boost productivity, it may also lead to job displacement.","translation":"虽然技术的飞跃可以提高生产力，但也可能导致工作岗位流失。"},{"sentence":"The company's leap from a local brand to a global player was achieved through strategic partnerships.","translation":"该公司通过战略合作伙伴关系，实现了从本土品牌到全球参与者的飞跃。"},{"sentence":"Taking a leap of faith, she invested in the startup, which later became a unicorn.","translation":"她抱着信念冒险投资了那家初创公司，后来它成为了一家独角兽企业。"},{"sentence":"A leap in renewable energy capacity is essential if we are to meet climate targets.","translation":"如果我们要实现气候目标，可再生能源产能的飞跃至关重要。"}]},"concert":{"examples":[{"sentence":"The charity concert, which featured renowned musicians, raised significant funds for disaster relief.","translation":"这场有著名音乐家参与的慈善音乐会，为救灾筹集了大量资金。"},{"sentence":"Because the concert was sold out, many fans were disappointed.","translation":"因为音乐会门票售罄，许多粉丝感到失望。"},{"sentence":"The two departments worked in concert to ensure the project was completed on time.","translation":"两个部门协同合作，以确保项目按时完成。"},{"sentence":"Attending a live concert can be a transformative experience, thereby fostering a lifelong love for music.","translation":"参加现场音乐会可以是一种变革性的体验，从而培养对音乐的终身热爱。"},{"sentence":"Although the concert was delayed by technical issues, the audience remained patient.","translation":"尽管音乐会因技术问题而延迟，但观众仍然保持耐心。"}]},"output":{"examples":[{"sentence":"Although the factory operated around the clock, its output still fell short of the quarterly target.","translation":"尽管工厂昼夜不停地运转，其产量仍未达到季度目标。"},{"sentence":"The agricultural output of the region declined sharply because a prolonged drought affected crop yields.","translation":"该地区的农业产量急剧下降，因为长期干旱影响了作物收成。"},{"sentence":"When the new software was implemented, the team's output of code increased by thirty percent.","translation":"当新软件实施后，团队的代码产出增加了百分之三十。"},{"sentence":"A country's economic output, which is often measured by GDP, reflects its overall productive capacity.","translation":"一个国家的经济产出，通常以国内生产总值衡量，反映了其整体生产能力。"},{"sentence":"The research institute's output of peer-reviewed papers has doubled, thereby enhancing its academic reputation.","translation":"该研究所的同行评审论文产出翻了一番，从而提升了其学术声誉。"}]},"scale":{"examples":[{"sentence":"The project was implemented on a national scale, which required coordination among multiple government agencies and private stakeholders.","translation":"该项目在全国范围内实施，这需要多个政府机构和私人利益相关者之间的协调。"},{"sentence":"Economies of scale enabled the manufacturer to reduce unit costs significantly, thereby gaining a competitive edge in the global market.","translation":"规模经济使制造商能够大幅降低单位成本，从而在全球市场中获得竞争优势。"},{"sentence":"Researchers used a five-point scale to measure participants' satisfaction, ensuring that the data could be analyzed with standard statistical methods.","translation":"研究人员使用五点量表来衡量参与者的满意度，确保数据可以用标准统计方法进行分析。"},{"sentence":"The Richter scale, which quantifies the energy released by an earthquake, remains a crucial tool for assessing seismic hazards.","translation":"里氏震级量化了地震释放的能量，它仍然是评估地震灾害的关键工具。"},{"sentence":"Because the map was drawn to a scale of 1:50,000, even small geographical features were represented with remarkable accuracy.","translation":"由于该地图是按1:50000的比例绘制的，即使是微小的地理特征也被极其精确地呈现出来。"}]},"jargon":{"examples":[{"sentence":"Although medical jargon facilitates precise communication among doctors, it often confuses patients who are not familiar with the terminology.","translation":"尽管医学术语有助于医生之间的精确交流，但它常常使不熟悉术语的患者感到困惑。"},{"sentence":"The professor urged students to avoid legal jargon when drafting public notices, because clarity is essential for ensuring that citizens understand their rights.","translation":"教授敦促学生在起草公告时避免使用法律术语，因为清晰性对于确保公民理解其权利至关重要。"},{"sentence":"While technical jargon can enhance efficiency within a specialized field, it creates a barrier that prevents interdisciplinary collaboration.","translation":"虽然技术术语可以提高专业领域内的效率，但它却形成了阻碍跨学科合作的障碍。"},{"sentence":"The report demystified the financial jargon surrounding derivatives, thereby enabling retail investors to make more informed decisions.","translation":"该报告揭开了围绕衍生品的金融术语的神秘面纱，从而使散户投资者能够做出更明智的决策。"},{"sentence":"Because the software manual was filled with unnecessary jargon, many users found it inaccessible, which led to a surge in customer support calls.","translation":"由于软件手册充满了不必要的行话，许多用户觉得难以理解，这导致客户支持电话激增。"}]},"power":{"examples":[{"sentence":"Although renewable power sources are becoming more affordable, many regions still rely heavily on fossil fuels.","translation":"尽管可再生能源正变得越来越便宜，许多地区仍然严重依赖化石燃料。"},{"sentence":"The committee's power to veto legislation ensures that no single branch can dominate the government.","translation":"委员会否决立法的权力确保没有任何一个分支能够主导政府。"},{"sentence":"Because economic power is shifting toward emerging markets, global trade patterns are undergoing significant changes.","translation":"由于经济权力正转向新兴市场，全球贸易格局正在经历重大变化。"},{"sentence":"The statistical power of a study determines its ability to detect true effects, which is why researchers prioritize large sample sizes.","translation":"一项研究的统计功效决定了其检测真实效应的能力，这就是研究人员优先考虑大样本量的原因。"},{"sentence":"Nuclear power plants must adhere to strict safety protocols, thereby minimizing the risk of catastrophic accidents.","translation":"核电站必须遵守严格的安全规程，从而将灾难性事故的风险降至最低。"}]},"yellow":{"examples":[{"sentence":"The yellow hue of autumn leaves results from the breakdown of chlorophyll, which reveals underlying pigments.","translation":"秋叶的黄色是由于叶绿素分解，显露出底层的色素。"},{"sentence":"In many cultures, yellow symbolizes warmth and happiness, which is why it is often used in festive decorations.","translation":"在许多文化中，黄色象征温暖和幸福，因此常用于节日装饰。"},{"sentence":"The artist chose a vivid yellow to highlight the focal point of the painting, thereby drawing the viewer's eye immediately.","translation":"艺术家选用鲜艳的黄色来突出画作的焦点，从而立即吸引了观众的目光。"},{"sentence":"Although yellow is often associated with caution, it can also convey optimism when used in design.","translation":"尽管黄色常与警示联系在一起，但在设计中也能传达乐观情绪。"},{"sentence":"The yellow sandstorms that sweep across the region have intensified because prolonged drought and deforestation have degraded the land.","translation":"席卷该地区的黄色沙尘暴愈演愈烈，因为长期干旱和森林砍伐使土地退化。"}]},"marginal":{"examples":[{"sentence":"The study found only a marginal improvement in student performance after the new teaching method was implemented, which suggests that further refinement is needed.","translation":"研究发现，实施新教学方法后，学生的表现仅有微小的改善，这表明需要进一步改进。"},{"sentence":"Economists argue that marginal cost analysis is essential for determining optimal production levels, because it helps firms maximize profit.","translation":"经济学家认为，边际成本分析对于确定最优生产水平至关重要，因为它有助于企业实现利润最大化。"},{"sentence":"Although the policy had a marginal impact on overall employment, it significantly benefited workers in remote areas.","translation":"尽管该政策对总体就业影响甚微，却使偏远地区的工人显著受益。"},{"sentence":"The marginal notes in the ancient manuscript provided valuable insights into the author's original intentions, which scholars had long debated.","translation":"古代手稿中的旁注为理解作者的原意提供了宝贵的见解，而学者们对此长期争论不休。"},{"sentence":"Because the company focused on marginal cost reduction, it was able to increase profitability without raising prices.","translation":"由于公司专注于降低边际成本，它得以在不提价的情况下提高盈利能力。"}]},"nature":{"examples":[{"sentence":"Because the nature of scientific inquiry demands rigorous evidence, researchers must design experiments that can be replicated by independent teams.","translation":"由于科学探究的性质要求严格的证据，研究人员必须设计能够被独立团队重复的实验。"},{"sentence":"Although human nature inclines us toward immediate gratification, long-term goals often require the discipline to delay rewards.","translation":"尽管人类的本性倾向于即时满足，但长期目标往往需要延迟奖励的自律。"},{"sentence":"The collaborative nature of modern engineering projects means that effective communication is as crucial as technical expertise.","translation":"现代工程项目的协作性质意味着有效沟通与技术专长同样至关重要。"},{"sentence":"While nature provides the raw materials for countless innovations, it is human ingenuity that transforms them into practical solutions.","translation":"虽然大自然为无数创新提供了原材料，但将其转化为实用解决方案的是人类的聪明才智。"},{"sentence":"Understanding the dynamic nature of ecosystems helps policymakers craft regulations that balance economic development with environmental protection.","translation":"理解生态系统的动态性质有助于决策者制定平衡经济发展与环境保护的法规。"}]},"foreign":{"examples":[{"sentence":"Although learning a foreign language requires consistent effort, the cognitive benefits it provides can last a lifetime.","translation":"尽管学习一门外语需要持续的努力，但它带来的认知益处可以持续一生。"},{"sentence":"Because foreign trade agreements often lower consumer prices, they can significantly improve the standard of living in participating nations.","translation":"由于对外贸易协定通常会降低消费者价格，它们能显著提高参与国人民的生活水平。"},{"sentence":"When a country relies heavily on foreign oil, its economy becomes vulnerable to global supply disruptions.","translation":"当一个国家严重依赖外国石油时，其经济容易受到全球供应中断的影响。"},{"sentence":"The study of foreign legal systems, which reveals alternative approaches to justice, can inspire meaningful reforms at home.","translation":"对外国法律体系的研究揭示了不同的司法途径，可以启发国内有意义的改革。"},{"sentence":"While foreign films often struggle at the box office, they enrich the cultural landscape by introducing diverse storytelling traditions.","translation":"虽然外国电影在票房上常常表现不佳，但它们通过引入多样的叙事传统丰富了文化景观。"}]},"publish":{"examples":[{"sentence":"Although the research team faced funding shortages, they managed to publish their groundbreaking findings in a top-tier journal.","translation":"尽管研究团队面临资金短缺，他们还是设法在顶级期刊上发表了开创性的发现。"},{"sentence":"The university press decided to publish the professor's manuscript because it offered a fresh perspective on ancient history.","translation":"大学出版社决定出版这位教授的手稿，因为它为古代史提供了新颖的视角。"},{"sentence":"When governments publish transparent data on public spending, citizens can hold officials accountable more effectively.","translation":"当政府公布透明的公共支出数据时，公民可以更有效地追究官员的责任。"},{"sentence":"To ensure academic integrity, journals should publish detailed peer-review reports alongside accepted articles.","translation":"为了确保学术诚信，期刊应在发表已接受文章的同时公布详细的同行评审报告。"},{"sentence":"Rather than publish unverified rumors, responsible media outlets verify facts through multiple independent sources.","translation":"负责任的媒体机构不会发表未经核实的谣言，而是通过多个独立来源核实事实。"}]},"budget":{"examples":[{"sentence":"Although the marketing team proposed an ambitious campaign, the finance department insisted on a more conservative budget to avoid overspending.","translation":"尽管营销团队提出了一个雄心勃勃的活动方案，但财务部门坚持采用更保守的预算以避免超支。"},{"sentence":"Because the city council allocated a significant budget to renewable energy projects, the region reduced its carbon emissions substantially.","translation":"由于市议会为可再生能源项目分配了大量预算，该地区大幅减少了碳排放。"},{"sentence":"When planning a conference, it is essential to create a detailed budget that accounts for venue costs, speaker fees, and promotional materials.","translation":"在规划会议时，制定一份详细的预算至关重要，其中要考虑到场地费用、演讲者酬金和宣传材料。"},{"sentence":"The nonprofit organization managed to expand its services despite a shrinking budget, thanks to efficient resource allocation and volunteer support.","translation":"尽管预算缩减，该非营利组织凭借高效的资源分配和志愿者支持，成功扩大了服务范围。"},{"sentence":"A well-structured budget not only prevents financial waste but also ensures that funds are directed toward high-priority initiatives.","translation":"一个结构良好的预算不仅能防止资金浪费，还能确保资金用于高优先级的项目。"}]},"authentic":{"examples":[{"sentence":"Although the painting was initially doubted, experts later confirmed it was an authentic work from the Renaissance period.","translation":"尽管这幅画最初受到质疑，专家后来确认它是文艺复兴时期的真迹。"},{"sentence":"Because the restaurant uses authentic regional recipes, it attracts customers who seek a genuine culinary experience.","translation":"因为这家餐厅使用地道的当地食谱，它吸引了寻求真实烹饪体验的顾客。"},{"sentence":"When conducting historical research, scholars must rely on authentic primary sources rather than secondary interpretations.","translation":"在进行历史研究时，学者必须依赖真实的一手资料，而非二手解读。"},{"sentence":"The museum's collection of authentic artifacts provides a tangible link to ancient civilizations, which fascinates visitors.","translation":"博物馆收藏的真品文物提供了与古代文明的有形联系，这令参观者着迷。"},{"sentence":"To ensure an authentic learning environment, the language program employs native speakers who share cultural insights.","translation":"为了确保真实的学习环境，该语言项目聘请母语者分享文化见解。"}]},"consolidate":{"examples":[{"sentence":"The company plans to consolidate its manufacturing facilities, thereby reducing overhead costs and improving efficiency.","translation":"公司计划整合其制造设施，从而降低间接成本并提高效率。"},{"sentence":"Because students often struggle with scattered notes, teachers recommend that they consolidate key concepts into summary sheets.","translation":"因为学生经常因笔记零散而苦恼，老师建议他们将关键概念整合到摘要表中。"},{"sentence":"When the new government came to power, it moved quickly to consolidate its authority by reforming the legal system.","translation":"新政府上台后，迅速通过改革法律体系来巩固其权威。"},{"sentence":"The merger allowed the two firms to consolidate their market share, which gave them a competitive edge over rivals.","translation":"这次合并使两家公司得以整合市场份额，这使它们比竞争对手更具优势。"},{"sentence":"If we consolidate the data from various departments, we can identify trends that were previously overlooked.","translation":"如果我们整合各部门的数据，就能发现之前被忽视的趋势。"}]},"tend":{"examples":[{"sentence":"Employees who work remotely tend to report higher job satisfaction, provided that they maintain a structured routine.","translation":"远程工作的员工往往报告更高的工作满意度，前提是他们保持有规律的作息。"},{"sentence":"Because early intervention can mitigate long-term issues, policymakers tend to prioritize preventive healthcare.","translation":"由于早期干预能缓解长期问题，政策制定者往往优先考虑预防性医疗。"},{"sentence":"Although digital tools offer convenience, students tend to retain information better when they take handwritten notes.","translation":"尽管数字工具提供了便利，但学生在手写笔记时往往能更好地记住信息。"},{"sentence":"Communities that invest in green infrastructure tend to experience lower pollution levels over time.","translation":"投资绿色基础设施的社区，随着时间的推移，往往污染水平更低。"},{"sentence":"When faced with complex decisions, people tend to rely on mental shortcuts, which can lead to systematic biases.","translation":"面对复杂决策时，人们倾向于依赖心理捷径，这可能导致系统性偏见。"}]},"erroneous":{"examples":[{"sentence":"Although the initial diagnosis was erroneous, the subsequent tests revealed the true nature of the illness.","translation":"尽管最初的诊断是错误的，但随后的检查揭示了疾病的真实性质。"},{"sentence":"The financial report was withdrawn because it contained erroneous data that misled investors.","translation":"那份财务报告被撤回，因为它包含了误导投资者的错误数据。"},{"sentence":"When a policy is based on erroneous assumptions, it often fails to achieve its intended outcomes.","translation":"当一项政策基于错误假设时，它往往无法实现预期结果。"},{"sentence":"The researcher's reputation suffered after the journal published an erroneous conclusion that contradicted established facts.","translation":"在该期刊发表了一个与既定事实相矛盾的错误结论后，那位研究者的声誉受损。"},{"sentence":"If the algorithm receives erroneous input, the entire system may produce unreliable predictions.","translation":"如果算法接收到错误的输入，整个系统可能会产生不可靠的预测。"}]},"tower":{"examples":[{"sentence":"The ancient bell tower, which has survived several earthquakes, remains a symbol of the city's resilience.","translation":"那座历经数次地震仍屹立不倒的古钟楼，依然是这座城市坚韧精神的象征。"},{"sentence":"Because the transmission tower was struck by lightning, the entire region experienced a prolonged power outage.","translation":"由于输电塔被闪电击中，整个地区经历了长时间的停电。"},{"sentence":"While the ivory tower is often criticized for isolating scholars, it can also foster groundbreaking research that benefits society.","translation":"尽管象牙塔常因使学者脱离现实而受批评，但它也能孕育出造福社会的突破性研究。"},{"sentence":"The observation tower offers a panoramic view of the valley, thereby attracting tourists and boosting the local economy.","translation":"观景塔提供了山谷的全景视野，从而吸引了游客并促进了当地经济。"},{"sentence":"Modern wind turbines tower over the countryside, generating clean energy while altering the traditional landscape.","translation":"现代风力涡轮机高耸于乡间，在改变传统景观的同时产生清洁能源。"}]},"dictate":{"examples":[{"sentence":"Although personal preferences vary, cultural traditions often dictate the rituals observed during major life events.","translation":"尽管个人偏好各异，文化传统往往决定了重大人生事件中遵循的仪式。"},{"sentence":"Because market trends can shift rapidly, companies should not allow short-term profits to dictate their long-term strategy.","translation":"由于市场趋势可能迅速变化，公司不应让短期利润支配其长期战略。"},{"sentence":"While technological advancements offer new possibilities, ethical considerations must dictate the boundaries of their application.","translation":"虽然技术进步提供了新的可能性，但伦理考量必须决定其应用的界限。"},{"sentence":"The availability of funding will ultimately dictate the scope of the research project, which aims to address climate change.","translation":"资金的可用性将最终决定该研究项目的范围，该项目旨在应对气候变化。"},{"sentence":"Rather than allowing fear to dictate their decisions, leaders should rely on data-driven analysis to navigate crises.","translation":"领导者不应让恐惧支配其决策，而应依靠数据驱动的分析来应对危机。"}]},"red":{"examples":[{"sentence":"Because red is associated with urgency, it is commonly used in warning signs to capture immediate attention.","translation":"由于红色与紧迫性相关，它通常用于警告标志中以立即引起注意。"},{"sentence":"In traditional Chinese weddings, the bride often wears a red dress, which symbolizes happiness and prosperity.","translation":"在中国传统婚礼中，新娘常穿红色礼服，这象征着幸福和繁荣。"},{"sentence":"When the traffic light turns red, all vehicles must come to a complete stop to ensure pedestrian safety.","translation":"当交通灯变红时，所有车辆必须完全停下，以确保行人安全。"},{"sentence":"The artist's use of a vivid red background creates a stark contrast that emphasizes the subject's isolation.","translation":"艺术家使用鲜艳的红色背景形成了鲜明对比，突出了主体的孤立感。"},{"sentence":"Although red is often linked to danger, it also represents passion and energy in many cultural contexts.","translation":"尽管红色常与危险联系在一起，但在许多文化语境中它也代表激情和活力。"}]},"throat":{"examples":[{"sentence":"Because the patient complained of a persistent sore throat, the doctor recommended a thorough examination to rule out any serious condition.","translation":"因为病人抱怨喉咙持续疼痛，医生建议进行彻底检查以排除任何严重情况。"},{"sentence":"The singer's throat felt dry after the long rehearsal, which prompted her to drink warm water with honey to soothe the irritation.","translation":"长时间排练后，歌手的喉咙感到干燥，这促使她喝温蜂蜜水来缓解不适。"},{"sentence":"Although he had a frog in his throat, the lecturer managed to deliver an inspiring speech that resonated with the audience.","translation":"尽管他喉咙沙哑，这位讲师还是设法发表了一场鼓舞人心的演讲，引起了听众的共鸣。"},{"sentence":"The child accidentally swallowed a small object that became lodged in his throat, requiring immediate medical intervention.","translation":"孩子不小心吞下了一个小物体，卡在了喉咙里，需要立即进行医疗干预。"},{"sentence":"When the air quality is poor, many people experience a scratchy throat, which can be alleviated by wearing a protective mask.","translation":"当空气质量差时，许多人会感到喉咙发痒，这可以通过佩戴防护口罩来缓解。"}]},"monarch":{"examples":[{"sentence":"Although the monarch holds a ceremonial role, the prime minister exercises actual political power.","translation":"尽管君主扮演礼仪性角色，但首相行使实际政治权力。"},{"sentence":"The monarch's decision to abdicate, which surprised the nation, led to a smooth succession.","translation":"君主退位的决定令全国惊讶，这导致了平稳的继位。"},{"sentence":"Because the monarch was a patron of the arts, the royal court became a center of cultural innovation.","translation":"由于君主是艺术的赞助人，宫廷成为了文化创新的中心。"},{"sentence":"The monarch addressed the parliament, urging unity while the country faced an economic crisis.","translation":"君主在议会发表讲话，敦促在国家面临经济危机时团结一致。"},{"sentence":"Historians debate whether the monarch was a reformer, whereas his predecessors were staunch traditionalists.","translation":"历史学家争论这位君主是否是改革者，而他的前任们则是坚定的传统主义者。"}]},"destiny":{"examples":[{"sentence":"Many believe that individuals shape their own destiny through hard work, rather than relying on fate.","translation":"许多人认为，个人通过努力塑造自己的命运，而不是依赖命运。"},{"sentence":"The discovery of oil transformed the nation's destiny, which had previously been marked by poverty.","translation":"石油的发现改变了国家的命运，此前这个国家一直贫困。"},{"sentence":"She felt that meeting her mentor was a twist of destiny, because it redirected her career path.","translation":"她觉得遇到导师是命运的转折，因为这改变了她的职业道路。"},{"sentence":"The novel explores destiny versus free will, while depicting a society in rapid transition.","translation":"这部小说探讨命运与自由意志，同时描绘了一个快速转型的社会。"},{"sentence":"Despite numerous setbacks, he remained convinced that destiny had a grand plan for him.","translation":"尽管遭遇无数挫折，他仍坚信命运对他有宏伟的安排。"}]},"react":{"examples":[{"sentence":"When faced with unexpected criticism, a thoughtful professional should pause to analyze the feedback rather than react defensively.","translation":"面对突如其来的批评时，一位深思熟虑的专业人士应当停下来分析反馈，而不是做出防御性的反应。"},{"sentence":"Because certain medications react adversely with grapefruit, patients must consult their physicians before making dietary changes.","translation":"由于某些药物会与葡萄柚产生不良反应，患者必须在改变饮食前咨询医生。"},{"sentence":"Although the market tends to react swiftly to policy shifts, long-term investors often benefit from maintaining a steady strategy.","translation":"尽管市场往往会对政策变化迅速作出反应，但长期投资者通常能从保持稳定策略中获益。"},{"sentence":"In order to foster a constructive dialogue, community leaders should listen carefully and react with empathy rather than hostility.","translation":"为了促进建设性对话，社区领袖应当仔细倾听，并以同理心而非敌意作出回应。"},{"sentence":"When sodium is exposed to water, it will react vigorously, producing hydrogen gas and heat.","translation":"当钠暴露在水中时，它会剧烈反应，产生氢气和热量。"}]},"blue":{"examples":[{"sentence":"The artist chose a deep blue for the background, which created a striking contrast with the vibrant foreground elements.","translation":"艺术家为背景选择了深蓝色，这与前景中充满活力的元素形成了鲜明的对比。"},{"sentence":"Although the team felt blue after the unexpected defeat, their coach reminded them that setbacks often precede improvement.","translation":"尽管队伍在意外失利后感到沮丧，但教练提醒他们，挫折往往是进步的前奏。"},{"sentence":"Because the ocean absorbs red light more efficiently, water appears blue to the human eye in most natural settings.","translation":"由于海洋更有效地吸收红光，在大多数自然环境中，水在人眼看来呈蓝色。"},{"sentence":"In many cultures, blue symbolizes tranquility and trust, which is why financial institutions frequently incorporate it into their branding.","translation":"在许多文化中，蓝色象征着宁静与信任，这就是金融机构经常将其融入品牌设计的原因。"},{"sentence":"The researcher discovered that exposure to blue light in the evening can suppress melatonin production, thereby disrupting sleep patterns.","translation":"研究人员发现，晚间暴露于蓝光会抑制褪黑激素的分泌，从而扰乱睡眠模式。"}]},"rail":{"examples":[{"sentence":"Although high-speed rail offers a sustainable alternative to air travel, its construction costs remain prohibitively high.","translation":"尽管高速铁路为航空旅行提供了一种可持续的替代方案，但其建设成本仍然高得令人望而却步。"},{"sentence":"Because the rail network is integrated with other public transport systems, commuters can travel seamlessly across the city.","translation":"由于铁路网络与其他公共交通系统整合，通勤者可以在整个城市无缝出行。"},{"sentence":"Investing in rail infrastructure not only boosts economic growth but also reduces traffic congestion and pollution.","translation":"投资铁路基础设施不仅能促进经济增长，还能减少交通拥堵和污染。"},{"sentence":"When the government upgraded the rail tracks, it significantly improved the punctuality and safety of train services.","translation":"当政府升级了铁轨后，它显著提高了列车服务的准点率和安全性。"},{"sentence":"Rail freight is often more energy-efficient than road transport, which makes it a key component of green logistics strategies.","translation":"铁路货运通常比公路运输更节能，这使其成为绿色物流战略的关键组成部分。"}]},"explanation":{"examples":[{"sentence":"Although the committee requested a detailed explanation, the report provided only a superficial summary of the findings.","translation":"尽管委员会要求提供详细的解释，但报告只对调查结果进行了肤浅的总结。"},{"sentence":"The professor's explanation, which drew on recent research, clarified the complex relationship between genetics and behavior.","translation":"教授的解释借鉴了最近的研究，阐明了遗传学与行为之间的复杂关系。"},{"sentence":"Because the company failed to offer a credible explanation for the data breach, its reputation suffered significantly.","translation":"由于公司未能对数据泄露给出可信的解释，其声誉受到了严重损害。"},{"sentence":"A thorough explanation of the new tax policy is essential to ensure that citizens understand its potential impact.","translation":"对新税收政策的全面解释对于确保公民理解其潜在影响至关重要。"},{"sentence":"While the initial explanation seemed plausible, further investigation revealed several inconsistencies in the witness's account.","translation":"虽然最初的解释看似合理，但进一步调查揭示了证人陈述中的几处矛盾。"}]},"educate":{"examples":[{"sentence":"Although schools primarily educate students in academic subjects, they also shape their character and values.","translation":"虽然学校主要在教育学生学术科目，但它们也塑造他们的品格和价值观。"},{"sentence":"Public health campaigns must educate communities about preventive measures, because early awareness can save lives.","translation":"公共卫生运动必须教育社区了解预防措施，因为早期意识可以挽救生命。"},{"sentence":"Parents who educate their children through open dialogue rather than strict discipline often foster stronger trust.","translation":"通过开放对话而不是严格纪律来教育孩子的父母往往能培养更强的信任。"},{"sentence":"Museums can educate visitors effectively when they use interactive exhibits that engage multiple senses.","translation":"当博物馆使用能调动多种感官的互动展品时，它们可以有效地教育参观者。"},{"sentence":"Governments should educate citizens about digital literacy, thereby empowering them to navigate online information critically.","translation":"政府应该教育公民数字素养，从而使他们能够批判性地浏览在线信息。"}]},"news":{"examples":[{"sentence":"Because fake news spreads rapidly on social media, media literacy education has become essential for the public.","translation":"由于假新闻在社交媒体上迅速传播，媒体素养教育对公众来说已变得至关重要。"},{"sentence":"The news that the government would increase funding for education was widely welcomed, which boosted public morale.","translation":"政府将增加教育经费的消息受到了广泛欢迎，这提振了公众士气。"},{"sentence":"While news reports often focus on conflicts, they should also highlight positive developments to provide a balanced perspective.","translation":"虽然新闻报道通常聚焦于冲突，但它们也应该突出积极的发展，以提供平衡的视角。"},{"sentence":"Reliable news sources are essential for citizens to make informed decisions, especially when facing complex political issues.","translation":"可靠的新闻来源对于公民做出知情决策至关重要，尤其是在面对复杂的政治问题时。"},{"sentence":"Breaking news about the economic downturn prompted investors to reconsider their strategies, thereby affecting global markets.","translation":"关于经济衰退的突发新闻促使投资者重新考虑他们的策略，从而影响了全球市场。"}]},"employee":{"examples":[{"sentence":"An employee who continuously updates his skills is more likely to adapt to technological changes, which benefits both the individual and the company.","translation":"一个不断更新技能的员工更有可能适应技术变革，这对个人和公司都有利。"},{"sentence":"Companies that invest in employee well-being often see higher productivity, because satisfied workers are more engaged and loyal.","translation":"投资于员工福祉的公司通常能获得更高的生产率，因为满意的员工更投入和忠诚。"},{"sentence":"Every employee, regardless of position, should be encouraged to contribute innovative ideas, thereby fostering a culture of creativity.","translation":"无论职位高低，每位员工都应被鼓励贡献创新想法，从而培养一种创新文化。"},{"sentence":"The new policy requires each employee to complete a mandatory ethics training program, which aims to ensure compliance with legal standards.","translation":"新政策要求每位员工完成一个强制性的道德培训项目，旨在确保符合法律标准。"},{"sentence":"When an employee feels valued by the organization, his commitment to work naturally increases, leading to higher performance.","translation":"当员工感到被组织重视时，他对工作的投入自然会增加，从而带来更高的绩效。"}]},"health":{"examples":[{"sentence":"Because regular exercise strengthens the immune system, it is a cornerstone of long-term health maintenance.","translation":"由于定期锻炼能增强免疫系统，它是长期保持健康的基石。"},{"sentence":"Although health care costs continue to rise, preventive measures can significantly reduce the financial burden on society.","translation":"尽管医疗保健成本持续上升，但预防措施可以显著减轻社会的经济负担。"},{"sentence":"Mental health, which is often overlooked in fast-paced societies, deserves equal attention in public policy.","translation":"在快节奏的社会中，心理健康常常被忽视，但在公共政策中应得到同等重视。"},{"sentence":"When individuals prioritize their health through balanced diets, they tend to experience higher productivity at work.","translation":"当个人通过均衡饮食来优先考虑健康时，他们在工作中往往会体验到更高的生产力。"},{"sentence":"Environmental pollution poses a serious threat to public health, thereby necessitating stricter emission controls.","translation":"环境污染对公共健康构成严重威胁，因此需要更严格的排放控制。"}]},"bunch":{"examples":[{"sentence":"A bunch of empirical studies suggests that early childhood education yields long-term economic benefits.","translation":"一系列实证研究表明，早期儿童教育能带来长期的经济效益。"},{"sentence":"Although a bunch of critics questioned the methodology, the research findings were later validated by independent teams.","translation":"尽管一群批评者质疑该方法论，但研究结果后来得到了独立团队的验证。"},{"sentence":"The manager received a bunch of complaints about the new policy, which prompted an immediate review.","translation":"经理收到了一堆关于新政策的投诉，这促使了立即审查。"},{"sentence":"Because a bunch of factors contributed to the project's delay, the team had to revise the timeline significantly.","translation":"由于一系列因素导致了项目的延迟，团队不得不大幅修改时间表。"},{"sentence":"Investors often diversify their portfolios by acquiring a bunch of assets rather than concentrating on a single stock.","translation":"投资者通常通过收购一批资产来分散投资组合，而不是集中于单一股票。"}]},"weekend":{"examples":[{"sentence":"Many professionals use the weekend to pursue further education, which enhances their career prospects significantly.","translation":"许多专业人士利用周末进修，这显著提升了他们的职业前景。"},{"sentence":"Although the weather forecast predicted rain, the outdoor festival went ahead as planned over the weekend.","translation":"尽管天气预报预测有雨，户外节还是按计划在周末进行了。"},{"sentence":"Volunteering at the animal shelter every weekend has taught her responsibility and compassion, which are valuable life skills.","translation":"每个周末在动物收容所做志愿者教会了她责任感和同情心，这些都是宝贵的生活技能。"},{"sentence":"Because the city marathon is held on a weekend, it attracts thousands of participants from around the country.","translation":"由于城市马拉松在周末举行，它吸引了来自全国各地的数千名参与者。"},{"sentence":"Parents who spend quality time with their children on the weekend often strengthen family bonds, which benefits emotional development.","translation":"在周末与孩子共度美好时光的父母往往能加强家庭纽带，这有利于情感发展。"}]},"centigrade":{"examples":[{"sentence":"Water freezes at 0 degrees centigrade, which is a fundamental concept taught in elementary science classes.","translation":"水在0摄氏度结冰，这是小学科学课上教授的基本概念。"},{"sentence":"The laboratory must maintain a temperature of 37 degrees centigrade to cultivate bacteria, which is optimal for their growth.","translation":"实验室必须保持37摄氏度的温度来培养细菌，这是它们生长的最佳温度。"},{"sentence":"Global warming could raise average temperatures by several degrees centigrade, which would have catastrophic effects on coastal cities.","translation":"全球变暖可能使平均气温上升几摄氏度，这将对沿海城市产生灾难性影响。"},{"sentence":"The vaccine requires storage at minus 70 degrees centigrade, which necessitates specialized freezers for transportation.","translation":"疫苗需要在零下70摄氏度储存，这需要专门的冷冻设备进行运输。"},{"sentence":"When the temperature exceeds 35 degrees centigrade, outdoor workers are at risk of heatstroke, so employers must provide adequate breaks.","translation":"当温度超过35摄氏度时，户外工作者有中暑的风险，因此雇主必须提供充足的休息时间。"}]},"champagne":{"examples":[{"sentence":"Although the wedding budget was tight, the couple insisted on serving champagne to ensure their guests felt truly celebrated.","translation":"尽管婚礼预算紧张，这对夫妇坚持提供香槟，以确保宾客们感到真正的庆祝。"},{"sentence":"The company's annual report revealed that champagne sales had surged, which indicated a growing consumer preference for premium beverages.","translation":"公司的年度报告显示香槟销量激增，这表明消费者对高端饮品的偏好日益增长。"},{"sentence":"Because the vintage champagne had been stored improperly, its delicate flavor was compromised, thereby disappointing the connoisseurs.","translation":"由于年份香槟储存不当，其细腻的风味受损，从而使鉴赏家们感到失望。"},{"sentence":"When the research team secured the grant, they celebrated with a bottle of champagne, rather than simply acknowledging the achievement in an email.","translation":"当研究团队获得资助时，他们用一瓶香槟庆祝，而不是仅仅在电子邮件中确认这一成就。"},{"sentence":"The diplomat noted that champagne diplomacy often facilitates informal negotiations, because the relaxed atmosphere encourages candid dialogue.","translation":"这位外交官指出，香槟外交常常促进非正式谈判，因为轻松的氛围鼓励坦诚对话。"}]},"substance":{"examples":[{"sentence":"Although the speech was eloquent, it lacked substance and failed to address the core issues facing the community.","translation":"尽管演讲雄辩有力，但缺乏实质内容，未能解决社区面临的核心问题。"},{"sentence":"The new regulation bans any substance that poses a significant risk to public health, which has sparked debate among manufacturers.","translation":"新法规禁止任何对公共健康构成重大风险的物质，这在制造商中引发了争论。"},{"sentence":"Because the argument was based on solid evidence, its substance convinced even the most skeptical members of the committee.","translation":"由于该论点基于确凿的证据，其实质内容甚至说服了委员会中最持怀疑态度的成员。"},{"sentence":"When heated, the substance releases a toxic gas, so experiments must be conducted in a well-ventilated area.","translation":"加热时，该物质会释放有毒气体，因此实验必须在通风良好的区域进行。"},{"sentence":"The philosopher's work explores the substance of human consciousness, a topic that continues to challenge scientists and thinkers alike.","translation":"这位哲学家的著作探索了人类意识的实质，这个课题至今仍挑战着科学家和思想家。"}]},"calcium":{"examples":[{"sentence":"Adequate calcium intake during adolescence is essential because it helps build peak bone mass, which reduces the risk of osteoporosis later in life.","translation":"青春期摄入足够的钙至关重要，因为它有助于建立峰值骨量，从而降低日后患骨质疏松症的风险。"},{"sentence":"Although dairy products are a well-known source of calcium, leafy green vegetables and fortified plant milks can also provide significant amounts.","translation":"尽管乳制品是众所周知的钙来源，但绿叶蔬菜和强化植物奶也能提供大量的钙。"},{"sentence":"When calcium levels in the blood drop too low, the body compensates by releasing the mineral from bones, which may weaken them over time.","translation":"当血液中的钙含量过低时，身体会通过从骨骼中释放这种矿物质来进行补偿，久而久之可能会使骨骼变弱。"},{"sentence":"Researchers have found that combining calcium with vitamin D improves absorption, making supplementation more effective for those at risk of deficiency.","translation":"研究人员发现，将钙与维生素D结合使用可以改善吸收，从而使补充剂对缺乏风险人群更有效。"},{"sentence":"Public health campaigns often emphasize dietary calcium because insufficient intake is linked to conditions such as hypertension and colon cancer.","translation":"公共卫生宣传通常强调膳食钙，因为摄入不足与高血压和结肠癌等疾病有关。"}]},"merry":{"examples":[{"sentence":"Although the workload was heavy, the team maintained a merry atmosphere, which significantly improved their productivity.","translation":"尽管工作量很大，团队仍保持着愉快的氛围，这显著提高了他们的生产力。"},{"sentence":"A merry heart does good like medicine, whereas a broken spirit dries the bones.","translation":"喜乐的心乃是良药，而忧伤的灵使骨枯干。"},{"sentence":"Because the festival was filled with merry music and dancing, it attracted visitors from all over the world.","translation":"因为节日充满了欢快的音乐和舞蹈，它吸引了来自世界各地的游客。"},{"sentence":"The children's merry laughter echoed through the park, which created a warm and joyful atmosphere.","translation":"孩子们欢快的笑声在公园里回荡，营造出温暖而快乐的氛围。"},{"sentence":"While some people seek happiness in material possessions, others find a merry life through simple pleasures.","translation":"虽然有些人从物质财富中寻求幸福，但另一些人通过简单的乐趣找到了快乐的生活。"}]},"eight":{"examples":[{"sentence":"The research team, which consisted of eight experts from different fields, successfully solved the complex problem.","translation":"由八位来自不同领域的专家组成的研究团队成功解决了这个复杂问题。"},{"sentence":"After eight months of intensive training, the athletes showed remarkable improvement, thereby qualifying for the national competition.","translation":"经过八个月的强化训练，运动员们表现出显著进步，从而获得了全国比赛的资格。"},{"sentence":"Because the course requires eight core modules, students gain a comprehensive understanding of the subject.","translation":"由于该课程要求八个核心模块，学生能对该学科获得全面的理解。"},{"sentence":"The policy was implemented across eight provinces, aiming to reduce carbon emissions through coordinated efforts.","translation":"该政策在八个省份实施，旨在通过协调努力减少碳排放。"},{"sentence":"Although the company had only eight employees, it managed to develop innovative products that disrupted the market.","translation":"尽管公司只有八名员工，但它成功开发出颠覆市场的创新产品。"}]},"shy":{"examples":[{"sentence":"Many talented individuals shy away from leadership roles because they underestimate their own capabilities.","translation":"许多有才华的人回避领导角色，因为他们低估了自己的能力。"},{"sentence":"Although she was naturally shy, she gradually developed confidence through participating in group discussions.","translation":"尽管她天生羞怯，但通过参与小组讨论，她逐渐培养了自信。"},{"sentence":"Investors often shy from volatile markets, preferring stable assets that offer predictable returns.","translation":"投资者常常回避波动性市场，更青睐能提供可预测回报的稳定资产。"},{"sentence":"The shy student surprised everyone by delivering a compelling presentation, which earned her a standing ovation.","translation":"那位羞怯的学生发表了一场引人入胜的演讲，赢得了全场起立鼓掌，令所有人惊讶。"},{"sentence":"Companies that shy away from innovation risk losing their competitive edge in a rapidly changing economy.","translation":"回避创新的公司面临在快速变化的经济中失去竞争优势的风险。"}]},"consensus":{"examples":[{"sentence":"Although the committee members held diverse opinions, they eventually reached a consensus on the budget allocation after lengthy discussions.","translation":"尽管委员会成员意见不一，但经过长时间讨论，他们最终就预算分配达成了共识。"},{"sentence":"Because a scientific consensus supports the theory of evolution, it is taught as a fundamental concept in biology classes worldwide.","translation":"由于科学共识支持进化论，它被作为全球生物课的基本概念来教授。"},{"sentence":"The lack of consensus among world leaders on climate action has delayed meaningful progress, which exacerbates the environmental crisis.","translation":"世界各国领导人在气候行动上缺乏共识，这拖延了有意义的进展，加剧了环境危机。"},{"sentence":"When a consensus is built through inclusive dialogue, the resulting policies are more likely to be accepted and implemented effectively.","translation":"当通过包容性对话达成共识时，由此产生的政策更有可能被接受和有效实施。"},{"sentence":"The consensus among historians is that the Industrial Revolution brought both unprecedented prosperity and severe social challenges.","translation":"历史学家的共识是，工业革命既带来了前所未有的繁荣，也带来了严重的社会挑战。"}]},"superfluous":{"examples":[{"sentence":"Although the report contained valuable insights, the superfluous technical jargon made it inaccessible to non-specialists.","translation":"尽管报告包含宝贵的见解，但多余的技术术语使非专业人士难以理解。"},{"sentence":"Because the budget was tight, the team eliminated all superfluous expenses to ensure the project could continue.","translation":"由于预算紧张，团队削减了所有多余的开支，以确保项目能够继续。"},{"sentence":"While the new software offers many features, most are superfluous for users who only need basic functionality.","translation":"虽然新软件提供了许多功能，但对于只需要基本功能的用户来说，大多数都是多余的。"},{"sentence":"The editor removed superfluous adjectives from the manuscript, thereby sharpening the narrative and improving readability.","translation":"编辑从手稿中删除了多余的形容词，从而使叙述更加精炼，提高了可读性。"},{"sentence":"If the committee had avoided superfluous debates, they could have reached a decision much sooner.","translation":"如果委员会避免了多余的辩论，他们本可以更快地做出决定。"}]},"statesman":{"examples":[{"sentence":"Although he was a skilled politician, his legacy as a statesman was cemented by his commitment to peace.","translation":"尽管他是一位老练的政客，但他作为政治家的遗产因其对和平的承诺而得以巩固。"},{"sentence":"The statesman, who had served as foreign minister, was known for his ability to forge alliances through diplomacy.","translation":"这位曾担任外交部长的政治家以通过外交手段建立联盟的能力而闻名。"},{"sentence":"Because the crisis demanded visionary leadership, the nation turned to an elder statesman for guidance.","translation":"由于危机需要有远见的领导，国家求助于一位资深政治家来寻求指导。"},{"sentence":"While many politicians focus on reelection, a true statesman prioritizes policies that benefit future generations.","translation":"许多政客专注于连任，而真正的政治家则优先考虑造福后代的政策。"},{"sentence":"The memoirs of the late statesman reveal how careful negotiation prevented a war, thereby saving countless lives.","translation":"这位已故政治家的回忆录揭示了谨慎的谈判如何阻止了一场战争，从而挽救了无数生命。"}]},"dealer":{"examples":[{"sentence":"Although the dealer offered a substantial discount, the buyer insisted on inspecting the vehicle thoroughly before making a decision.","translation":"尽管经销商提供了大幅折扣，买家仍坚持在做出决定前彻底检查车辆。"},{"sentence":"Because the art dealer had an impeccable reputation, collectors trusted her judgment when she recommended emerging artists.","translation":"由于这位艺术品经销商声誉无可挑剔，收藏家们在她推荐新兴艺术家时信任她的判断。"},{"sentence":"The dealer, who specialized in rare coins, provided a certificate of authenticity to ensure the buyer's confidence in the purchase.","translation":"这位专门经营稀有硬币的经销商提供了真品证书，以确保买家对购买的信心。"},{"sentence":"When the dealer failed to disclose the car's accident history, the customer filed a complaint with the consumer protection agency.","translation":"当经销商未能披露汽车的事故历史时，客户向消费者保护机构提出了投诉。"},{"sentence":"A reputable dealer will always prioritize customer satisfaction over short-term profits, thereby building long-term loyalty.","translation":"信誉良好的经销商总是将客户满意度置于短期利润之上，从而建立长期的忠诚度。"}]},"religious":{"examples":[{"sentence":"Although she was not raised in a religious household, she developed a deep interest in Buddhist philosophy during college.","translation":"虽然她不是在宗教家庭中长大的，但她在大学期间对佛教哲学产生了浓厚的兴趣。"},{"sentence":"Because religious institutions often provide community support, they play a vital role in social cohesion.","translation":"由于宗教机构经常提供社区支持，它们在社会凝聚力中发挥着至关重要的作用。"},{"sentence":"The government must balance religious freedom with public health concerns when regulating large gatherings during a pandemic.","translation":"在大流行病期间监管大型集会时，政府必须在宗教自由与公共卫生关切之间取得平衡。"},{"sentence":"Many religious traditions emphasize compassion and charity as fundamental virtues that guide moral conduct.","translation":"许多宗教传统强调同情和慈善是指导道德行为的基本美德。"},{"sentence":"While some people find solace in religious rituals, others seek meaning through secular philosophies.","translation":"虽然有些人在宗教仪式中找到慰藉，但其他人通过世俗哲学寻求意义。"}]},"gang":{"examples":[{"sentence":"Although the gang was notorious for its illegal activities, community outreach programs eventually helped many members reintegrate into society.","translation":"尽管该团伙因其非法活动而臭名昭著，但社区外展计划最终帮助许多成员重新融入社会。"},{"sentence":"The gang that operated in the downtown area was dismantled after a lengthy investigation, which involved multiple law enforcement agencies.","translation":"在市中心活动的那个团伙经过长期调查后被瓦解，该调查涉及多个执法机构。"},{"sentence":"Because the gang relied on a strict code of silence, witnesses were often reluctant to testify, thereby hindering the prosecution's case.","translation":"由于该团伙依赖严格的沉默守则，证人往往不愿作证，从而阻碍了检方的案件。"},{"sentence":"A gang of skilled artisans worked tirelessly to restore the historic cathedral, ensuring that every detail was accurate.","translation":"一群技艺精湛的工匠不知疲倦地工作，以修复这座历史悠久的教堂，确保每个细节都准确无误。"},{"sentence":"When a gang of teenagers was caught vandalizing the park, the judge ordered them to perform community service rather than face detention.","translation":"当一群青少年因破坏公园被抓时，法官命令他们进行社区服务，而不是被拘留。"}]},"vapour":{"examples":[{"sentence":"Water vapour, which is the most abundant greenhouse gas, plays a critical role in the Earth's energy balance.","translation":"水蒸气是最丰富的温室气体，在地球能量平衡中起着关键作用。"},{"sentence":"Although the chemical vapour released from the plant is not toxic, it contributes to the formation of smog in the region.","translation":"尽管工厂排放的化学蒸气无毒，但它会导致该地区烟雾的形成。"},{"sentence":"When water vapour condenses into clouds, it releases latent heat, which drives atmospheric circulation patterns.","translation":"当水蒸气凝结成云时，会释放潜热，从而驱动大气环流模式。"},{"sentence":"Because the vapour pressure of the solvent is high, it evaporates quickly at room temperature, making it useful in industrial processes.","translation":"由于该溶剂的蒸气压高，它在室温下迅速蒸发，使其在工业过程中很有用。"},{"sentence":"Scientists use satellite data to measure water vapour in the upper atmosphere, thereby improving weather prediction models.","translation":"科学家利用卫星数据测量高层大气中的水蒸气，从而改进天气预报模型。"}]},"say":{"examples":[{"sentence":"Many educators say that fostering critical thinking is more important than simply transmitting factual knowledge.","translation":"许多教育工作者说，培养批判性思维比单纯传授事实知识更重要。"},{"sentence":"Although critics say the new regulation is too restrictive, proponents argue that it is essential for protecting public health.","translation":"尽管批评者说新规定限制过多，但支持者认为它对于保护公众健康至关重要。"},{"sentence":"The survey results say that a majority of employees prefer flexible working hours to a higher salary.","translation":"调查结果说，大多数员工更喜欢灵活的工作时间而不是更高的薪水。"},{"sentence":"When researchers say that social media can affect mental well-being, they base their claims on longitudinal studies.","translation":"当研究人员说社交媒体可能影响心理健康时，他们的说法是基于纵向研究的。"},{"sentence":"It is fair to say that international collaboration has accelerated the development of renewable energy technologies.","translation":"可以说，国际合作加速了可再生能源技术的发展。"}]},"yesterday":{"examples":[{"sentence":"Although the committee approved the budget yesterday, several members expressed reservations about the long-term financial impact.","translation":"尽管委员会昨天批准了预算，但几位成员对长期财务影响表示了保留意见。"},{"sentence":"The report published yesterday reveals that consumer confidence has declined for the third consecutive month, which may affect retail sales.","translation":"昨天发布的报告显示，消费者信心已连续第三个月下降，这可能会影响零售销售。"},{"sentence":"Because the negotiations concluded yesterday without a consensus, both parties agreed to extend the deadline to ensure further discussion.","translation":"由于谈判昨天未达成共识而结束，双方同意延长最后期限以确保进一步讨论。"},{"sentence":"The seminar that I attended yesterday provided valuable insights into the challenges of implementing artificial intelligence in healthcare.","translation":"我昨天参加的研讨会为在医疗保健中实施人工智能的挑战提供了宝贵的见解。"},{"sentence":"While the stock market rebounded yesterday, analysts remain cautious about the sustainability of this recovery given global uncertainties.","translation":"尽管股市昨天反弹，但鉴于全球不确定性，分析师对此次复苏的可持续性仍持谨慎态度。"}]},"criticize":{"examples":[{"sentence":"Although the new policy aims to reduce traffic congestion, many experts criticize it for overlooking the needs of low-income commuters.","translation":"尽管新政策旨在减少交通拥堵，但许多专家批评它忽视了低收入通勤者的需求。"},{"sentence":"The report does not merely criticize current practices; it also proposes several practical alternatives that deserve serious consideration.","translation":"这份报告不仅仅批评了当前的做法，还提出了几个值得认真考虑的实际替代方案。"},{"sentence":"Some scholars criticize the traditional curriculum because it emphasizes rote memorization at the expense of critical thinking skills.","translation":"一些学者批评传统课程，因为它强调死记硬背而牺牲了批判性思维能力。"},{"sentence":"While it is easy to criticize the government's slow response, we must acknowledge the unprecedented scale of the disaster.","translation":"虽然批评政府反应迟缓很容易，但我们必须承认这场灾难的规模是前所未有的。"},{"sentence":"The editorial board decided to criticize the proposed legislation, arguing that it would undermine environmental protections without boosting economic growth.","translation":"编辑委员会决定批评这项拟议的立法，认为它会削弱环境保护，却无法促进经济增长。"}]},"capsule":{"examples":[{"sentence":"Although the time capsule was buried in 1950, its contents remained perfectly preserved until the recent excavation.","translation":"尽管这个时间胶囊是在1950年埋下的，但其中的物品直到最近挖掘时仍保存完好。"},{"sentence":"The doctor recommended a probiotic capsule, which helps restore gut flora after a course of antibiotics.","translation":"医生推荐了一种益生菌胶囊，它有助于在抗生素疗程后恢复肠道菌群。"},{"sentence":"Because the space capsule's heat shield was damaged, the mission control team had to devise an emergency re-entry plan.","translation":"由于太空舱的隔热罩受损，任务控制团队不得不制定紧急重返大气层的计划。"},{"sentence":"The botanist collected a seed capsule from the rare orchid, thereby ensuring its propagation in the botanical garden.","translation":"植物学家从这种稀有兰花上采集了一个种子蒴果，从而确保它在植物园中得以繁殖。"},{"sentence":"When the archaeologist opened the clay capsule, she found ancient scrolls that shed new light on early trade routes.","translation":"当考古学家打开那个陶制小容器时，她发现了古代卷轴，为早期贸易路线提供了新的线索。"}]},"conceal":{"examples":[{"sentence":"Although the company tried to conceal the defect, the product recall became inevitable after several accidents were reported.","translation":"尽管该公司试图隐瞒缺陷，但在多起事故被报道后，产品召回已不可避免。"},{"sentence":"The spy used a hollowed-out book to conceal the microfilm, which contained classified information about the operation.","translation":"间谍用一本挖空的书来藏匿缩微胶卷，其中包含了有关该行动的机密信息。"},{"sentence":"Because he could not conceal his disappointment, his colleagues immediately realized that the proposal had been rejected.","translation":"因为他无法掩饰自己的失望，同事们立刻意识到提案被否决了。"},{"sentence":"The ancient tomb was designed to conceal its entrance, thereby protecting the treasures from grave robbers for centuries.","translation":"这座古墓被设计成隐藏其入口，从而保护宝藏数世纪免受盗墓者侵扰。"},{"sentence":"While some politicians conceal their true intentions, others openly advocate for policies that benefit their constituents.","translation":"虽然一些政客隐瞒自己的真实意图，但另一些则公开倡导有利于其选民的政策。"}]},"lesson":{"examples":[{"sentence":"The most important lesson we can draw from history is that societies that invest in education tend to be more resilient during crises.","translation":"我们从历史中能汲取的最重要教训是，投资教育的社会在危机中往往更具韧性。"},{"sentence":"Although the lesson was designed for beginners, it contained insights that even advanced learners found valuable.","translation":"尽管这堂课是为初学者设计的，但它包含的见解甚至让高级学习者都觉得有价值。"},{"sentence":"The lesson that failure can be a stepping stone to success is often repeated, yet few people truly internalize it.","translation":"失败可以是通往成功的垫脚石这一教训经常被重复，但很少有人真正内化它。"},{"sentence":"By incorporating real-world case studies into each lesson, the professor ensured that theoretical concepts became tangible and memorable.","translation":"通过将现实案例融入每堂课，教授确保了理论概念变得具体且令人难忘。"},{"sentence":"The lesson that patience is essential in scientific research was reinforced when the team finally achieved a breakthrough after years of experimentation.","translation":"当团队经过多年实验终于取得突破时，耐心在科学研究中至关重要的教训得到了强化。"}]},"concise":{"examples":[{"sentence":"Although the manual is concise, it covers all essential procedures that technicians need to follow.","translation":"尽管手册很简洁，但它涵盖了技术人员需要遵循的所有基本程序。"},{"sentence":"Because her presentation was concise and well-organized, the audience remained engaged throughout the session.","translation":"因为她的演讲简洁且条理清晰，听众在整个会议期间都保持专注。"},{"sentence":"The editor insisted on a concise writing style, which eliminated redundant phrases and improved readability.","translation":"编辑坚持简洁的写作风格，这消除了冗余短语并提高了可读性。"},{"sentence":"When drafting a business email, being concise is crucial to ensure that the recipient quickly understands the main point.","translation":"在起草商务邮件时，简洁至关重要，以确保收件人快速理解要点。"},{"sentence":"A concise summary of the policy changes was distributed to all employees, thereby reducing confusion and saving time.","translation":"一份简洁的政策变更摘要分发给所有员工，从而减少了混乱并节省了时间。"}]},"logical":{"examples":[{"sentence":"Although the theory appears logical, it fails to account for several real-world anomalies that contradict its predictions.","translation":"尽管该理论看似合乎逻辑，但它未能解释几个与其预测相矛盾的现实异常。"},{"sentence":"Because the software uses a logical algorithm to sort data, it can process large datasets with remarkable efficiency.","translation":"由于该软件使用逻辑算法对数据进行排序，因此它可以高效地处理大型数据集。"},{"sentence":"The logical structure of the essay, which progresses from general principles to specific examples, makes the argument persuasive.","translation":"文章的逻辑结构从一般原则推进到具体例子，使论证具有说服力。"},{"sentence":"When evaluating competing proposals, a logical framework helps decision-makers compare options objectively rather than relying on bias.","translation":"在评估相互竞争的提案时，逻辑框架有助于决策者客观地比较选项，而不是依赖偏见。"},{"sentence":"A logical sequence of steps was established to ensure that the experiment could be replicated by other researchers.","translation":"建立了一个合乎逻辑的步骤序列，以确保其他研究人员可以复制该实验。"}]},"apology":{"examples":[{"sentence":"Although the CEO issued a public apology, many stakeholders remained skeptical about the company's commitment to change.","translation":"尽管首席执行官公开道歉，许多利益相关者仍对公司的改革承诺持怀疑态度。"},{"sentence":"A formal apology, which acknowledges the harm caused and outlines corrective measures, is essential for rebuilding trust.","translation":"一份承认造成的伤害并概述纠正措施的正式道歉，对于重建信任至关重要。"},{"sentence":"Because the apology was perceived as insincere, it further damaged the organization's reputation rather than mending it.","translation":"由于道歉被认为不真诚，它进一步损害了组织的声誉，而不是修复它。"},{"sentence":"When a nation offers an apology for historical wrongs, it can pave the way for reconciliation and healing.","translation":"当一个国家为历史错误道歉时，它可以为和解与治愈铺平道路。"},{"sentence":"The student's apology for plagiarism, while necessary, did not exempt him from the academic penalties that followed.","translation":"该学生为抄袭道歉，虽然必要，但并未使他免于随后的学术处罚。"}]},"attendance":{"examples":[{"sentence":"Regular attendance at lectures, which fosters active learning, is strongly correlated with higher academic performance.","translation":"定期参加讲座，这能促进主动学习，与更高的学业成绩密切相关。"},{"sentence":"Because attendance at the training sessions was mandatory, all employees acquired the necessary safety skills.","translation":"由于培训课程是强制参加的，所有员工都掌握了必要的安全技能。"},{"sentence":"The conference saw a decline in attendance this year, despite the organizers' efforts to attract international speakers.","translation":"尽管组织者努力吸引国际演讲者，今年会议的出席人数有所下降。"},{"sentence":"When attendance is consistently low, it may signal deeper issues such as employee disengagement or dissatisfaction.","translation":"当出勤率持续偏低时，可能预示着更深层次的问题，如员工不投入或不满意。"},{"sentence":"The school's new policy, which rewards perfect attendance, has led to a noticeable improvement in student punctuality.","translation":"学校的新政策，即奖励全勤，已导致学生守时性显著提高。"}]},"violate":{"examples":[{"sentence":"Companies that violate environmental regulations not only face heavy fines but also suffer lasting damage to their public image.","translation":"违反环境法规的公司不仅要面临巨额罚款，还会遭受公众形象的持久损害。"},{"sentence":"When governments violate citizens' privacy rights in the name of security, they risk eroding the very democratic values they claim to protect.","translation":"当政府以安全为名侵犯公民的隐私权时，他们可能会侵蚀他们声称要保护的民主价值观。"},{"sentence":"Academic institutions must ensure that their admission policies do not violate principles of equal opportunity, as such violations can perpetuate social inequality.","translation":"学术机构必须确保其招生政策不违反机会均等的原则，因为这种违反行为可能会使社会不平等长期存在。"},{"sentence":"Although the experiment was designed to advance medical knowledge, some argued that its methods violate basic ethical standards.","translation":"尽管该实验旨在推进医学知识，但有些人认为其方法违反了基本的伦理标准。"},{"sentence":"To maintain a fair marketplace, regulatory bodies should impose severe penalties on firms that violate antitrust laws.","translation":"为了维持公平的市场，监管机构应对违反反垄断法的公司施加严厉的处罚。"}]},"may":{"examples":[{"sentence":"Although the experiment was carefully designed, unforeseen variables may still affect the results.","translation":"尽管实验设计得很仔细，但不可预见的变量仍可能影响结果。"},{"sentence":"Because the new drug has not been fully tested, it may cause unexpected side effects in some patients.","translation":"由于新药尚未经过充分测试，它可能会在一些患者中引起意想不到的副作用。"},{"sentence":"While artificial intelligence may enhance productivity, it also raises ethical concerns that society must address.","translation":"虽然人工智能可能会提高生产力，但它也引发了社会必须解决的伦理问题。"},{"sentence":"If the government fails to regulate emissions, air quality may deteriorate to hazardous levels.","translation":"如果政府未能监管排放，空气质量可能会恶化到危险水平。"},{"sentence":"Without proper funding, the research project may not achieve its ambitious goals.","translation":"如果没有适当的资金，该研究项目可能无法实现其雄心勃勃的目标。"}]},"charter":{"examples":[{"sentence":"Although the charter was granted centuries ago, it still governs the city's administrative structure today.","translation":"尽管这份特许状是几个世纪前颁发的，但它至今仍规范着该市的行政结构。"},{"sentence":"The organization's charter, which emphasizes transparency, has attracted donors who value accountability.","translation":"该组织的章程强调透明度，吸引了重视问责制的捐赠者。"},{"sentence":"Because the charter school receives public funding, it must adhere to state educational standards.","translation":"由于特许学校接受公共资助，它必须遵守州教育标准。"},{"sentence":"When the royal charter was revoked, the colony lost its legal autonomy and became a crown possession.","translation":"当皇家特许状被撤销时，殖民地失去了法律自治权，成为王室领地。"},{"sentence":"A corporate charter that fails to define shareholder rights can lead to disputes during mergers.","translation":"未能界定股东权利的公司章程可能在合并期间引发争议。"}]},"skyscraper":{"examples":[{"sentence":"Although the skyscraper was designed by a renowned architect, its energy consumption has drawn criticism.","translation":"尽管这座摩天大楼由一位著名建筑师设计，但其能源消耗却招致了批评。"},{"sentence":"Because the skyscraper is located in a seismic zone, its foundation includes base isolators for safety.","translation":"由于这座摩天大楼位于地震带，其地基包含了隔震装置以确保安全。"},{"sentence":"The iconic skyscraper, which reshaped the city's skyline, has become a symbol of economic revival.","translation":"这座重塑了城市天际线的标志性摩天大楼已成为经济复苏的象征。"},{"sentence":"A skyscraper that integrates green spaces can improve the well-being of its occupants.","translation":"融合绿色空间的摩天大楼可以改善住户的福祉。"},{"sentence":"When a skyscraper exceeds 300 meters, wind engineering becomes critical to ensure structural stability.","translation":"当摩天大楼超过300米时，风工程对于确保结构稳定性变得至关重要。"}]},"arrow":{"examples":[{"sentence":"Although the arrow was ancient, its craftsmanship revealed sophisticated metallurgical knowledge.","translation":"尽管这支箭很古老，但其工艺揭示了先进的冶金知识。"},{"sentence":"Because the arrow on the sign was faded, many hikers took the wrong path through the dense forest.","translation":"因为标志上的箭头褪色了，许多徒步者在茂密的森林中走错了路。"},{"sentence":"When the archer released the arrow, it flew straight toward the target with a soft whistling sound.","translation":"当弓箭手放箭时，它带着轻柔的呼啸声径直飞向目标。"},{"sentence":"The diagram uses a red arrow, which clearly indicates the direction of data flow in the system.","translation":"该图表使用了一个红色箭头，它清楚地指示了系统中数据流的方向。"},{"sentence":"If you follow the arrow on the map, you will reach the historic monument without unnecessary detours.","translation":"如果你沿着地图上的箭头走，你就能到达历史纪念碑，而无需不必要的绕路。"}]},"wagon":{"examples":[{"sentence":"Although the wagon was heavily loaded, the sturdy horses pulled it steadily up the steep hill.","translation":"尽管马车装载得很重，但强壮的马匹稳步地把它拉上了陡峭的山坡。"},{"sentence":"Because the delivery wagon broke down, the fresh produce arrived late at the market.","translation":"因为送货车抛锚了，新鲜农产品到达市场时已经晚了。"},{"sentence":"When pioneers crossed the prairie, their covered wagon served as both transport and shelter.","translation":"当拓荒者穿越草原时，他们的篷车既是交通工具又是庇护所。"},{"sentence":"The children decorated a small wagon, which they used to carry their Halloween costumes through the neighborhood.","translation":"孩子们装饰了一辆小货车，他们用它载着万圣节服装穿过街区。"},{"sentence":"If you load the wagon carefully, you can transport all the equipment in a single trip.","translation":"如果你小心地装载货车，你就能一次运走所有的设备。"}]},"thanksgiving":{"examples":[{"sentence":"Although the harvest was poor, the villagers still held a thanksgiving feast to celebrate their unity.","translation":"尽管收成不好，村民们仍然举行了感恩宴来庆祝他们的团结。"},{"sentence":"Because the community showed such generosity, the mayor issued a proclamation of thanksgiving.","translation":"因为社区表现出如此的慷慨，市长发布了一份感恩公告。"},{"sentence":"When the survivors were rescued, they offered a prayer of thanksgiving for their deliverance.","translation":"当幸存者获救时，他们为获救献上了感恩的祈祷。"},{"sentence":"The charity event fostered a spirit of thanksgiving, which strengthened the bonds among the participants.","translation":"慈善活动培养了一种感恩的精神，这加强了参与者之间的联系。"},{"sentence":"If we express thanksgiving regularly, we can cultivate a more positive outlook on life.","translation":"如果我们经常表达感恩，我们就能培养更积极的人生观。"}]},"vulgar":{"examples":[{"sentence":"Although the comedian's jokes were undeniably vulgar, they nonetheless revealed uncomfortable truths about social inequality.","translation":"尽管这位喜剧演员的笑话无疑粗俗，但它们仍揭示了关于社会不平等的令人不安的真相。"},{"sentence":"A vulgar display of wealth on social media often alienates followers rather than inspiring genuine admiration.","translation":"在社交媒体上庸俗地炫耀财富往往疏远粉丝，而非激发真正的钦佩。"},{"sentence":"Because the advertisement relied on vulgar humor to attract attention, it failed to resonate with a more discerning audience.","translation":"由于广告依赖粗俗的幽默来吸引注意力，它未能引起更有鉴赏力的观众的共鸣。"},{"sentence":"The politician's vulgar remarks during the debate not only offended many voters but also undermined the dignity of the office.","translation":"那位政治家在辩论中的粗俗言论不仅冒犯了许多选民，还损害了该职位的尊严。"},{"sentence":"While some argue that vulgar language reflects authenticity, it often detracts from the substance of one's argument in formal settings.","translation":"虽然有人认为粗俗的语言反映了真实性，但在正式场合它往往会减损论点的实质。"}]},"sake":{"examples":[{"sentence":"Although the policy was controversial, it was implemented for the sake of national security.","translation":"尽管该政策存在争议，但为了国家安全还是实施了。"},{"sentence":"For the sake of clarity, the report includes a detailed appendix that explains the methodology.","translation":"为了清晰起见，该报告包含一个详细解释方法论的附录。"},{"sentence":"He chose to work overtime for the sake of meeting the project deadline, which was critical for the company.","translation":"他为了赶上项目截止日期而选择加班，这对公司至关重要。"},{"sentence":"For the sake of future generations, we must adopt sustainable practices that preserve natural resources.","translation":"为了子孙后代，我们必须采取可持续的做法来保护自然资源。"},{"sentence":"She declined the promotion for the sake of maintaining a healthy work-life balance, which she valued more.","translation":"她为了保持健康的工作与生活平衡而拒绝了晋升，她更看重这一点。"}]},"basketball":{"examples":[{"sentence":"Although basketball is physically demanding, it teaches valuable lessons about teamwork and discipline.","translation":"尽管篮球对体能要求很高，但它教会了关于团队合作和纪律的宝贵经验。"},{"sentence":"The school's basketball team, which won the regional championship last year, is now recruiting new players.","translation":"该校的篮球队去年赢得了地区冠军，现在正在招募新队员。"},{"sentence":"Because basketball requires both individual skill and collective strategy, it is an ideal sport for youth development.","translation":"因为篮球既需要个人技术又需要集体策略，所以它是青少年发展的理想运动。"},{"sentence":"The new community center offers basketball clinics that aim to improve participants' fitness and coordination.","translation":"新的社区中心提供篮球训练营，旨在提高参与者的体能和协调性。"},{"sentence":"While basketball is popular worldwide, its cultural impact varies significantly across different regions.","translation":"虽然篮球在全球都很流行，但其文化影响在不同地区差异很大。"}]},"anniversary":{"examples":[{"sentence":"Although the company celebrated its 50th anniversary with a grand gala, the CEO emphasized that sustained innovation remains the key to future success.","translation":"尽管公司以盛大的晚会庆祝其五十周年纪念，但首席执行官强调持续创新仍是未来成功的关键。"},{"sentence":"The anniversary of the peace treaty serves as a powerful reminder that diplomatic dialogue can resolve conflicts that once seemed intractable.","translation":"和平条约的周年纪念有力地提醒人们，外交对话能够解决曾经看似棘手的冲突。"},{"sentence":"Because the university's centennial anniversary attracted alumni from over 30 countries, the organizing committee arranged multilingual guided tours to ensure inclusivity.","translation":"由于大学的百年校庆吸引了来自30多个国家的校友，组委会安排了多语种导览以确保包容性。"},{"sentence":"On the anniversary of the landmark legislation, scholars published a comprehensive report which analyzed its long-term impact on social equality.","translation":"在这项具有里程碑意义的立法周年纪念日，学者们发表了一份综合分析其对社会平等长期影响的报告。"},{"sentence":"While the couple planned a quiet dinner for their wedding anniversary, their children surprised them with a video montage that captured decades of family memories.","translation":"虽然这对夫妇计划为结婚周年纪念安排一次安静的晚餐，但他们的孩子们用一段记录了几十年家庭回忆的视频剪辑给了他们惊喜。"}]},"multitude":{"examples":[{"sentence":"A multitude of empirical studies have confirmed that regular exercise not only improves physical health but also enhances cognitive function.","translation":"大量实证研究证实，定期锻炼不仅改善身体健康，而且增强认知功能。"},{"sentence":"Because the new policy addresses a multitude of environmental concerns, it has garnered support from both scientists and industry leaders.","translation":"由于新政策解决了众多环境问题，它获得了科学家和行业领袖的支持。"},{"sentence":"The multitude of languages spoken in the region, which reflects centuries of migration, poses challenges for educators who strive to provide equitable instruction.","translation":"该地区使用的众多语言反映了几个世纪的移民，给努力提供公平教学的教育工作者带来了挑战。"},{"sentence":"While a multitude of factors contribute to economic inequality, the lack of access to quality education is widely regarded as the most critical.","translation":"尽管众多因素导致了经济不平等，但缺乏优质教育被广泛认为是最关键的因素。"},{"sentence":"Through analyzing a multitude of data points, the research team identified a correlation between urban green spaces and residents' mental well-being.","translation":"通过分析众多数据点，研究团队确定了城市绿地与居民心理健康之间的相关性。"}]},"prejudice":{"examples":[{"sentence":"Although explicit prejudice has declined in many societies, implicit bias continues to influence hiring decisions, thereby perpetuating workplace inequality.","translation":"尽管明显的偏见在许多社会中有所减少，但隐性偏见继续影响招聘决策，从而使职场不平等长期存在。"},{"sentence":"Educational interventions that promote perspective-taking have been shown to reduce prejudice, because they foster empathy and understanding across social groups.","translation":"促进观点采择的教育干预已被证明能减少偏见，因为它们培养了跨社会群体的同理心和理解。"},{"sentence":"The researcher argued that prejudice against certain dialects can lead to linguistic discrimination, which undermines the cultural identity of minority communities.","translation":"研究人员认为，对某些方言的偏见可能导致语言歧视，这破坏了少数族裔社区的文化认同。"},{"sentence":"To combat deep-rooted prejudice in the legal system, the government introduced mandatory training that focuses on recognizing and mitigating unconscious bias.","translation":"为了打击法律体系中根深蒂固的偏见，政府引入了强制性培训，重点在于识别和减轻无意识偏见。"},{"sentence":"Whereas prejudice often stems from ignorance, sustained intergroup contact under equal-status conditions can effectively break down stereotypes.","translation":"尽管偏见往往源于无知，但在平等地位条件下的持续群际接触可以有效打破刻板印象。"}]},"indicative":{"examples":[{"sentence":"Although the initial data is limited, the early results are indicative of a significant breakthrough in renewable energy storage.","translation":"尽管初步数据有限，但早期结果表明可再生能源存储领域取得了重大突破。"},{"sentence":"The sharp decline in voter turnout is indicative of widespread disillusionment with the political system, which requires immediate attention.","translation":"选民投票率的急剧下降表明人们对政治制度普遍失望，这需要立即关注。"},{"sentence":"Because the patient's symptoms are indicative of a rare autoimmune disorder, the doctors have ordered further specialized tests.","translation":"由于患者的症状表明可能是一种罕见的自身免疫性疾病，医生已要求进行进一步的专项检查。"},{"sentence":"The rapid spread of misinformation online is indicative of a deeper crisis in media literacy that educators must address.","translation":"网络虚假信息的迅速传播表明媒介素养存在更深层次的危机，教育工作者必须加以应对。"},{"sentence":"While not conclusive, the archaeological findings are indicative of a previously unknown trade route between the two ancient civilizations.","translation":"尽管尚无定论，但考古发现表明这两个古代文明之间可能存在一条此前未知的贸易路线。"}]},"idea":{"examples":[{"sentence":"The idea that economic growth can be decoupled from environmental degradation is central to the concept of sustainable development.","translation":"经济增长可以与环境退化脱钩的理念是可持续发展概念的核心。"},{"sentence":"Although the idea of universal basic income is controversial, it has gained traction as a potential solution to job displacement caused by automation.","translation":"尽管全民基本收入的想法存在争议，但作为解决自动化导致失业问题的潜在方案，它已获得越来越多的支持。"},{"sentence":"The fundamental idea behind this algorithm is to optimize resource allocation by simulating natural selection, which improves efficiency significantly.","translation":"该算法背后的基本思想是通过模拟自然选择来优化资源分配，从而显著提高效率。"},{"sentence":"She challenged the long-held idea that leadership is an innate trait, arguing instead that it can be cultivated through deliberate practice.","translation":"她挑战了领导力是与生俱来的特质这一长期观念，认为通过刻意练习可以培养领导力。"},{"sentence":"The idea that language influences perception, known as linguistic relativity, has profound implications for cross-cultural communication.","translation":"语言影响感知的观点，即语言相对论，对跨文化交流具有深远影响。"}]},"ton":{"examples":[{"sentence":"Although the new electric truck weighs nearly a ton, its advanced battery system allows for a range of 500 miles.","translation":"尽管这辆新型电动卡车重近一吨，但其先进的电池系统使其续航里程达到500英里。"},{"sentence":"The factory produces a ton of steel every hour, which significantly contributes to the local economy.","translation":"该工厂每小时生产一吨钢铁，这对当地经济做出了重大贡献。"},{"sentence":"Because the shipment exceeded a ton, the logistics company had to use a specialized freight service.","translation":"由于货物超过一吨，物流公司不得不使用专门的货运服务。"},{"sentence":"When the bridge was designed, engineers calculated that each support beam must withstand a ton of pressure.","translation":"在设计桥梁时，工程师计算出每根支撑梁必须承受一吨的压力。"},{"sentence":"The recycling initiative aims to collect a ton of plastic waste per day, thereby reducing ocean pollution.","translation":"该回收计划旨在每天收集一吨塑料废物，从而减少海洋污染。"}]},"theoretical":{"examples":[{"sentence":"Although the theoretical model predicts high efficiency, practical experiments often yield lower results due to unforeseen variables.","translation":"尽管理论模型预测效率很高，但由于不可预见的变量，实际实验往往产生较低的结果。"},{"sentence":"The professor emphasized that a solid theoretical foundation is essential before conducting any applied research.","translation":"教授强调，在进行任何应用研究之前，坚实的理论基础是必不可少的。"},{"sentence":"Because the concept remains purely theoretical, further empirical studies are needed to validate its feasibility.","translation":"由于该概念仍纯属理论，需要进一步的实证研究来验证其可行性。"},{"sentence":"The theoretical framework, which integrates psychology and economics, offers new insights into consumer behavior.","translation":"该理论框架融合了心理学和经济学，为消费者行为提供了新的见解。"},{"sentence":"While theoretical knowledge is important, practical skills are equally crucial for solving real-world problems.","translation":"虽然理论知识很重要，但实践技能对于解决现实问题同样至关重要。"}]},"verify":{"examples":[{"sentence":"Although the initial results appeared promising, the team conducted additional tests to verify their accuracy.","translation":"尽管初步结果看起来很有希望，团队还是进行了额外的测试来验证其准确性。"},{"sentence":"To ensure the software functions correctly, engineers must verify each module through systematic testing.","translation":"为了确保软件正常运行，工程师必须通过系统测试来验证每个模块。"},{"sentence":"Because the witness's testimony was inconsistent, the detective sought other evidence to verify the alibi.","translation":"因为证人的证词前后矛盾，侦探寻找其他证据来核实不在场证明。"},{"sentence":"When applying for a visa, officials verify your documents, which can delay the process if any are missing.","translation":"申请签证时，官员会核实你的文件，如果有任何缺失，可能会延误流程。"},{"sentence":"The auditor's role is to verify financial statements, thereby ensuring transparency for investors.","translation":"审计师的职责是核实财务报表，从而确保对投资者的透明度。"}]},"waste":{"examples":[{"sentence":"Although recycling programs exist, electronic waste continues to accumulate, which poses environmental risks.","translation":"尽管有回收项目，电子废弃物仍在累积，这构成了环境风险。"},{"sentence":"Because improper disposal of industrial waste contaminates water sources, stricter regulations are necessary.","translation":"因为工业废物的不当处理会污染水源，所以更严格的法规是必要的。"},{"sentence":"To reduce food waste, supermarkets can donate unsold items, thereby supporting local communities.","translation":"为了减少食物浪费，超市可以捐赠未售出的物品，从而支持当地社区。"},{"sentence":"When households minimize waste through composting, they not only reduce landfill but also enrich soil.","translation":"当家庭通过堆肥减少垃圾时，他们不仅减少了填埋量，还肥沃了土壤。"},{"sentence":"The company's zero-waste policy, which includes reusing materials, has significantly cut operational costs.","translation":"公司的零废弃物政策，包括重复使用材料，显著降低了运营成本。"}]},"bolt":{"examples":[{"sentence":"Although the carpenter used a sturdy bolt to secure the door, the frame itself was too weak to withstand the force.","translation":"尽管木匠用了一根结实的门闩来固定门，但门框本身太脆弱，无法承受力量。"},{"sentence":"Because the engineer specified a high-tensile bolt for the joint, the structure remained stable under extreme loads.","translation":"因为工程师指定在接头处使用高强度螺栓，结构在极端载荷下保持稳定。"},{"sentence":"When a bolt of lightning struck the power line, the entire neighborhood was plunged into darkness without warning.","translation":"当一道闪电击中电线时，整个街区毫无预警地陷入黑暗。"},{"sentence":"The news of the merger came as a bolt from the blue, which forced the employees to reconsider their career plans.","translation":"合并的消息如同晴天霹雳，迫使员工重新考虑他们的职业规划。"},{"sentence":"To ensure the safety of the equipment, the technician inserted a locking bolt that prevented unauthorized access.","translation":"为确保设备安全，技术员插入了一个锁定螺栓，防止未经授权的访问。"}]},"head":{"examples":[{"sentence":"As the head of the department, she implemented a new policy that significantly improved employee satisfaction.","translation":"作为部门负责人，她实施了一项新政策，显著提高了员工满意度。"},{"sentence":"Although he suffered a head injury during the accident, he remained conscious and provided crucial details to the paramedics.","translation":"尽管在事故中头部受伤，他仍保持清醒，并向急救人员提供了关键细节。"},{"sentence":"The company's head office, which is located in Shanghai, oversees operations across the entire Asia-Pacific region.","translation":"公司总部位于上海，负责监管整个亚太地区的运营。"},{"sentence":"Because she had a clear head for numbers, she was able to solve the complex financial problem in minutes.","translation":"因为她对数字头脑清晰，所以能在几分钟内解决复杂的财务问题。"},{"sentence":"When the project faced a critical delay, the team head decided to reallocate resources to ensure timely completion.","translation":"当项目面临严重延误时，团队负责人决定重新分配资源以确保按时完成。"}]},"revive":{"examples":[{"sentence":"Although the patient had been unconscious for hours, the medical team managed to revive him with a new treatment.","translation":"尽管病人已经昏迷了几个小时，医疗团队还是用一种新疗法使他苏醒过来。"},{"sentence":"Because the local economy was struggling, the government launched a series of initiatives to revive small businesses.","translation":"由于当地经济陷入困境，政府推出了一系列举措来复兴小企业。"},{"sentence":"While reading her grandfather's letters, she was able to revive cherished memories of her childhood.","translation":"在阅读祖父的信件时，她得以回想起童年珍贵的记忆。"},{"sentence":"The director decided to revive the classic play, which had not been performed for over fifty years.","translation":"导演决定重演这部已有五十多年未曾上演的经典戏剧。"},{"sentence":"Through regular exercise and a balanced diet, one can revive one's energy levels and improve overall health.","translation":"通过定期锻炼和均衡饮食，一个人可以恢复精力并改善整体健康。"}]},"concrete":{"examples":[{"sentence":"Although the architect preferred steel, the client insisted on using concrete for its fire-resistant properties.","translation":"尽管建筑师偏爱钢材，客户坚持使用混凝土，因为它具有防火性能。"},{"sentence":"Because the foundation was made of reinforced concrete, the building withstood the earthquake without major damage.","translation":"由于地基由钢筋混凝土制成，该建筑经受住了地震而没有重大损坏。"},{"sentence":"The researcher emphasized the need for concrete data, which could be verified through repeated experiments.","translation":"研究人员强调需要具体的数据，这些数据可以通过重复实验来验证。"},{"sentence":"While abstract theories are important, students often learn better when they are given concrete examples.","translation":"虽然抽象理论很重要，但当给学生具体的例子时，他们往往学得更好。"},{"sentence":"The city plans to replace the old asphalt road with a concrete surface, thereby reducing maintenance costs.","translation":"该市计划用混凝土路面取代旧的柏油路，从而降低维护成本。"}]},"submerge":{"examples":[{"sentence":"Although the dam was built to control flooding, it will submerge several ancient temples that hold great cultural significance.","translation":"尽管这座大坝是为了控制洪水而建，但它将淹没几座具有重大文化意义的古庙。"},{"sentence":"When the tide comes in, it can submerge the causeway, which isolates the island from the mainland for hours.","translation":"涨潮时，潮水会淹没堤道，从而使岛屿与大陆隔绝数小时。"},{"sentence":"To ensure the metal cools evenly, the blacksmith must submerge it in oil rather than water.","translation":"为了确保金属均匀冷却，铁匠必须将其浸入油中而不是水中。"},{"sentence":"Because she tends to submerge her own ambitions in supporting her family, she rarely pursues personal goals.","translation":"因为她倾向于在支持家庭时埋没自己的抱负，所以她很少追求个人目标。"},{"sentence":"The submarine can submerge to a depth of 300 meters, which allows it to explore previously inaccessible underwater caves.","translation":"这艘潜艇能下潜到300米的深度，这使它能够探索以前无法进入的水下洞穴。"}]},"recite":{"examples":[{"sentence":"Although the poem was written centuries ago, students still recite it to appreciate its timeless beauty.","translation":"尽管这首诗写于几个世纪前，学生们仍然背诵它以欣赏其永恒的美。"},{"sentence":"The witness was asked to recite the license plate number, which proved crucial in identifying the suspect.","translation":"证人被要求背出车牌号码，这在识别嫌疑人时被证明是至关重要的。"},{"sentence":"Because he could recite the entire periodic table from memory, he excelled in chemistry class.","translation":"因为他能凭记忆背诵整个元素周期表，所以他在化学课上表现出色。"},{"sentence":"During the festival, the actor will recite a monologue that captures the essence of human struggle.","translation":"在节日期间，这位演员将朗诵一段独白，它捕捉了人类奋斗的本质。"},{"sentence":"To ensure accuracy, the clerk must recite the order back to the customer before finalizing the transaction.","translation":"为了确保准确性，店员必须在完成交易前向顾客复述订单。"}]},"hurl":{"examples":[{"sentence":"With a single powerful hurl, the athlete broke the world record, which had stood for over a decade.","translation":"凭借一次有力的投掷，这位运动员打破了保持十多年的世界纪录。"},{"sentence":"Although he was tempted to hurl insults at his opponent, he maintained his composure and won the debate.","translation":"尽管他很想对他的对手恶语相加，但他保持了冷静并赢得了辩论。"},{"sentence":"The storm's fierce winds can hurl debris through the air, which poses a serious risk to pedestrians.","translation":"暴风雨的强风能将碎片抛向空中，这对行人构成了严重危险。"},{"sentence":"Because the politician chose to hurl accusations without evidence, his credibility was severely damaged.","translation":"因为这位政客选择在没有证据的情况下提出指责，他的信誉受到了严重损害。"},{"sentence":"The catapult was designed to hurl stones over the castle walls, thereby breaching the enemy's defenses.","translation":"投石机被设计用来将石头猛掷过城墙，从而突破敌人的防御。"}]},"peanut":{"examples":[{"sentence":"Peanut cultivation, which enriches soil through nitrogen fixation, plays a vital role in sustainable agriculture in many developing regions.","translation":"花生种植通过固氮作用使土壤变得肥沃，在许多发展中地区的可持续农业中发挥着至关重要的作用。"},{"sentence":"Because peanut allergies can trigger severe reactions, food manufacturers are required to clearly label products that may contain traces of peanuts.","translation":"由于花生过敏可能引发严重反应，食品制造商必须明确标注可能含有微量花生的产品。"},{"sentence":"Researchers have developed a hypoallergenic peanut variety that could significantly reduce the risk of allergic responses among sensitive consumers.","translation":"研究人员开发出一种低过敏性花生品种，可显著降低敏感消费者发生过敏反应的风险。"},{"sentence":"Although peanut oil is widely used in cooking for its high smoke point, some chefs prefer alternatives to avoid allergenic concerns.","translation":"尽管花生油因其高烟点而广泛用于烹饪，但一些厨师更倾向于使用替代品以避免过敏问题。"},{"sentence":"The peanut, a legume rather than a true nut, provides an affordable source of protein and healthy fats for populations worldwide.","translation":"花生是一种豆科植物而非真正的坚果，为全球人口提供了经济实惠的蛋白质和健康脂肪来源。"}]},"reality":{"examples":[{"sentence":"In reality, the success of any policy depends not only on its theoretical soundness but also on effective implementation.","translation":"实际上，任何政策的成功不仅取决于其理论上的合理性，还取决于有效的实施。"},{"sentence":"Virtual reality technology, which creates immersive digital environments, is increasingly used in medical training to simulate complex surgeries.","translation":"虚拟现实技术创造了沉浸式数字环境，正越来越多地用于医学培训以模拟复杂手术。"},{"sentence":"Although the initial proposal appeared feasible, a detailed analysis revealed that it was completely detached from financial reality.","translation":"尽管最初的提案看似可行，但详细分析显示它完全脱离了财务现实。"},{"sentence":"The harsh reality of climate change demands that governments and industries collaborate to reduce carbon emissions without delay.","translation":"气候变化的严峻现实要求政府与工业界合作，毫不拖延地减少碳排放。"},{"sentence":"Because our perception of reality is shaped by cultural and personal biases, objective truth can be difficult to ascertain.","translation":"由于我们对现实的感知受到文化和个人偏见的影响，客观真理可能难以确定。"}]},"weld":{"examples":[{"sentence":"Although the weld appeared flawless on the surface, radiographic testing revealed internal porosity that compromised its strength.","translation":"尽管焊接处表面看起来完美无瑕，但射线检测显示内部有气孔，削弱了其强度。"},{"sentence":"Because the weld was performed at an incorrect temperature, the joint lacked the necessary ductility to withstand cyclic loading.","translation":"由于焊接时温度不当，接头缺乏承受循环载荷所需的延展性。"},{"sentence":"The engineer decided to weld the cracked pipe rather than replace it, thereby saving both time and material costs.","translation":"工程师决定焊接破裂的管道而不是更换它，从而节省了时间和材料成本。"},{"sentence":"When dissimilar metals are joined, a proper weld requires careful selection of filler material to avoid galvanic corrosion.","translation":"当连接异种金属时，合适的焊接需要仔细选择填充材料以避免电偶腐蚀。"},{"sentence":"The new curriculum aims to weld theoretical knowledge with practical skills, which is essential for producing industry-ready graduates.","translation":"新课程旨在将理论知识与实践技能结合起来，这对于培养符合行业需求的毕业生至关重要。"}]},"magazine":{"examples":[{"sentence":"Because the magazine publishes peer-reviewed articles on climate change, it has become a trusted source for policymakers worldwide.","translation":"由于该杂志发表关于气候变化的同行评审文章，它已成为全球政策制定者信赖的来源。"},{"sentence":"Although the magazine was originally founded as a literary journal, it now covers a broad range of scientific disciplines.","translation":"尽管该杂志最初是作为文学期刊创刊的，但现在它涵盖了广泛的科学学科。"},{"sentence":"The soldier quickly replaced the empty magazine with a full one, thereby ensuring continuous fire during the critical moment.","translation":"士兵迅速将空弹匣更换为满弹匣，从而在关键时刻确保了持续火力。"},{"sentence":"A well-edited magazine not only informs its readers but also stimulates critical thinking through in-depth analysis.","translation":"一本编辑精良的杂志不仅为读者提供信息，还通过深入分析激发批判性思维。"},{"sentence":"When the digital magazine introduced interactive infographics, its readership increased significantly among younger demographics.","translation":"当该数字杂志引入交互式信息图表时，其在年轻群体中的读者数量显著增加。"}]},"library":{"examples":[{"sentence":"Although the library has a vast collection of physical books, it is increasingly investing in digital resources to meet modern demands.","translation":"尽管图书馆拥有大量实体藏书，但它正越来越多地投资于数字资源以满足现代需求。"},{"sentence":"Because the library offers quiet study areas and high-speed internet, it has become a popular workspace for graduate students.","translation":"由于图书馆提供安静的学习区域和高速互联网，它已成为研究生受欢迎的工作场所。"},{"sentence":"The library not only preserves historical documents but also hosts exhibitions that engage the community with local heritage.","translation":"图书馆不仅保存历史文献，还举办展览，让社区参与当地遗产的保护。"},{"sentence":"When the library extended its hours during finals week, students were able to access resources late into the night.","translation":"当图书馆在期末考试周延长开放时间时，学生们能够深夜使用资源。"},{"sentence":"By digitizing its rare manuscript collection, the library ensures that scholars worldwide can study these texts without traveling.","translation":"通过将珍贵手稿收藏数字化，图书馆确保世界各地的学者无需旅行就能研究这些文本。"}]},"zebra":{"examples":[{"sentence":"Although the zebra is native to Africa, its striking appearance has made it a popular subject in art worldwide.","translation":"尽管斑马原产于非洲，但其引人注目的外表使其成为世界各地艺术中的热门主题。"},{"sentence":"Because a zebra's stripes are unique to each individual, researchers can identify them without invasive tagging.","translation":"因为每匹斑马的条纹都是独一无二的，研究人员无需侵入性标记就能识别它们。"},{"sentence":"When a zebra foal is born, it can stand within minutes, which is crucial for survival on the predator-rich plains.","translation":"当斑马驹出生时，它能在几分钟内站立，这对于在捕食者众多的平原上生存至关重要。"},{"sentence":"The zebra's grazing habits help maintain the grassland ecosystem, thereby supporting a diverse range of species.","translation":"斑马的放牧习性有助于维持草原生态系统，从而支持了多种物种。"},{"sentence":"While the zebra is often compared to the horse, its temperament is far more aggressive and unpredictable.","translation":"虽然斑马常被与马比较，但它的性情要凶猛和难以预测得多。"}]},"positive":{"examples":[{"sentence":"Although the experiment failed, the researchers maintained a positive outlook because they had gathered valuable data.","translation":"尽管实验失败了，研究人员仍保持积极的态度，因为他们收集到了宝贵的数据。"},{"sentence":"A positive correlation between education levels and income has been observed in many countries, which suggests that investing in schooling yields economic benefits.","translation":"在许多国家观察到教育水平与收入之间存在正相关，这表明投资教育能带来经济效益。"},{"sentence":"When employees receive positive feedback, their motivation and productivity tend to increase significantly.","translation":"当员工收到积极反馈时，他们的积极性和生产力往往会显著提高。"},{"sentence":"The new policy had a positive effect on the environment, thereby reducing carbon emissions by 20 percent within two years.","translation":"新政策对环境产生了积极影响，从而在两年内将碳排放量减少了20%。"},{"sentence":"A positive integer, such as 7 or 42, is a whole number that is greater than zero.","translation":"正整数，如7或42，是大于零的整数。"}]},"void":{"examples":[{"sentence":"After the sudden death of her mentor, she felt a deep emotional void that no amount of success could fill.","translation":"在她的导师突然去世后，她感到一种深刻的情感空虚，任何成功都无法填补。"},{"sentence":"If a contract is signed under duress, it may be declared void by a court, which means it has no legal force.","translation":"如果合同是在胁迫下签署的，法院可能宣布其无效，这意味着它没有法律效力。"},{"sentence":"The proposal was void of any practical solutions, thereby failing to address the urgent housing crisis.","translation":"该提案缺乏任何实际的解决方案，因此未能解决紧迫的住房危机。"},{"sentence":"When the factory closed, the once-bustling industrial area became a silent void, devoid of workers and machinery.","translation":"工厂关闭后，曾经繁忙的工业区变成了一片寂静的空虚，没有了工人和机器。"},{"sentence":"The agreement became void because one party failed to meet its obligations within the specified timeframe.","translation":"由于一方未能在规定时间内履行其义务，该协议变得无效。"}]},"arithmetic":{"examples":[{"sentence":"Although arithmetic is often considered elementary, its principles underpin complex algorithms in computer science.","translation":"尽管算术常被视为基础，但其原理支撑着计算机科学中的复杂算法。"},{"sentence":"Because arithmetic operations are fundamental to financial literacy, schools should prioritize their instruction from an early age.","translation":"由于算术运算是金融素养的基础，学校应从小优先教授它们。"},{"sentence":"While calculators can perform arithmetic instantly, understanding the underlying logic enhances problem-solving abilities.","translation":"虽然计算器能瞬间完成算术运算，但理解其底层逻辑能提升解决问题的能力。"},{"sentence":"When students master arithmetic, they gain confidence to tackle more advanced mathematical concepts later.","translation":"当学生掌握算术时，他们便获得信心去应对日后更高级的数学概念。"},{"sentence":"If arithmetic skills are neglected, individuals may struggle with everyday tasks such as budgeting and data interpretation.","translation":"如果算术技能被忽视，个人可能会在预算和解读数据等日常任务中遇到困难。"}]},"survive":{"examples":[{"sentence":"Although the startup faced fierce competition, it managed to survive by pivoting to a niche market.","translation":"尽管这家初创公司面临激烈竞争，但它通过转向利基市场得以生存。"},{"sentence":"Because the species can survive in low-oxygen environments, it thrives in deep ocean trenches.","translation":"由于该物种能在低氧环境中生存，它在深海海沟中繁衍生息。"},{"sentence":"While many traditional crafts are disappearing, some survive through the dedication of local artisans.","translation":"虽然许多传统工艺正在消失，但有些通过当地工匠的奉献得以留存。"},{"sentence":"If a company does not innovate, it cannot survive in today's rapidly changing technological landscape.","translation":"如果一家公司不创新，它就无法在当今快速变化的技术格局中生存。"},{"sentence":"When communities work together, they are more likely to survive natural disasters and rebuild effectively.","translation":"当社区齐心协力时，他们更有可能在自然灾害中生存并有效重建。"}]},"must":{"examples":[{"sentence":"Although talent is beneficial, consistent practice is a must for achieving mastery in any field.","translation":"尽管天赋有益，但持续练习是在任何领域达到精通的必要条件。"},{"sentence":"Because the exam covers a vast syllabus, a well-organized study plan is an absolute must for success.","translation":"由于考试涵盖大量大纲，一个组织良好的学习计划是成功的绝对必要条件。"},{"sentence":"While technical skills are important, strong communication abilities are a must for effective teamwork.","translation":"虽然技术技能很重要，但强大的沟通能力是有效团队合作的必备条件。"},{"sentence":"If you aim to work in international relations, proficiency in multiple languages is often a must.","translation":"如果你打算从事国际关系工作，精通多种语言通常是必备条件。"},{"sentence":"When applying for competitive programs, relevant internship experience is increasingly seen as a must.","translation":"在申请竞争性项目时，相关的实习经验越来越被视为必备条件。"}]},"household":{"examples":[{"sentence":"Because the household budget was carefully planned, the family could afford both education and leisure activities.","translation":"由于家庭预算经过精心规划，这个家庭能够同时负担教育和休闲活动。"},{"sentence":"Although she managed the entire household, she still found time to pursue a part-time degree in accounting.","translation":"尽管她管理着整个家庭，她仍然抽出时间攻读会计学的在职学位。"},{"sentence":"The survey revealed that household energy consumption tends to rise significantly during the winter months.","translation":"调查显示，家庭能源消耗在冬季往往会显著上升。"},{"sentence":"When both parents work full-time, sharing household chores becomes essential for maintaining harmony.","translation":"当父母双方都全职工作时，分担家务对于维持和谐至关重要。"},{"sentence":"Investing in household appliances that save water can reduce monthly expenses over the long term.","translation":"投资于节水的家用电器从长远来看可以减少每月开支。"}]},"rod":{"examples":[{"sentence":"Although the fishing rod was inexpensive, it proved durable enough to catch several large trout.","translation":"尽管这根钓鱼竿价格低廉，但它足够耐用，钓到了好几条大鳟鱼。"},{"sentence":"Because the curtain rod was installed securely, the heavy drapes hung without sagging.","translation":"由于窗帘杆安装牢固，厚重的窗帘悬挂时没有下垂。"},{"sentence":"The engineer used a calibrated measuring rod to ensure the foundation depth met safety standards.","translation":"工程师使用标定过的测量杆，以确保地基深度符合安全标准。"},{"sentence":"When the lightning rod was struck, the electrical charge was safely conducted into the ground.","translation":"当避雷针被击中时，电荷被安全地导入地下。"},{"sentence":"In chemistry labs, a glass stirring rod is essential for mixing solutions without contaminating them.","translation":"在化学实验室中，玻璃搅拌棒对于混合溶液而不污染它们至关重要。"}]},"review":{"examples":[{"sentence":"Although the initial findings were promising, the research team decided to conduct a comprehensive review of the data to ensure accuracy.","translation":"尽管初步发现很有希望，研究团队还是决定对数据进行全面审查以确保准确性。"},{"sentence":"Because the policy is currently under review, stakeholders are advised to submit their feedback before the deadline.","translation":"由于该政策目前正在审查中，建议利益相关者在截止日期前提交反馈。"},{"sentence":"The journal requires a double-blind peer review process, which helps maintain objectivity and fairness in evaluating submissions.","translation":"该期刊要求双盲同行评审过程，这有助于在评估投稿时保持客观和公正。"},{"sentence":"When students review their notes regularly, they are more likely to retain information and perform well on exams.","translation":"当学生定期复习笔记时，他们更有可能记住信息并在考试中取得好成绩。"},{"sentence":"The committee will review the proposal thoroughly, thereby ensuring that all potential risks are identified and addressed.","translation":"委员会将彻底审查该提案，从而确保所有潜在风险都被识别和处理。"}]},"december":{"examples":[{"sentence":"Because the conference is scheduled for December, participants must submit their abstracts by early September.","translation":"由于会议定于十二月举行，与会者必须在九月初之前提交摘要。"},{"sentence":"Many companies finalize their annual budgets in December, which allows them to start the new year with a clear financial plan.","translation":"许多公司在十二月敲定年度预算，这使他们能够以清晰的财务计划开始新的一年。"},{"sentence":"Although December is typically a busy month, the team managed to complete the project ahead of schedule.","translation":"尽管十二月通常是一个繁忙的月份，团队还是设法提前完成了项目。"},{"sentence":"The university's admission deadline falls on December 15th, after which no further applications will be accepted.","translation":"大学的录取截止日期是十二月十五日，之后将不再接受申请。"},{"sentence":"In December, the government releases its annual economic report, which provides insights into the country's fiscal health.","translation":"在十二月，政府发布年度经济报告，该报告提供了对国家财政状况的见解。"}]},"analysis":{"examples":[{"sentence":"A thorough analysis of the survey data revealed that flexible work arrangements significantly improve employee retention, which prompted the company to revise its policies.","translation":"对调查数据的彻底分析显示，灵活的工作安排显著提高了员工留任率，这促使公司修订了政策。"},{"sentence":"Although the initial analysis suggested a budget surplus, a more detailed review uncovered hidden infrastructure liabilities, which led to a revised fiscal strategy.","translation":"尽管初步分析表明有预算盈余，但更详细的审查发现了隐藏的基础设施负债，这导致了财政策略的修订。"},{"sentence":"The policy brief was grounded in a comparative analysis of renewable energy subsidies across five European countries, which highlighted best practices for adoption.","translation":"该政策简报基于对五个欧洲国家可再生能源补贴的比较分析，这突出了可供采纳的最佳实践。"},{"sentence":"By applying sentiment analysis to customer feedback, the company identified emerging dissatisfaction with its after-sales service, which necessitated immediate corrective action.","translation":"通过对客户反馈进行情感分析，该公司发现了对其售后服务日益增长的不满，这需要立即采取纠正措施。"},{"sentence":"A rigorous cost-benefit analysis must account for long-term environmental impacts, not merely short-term economic gains, which is essential for sustainable policy-making.","translation":"严格的成本效益分析必须考虑长期环境影响，而不仅仅是短期经济收益，这对可持续决策至关重要。"}]},"talk":{"examples":[{"sentence":"Although the formal talk was scheduled for an hour, the engaging discussion extended well into the afternoon.","translation":"尽管正式会谈原定一小时，但引人入胜的讨论一直持续到下午。"},{"sentence":"The CEO's talk on innovation inspired the team, which subsequently developed a groundbreaking product.","translation":"首席执行官关于创新的讲话激励了团队，随后他们开发出了一款突破性产品。"},{"sentence":"Because the peace talk between the two nations was productive, a historic treaty was signed the following week.","translation":"由于两国之间的和平会谈富有成效，随后一周签署了历史性条约。"},{"sentence":"Informal talk among researchers often leads to collaborations that result in significant scientific breakthroughs.","translation":"研究人员之间的非正式交谈常常促成合作，从而带来重大科学突破。"},{"sentence":"The professor's talk on ethics challenged students to reconsider their assumptions, thereby fostering critical thinking.","translation":"教授关于伦理的演讲促使学生重新审视自己的假设，从而培养了批判性思维。"}]},"slap":{"examples":[{"sentence":"Although the remark was intended as a joke, it felt like a slap that damaged their professional relationship.","translation":"尽管那句话本意是开玩笑，但它像一记耳光，损害了他们的职业关系。"},{"sentence":"The sudden slap of the wave against the hull reminded the crew that the storm was far from over.","translation":"海浪突然拍打船体的声音提醒船员们，风暴远未结束。"},{"sentence":"Because the policy change was a slap to long-standing traditions, many employees voiced their discontent.","translation":"因为政策变化是对长期传统的侮辱，许多员工表达了不满。"},{"sentence":"When the door swung open with a loud slap, everyone in the room turned to see who had entered.","translation":"当门砰的一声打开时，房间里的每个人都转过头去看是谁进来了。"},{"sentence":"The critic's harsh review was a slap that forced the artist to rethink her entire approach to painting.","translation":"评论家苛刻的评论是一记耳光，迫使艺术家重新思考她的整个绘画方法。"}]},"bother":{"examples":[{"sentence":"Although the constant interruptions bother her, she maintains a polite demeanor to avoid conflict.","translation":"尽管不断的打扰让她烦恼，但她保持礼貌的态度以避免冲突。"},{"sentence":"Because the task is trivial, it does not bother him to complete it before moving on to more important work.","translation":"因为这项任务微不足道，他不介意在继续更重要的工作之前完成它。"},{"sentence":"When students bother their teachers with irrelevant questions, the entire class loses valuable learning time.","translation":"当学生用无关的问题打扰老师时，整个班级都会失去宝贵的学习时间。"},{"sentence":"The noise from the nearby construction site can bother residents, which often leads to formal complaints.","translation":"附近建筑工地的噪音会打扰居民，这常常导致正式投诉。"},{"sentence":"Rather than bother his colleagues with minor issues, he prefers to solve problems independently whenever possible.","translation":"他宁愿尽可能独立解决问题，而不是用小事去打扰同事。"}]},"relay":{"examples":[{"sentence":"The satellite acts as a relay, which enables television signals to reach even the most remote areas.","translation":"卫星充当一个中继站，这使得电视信号能够到达最偏远的地区。"},{"sentence":"Because the relay failed, the entire communication network experienced a significant delay in data transmission.","translation":"因为中继器故障，整个通信网络在数据传输中经历了显著延迟。"},{"sentence":"In a relay race, each runner must pass the baton smoothly to ensure the team maintains its lead.","translation":"在接力赛中，每位跑者必须顺利传递接力棒，以确保团队保持领先。"},{"sentence":"The manager served as a relay, conveying the board's decisions to the various departments without distortion.","translation":"经理充当了一个中转人，将董事会的决定原原本本地传达给各个部门。"},{"sentence":"When the relay station was upgraded, the broadcast quality improved dramatically for all listeners.","translation":"当中继站升级后，所有听众的广播质量都显著提高了。"}]},"medical":{"examples":[{"sentence":"Although medical technology has advanced dramatically, equitable access to these innovations remains a global challenge.","translation":"尽管医学技术取得了巨大进步，但这些创新的公平获取仍然是一个全球性挑战。"},{"sentence":"The government increased funding for medical research, which aims to develop more effective treatments for chronic diseases.","translation":"政府增加了对医学研究的资助，旨在开发更有效的慢性病治疗方法。"},{"sentence":"Because preventive medical care can reduce long-term healthcare costs, policymakers should prioritize public health education.","translation":"由于预防性医疗可以降低长期医疗成本，政策制定者应优先考虑公共卫生教育。"},{"sentence":"Medical professionals who work in underserved areas often face resource shortages that hinder their ability to provide optimal care.","translation":"在服务不足地区工作的医学专业人员经常面临资源短缺，这阻碍了他们提供最佳护理的能力。"},{"sentence":"A comprehensive medical examination, which includes both physical and psychological assessments, is essential for early disease detection.","translation":"全面的体格检查，包括身体和心理评估，对于早期疾病检测至关重要。"}]},"mission":{"examples":[{"sentence":"Although the mission was fraught with danger, the volunteers remained committed to delivering aid to the remote village.","translation":"尽管任务充满危险，志愿者们仍致力于向偏远村庄运送援助物资。"},{"sentence":"The company's mission to reduce carbon emissions has led to innovative practices that benefit both the environment and the economy.","translation":"公司减少碳排放的使命催生了既有利于环境又有利于经济的创新实践。"},{"sentence":"Because the peacekeeping mission required cultural sensitivity, the soldiers underwent extensive training before deployment.","translation":"由于维和任务需要文化敏感性，士兵们在部署前接受了广泛的培训。"},{"sentence":"The scientist's mission to find a cure for the disease was driven by a personal loss, which gave her work profound meaning.","translation":"科学家寻找该疾病治疗方法的使命源于个人损失，这使她的工作具有深远意义。"},{"sentence":"When the diplomatic mission concluded successfully, it paved the way for a historic trade agreement between the two nations.","translation":"当外交使命成功结束时，它为两国之间历史性的贸易协定铺平了道路。"}]},"camera":{"examples":[{"sentence":"Because the camera's sensor was highly sensitive to light, it captured clear images even in dimly lit environments.","translation":"由于相机的传感器对光线高度敏感，即使在光线昏暗的环境中也能捕捉到清晰的图像。"},{"sentence":"The documentary filmmaker used a vintage camera, which added a nostalgic quality to the footage that resonated with audiences.","translation":"纪录片制片人使用了一台老式相机，这为画面增添了怀旧质感，引起了观众的共鸣。"},{"sentence":"While the surveillance camera deterred petty crime, it also raised concerns about privacy among the residents.","translation":"虽然监控摄像头震慑了轻微犯罪，但也引起了居民对隐私的担忧。"},{"sentence":"The photographer adjusted the camera's aperture to ensure that both the foreground and background were in sharp focus.","translation":"摄影师调整了相机的光圈，以确保前景和背景都清晰对焦。"},{"sentence":"A camera that is equipped with a telephoto lens allows wildlife photographers to capture detailed shots from a safe distance.","translation":"配备长焦镜头的相机使野生动物摄影师能够从安全距离拍摄细节照片。"}]},"pronoun":{"examples":[{"sentence":"Although a pronoun simplifies sentence structure, its misuse can obscure the intended meaning, which is why careful editing is essential.","translation":"尽管代词简化了句子结构，但误用会模糊原意，这就是为什么仔细编辑至关重要。"},{"sentence":"Because a pronoun must agree with its antecedent in number, writers should verify that each pronoun clearly refers to a specific noun.","translation":"因为代词必须在数上与其先行词一致，作者应核实每个代词都明确指代一个特定的名词。"},{"sentence":"While a pronoun enhances cohesion in a paragraph, overusing it without clear references can confuse readers, thereby weakening the argument.","translation":"虽然代词能增强段落的连贯性，但过度使用而没有明确指代会令读者困惑，从而削弱论证。"},{"sentence":"When a pronoun appears before its antecedent, the sentence may become ambiguous, which is a common pitfall in complex academic writing.","translation":"当代词出现在先行词之前时，句子可能变得模糊，这是复杂学术写作中常见的陷阱。"},{"sentence":"If a pronoun lacks a clear antecedent, the resulting ambiguity can undermine the credibility of the entire essay, rather than merely causing a minor grammatical error.","translation":"如果代词缺乏明确的先行词，由此产生的歧义会损害整篇文章的可信度，而不仅仅是造成一个小的语法错误。"}]},"fond":{"examples":[{"sentence":"Although she is fond of classical literature, she also recognizes the value of contemporary works that address modern social issues.","translation":"尽管她喜欢古典文学，但她也认识到那些探讨现代社会问题的当代作品的价值。"},{"sentence":"Many educators are fond of using interactive teaching methods because they enhance student engagement and improve learning outcomes.","translation":"许多教育工作者喜欢使用互动式教学方法，因为它们能提高学生的参与度并改善学习效果。"},{"sentence":"While some people are fond of urban living for its convenience, others prefer rural areas where they can enjoy a slower pace of life.","translation":"虽然有些人喜欢城市生活的便利，但另一些人更喜欢乡村地区，在那里他们可以享受更慢的生活节奏。"},{"sentence":"The elderly professor, who was fond of mentoring young researchers, left a lasting legacy through his dedicated guidance and support.","translation":"这位喜欢指导年轻研究者的老教授，通过他专注的指导和支持留下了持久的遗产。"},{"sentence":"Researchers who are fond of interdisciplinary collaboration often produce more innovative solutions, which can lead to breakthroughs in their fields.","translation":"喜欢跨学科合作的研究人员往往能提出更具创新性的解决方案，这可能会带来他们领域的突破。"}]},"persevere":{"examples":[{"sentence":"Graduate students who persevere through the rigorous demands of their research projects often develop exceptional problem-solving skills that benefit their future careers.","translation":"那些能够坚持完成严格研究项目要求的研究生，往往会培养出卓越的解决问题的能力，这有益于他们未来的职业生涯。"},{"sentence":"Although the team encountered numerous technical setbacks, they chose to persevere because they believed the project would eventually benefit public health.","translation":"尽管团队遇到了许多技术挫折，但他们选择坚持下去，因为他们相信该项目最终会有益于公共健康。"},{"sentence":"To master a foreign language, one must persevere in daily practice even when progress seems slow and motivation wanes, thereby ensuring steady improvement.","translation":"要掌握一门外语，即使进步缓慢、动力减弱，也必须坚持每天练习，从而确保稳步提高。"},{"sentence":"The entrepreneur's decision to persevere after the initial product failure ultimately led to a breakthrough that transformed the industry, demonstrating the power of resilience.","translation":"这位企业家在产品最初失败后决定坚持下去，最终带来了改变整个行业的突破，这证明了韧性的力量。"},{"sentence":"Teachers who encourage students to persevere in the face of academic challenges help them build resilience and a growth mindset, which are essential for lifelong learning.","translation":"鼓励学生在面对学业挑战时坚持不懈的教师，有助于他们培养韧性和成长型思维，这对终身学习至关重要。"}]},"add":{"examples":[{"sentence":"To add credibility to her argument, the researcher cited several peer-reviewed studies that supported the same conclusion.","translation":"为了增加论点的可信度，这位研究员引用了数项支持同一结论的同行评审研究。"},{"sentence":"Governments that add investment in early childhood education often see long-term improvements in social equity and economic productivity.","translation":"增加对早期儿童教育投入的政府，通常会在社会公平和经济生产力方面看到长期的改善。"},{"sentence":"When designing public spaces, architects should add elements that encourage community interaction, such as seating areas and green zones.","translation":"在设计公共空间时，建筑师应增加鼓励社区互动的元素，例如休息区和绿化带。"},{"sentence":"Although digital tools can add efficiency to routine tasks, they may also reduce opportunities for critical thinking if not implemented thoughtfully.","translation":"尽管数字工具能为常规任务增添效率，但如果实施不当，也可能减少批判性思考的机会。"},{"sentence":"The new policy will add a layer of oversight to ensure that environmental regulations are enforced more consistently across regions.","translation":"新政策将增加一层监督，以确保环境法规在各地区得到更一致的执行。"}]},"absurd":{"examples":[{"sentence":"It is absurd to claim that reducing carbon emissions will harm the economy, given that green technologies have created millions of jobs worldwide.","translation":"声称减少碳排放会损害经济是荒谬的，因为绿色技术已在全球创造了数百万个就业机会。"},{"sentence":"The notion that a single test score can fully capture a student's potential is not only simplistic but also fundamentally absurd.","translation":"认为单一考试分数能完全反映学生潜力的想法不仅过于简单，而且从根本上就是荒谬的。"},{"sentence":"Because the proposal relied on assumptions that contradicted established scientific consensus, the committee dismissed it as absurd.","translation":"由于该提案所依赖的假设与既定的科学共识相矛盾，委员会认为其荒谬而予以驳回。"},{"sentence":"While some traditions enrich cultural identity, others persist despite having become absurd in the context of modern ethical standards.","translation":"虽然一些传统丰富了文化认同，但另一些尽管在现代伦理标准下已变得荒谬，却依然存在。"},{"sentence":"The absurd disparity in funding between urban and rural schools perpetuates a cycle of inequality that undermines social mobility.","translation":"城乡学校之间荒谬的经费差距使不平等循环持续，从而破坏了社会流动性。"}]},"parachute":{"examples":[{"sentence":"Although the parachute was invented centuries ago, its modern design now incorporates advanced materials that enhance safety and control.","translation":"尽管降落伞在几个世纪前就已发明，但其现代设计现在采用了增强安全性和控制力的先进材料。"},{"sentence":"Because the pilot lost engine power, the crew had to parachute from the aircraft, which ultimately saved their lives.","translation":"由于飞行员失去了发动机动力，机组人员不得不从飞机上跳伞，这最终挽救了他们的生命。"},{"sentence":"The humanitarian organization decided to parachute food supplies into the isolated village, thereby averting a severe famine.","translation":"人道主义组织决定向这个与世隔绝的村庄空投食品，从而避免了一场严重的饥荒。"},{"sentence":"When a parachute fails to deploy properly, the consequences are often fatal, which is why rigorous maintenance is essential.","translation":"当降落伞未能正常展开时，后果往往是致命的，这就是为什么严格的维护至关重要。"},{"sentence":"Rather than parachute into a risky situation without preparation, the team conducted thorough reconnaissance to ensure a safe landing.","translation":"团队没有在没有准备的情况下空降到危险境地，而是进行了彻底的侦察以确保安全着陆。"}]},"superstition":{"examples":[{"sentence":"Although many people dismiss superstition as irrational, it continues to shape cultural practices around the world.","translation":"尽管许多人认为迷信是非理性的，但它仍在世界范围内影响着文化习俗。"},{"sentence":"The superstition that walking under a ladder brings misfortune persists, even among those who consider themselves logical.","translation":"从梯子下走过会带来厄运的迷信依然存在，即使在那些自认为理性的人中也是如此。"},{"sentence":"Because superstition can lead to harmful behaviors, such as avoiding necessary medical treatment, public education is essential.","translation":"由于迷信可能导致有害行为，例如回避必要的医疗，公众教育至关重要。"},{"sentence":"Superstition, which often arises from a desire to control the uncontrollable, can be observed in various forms across societies.","translation":"迷信通常源于控制不可控事物的愿望，在不同社会中以各种形式存在。"},{"sentence":"While superstition may seem harmless, it can reinforce stereotypes and hinder social progress when left unchallenged.","translation":"虽然迷信看似无害，但如果不加质疑，它可能强化刻板印象并阻碍社会进步。"}]},"disease":{"examples":[{"sentence":"Although modern medicine has made great strides, chronic disease remains a major challenge for public health systems.","translation":"尽管现代医学取得了巨大进步，慢性疾病仍然是公共卫生系统的主要挑战。"},{"sentence":"The spread of infectious disease can be mitigated through vaccination programs, which protect both individuals and communities.","translation":"传染病的传播可以通过疫苗接种计划来缓解，这既保护个人也保护社区。"},{"sentence":"Because lifestyle factors such as poor diet and lack of exercise contribute to heart disease, prevention is better than cure.","translation":"由于不良饮食和缺乏锻炼等生活方式因素会导致心脏病，预防胜于治疗。"},{"sentence":"Disease, when detected early, can often be treated more effectively, thereby reducing long-term healthcare costs.","translation":"疾病如果早期发现，通常可以更有效地治疗，从而降低长期医疗成本。"},{"sentence":"The stigma surrounding mental disease prevents many from seeking help, which exacerbates the problem for society as a whole.","translation":"围绕精神疾病的污名阻止了许多人寻求帮助，这加剧了整个社会的问题。"}]},"aeroplane":{"examples":[{"sentence":"The aeroplane, which was once a marvel of engineering, has become an indispensable part of modern life.","translation":"飞机曾经是工程学的奇迹，如今已成为现代生活不可或缺的一部分。"},{"sentence":"Although the aeroplane enables rapid global travel, it also contributes significantly to carbon emissions.","translation":"尽管飞机使快速全球旅行成为可能，但它也显著增加了碳排放。"},{"sentence":"Because aeroplane noise can disturb communities near airports, engineers are designing quieter engines.","translation":"由于飞机噪音会干扰机场附近的社区，工程师们正在设计更安静的发动机。"},{"sentence":"The aeroplane revolutionized warfare in the 20th century, thereby changing the nature of international conflicts.","translation":"飞机在20世纪彻底改变了战争，从而改变了国际冲突的性质。"},{"sentence":"While the aeroplane has made the world more connected, it has also raised concerns about the spread of diseases.","translation":"虽然飞机使世界联系更紧密，但也引发了人们对疾病传播的担忧。"}]},"street":{"examples":[{"sentence":"Although the street was originally designed for pedestrians, it was later converted into a vehicle-only thoroughfare to ease congestion.","translation":"尽管这条街道最初是为行人设计的，但后来被改造成仅供车辆通行的干道以缓解拥堵。"},{"sentence":"Because the narrow street lacked proper drainage, heavy rainfall frequently caused flooding that disrupted local businesses.","translation":"由于这条狭窄的街道缺乏适当的排水系统，暴雨经常引发洪水，扰乱了当地商业。"},{"sentence":"When a street is lined with mature trees, the canopy not only provides shade but also reduces ambient noise levels.","translation":"当一条街道两旁种满成熟的树木时，树冠不仅能提供阴凉，还能降低环境噪音水平。"},{"sentence":"The municipality installed speed bumps along the residential street, thereby forcing drivers to slow down and improving safety for children.","translation":"市政当局在居民区街道上安装了减速带，从而迫使司机减速并提高了儿童的安全。"},{"sentence":"Urban sociologists argue that a vibrant street life, which encourages casual social interactions, is essential for building community cohesion.","translation":"城市社会学家认为，充满活力的街道生活能鼓励随意的社交互动，这对于建立社区凝聚力至关重要。"}]},"bias":{"examples":[{"sentence":"Because confirmation bias causes individuals to seek information that aligns with their preexisting beliefs, critical thinking training is essential.","translation":"由于确认偏误导致个体寻求与其既有信念一致的信息，批判性思维训练至关重要。"},{"sentence":"Although the hiring panel aimed for objectivity, unconscious bias influenced their evaluation of candidates from non-traditional backgrounds.","translation":"尽管招聘小组力求客观，但无意识偏见影响了他们对非传统背景候选人的评估。"},{"sentence":"When an algorithm is trained on historical data that reflects societal bias, it may perpetuate discrimination unless corrective measures are taken.","translation":"当算法基于反映社会偏见的历史数据进行训练时，除非采取纠正措施，否则它可能会延续歧视。"},{"sentence":"Media literacy programs teach students to detect bias in news reporting, thereby enabling them to form more balanced opinions.","translation":"媒介素养课程教导学生察觉新闻报道中的偏见，从而使他们能够形成更均衡的观点。"},{"sentence":"To ensure judicial fairness, any appearance of bias requires a judge to recuse themselves from the case, which upholds public trust in the legal system.","translation":"为了确保司法公正，任何偏见的表象都要求法官回避案件，这维护了公众对法律体系的信任。"}]},"final":{"examples":[{"sentence":"Because the final exam accounts for half of the course grade, students must prepare thoroughly to achieve a satisfactory overall result.","translation":"由于期末考试占课程成绩的一半，学生必须充分准备以获得令人满意的总成绩。"},{"sentence":"The final of the basketball tournament, which was held in a packed stadium, showcased the exceptional talent of both teams.","translation":"篮球锦标赛的决赛在座无虚席的体育场举行，展示了两支球队的非凡才华。"},{"sentence":"Although the final project was demanding, it allowed students to apply the theoretical knowledge they had acquired throughout the semester.","translation":"尽管期末项目要求很高，但它使学生能够应用整个学期所学的理论知识。"},{"sentence":"The committee's final decision, which was reached after lengthy deliberation, will have a lasting impact on the community.","translation":"委员会经过长时间审议后做出的最终决定将对社区产生持久影响。"},{"sentence":"While the final round of negotiations was tense, both parties eventually reached a compromise that satisfied their core interests.","translation":"虽然最后一轮谈判气氛紧张，但双方最终达成了满足其核心利益的妥协。"}]},"up-to-date":{"examples":[{"sentence":"Because technology evolves rapidly, professionals must engage in continuous learning to keep their skills up-to-date.","translation":"由于技术发展迅速，专业人士必须不断学习以保持技能的最新状态。"},{"sentence":"An up-to-date database, which is regularly maintained, ensures that researchers have access to accurate and current information.","translation":"一个定期维护的最新数据库可确保研究人员能够获取准确和当前的信息。"},{"sentence":"Although the textbook was published recently, the instructor supplemented it with up-to-date case studies to reflect recent developments.","translation":"尽管这本教科书是最近出版的，但教师补充了最新的案例研究以反映近期的发展。"},{"sentence":"Companies that fail to adopt up-to-date security measures risk exposing sensitive customer data to cyber threats.","translation":"未能采用最新安全措施的公司可能会使敏感的客户数据面临网络威胁。"},{"sentence":"To ensure patient safety, hospitals must follow up-to-date clinical guidelines that incorporate the latest medical research.","translation":"为了确保患者安全，医院必须遵循纳入最新医学研究的最新临床指南。"}]},"relevant":{"examples":[{"sentence":"When conducting a literature review, it is essential to select sources that are directly relevant to the research question.","translation":"进行文献综述时，选择与研究问题直接相关的来源至关重要。"},{"sentence":"Although the historical event occurred centuries ago, its analysis remains relevant to understanding modern political conflicts.","translation":"尽管这一历史事件发生在几个世纪前，但对其分析仍与理解现代政治冲突相关。"},{"sentence":"Because the job market is highly competitive, candidates should highlight skills that are relevant to the position they are applying for.","translation":"由于就业市场竞争激烈，求职者应突出与所申请职位相关的技能。"},{"sentence":"The professor emphasized the importance of using relevant examples, which help students connect theoretical concepts to real-world situations.","translation":"教授强调了使用相关例子的重要性，这有助于学生将理论概念与现实情况联系起来。"},{"sentence":"To make effective policy decisions, lawmakers must consider data that is relevant to the specific social issue being addressed.","translation":"为了做出有效的政策决策，立法者必须考虑与正在解决的具体社会问题相关的数据。"}]},"surgery":{"examples":[{"sentence":"Although the surgery was successful, the patient required several weeks of physical therapy to regain full mobility.","translation":"尽管手术很成功，患者仍需要几周的物理治疗才能完全恢复活动能力。"},{"sentence":"Because the tumor was malignant, the oncologist recommended surgery as the primary treatment option.","translation":"由于肿瘤是恶性的，肿瘤学家建议将手术作为主要治疗选择。"},{"sentence":"The hospital invested in a robotic system, which allows surgeons to perform minimally invasive surgery with greater precision.","translation":"医院投资了一套机器人系统，使外科医生能够以更高的精度进行微创手术。"},{"sentence":"While surgery can correct the structural defect, it carries inherent risks such as infection and anesthesia complications.","translation":"虽然手术可以纠正结构缺陷，但它具有固有的风险，如感染和麻醉并发症。"},{"sentence":"The patient decided to postpone the surgery until after the semester, thereby avoiding disruption to her academic schedule.","translation":"患者决定将手术推迟到学期结束后，从而避免打乱她的学业安排。"}]},"flower":{"examples":[{"sentence":"Although the flower is often admired for its beauty, its medicinal properties have been valued for centuries.","translation":"尽管这种花常因其美丽而受到赞赏，但其药用价值已被珍视了几个世纪。"},{"sentence":"The flower, which blooms only at night, attracts a specific moth that ensures its pollination.","translation":"这种只在夜间开放的花，吸引了一种特定的蛾子来确保其授粉。"},{"sentence":"Because the flower is highly sensitive to temperature changes, it serves as an indicator of climate shifts.","translation":"由于这种花对温度变化高度敏感，它成为了气候变化的指示物。"},{"sentence":"A carefully arranged flower display can enhance the ambiance of a formal event, thereby impressing the guests.","translation":"精心布置的花卉展示能提升正式活动的氛围，从而给宾客留下深刻印象。"},{"sentence":"The flower, rather than being a mere decoration, plays a crucial role in maintaining the local ecosystem.","translation":"这种花不仅仅是一种装饰，它在维持当地生态系统方面起着至关重要的作用。"}]},"bathroom":{"examples":[{"sentence":"Although the bathroom is often overlooked in home design, its layout can significantly affect daily routines.","translation":"尽管浴室在家居设计中常被忽视，但其布局能显著影响日常生活。"},{"sentence":"The bathroom, which was equipped with a smart mirror, allowed users to check the weather while getting ready.","translation":"配备了智能镜子的浴室，让用户在准备时能查看天气。"},{"sentence":"Because the bathroom lacked adequate lighting, the homeowners decided to install additional fixtures to improve visibility.","translation":"由于浴室缺乏足够的照明，房主决定安装额外的灯具以提高可见度。"},{"sentence":"A well-ventilated bathroom prevents moisture buildup, thereby reducing the risk of mold and structural damage.","translation":"通风良好的浴室能防止湿气积聚，从而降低霉菌和结构损坏的风险。"},{"sentence":"The bathroom serves not only as a functional space but also as a sanctuary where one can escape daily stress.","translation":"浴室不仅是一个功能空间，还是一个可以逃离日常压力的庇护所。"}]},"sink":{"examples":[{"sentence":"Although the sink is a common fixture, its material can greatly influence both durability and maintenance requirements.","translation":"尽管水槽是一个常见装置，但其材料能极大地影响耐用性和维护要求。"},{"sentence":"The sink, which was installed with a high-arc faucet, made it easier to fill large pots for cooking.","translation":"安装了高弧形水龙头的水槽，使得为烹饪注满大锅变得更加容易。"},{"sentence":"Because the sink was positioned under a window, washing dishes became a more pleasant task with natural light.","translation":"由于水槽位于窗户下方，在自然光下洗碗变成了一件更愉快的事。"},{"sentence":"A double-basin sink allows for multitasking, such as soaking vegetables while rinsing dishes, thereby saving time.","translation":"双槽水槽允许同时进行多项任务，比如浸泡蔬菜的同时冲洗碗碟，从而节省时间。"},{"sentence":"The sink, rather than being a simple basin, can be a focal point in kitchen design when crafted from unique materials.","translation":"水槽不仅仅是一个简单的盆，当用独特材料制作时，它可以成为厨房设计的焦点。"}]},"suspend":{"examples":[{"sentence":"Although the airline had to suspend flights due to the volcanic ash cloud, it quickly arranged alternative transportation for stranded passengers.","translation":"尽管航空公司因火山灰云而不得不暂停航班，但它迅速为滞留乘客安排了替代交通。"},{"sentence":"Because the athlete tested positive for a banned substance, the sports federation decided to suspend him from all competitions for two years.","translation":"由于该运动员违禁药物检测呈阳性，体育联合会决定暂停其所有比赛资格两年。"},{"sentence":"The construction company was forced to suspend work on the skyscraper when inspectors discovered critical safety violations.","translation":"当检查人员发现严重的安全违规行为时，建筑公司被迫暂停了摩天大楼的施工。"},{"sentence":"To ensure a fair hearing, the committee voted to suspend the member accused of misconduct until the investigation concluded.","translation":"为确保公正听证，委员会投票决定暂停被指控行为不当的成员的职务，直到调查结束。"},{"sentence":"If the government fails to reach a budget agreement, it may have to suspend non-essential services, which would affect millions of citizens.","translation":"如果政府未能达成预算协议，它可能不得不暂停非必要服务，这将影响数百万公民。"}]},"lock":{"examples":[{"sentence":"Because the lock on the safe was jammed, the technician had to drill through it to retrieve the important documents.","translation":"由于保险箱的锁卡住了，技术人员不得不钻开它来取出重要文件。"},{"sentence":"The antique lock, which was crafted by a renowned locksmith in the 18th century, is now displayed in the museum.","translation":"这把由18世纪著名锁匠制作的古董锁现在陈列在博物馆里。"},{"sentence":"To prevent unauthorized access, the laboratory installed a biometric lock that scans the retina of each researcher.","translation":"为了防止未经授权的进入，实验室安装了一个生物识别锁，扫描每位研究人员的视网膜。"},{"sentence":"Although the lock appeared simple, its internal mechanism was so complex that even experts struggled to pick it.","translation":"尽管这把锁看起来简单，但其内部机制非常复杂，连专家都难以撬开。"},{"sentence":"The ship had to wait at the entrance of the lock while the water level was adjusted to match the downstream canal.","translation":"船只不得不在船闸入口等待，同时水位被调整以匹配下游运河。"}]},"fireman":{"examples":[{"sentence":"Although the fireman was exhausted, he continued to rescue survivors from the collapsed building.","translation":"尽管消防队员筋疲力尽，他仍继续从倒塌的建筑中营救幸存者。"},{"sentence":"The fireman used a thermal imaging camera, which allowed him to locate victims through thick smoke.","translation":"消防队员使用了热成像仪，这使他能够透过浓烟定位受害者。"},{"sentence":"Because the fireman had extensive first-aid training, he was able to stabilize the injured before paramedics arrived.","translation":"因为消防队员接受过广泛的急救培训，他能够在医护人员到达前稳定伤者。"},{"sentence":"When the fireman noticed the structural weakness, he ordered an immediate evacuation to ensure everyone's safety.","translation":"当消防队员注意到结构弱点时，他立即下令疏散，以确保所有人的安全。"},{"sentence":"The fireman's bravery was recognized with a medal, which he received at a formal ceremony.","translation":"消防队员的勇敢得到了一枚奖章的认可，他在正式仪式上接受了这枚奖章。"}]},"quarter":{"examples":[{"sentence":"Although the company's profits declined in the first quarter, they rebounded strongly in the second.","translation":"尽管公司第一季度的利润下降，但第二季度强劲反弹。"},{"sentence":"The report indicates that sales increased by a quarter compared to the previous year, which is a remarkable achievement.","translation":"报告显示，与去年相比销售额增长了四分之一，这是一个了不起的成就。"},{"sentence":"Because the train was delayed, we arrived at a quarter past six instead of the scheduled time.","translation":"因为火车晚点，我们在六点一刻到达，而不是原定时间。"},{"sentence":"The historic quarter of the city, which features cobblestone streets and ancient buildings, attracts many tourists.","translation":"这座城市的历史街区以鹅卵石街道和古老建筑为特色，吸引了许多游客。"},{"sentence":"When the clock struck a quarter to twelve, the students began to pack their books, eager for lunch.","translation":"当钟敲响十一点四十五分时，学生们开始收拾书本，急切地等待午餐。"}]},"regular":{"examples":[{"sentence":"Regular maintenance of equipment, which is often overlooked, can prevent costly breakdowns and extend lifespan.","translation":"设备的定期维护常常被忽视，但它可以防止代价高昂的故障并延长使用寿命。"},{"sentence":"Because she followed a regular study schedule, she was well-prepared for the final examination.","translation":"因为她遵循规律的学习计划，她为期末考试做好了充分准备。"},{"sentence":"The company offers regular training sessions to ensure that employees stay updated with industry trends.","translation":"公司提供定期培训课程，以确保员工跟上行业趋势。"},{"sentence":"Although he was not a regular employee, his contributions to the project were invaluable.","translation":"尽管他不是正式员工，但他对项目的贡献是无价的。"},{"sentence":"Regular exercise, when combined with a balanced diet, leads to significant improvements in overall health.","translation":"定期锻炼与均衡饮食相结合时，会显著改善整体健康。"}]},"adhere":{"examples":[{"sentence":"To ensure the integrity of the study, researchers must adhere to a strict ethical protocol that governs data collection and participant consent.","translation":"为确保研究的诚信，研究人员必须遵守严格的伦理规程，该规程规范了数据收集和参与者同意。"},{"sentence":"Although the new policy was controversial, the committee decided to adhere to its original decision after reviewing the evidence.","translation":"尽管新政策存在争议，委员会在审查证据后仍决定坚持其最初的决定。"},{"sentence":"The paint will adhere more effectively to the surface if you apply a primer before painting.","translation":"如果在涂漆前先涂一层底漆，油漆会更有效地附着在表面上。"},{"sentence":"Successful organizations often adhere to a set of core values that guide their strategic decisions and daily operations.","translation":"成功的组织通常坚持一套核心价值观，这些价值观指导着它们的战略决策和日常运营。"},{"sentence":"Because the tape failed to adhere to the damp wall, the posters fell down overnight.","translation":"由于胶带未能粘附在潮湿的墙上，海报一夜之间就掉了下来。"}]},"subscribe":{"examples":[{"sentence":"Many academics subscribe to the theory that language shapes thought, a view that has influenced both linguistics and psychology.","translation":"许多学者赞同语言塑造思维的理论，这一观点影响了语言学和心理学。"},{"sentence":"To stay informed about industry trends, professionals often subscribe to specialized journals that offer in-depth analysis.","translation":"为了了解行业趋势，专业人士经常订阅提供深入分析的专业期刊。"},{"sentence":"Although he does not subscribe to any particular political party, he consistently supports policies that promote social equality.","translation":"尽管他不拥护任何特定政党，但他一贯支持促进社会平等的政策。"},{"sentence":"The library decided to subscribe to several online databases, thereby expanding the resources available to students and researchers.","translation":"图书馆决定订阅几个在线数据库，从而扩大了学生和研究人员可用的资源。"},{"sentence":"If you subscribe to the newsletter, you will receive weekly updates on the latest developments in renewable energy technology.","translation":"如果您订阅该时事通讯，您将每周收到关于可再生能源技术最新发展的更新。"}]},"shipment":{"examples":[{"sentence":"Although the shipment was scheduled to arrive on Monday, a customs delay pushed the delivery back to Thursday.","translation":"尽管这批货物原定于周一到达，但海关延误将交货推迟到了周四。"},{"sentence":"The company tracks every shipment in real time, which allows customers to monitor their orders from dispatch to delivery.","translation":"公司实时跟踪每一批货物，这使得客户能够从发货到交货全程监控他们的订单。"},{"sentence":"Because the shipment contained perishable goods, the logistics team prioritized its transportation to prevent spoilage.","translation":"由于这批货物包含易腐商品，物流团队优先安排运输以防止变质。"},{"sentence":"To ensure the shipment complies with international regulations, all items must be inspected and certified before export.","translation":"为确保这批货物符合国际规定，所有物品在出口前必须经过检查和认证。"},{"sentence":"The unexpected delay in the shipment disrupted the production schedule, thereby causing a ripple effect throughout the supply chain.","translation":"货物运输的意外延误打乱了生产计划，从而在整个供应链中引起了连锁反应。"}]},"staircase":{"examples":[{"sentence":"The ancient stone staircase, which had been worn smooth by centuries of use, led to a hidden library that few visitors ever discovered.","translation":"那座古老的石梯因数百年的使用而被磨得光滑，通向一个很少有游客发现的隐秘图书馆。"},{"sentence":"Because the elevator was under maintenance, residents had to climb the narrow staircase to reach their apartments on the top floor.","translation":"由于电梯正在维修，居民们不得不爬上狭窄的楼梯才能到达顶层的公寓。"},{"sentence":"The architect designed a spiral staircase to save space while adding an elegant focal point to the modern lobby.","translation":"建筑师设计了一个螺旋楼梯，既节省了空间，又为现代大堂增添了一个优雅的视觉焦点。"},{"sentence":"Although the grand staircase impressed visitors with its marble balustrades, it also posed a safety risk for elderly residents during emergencies.","translation":"尽管宏伟的楼梯以其大理石栏杆给访客留下了深刻印象，但在紧急情况下对老年居民构成了安全隐患。"},{"sentence":"Researchers observed that students who used the staircase instead of the elevator showed measurable improvements in cardiovascular fitness over a semester.","translation":"研究人员观察到，那些走楼梯而不是乘电梯的学生在一个学期内的心血管健康状况有了可测量的改善。"}]},"fix":{"examples":[{"sentence":"To fix the persistent software glitch, the development team conducted a thorough code review that revealed several hidden errors.","translation":"为了修复那个持续存在的软件故障，开发团队进行了一次彻底的代码审查，发现了几个隐藏的错误。"},{"sentence":"The committee decided to fix the annual conference date in early September so that members could plan their schedules well in advance.","translation":"委员会决定将年度会议日期定在九月初，以便成员们能提前安排好日程。"},{"sentence":"Although the mechanic managed to fix the engine temporarily, he warned that a complete overhaul would be necessary within the year.","translation":"尽管机械师设法暂时修好了发动机，但他警告说一年内必须进行彻底的大修。"},{"sentence":"Researchers are working to fix the flaws in the experimental design, which have led to inconsistent results across multiple trials.","translation":"研究人员正在努力修正实验设计中的缺陷，这些缺陷导致了多次试验结果不一致。"},{"sentence":"The government introduced price controls to fix the cost of essential medicines, thereby ensuring that low-income families could afford treatment.","translation":"政府实行价格管制来固定基本药品的费用，从而确保低收入家庭能负担得起治疗。"}]},"brandy":{"examples":[{"sentence":"Although brandy is traditionally distilled from grapes, some varieties are made from other fruits such as apples or cherries.","translation":"尽管白兰地传统上由葡萄蒸馏而成，但有些品种是用苹果或樱桃等其他水果制成的。"},{"sentence":"Because the brandy had been aged in oak barrels for twenty years, it possessed a remarkably smooth and complex flavor profile.","translation":"由于白兰地已在橡木桶中陈酿了二十年，它具有非常顺滑和复杂的风味特征。"},{"sentence":"When the chef added a splash of brandy to the sauce, it ignited briefly, which enhanced the dish with a rich caramelized note.","translation":"当厨师向酱汁中加入少许白兰地时，它短暂燃烧起来，这为菜肴增添了浓郁的焦糖风味。"},{"sentence":"While brandy is often enjoyed as a digestif after a meal, it can also be used in cooking to deglaze pans and add depth to sauces.","translation":"虽然白兰地常在餐后作为消化酒享用，但它也可用于烹饪，用来给锅底去渣并为酱汁增添层次感。"},{"sentence":"The distillery's decision to use traditional copper pot stills, rather than modern column stills, gives their brandy a distinctive character.","translation":"酿酒厂决定使用传统的铜制壶式蒸馏器，而不是现代的柱式蒸馏器，这赋予了他们的白兰地独特的个性。"}]},"against":{"examples":[{"sentence":"Although the new evidence weighed heavily against the defendant, the jury remained unconvinced due to procedural errors.","translation":"尽管新证据对被告极为不利，但由于程序错误，陪审团仍未被说服。"},{"sentence":"Because the insurance policy specifically guards against flood damage, the homeowners were able to recover their losses after the storm.","translation":"由于保险单专门防范洪水损害，房主在暴风雨后得以挽回损失。"},{"sentence":"When the committee voted against the proposal, they cited a lack of long-term feasibility studies to support the plan.","translation":"当委员会投票反对该提案时，他们指出缺乏支持该计划的长期可行性研究。"},{"sentence":"Public health campaigns that warn against the dangers of smoking have contributed to a significant decline in tobacco use.","translation":"警告吸烟危害的公共卫生运动促使烟草使用显著下降。"},{"sentence":"The new regulation is designed to protect consumers against fraudulent practices, thereby increasing trust in the financial system.","translation":"新规定旨在保护消费者免受欺诈行为的侵害，从而增强对金融体系的信任。"}]},"inspire":{"examples":[{"sentence":"Although the novel was written centuries ago, its profound themes continue to inspire modern readers to question societal norms.","translation":"尽管这部小说写于几个世纪前，但其深刻的主题仍能激励现代读者质疑社会规范。"},{"sentence":"Because the keynote speaker shared her personal journey of overcoming adversity, she managed to inspire the entire graduating class to pursue their dreams relentlessly.","translation":"因为主讲人分享了她克服逆境的个人历程，她成功地激励了整个毕业班不懈追求梦想。"},{"sentence":"When leaders demonstrate integrity and compassion, they inspire loyalty and dedication among their followers, which strengthens the entire organization.","translation":"当领导者展现出正直和同情心时，他们会激发追随者的忠诚和奉献精神，从而加强整个组织。"},{"sentence":"The breathtaking beauty of the natural landscape can inspire artists to create works that capture the essence of tranquility and awe.","translation":"自然景观的惊人美丽可以激发艺术家创作出捕捉宁静与敬畏本质的作品。"},{"sentence":"Innovative teaching methods that incorporate real-world problems often inspire students to develop critical thinking skills, thereby preparing them for future challenges.","translation":"融入现实世界问题的创新教学方法往往能激励学生发展批判性思维技能，从而为未来的挑战做好准备。"}]},"applaud":{"examples":[{"sentence":"While we applaud the company's efforts to reduce waste, its overall environmental record remains questionable due to past violations.","translation":"尽管我们称赞该公司减少浪费的努力，但由于过去的违规行为，其整体环境记录仍然值得怀疑。"},{"sentence":"The committee decided to applaud the researcher's groundbreaking discovery, which could lead to more effective treatments for the disease.","translation":"委员会决定称赞这位研究人员的突破性发现，这可能会带来更有效的疾病治疗方法。"},{"sentence":"Although the policy has flaws, we should applaud the government for taking a proactive stance on mental health issues.","translation":"尽管该政策有缺陷，但我们应该称赞政府在心理健康问题上采取了积极主动的立场。"},{"sentence":"Because the volunteer team worked tirelessly to rebuild the community center, local residents gathered to applaud their dedication and hard work.","translation":"因为志愿者团队不知疲倦地重建社区中心，当地居民聚集起来称赞他们的奉献和辛勤工作。"},{"sentence":"Critics may applaud the film's artistic ambition, but its complex narrative structure alienates mainstream audiences, thereby limiting its commercial success.","translation":"评论家可能会称赞这部电影的艺术雄心，但其复杂的叙事结构疏远了主流观众，从而限制了其商业成功。"}]},"impatient":{"examples":[{"sentence":"Because the project deadline was approaching, the manager became increasingly impatient with any delays, which created a tense work environment.","translation":"因为项目截止日期临近，经理对任何延误变得越来越不耐烦，这造成了紧张的工作环境。"},{"sentence":"Although the students were impatient to receive their exam results, the university maintained a strict schedule to ensure accuracy.","translation":"尽管学生们急于收到考试成绩，但大学严格遵守时间表以确保准确性。"},{"sentence":"When dealing with complex negotiations, diplomats must remain patient, as an impatient attitude can derail the entire peace process.","translation":"在处理复杂的谈判时，外交官必须保持耐心，因为不耐烦的态度可能会破坏整个和平进程。"},{"sentence":"The audience grew impatient during the lengthy intermission, which prompted the theater to improve its scheduling for future performances.","translation":"观众在漫长的中场休息期间变得不耐烦，这促使剧院改进未来演出的时间安排。"},{"sentence":"Investors who are impatient for quick returns often overlook sustainable business models that yield long-term benefits, thereby missing valuable opportunities.","translation":"急于获得快速回报的投资者往往忽视能产生长期效益的可持续商业模式，从而错失宝贵机会。"}]},"luck":{"examples":[{"sentence":"Although hard work is essential, a measure of luck often determines whether a researcher makes a breakthrough discovery.","translation":"尽管勤奋至关重要，但一定程度上的运气往往决定着研究者能否取得突破性发现。"},{"sentence":"Because luck plays a role in career advancement, professionals should remain humble and open to unexpected opportunities.","translation":"由于运气在职业发展中起着作用，专业人士应当保持谦逊并对意外机遇持开放态度。"},{"sentence":"While luck can influence short-term outcomes, sustained success in any field ultimately depends on consistent effort and adaptability.","translation":"虽然运气能影响短期结果，但任何领域的持续成功最终都取决于持之以恒的努力和适应能力。"},{"sentence":"Entrepreneurs who attribute their achievements solely to luck overlook the countless hours of preparation that made success possible.","translation":"那些将成就完全归功于运气的企业家，忽视了使成功成为可能的无数准备时间。"},{"sentence":"In competitive environments, relying on luck rather than strategic planning is a risky approach that seldom yields long-term rewards.","translation":"在竞争环境中，依赖运气而非战略规划是一种风险很高的做法，很少能带来长期回报。"}]},"suggest":{"examples":[{"sentence":"Recent studies suggest that regular exposure to green spaces can significantly reduce stress levels among urban residents.","translation":"最近的研究表明，经常接触绿地可以显著降低城市居民的压力水平。"},{"sentence":"Economic indicators suggest that the country is gradually recovering from the recession, though challenges remain.","translation":"经济指标显示，该国正逐渐从衰退中复苏，尽管挑战依然存在。"},{"sentence":"To improve public health, experts suggest that governments invest more in preventive care rather than solely in treatment.","translation":"为改善公共健康，专家建议政府加大对预防保健的投入，而不仅仅是治疗。"},{"sentence":"The data suggest a strong correlation between early childhood education and later academic achievement, which warrants further investigation.","translation":"数据表明，早期儿童教育与日后的学业成就之间存在很强的相关性，这值得进一步研究。"},{"sentence":"Some psychologists suggest that fostering a growth mindset in students can enhance their resilience when facing academic setbacks.","translation":"一些心理学家提出，培养学生的成长型思维模式可以增强他们在面对学业挫折时的韧性。"}]},"these":{"examples":[{"sentence":"Although these findings are preliminary, they provide a solid foundation for future research on climate adaptation.","translation":"尽管这些发现是初步的，但它们为未来气候适应研究提供了坚实的基础。"},{"sentence":"Because these policies were implemented without sufficient public consultation, they faced widespread opposition from local communities.","translation":"由于这些政策在实施时没有充分征求公众意见，它们遭到了当地社区的广泛反对。"},{"sentence":"While these statistics indicate a positive trend, policymakers must remain cautious about drawing definitive conclusions.","translation":"虽然这些统计数据表明了一个积极的趋势，但政策制定者在得出明确结论时必须保持谨慎。"},{"sentence":"These innovative approaches, which integrate traditional knowledge with modern technology, have the potential to revolutionize sustainable agriculture.","translation":"这些将传统知识与现代技术相结合的创新方法，有可能彻底改变可持续农业。"},{"sentence":"When analyzing these complex issues, researchers should adopt an interdisciplinary perspective to ensure a comprehensive understanding.","translation":"在分析这些复杂问题时，研究人员应采用跨学科的视角，以确保全面的理解。"}]},"turkey":{"examples":[{"sentence":"Although turkey is a traditional centerpiece for Thanksgiving dinners, many families now opt for plant-based alternatives.","translation":"尽管火鸡是感恩节晚餐的传统主菜，但许多家庭现在选择植物性替代品。"},{"sentence":"The chef recommended brining the turkey overnight to ensure the meat remained moist during roasting.","translation":"厨师建议将火鸡浸泡在盐水中过夜，以确保在烤制过程中肉质保持湿润。"},{"sentence":"Because turkey is a lean source of protein, it is often included in diets designed for weight management.","translation":"由于火鸡是一种低脂蛋白质来源，它常被纳入为体重管理而设计的饮食中。"},{"sentence":"Turkey, which straddles the boundary between Europe and Asia, has a rich cultural heritage that attracts millions of tourists annually.","translation":"土耳其横跨欧亚边界，拥有丰富的文化遗产，每年吸引数百万游客。"},{"sentence":"Economists have noted that Turkey's strategic location makes it a vital hub for energy pipelines connecting East and West.","translation":"经济学家指出，土耳其的战略位置使其成为连接东西方能源管道的重要枢纽。"}]},"deceive":{"examples":[{"sentence":"Although the company's financial reports appeared sound, they were crafted to deceive investors about its true liabilities.","translation":"尽管公司的财务报告看似稳健，但它们被精心编造以欺骗投资者了解其真实负债。"},{"sentence":"Because the witness chose to deceive the court, the entire case was compromised, which led to a mistrial.","translation":"由于证人选择欺骗法庭，整个案件受到影响，导致审判无效。"},{"sentence":"While some advertisements use exaggerated claims to deceive consumers, regulatory bodies work to ensure such practices are penalized.","translation":"虽然一些广告使用夸大宣传来欺骗消费者，但监管机构努力确保此类行为受到处罚。"},{"sentence":"If leaders deceive their followers about the severity of a crisis, they risk losing authority when the truth emerges.","translation":"如果领导者在危机严重性上欺骗追随者，当真相浮出水面时，他们就有失去权威的风险。"},{"sentence":"The magician's performance did not deceive the audience, which quickly discerned the hidden mechanism behind the illusion.","translation":"魔术师的表演没有欺骗观众，观众很快识破了幻觉背后的隐藏机关。"}]},"numerous":{"examples":[{"sentence":"Numerous experiments have confirmed that sleep deprivation impairs cognitive function, which is why experts recommend consistent sleep schedules.","translation":"大量实验证实，睡眠不足会损害认知功能，这就是专家建议保持规律睡眠的原因。"},{"sentence":"Although the proposal received numerous endorsements from industry leaders, it was ultimately rejected due to environmental concerns.","translation":"尽管该提案得到了行业领袖的众多支持，但最终因环境问题而被否决。"},{"sentence":"Because the city has numerous historical sites, it attracts tourists who are eager to explore its cultural heritage.","translation":"由于这座城市拥有众多历史遗迹，它吸引了渴望探索其文化遗产的游客。"},{"sentence":"The researcher encountered numerous obstacles while collecting data, yet she persisted to ensure the study's validity.","translation":"研究人员在收集数据时遇到了无数障碍，但她坚持不懈以确保研究的有效性。"},{"sentence":"Numerous factors contribute to economic inequality, including disparities in education, which policymakers must address through comprehensive reforms.","translation":"众多因素导致了经济不平等，包括教育差距，政策制定者必须通过全面改革来解决这些问题。"}]},"cure":{"examples":[{"sentence":"While a definitive cure for Alzheimer's disease remains elusive, early intervention can significantly slow its progression.","translation":"虽然阿尔茨海默病的根治方法仍然难以找到，但早期干预可以显著减缓其进展。"},{"sentence":"The development of a universal flu vaccine would represent a major cure for a virus that mutates rapidly each season.","translation":"通用流感疫苗的研发将是对每个季节都迅速变异的病毒的一种重大疗法。"},{"sentence":"Public health campaigns emphasize that prevention is often more cost-effective than searching for a cure after infection.","translation":"公共卫生运动强调，预防往往比感染后寻找治疗方法更具成本效益。"},{"sentence":"Researchers caution that a single cure for all types of cancer is unlikely, given the disease's genetic complexity.","translation":"研究人员提醒说，鉴于癌症的遗传复杂性，单一的治疗方法对所有类型都有效是不可能的。"},{"sentence":"The new policy aims to cure the systemic inefficiencies that have long plagued the healthcare system.","translation":"新政策旨在纠正长期困扰医疗保健系统的体制性低效问题。"}]},"prisoner":{"examples":[{"sentence":"Although the prisoner maintained his innocence throughout the trial, the jury found him guilty based on forensic evidence.","translation":"尽管该囚犯在整个审判过程中坚称自己无罪，陪审团还是根据法医证据判定他有罪。"},{"sentence":"The prisoner was transferred to a minimum-security facility because he had shown consistent good behavior and posed a low flight risk.","translation":"由于该囚犯表现一贯良好且逃跑风险低，他被转移到了最低安全级别的监狱。"},{"sentence":"While the prisoner served his sentence, he took advantage of educational programs to earn a degree, which improved his prospects for reintegration.","translation":"该囚犯在服刑期间利用教育项目获得了学位，从而改善了他重新融入社会的前景。"},{"sentence":"The prisoner's family appealed to the governor for clemency, arguing that the sentence was disproportionate to the crime committed.","translation":"该囚犯的家人向州长请求宽大处理，认为判决与所犯罪行不成比例。"},{"sentence":"Under the new rehabilitation policy, every prisoner is required to participate in vocational training, thereby reducing the likelihood of reoffending.","translation":"根据新的改造政策，每名囚犯都必须参加职业培训，从而降低再犯的可能性。"}]},"siege":{"examples":[{"sentence":"Although the siege lasted for months, the defenders never lost hope of eventual relief.","translation":"尽管围困持续了数月，守军从未失去最终解围的希望。"},{"sentence":"Because the city was under siege, all supply routes were cut off, which led to a humanitarian crisis.","translation":"由于城市被围困，所有补给线都被切断，这导致了人道主义危机。"},{"sentence":"The castle withstood the siege, thereby demonstrating the effectiveness of its new fortifications.","translation":"城堡经受住了围攻，从而证明了其新防御工事的有效性。"},{"sentence":"When the siege was finally lifted, the residents emerged to find their city in ruins.","translation":"当围困最终解除时，居民们出来发现他们的城市已成废墟。"},{"sentence":"The general laid siege to the fortress, while his engineers constructed siege engines to breach the walls.","translation":"将军包围了要塞，同时他的工程师建造攻城器械以突破城墙。"}]},"literature":{"examples":[{"sentence":"Because literature reflects the human experience, studying it fosters empathy and cultural understanding.","translation":"因为文学反映了人类经验，学习文学能培养同理心和文化理解。"},{"sentence":"Although modern literature often challenges traditional norms, it continues to draw on classical themes.","translation":"尽管现代文学经常挑战传统规范，但它仍然借鉴古典主题。"},{"sentence":"The professor argued that reading literature critically, which involves analyzing narrative techniques, enhances intellectual growth.","translation":"教授认为，批判性地阅读文学，包括分析叙事技巧，能促进智力成长。"},{"sentence":"When reviewing the scientific literature, researchers must evaluate the methodology to ensure the findings are reliable.","translation":"在查阅科学文献时，研究人员必须评估方法论以确保研究结果可靠。"},{"sentence":"The literature on climate change indicates that urgent action is needed, thereby compelling policymakers to act.","translation":"关于气候变化的文献表明需要采取紧急行动，从而迫使决策者采取行动。"}]},"syndrome":{"examples":[{"sentence":"Although the exact cause of chronic fatigue syndrome remains unclear, researchers believe that viral infections may trigger its onset.","translation":"尽管慢性疲劳综合征的确切原因尚不清楚，但研究人员认为病毒感染可能触发其发作。"},{"sentence":"Because Stockholm syndrome involves a paradoxical emotional bond between captor and captive, it challenges conventional understandings of trauma response.","translation":"由于斯德哥尔摩综合征涉及绑架者与俘虏之间矛盾的情感纽带，它挑战了对创伤反应的常规理解。"},{"sentence":"The empty nest syndrome, which often affects parents when children leave home, can be mitigated through proactive social engagement and new hobbies.","translation":"空巢综合征常在子女离家时影响父母，但通过积极的社交参与和新爱好可以缓解。"},{"sentence":"While Down syndrome is a genetic condition, early intervention programs can significantly improve the cognitive and social development of affected children.","translation":"虽然唐氏综合征是一种遗传病，但早期干预计划能显著改善受影响儿童的认知和社交发展。"},{"sentence":"The broken windows theory suggests that visible signs of disorder can foster a syndrome of escalating crime, thereby necessitating prompt community maintenance.","translation":"破窗理论表明，明显的混乱迹象会助长犯罪升级的综合征，因此需要及时的社区维护。"}]},"costume":{"examples":[{"sentence":"Because the costume designer meticulously researched 18th-century fashion, the film's visual authenticity earned widespread critical acclaim.","translation":"由于服装设计师精心研究了18世纪的时尚，这部电影的视觉真实性赢得了广泛的好评。"},{"sentence":"Although the traditional costume is rarely worn in daily life, it remains a powerful symbol of national pride during official ceremonies.","translation":"尽管传统服装在日常生活中很少穿着，但在官方仪式上它仍然是民族自豪感的有力象征。"},{"sentence":"The museum's costume exhibition, which features garments from over thirty cultures, offers visitors a vivid lesson in global textile history.","translation":"博物馆的服装展览展示了来自三十多种文化的服饰，为参观者提供了生动的全球纺织史课程。"},{"sentence":"When designing a mascot costume for the international sports event, the team prioritized lightweight materials to ensure the performer's comfort.","translation":"在为国际体育赛事设计吉祥物服装时，团队优先考虑轻质材料以确保表演者的舒适度。"},{"sentence":"The elaborate costume parade not only celebrates artistic creativity but also strengthens community bonds through shared cultural expression.","translation":"精心制作的服装游行不仅庆祝艺术创造力，还通过共同的文化表达加强了社区纽带。"}]},"hope":{"examples":[{"sentence":"Although the experimental treatment is still in its early stages, it offers a glimmer of hope for patients with previously incurable conditions.","translation":"尽管实验性治疗仍处于早期阶段，但它为先前无法治愈的患者带来了一线希望。"},{"sentence":"The hope that diplomatic dialogue can prevent armed conflict has prompted world leaders to convene an emergency summit.","translation":"外交对话能够防止武装冲突的希望促使世界领导人召开紧急峰会。"},{"sentence":"Because the community project provided vocational training, it restored hope among unemployed youth who had felt marginalized by society.","translation":"由于社区项目提供了职业培训，它重新点燃了那些感到被社会边缘化的失业青年的希望。"},{"sentence":"While the economic forecast remains uncertain, the central bank's decisive action has bolstered hope for a steady recovery.","translation":"尽管经济前景仍不确定，但央行的果断行动增强了稳步复苏的希望。"},{"sentence":"The hope of preserving endangered languages lies in digital archiving, which allows future generations to access and revitalize their linguistic heritage.","translation":"保护濒危语言的希望在于数字存档，这使后代能够获取并复兴他们的语言遗产。"}]},"physiological":{"examples":[{"sentence":"Although psychological factors are often emphasized, the physiological basis of addiction must be addressed through medical interventions.","translation":"尽管心理因素常被强调，但成瘾的生理基础必须通过医学干预来解决。"},{"sentence":"Because prolonged exposure to blue light disrupts circadian rhythms, it can lead to adverse physiological effects such as insomnia.","translation":"由于长时间暴露于蓝光会扰乱昼夜节律，它可能导致失眠等不良生理影响。"},{"sentence":"The study revealed that regular exercise induces beneficial physiological adaptations, which enhance cardiovascular efficiency over time.","translation":"研究表明，定期运动能引发有益的生理适应，从而逐渐提高心血管效率。"},{"sentence":"When individuals experience chronic stress, their physiological responses can become dysregulated, increasing the risk of hypertension.","translation":"当个体经历慢性压力时，其生理反应可能失调，从而增加患高血压的风险。"},{"sentence":"Understanding the physiological mechanisms behind aging is crucial for developing therapies that extend healthy lifespan.","translation":"理解衰老背后的生理机制对于开发延长健康寿命的疗法至关重要。"}]},"apartment":{"examples":[{"sentence":"Although the apartment was small, its proximity to the university library made it an ideal choice for graduate students.","translation":"尽管这间公寓很小，但它靠近大学图书馆的位置使其成为研究生的理想选择。"},{"sentence":"The apartment, which features a dedicated study nook, allows residents to separate work from relaxation effectively.","translation":"这间公寓设有一个专门的学习角落，使住户能够有效地将工作与放松分开。"},{"sentence":"Because the apartment is located in a mixed-use building, residents enjoy convenient access to shops and cafes on the ground floor.","translation":"由于这间公寓位于一栋商住两用楼内，住户可以方便地前往底层的商店和咖啡馆。"},{"sentence":"She renovated the apartment with soundproof walls to ensure a quiet environment for her online teaching sessions.","translation":"她翻新了公寓，安装了隔音墙，以确保在线教学时有一个安静的环境。"},{"sentence":"When choosing an apartment, graduate students often prioritize affordability and a short commute over spaciousness.","translation":"在选择公寓时，研究生通常优先考虑经济实惠和通勤时间短，而不是空间宽敞。"}]},"unify":{"examples":[{"sentence":"The new curriculum aims to unify theoretical knowledge with practical application, thereby enhancing students' problem-solving skills.","translation":"新课程旨在将理论知识与实际应用统一起来，从而提高学生解决问题的能力。"},{"sentence":"Although the two departments had different cultures, the joint project helped unify their efforts toward a common goal.","translation":"尽管两个部门文化不同，但联合项目有助于将他们的努力统一到共同的目标上。"},{"sentence":"To unify the scattered data sources, the research team developed a centralized database that streamlined analysis.","translation":"为了统一分散的数据源，研究团队开发了一个集中式数据库，简化了分析过程。"},{"sentence":"If we can unify the various assessment criteria, we will be able to compare student performance across institutions more accurately.","translation":"如果我们能统一各种评估标准，就能更准确地比较不同院校的学生表现。"},{"sentence":"The leader's vision helped unify the team, which had previously been divided by conflicting priorities.","translation":"领导者的愿景帮助团结了团队，此前团队因优先事项冲突而分裂。"}]},"crush":{"examples":[{"sentence":"Although she tried to focus on her studies, her crush on the class president made it difficult to concentrate during lectures.","translation":"尽管她试图专注于学习，但对班长的迷恋使她在课堂上难以集中注意力。"},{"sentence":"The crush of tourists during the holiday season often overwhelms the small town's infrastructure, which was designed for a much smaller population.","translation":"假日期间游客的拥挤常常使这个小镇的基础设施不堪重负，而这些设施原本是为少得多的人口设计的。"},{"sentence":"Because the machine applies a steady crush to the raw materials, it can extract juice more efficiently than traditional methods.","translation":"由于该机器对原材料施加稳定的压碎力，它能比传统方法更高效地榨取果汁。"},{"sentence":"When the crush of applicants exceeded expectations, the hiring committee decided to add an extra round of interviews to ensure a fair selection process.","translation":"当申请人数超出预期时，招聘委员会决定增加一轮面试，以确保选拔过程公平。"},{"sentence":"His adolescent crush on the pop star faded over time, but it taught him that intense feelings are often temporary and not a basis for life decisions.","translation":"他对那位流行歌星的青春期迷恋随时间消退，但这教会他，强烈的情感往往是暂时的，不能作为人生决策的基础。"}]},"pond":{"examples":[{"sentence":"Although the pond is small, it supports a diverse ecosystem that includes fish, frogs, and aquatic plants.","translation":"尽管这个池塘很小，但它支撑着一个包括鱼类、青蛙和水生植物在内的多样化生态系统。"},{"sentence":"Because the pond is located in a protected area, visitors are not allowed to swim or fish there.","translation":"由于这个池塘位于保护区，游客不得在那里游泳或钓鱼。"},{"sentence":"The pond, which was created by damming a small stream, now serves as a vital water source for local wildlife.","translation":"这个通过筑坝拦截小溪而形成的池塘，现在成为当地野生动物的重要水源。"},{"sentence":"When the pond freezes over in winter, children often skate on its surface despite the potential danger.","translation":"当池塘在冬天结冰时，孩子们经常在冰面上滑冰，尽管存在潜在危险。"},{"sentence":"To improve water quality, the community introduced a filtration system that circulates and cleans the pond water.","translation":"为了改善水质，社区引入了一个循环并净化池塘水的过滤系统。"}]},"restaurant":{"examples":[{"sentence":"Although the restaurant is expensive, it remains popular because of its exceptional service and unique ambiance.","translation":"尽管这家餐厅价格昂贵，但由于其卓越的服务和独特的氛围，它仍然很受欢迎。"},{"sentence":"The restaurant, which specializes in regional cuisine, attracts both locals and tourists seeking authentic flavors.","translation":"这家专营地方菜的餐厅吸引了寻求地道风味的当地人和游客。"},{"sentence":"Because the restaurant uses organic ingredients, its dishes are not only healthier but also more flavorful.","translation":"由于这家餐厅使用有机食材，其菜肴不仅更健康，而且更美味。"},{"sentence":"When the restaurant introduced online ordering, its revenue increased significantly within a few months.","translation":"当这家餐厅推出在线订餐后，其收入在几个月内显著增长。"},{"sentence":"To ensure customer satisfaction, the restaurant regularly updates its menu based on seasonal availability and feedback.","translation":"为了确保顾客满意，这家餐厅根据季节供应和反馈定期更新菜单。"}]},"vanish":{"examples":[{"sentence":"When a species loses its habitat, it may vanish from the ecosystem within a few decades.","translation":"当一个物种失去栖息地时，它可能在几十年内从生态系统中消失。"},{"sentence":"Without consistent practice, the language skills acquired through intensive study can vanish over time.","translation":"如果没有持续的练习，通过强化学习获得的语言技能会随着时间的推移而消失。"},{"sentence":"Many traditional crafts vanish because younger generations show little interest in learning them.","translation":"许多传统手工艺消失，是因为年轻一代对学习它们兴趣不大。"},{"sentence":"The sense of community can vanish when people rely solely on digital communication instead of face-to-face interaction.","translation":"当人们完全依赖数字通信而非面对面交流时，社区感可能会消失。"},{"sentence":"If governments fail to protect cultural heritage, unique historical sites may vanish forever.","translation":"如果政府未能保护文化遗产，独特的历史遗址可能会永远消失。"}]},"lose":{"examples":[{"sentence":"Although the team played well, they still managed to lose the final match due to a last-minute mistake.","translation":"尽管球队表现出色，但由于最后一刻的失误，他们还是输掉了决赛。"},{"sentence":"If you do not back up your files regularly, you may lose important data when your computer crashes.","translation":"如果你不定期备份文件，当电脑崩溃时你可能会丢失重要数据。"},{"sentence":"Because the company ignored market trends, it began to lose its competitive advantage over time.","translation":"因为公司忽视了市场趋势，它逐渐失去了竞争优势。"},{"sentence":"When individuals focus solely on short-term gains, they often lose sight of long-term sustainability.","translation":"当个人只关注短期利益时，他们常常会忽视长期的可持续性。"},{"sentence":"Without proper guidance, students may lose motivation and struggle to achieve their academic goals.","translation":"如果没有适当的指导，学生可能会失去动力，难以实现学业目标。"}]},"daytime":{"examples":[{"sentence":"Because daytime temperatures in the desert can exceed 40 degrees Celsius, many animals are nocturnal.","translation":"因为沙漠白天的温度可能超过40摄氏度，许多动物都是夜行性的。"},{"sentence":"Although daytime naps are often seen as unproductive, research shows they can enhance cognitive function.","translation":"尽管白天小睡常被视为效率低下，但研究表明它可以增强认知功能。"},{"sentence":"When cities implement daytime curfews for teenagers, juvenile crime rates tend to decrease significantly.","translation":"当城市对青少年实施白天宵禁时，青少年犯罪率往往会显著下降。"},{"sentence":"The daytime sky appears blue because air molecules scatter shorter wavelengths of light more effectively.","translation":"白天的天空呈现蓝色，是因为空气分子更有效地散射较短波长的光。"},{"sentence":"If workers are exposed to excessive noise during daytime hours, their hearing may be permanently damaged.","translation":"如果工人在白天时段暴露于过度噪音中，他们的听力可能会永久受损。"}]},"landlady":{"examples":[{"sentence":"Because the landlady was strict about late payments, the tenants always transferred the rent before the first of the month.","translation":"由于女房东对逾期付款很严格，租户们总是在每月一号之前转账租金。"},{"sentence":"Although the landlady advertised the apartment as furnished, the sofa and dining table were quite worn.","translation":"尽管女房东宣传公寓配有家具，但沙发和餐桌相当破旧。"},{"sentence":"The landlady decided to install a new heating system, which significantly reduced the tenants' winter energy bills.","translation":"女房东决定安装新的供暖系统，这大大降低了租户冬季的能源账单。"},{"sentence":"When a pipe burst in the kitchen, the landlady called a plumber immediately to prevent further water damage.","translation":"当厨房水管爆裂时，女房东立即叫来水管工，以防止进一步的水损。"},{"sentence":"A considerate landlady understands that respecting tenants' privacy is essential for maintaining a good landlord-tenant relationship.","translation":"一位体贴的女房东明白，尊重租户的隐私对于维持良好的房东-租户关系至关重要。"}]},"reliable":{"examples":[{"sentence":"Although the internet provides vast information, not all websites are reliable, which makes critical evaluation a necessary skill.","translation":"尽管互联网提供了大量信息，但并非所有网站都可靠，这使得批判性评估成为一项必要技能。"},{"sentence":"Because renewable energy sources are becoming more reliable, many countries are reducing their dependence on fossil fuels.","translation":"由于可再生能源正变得更加可靠，许多国家正在减少对化石燃料的依赖。"},{"sentence":"When conducting research, scholars must use reliable data to ensure that their conclusions are valid and reproducible.","translation":"在进行研究时，学者必须使用可靠的数据，以确保他们的结论有效且可重复。"},{"sentence":"A reliable public transit system can reduce traffic congestion, thereby improving air quality in urban areas.","translation":"可靠的公共交通系统可以减少交通拥堵，从而改善城市地区的空气质量。"},{"sentence":"If a company wants to build customer loyalty, it must provide reliable products that consistently meet high standards.","translation":"如果一家公司想建立客户忠诚度，它必须提供始终符合高标准的可靠产品。"}]},"ankle":{"examples":[{"sentence":"Because she twisted her ankle while jogging, she had to wear a brace for several weeks to allow the ligaments to heal.","translation":"因为她在慢跑时扭伤了脚踝，她不得不佩戴护具数周，以便韧带愈合。"},{"sentence":"Although ankle injuries are common in basketball, proper warm-up exercises can significantly reduce the risk of sprains.","translation":"尽管脚踝受伤在篮球运动中很常见，但适当的热身运动可以显著降低扭伤的风险。"},{"sentence":"The doctor recommended physical therapy to strengthen the muscles around the ankle, which helps prevent future injuries.","translation":"医生建议进行物理治疗以加强脚踝周围的肌肉，这有助于防止未来受伤。"},{"sentence":"When hiking on uneven terrain, wearing high-top boots provides better ankle support, thereby reducing the chance of twisting.","translation":"在不平坦的地形上徒步时，穿高帮靴能提供更好的脚踝支撑，从而减少扭伤的机会。"},{"sentence":"Elderly people often suffer from ankle instability, which can lead to falls unless they engage in balance training.","translation":"老年人经常患有脚踝不稳定，这可能导致跌倒，除非他们进行平衡训练。"}]},"goose":{"examples":[{"sentence":"The farmer noticed that a wild goose had joined his flock, which prompted him to research migratory patterns in the region.","translation":"农夫注意到一只野鹅加入了他的鹅群，这促使他研究该地区的迁徙模式。"},{"sentence":"Although roast goose is a traditional dish in many cultures, its high fat content has led health-conscious consumers to seek leaner alternatives.","translation":"尽管烤鹅在许多文化中是一道传统菜肴，但其高脂肪含量使得注重健康的消费者转而寻求更瘦的替代品。"},{"sentence":"The biologist explained that the greylag goose exhibits complex social behaviors, including lifelong pair bonding and cooperative parenting.","translation":"生物学家解释说，灰雁表现出复杂的社会行为，包括终生的配偶关系和合作育雏。"},{"sentence":"Because the goose population in the wetland reserve declined sharply, conservationists implemented measures to restore their natural habitat.","translation":"由于湿地保护区的鹅数量急剧下降，环保人士采取措施恢复它们的自然栖息地。"},{"sentence":"In the fable, the farmer who killed the goose that laid the golden eggs serves as a cautionary example of greed destroying sustainable wealth.","translation":"在这个寓言中，杀死了下金蛋的鹅的农夫是一个警示例子，说明贪婪会摧毁可持续的财富。"}]},"thousand":{"examples":[{"sentence":"Although the company invested a thousand hours into research, the breakthrough came only after they adopted a multidisciplinary approach.","translation":"尽管公司投入了上千小时进行研究，但直到他们采用多学科方法后才取得突破。"},{"sentence":"The ancient temple, which has withstood a thousand years of earthquakes, stands as a testament to the ingenuity of its builders.","translation":"这座历经千年地震仍屹立不倒的古庙，证明了其建造者的智慧。"},{"sentence":"Because the charity received a thousand donations within a week, it was able to launch a new literacy program for underprivileged children.","translation":"由于该慈善机构在一周内收到了上千笔捐款，它得以启动一项针对贫困儿童的新识字计划。"},{"sentence":"A journey of a thousand miles begins with a single step, which reminds us that even the most ambitious goals are attainable through persistent effort.","translation":"千里之行始于足下，这提醒我们，即使是最宏伟的目标也能通过坚持不懈的努力实现。"},{"sentence":"While a thousand voices may clamor for attention, it is the well-reasoned argument that ultimately prevails in academic discourse.","translation":"尽管可能有上千种声音在争夺关注，但在学术讨论中，最终胜出的是论证充分的观点。"}]},"crisis":{"examples":[{"sentence":"Although the financial crisis caused widespread unemployment, it also prompted reforms that strengthened the banking system.","translation":"尽管金融危机导致了大规模失业，但它也推动了改革，从而加强了银行体系。"},{"sentence":"Because the climate crisis intensifies extreme weather events, governments must invest in resilient infrastructure to protect communities.","translation":"由于气候危机加剧了极端天气事件，各国政府必须投资于有韧性的基础设施以保护社区。"},{"sentence":"When a public health crisis emerges, international collaboration is essential to develop vaccines and share critical information.","translation":"当公共卫生危机出现时，国际合作对于开发疫苗和共享关键信息至关重要。"},{"sentence":"The energy crisis has accelerated the transition to renewable sources, which reduces dependence on fossil fuels over time.","translation":"能源危机加速了向可再生能源的转型，随着时间的推移，这减少了对化石燃料的依赖。"},{"sentence":"While the refugee crisis poses humanitarian challenges, it also highlights the need for comprehensive immigration policies that balance security and compassion.","translation":"尽管难民危机带来了人道主义挑战，但它也凸显了制定平衡安全与同情的全面移民政策的必要性。"}]},"aloud":{"examples":[{"sentence":"Reading aloud to children not only improves their vocabulary but also fosters a lifelong love of literature.","translation":"给孩子大声朗读不仅能扩大他们的词汇量，还能培养他们对文学的终身热爱。"},{"sentence":"Because the acoustics in the hall were poor, the speaker had to read the speech aloud to ensure everyone could hear.","translation":"由于大厅的音响效果不佳，演讲者不得不大声朗读演讲稿，以确保每个人都能听到。"},{"sentence":"When learning a new language, practicing aloud helps to improve pronunciation and build confidence in speaking.","translation":"学习一门新语言时，大声练习有助于改善发音并建立说话的自信心。"},{"sentence":"The teacher encouraged students to think aloud while solving math problems, which revealed their cognitive processes.","translation":"老师鼓励学生在解数学题时出声思考，这揭示了他们的认知过程。"},{"sentence":"Although reading aloud can be time-consuming, it enhances comprehension by engaging auditory processing.","translation":"尽管大声朗读可能耗时，但它通过调动听觉处理来增强理解力。"}]},"attorney":{"examples":[{"sentence":"The defense attorney, who had prepared meticulously for months, delivered a closing argument that swayed the jury.","translation":"辩护律师精心准备了数月，发表了影响陪审团的结案陈词。"},{"sentence":"Before launching the startup, the founders retained an attorney to draft partnership agreements that would prevent future disputes.","translation":"在创办初创公司之前，创始人聘请了一位律师起草合伙协议，以防止未来的纠纷。"},{"sentence":"Although the attorney general's investigation was thorough, it ultimately found no evidence of wrongdoing.","translation":"尽管总检察长的调查很彻底，但最终没有发现不当行为的证据。"},{"sentence":"A skilled attorney can often negotiate a settlement, thereby saving both parties the expense of a trial.","translation":"一位熟练的律师通常能够通过谈判达成和解，从而为双方节省审判费用。"},{"sentence":"Because the case involved complex international law, the firm hired an attorney who specialized in cross-border litigation.","translation":"由于案件涉及复杂的国际法，事务所聘请了一位专门处理跨境诉讼的律师。"}]},"nice":{"examples":[{"sentence":"The researcher made a nice distinction between correlation and causation, which strengthened the study's conclusions.","translation":"研究人员对相关性和因果关系做出了精细的区分，这加强了研究的结论。"},{"sentence":"A nice adjustment to the algorithm improved accuracy without increasing computational cost, thereby enhancing efficiency.","translation":"对算法的精密调整提高了准确性而没有增加计算成本，从而提高了效率。"},{"sentence":"Although the two theories seem similar, a nice analysis reveals fundamental differences in their underlying assumptions.","translation":"尽管这两种理论看似相似，但细致的分析揭示了它们基本假设中的根本差异。"},{"sentence":"The diplomat's nice handling of the sensitive negotiations prevented a breakdown, which could have led to conflict.","translation":"外交官对敏感谈判的谨慎处理防止了破裂，否则可能导致冲突。"},{"sentence":"Because the experiment required nice control over environmental variables, the team used a specialized chamber.","translation":"由于实验需要对环境变量进行精密的控制，团队使用了一个专门的腔室。"}]},"climax":{"examples":[{"sentence":"Although the film's climax was visually stunning, some critics argued that it lacked emotional depth.","translation":"尽管这部电影的高潮在视觉上令人惊叹，但一些评论家认为它缺乏情感深度。"},{"sentence":"The negotiation reached its climax when both parties finally agreed to a compromise that satisfied their core interests.","translation":"当双方最终达成一项满足其核心利益的妥协时，谈判达到了高潮。"},{"sentence":"Because the novel's climax reveals the true identity of the murderer, readers are advised to avoid spoilers.","translation":"由于小说的高潮揭示了凶手的真实身份，建议读者避免剧透。"},{"sentence":"The symphony builds tension gradually through a series of crescendos, which leads to a powerful climax in the final movement.","translation":"交响曲通过一系列渐强逐渐营造紧张感，最终在最后一个乐章达到强有力的高潮。"},{"sentence":"While the story's climax is predictable, the author's skillful use of foreshadowing makes the journey engaging.","translation":"虽然故事的高潮是可预见的，但作者巧妙运用伏笔使整个过程引人入胜。"}]},"rehearsal":{"examples":[{"sentence":"Because the rehearsal was scheduled for early morning, the cast members had to arrive at the theater by six o'clock.","translation":"由于排练安排在清晨，演员们必须在六点前到达剧院。"},{"sentence":"The director used the final rehearsal to fine-tune the lighting cues, which were crucial for creating the desired atmosphere.","translation":"导演利用最后一次排练来微调灯光提示，这对于营造所需氛围至关重要。"},{"sentence":"Although the rehearsal went smoothly, the lead actor still felt nervous about the upcoming premiere.","translation":"尽管排练进行得很顺利，但主演对即将到来的首映仍感到紧张。"},{"sentence":"A thorough rehearsal of the evacuation plan ensured that all employees knew exactly where to go during the drill.","translation":"对疏散计划的彻底演练确保了所有员工在演习期间确切知道该去哪里。"},{"sentence":"The band decided to hold an extra rehearsal to perfect the new song, which they would debut at the festival.","translation":"乐队决定举行一次额外排练来完善新歌，他们将在音乐节上首次演唱这首歌。"}]},"packet":{"examples":[{"sentence":"Because each data packet contains a header with routing information, it can be efficiently directed through complex networks.","translation":"因为每个数据包都包含一个带有路由信息的头部，所以它可以高效地通过复杂的网络进行引导。"},{"sentence":"Although a single packet of seeds seems insignificant, it can initiate a community garden that enhances neighborhood cohesion.","translation":"尽管一小包种子看起来微不足道，但它可以启动一个社区花园，从而增强邻里凝聚力。"},{"sentence":"When you open a packet of silica gel, you should avoid contact with your eyes, as it can cause irritation.","translation":"当你打开一包硅胶时，你应该避免接触眼睛，因为它可能会引起刺激。"},{"sentence":"The charity distributed a packet of essential supplies to each displaced family, which included hygiene items and basic food.","translation":"慈善机构向每个流离失所的家庭分发了一包必需品，其中包括卫生用品和基本食品。"},{"sentence":"While a packet of instant soup offers convenience, preparing fresh ingredients provides greater nutritional value and flavor.","translation":"虽然一包速溶汤提供了便利，但准备新鲜食材能提供更高的营养价值和风味。"}]},"neutral":{"examples":[{"sentence":"Although the mediator remained neutral, both parties felt their concerns were addressed fairly.","translation":"尽管调解人保持中立，但双方都觉得他们的关切得到了公平处理。"},{"sentence":"Because Switzerland is a neutral country, it often hosts international peace negotiations.","translation":"因为瑞士是一个中立国，它经常主办国际和平谈判。"},{"sentence":"When writing a research paper, you must use neutral language to avoid introducing bias.","translation":"在撰写研究论文时，你必须使用中性语言以避免引入偏见。"},{"sentence":"The committee chose a neutral location for the talks, thereby ensuring neither side had an advantage.","translation":"委员会为会谈选择了一个中立地点，从而确保任何一方都没有优势。"},{"sentence":"Using neutral colors in the office can create a calming atmosphere, which enhances productivity.","translation":"在办公室使用中性色彩可以营造平静的氛围，从而提高工作效率。"}]},"south":{"examples":[{"sentence":"Although the north is industrialized, the south remains predominantly agricultural.","translation":"尽管北方是工业化的，但南方仍然以农业为主。"},{"sentence":"Because the south enjoys a warmer climate, it attracts many retirees seeking a comfortable lifestyle.","translation":"因为南方享有更温暖的气候，它吸引了许多寻求舒适生活方式的退休人员。"},{"sentence":"When birds migrate south for the winter, they rely on environmental cues such as daylight changes.","translation":"当鸟类在冬季向南迁徙时，它们依赖诸如日照变化等环境线索。"},{"sentence":"The house has large south-facing windows, which allow it to capture maximum sunlight during the day.","translation":"这所房子有朝南的大窗户，使其在白天能最大限度地吸收阳光。"},{"sentence":"The south of the country has experienced rapid economic growth, whereas the north has stagnated.","translation":"该国南部经历了快速的经济增长，而北部则停滞不前。"}]},"cold":{"examples":[{"sentence":"Because the cold virus mutates rapidly, developing a universal vaccine has proven to be a formidable scientific challenge.","translation":"由于感冒病毒变异迅速，开发通用疫苗已被证明是一项艰巨的科学挑战。"},{"sentence":"Although she took precautions, the sudden drop in temperature caused her to catch a cold that lingered for weeks.","translation":"尽管她采取了预防措施，但气温骤降导致她患上了持续数周的感冒。"},{"sentence":"When a cold spreads through a densely populated office, productivity often declines as employees take sick leave.","translation":"当感冒在人口密集的办公室传播时，随着员工请病假，生产力往往会下降。"},{"sentence":"Public health officials recommend annual flu shots, which, while not preventing the common cold, can reduce the burden on healthcare systems.","translation":"公共卫生官员建议每年接种流感疫苗，虽然不能预防普通感冒，但可以减轻医疗系统的负担。"},{"sentence":"The misconception that antibiotics can treat a cold persists, despite extensive campaigns to educate the public about viral infections.","translation":"尽管开展了广泛的运动来教育公众有关病毒感染的知识，但抗生素可以治疗感冒的误解仍然存在。"}]},"dramatic":{"examples":[{"sentence":"Although the initial results were modest, the new policy led to a dramatic reduction in pollution levels over time.","translation":"尽管最初的结果并不显著，但新政策随着时间的推移使污染水平急剧下降。"},{"sentence":"Because of the dramatic increase in online shopping, many traditional retailers have been forced to close their stores.","translation":"由于网上购物的急剧增加，许多传统零售商被迫关闭了门店。"},{"sentence":"While the play had a dramatic plot, the actors' performances were surprisingly understated.","translation":"虽然这部戏剧情节生动，但演员的表演却出奇地低调。"},{"sentence":"The scientist made a dramatic announcement that captured the world's attention, thereby highlighting the urgency of climate action.","translation":"这位科学家发表了一个引人注目的声明，吸引了全世界的注意力，从而凸显了气候行动的紧迫性。"},{"sentence":"When the company introduced the innovative product, it brought about a dramatic shift in consumer behavior.","translation":"当公司推出这款创新产品时，它带来了消费者行为的显著转变。"}]},"bully":{"examples":[{"sentence":"Although he appeared confident, the bully often targeted others to mask his own deep-seated insecurities.","translation":"尽管他看起来自信，但这个欺凌者经常针对他人以掩盖自己内心深处的不安全感。"},{"sentence":"Because the school implemented a strict anti-bullying policy, any student who acted as a bully faced immediate consequences.","translation":"因为学校实施了严格的反欺凌政策，任何充当欺凌者的学生都会立即面临后果。"},{"sentence":"When a bully uses intimidation tactics, it can create a toxic environment that affects everyone's well-being.","translation":"当欺凌者使用恐吓策略时，会创造一个影响每个人福祉的有害环境。"},{"sentence":"The manager was accused of being a bully, which led to a formal investigation by the human resources department.","translation":"这位经理被指控是一个欺凌者，这导致了人力资源部门的正式调查。"},{"sentence":"If we do not address the behavior of a bully early on, it may escalate into more serious forms of harassment.","translation":"如果我们不及早处理欺凌者的行为，它可能会升级为更严重的骚扰形式。"}]},"research":{"examples":[{"sentence":"Although the research was conducted under strict ethical guidelines, its findings remain controversial among scholars.","translation":"尽管这项研究是在严格的伦理准则下进行的，但其发现在学者中仍存在争议。"},{"sentence":"Because the research relies on self-reported data, the results may be subject to bias that undermines their validity.","translation":"因为这项研究依赖于自我报告的数据，其结果可能存在偏差，从而削弱其有效性。"},{"sentence":"The research, which spanned over a decade, provides compelling evidence that early intervention can alter developmental trajectories.","translation":"这项历时十多年的研究提供了令人信服的证据，表明早期干预可以改变发展轨迹。"},{"sentence":"While the research highlights significant trends, it does not establish a causal relationship between the variables.","translation":"尽管这项研究突出了显著的趋势，但它并未在变量之间建立因果关系。"},{"sentence":"Through meticulous research, the team identified a novel compound that inhibits tumor growth without harming healthy cells.","translation":"通过细致的研究，该团队发现了一种新型化合物，它能在不伤害健康细胞的情况下抑制肿瘤生长。"}]},"place":{"examples":[{"sentence":"In the first place, we must recognize that technological innovation often disrupts traditional industries, thereby creating both opportunities and challenges.","translation":"首先，我们必须认识到，技术创新常常颠覆传统行业，从而既创造机遇也带来挑战。"},{"sentence":"If I were in your place, I would seek mentorship from experienced professionals rather than relying solely on trial and error.","translation":"如果我是你，我会寻求经验丰富的专业人士的指导，而不是仅仅依靠反复尝试。"},{"sentence":"The library is not only a place for quiet study but also a hub where community members can exchange ideas and foster collaboration.","translation":"图书馆不仅是一个安静学习的场所，也是一个社区成员可以交流思想、促进合作的中心。"},{"sentence":"Because the company failed to adapt to market changes, it lost its place as an industry leader to more agile competitors.","translation":"由于公司未能适应市场变化，它失去了行业领导者的地位，被更灵活的竞争对手取代。"},{"sentence":"Finding a place of one's own in a competitive housing market requires careful financial planning, unless one has substantial external support.","translation":"在竞争激烈的住房市场中找到一个属于自己的住所需要仔细的财务规划，除非有大量的外部支持。"}]},"erect":{"examples":[{"sentence":"The city council decided to erect a monument that commemorates the sacrifices of healthcare workers during the pandemic.","translation":"市议会决定竖立一座纪念碑，以纪念疫情期间医护人员的牺牲。"},{"sentence":"Engineers had to erect a temporary bridge while the permanent structure was being repaired, thereby minimizing traffic disruption.","translation":"工程师们必须在永久性结构修复期间架设一座临时桥梁，从而最大限度地减少交通中断。"},{"sentence":"The organization aims to erect a legal framework that protects digital privacy, rather than relying on outdated regulations.","translation":"该组织旨在建立一个保护数字隐私的法律框架，而不是依赖过时的法规。"},{"sentence":"Despite strong winds, the workers managed to erect the scaffolding with remarkable precision, which ensured the project stayed on schedule.","translation":"尽管风很大，工人们还是以惊人的精确度搭起了脚手架，这确保了项目按计划进行。"},{"sentence":"The government plans to erect new barriers along the riverbank to prevent illegal dumping, unless alternative waste disposal methods are implemented.","translation":"政府计划沿河岸设置新的屏障以防止非法倾倒，除非实施替代废物处理方法。"}]},"bowling":{"examples":[{"sentence":"Although bowling is often seen as a casual pastime, it requires considerable skill and concentration to achieve a high score.","translation":"虽然保龄球常被视为一种休闲娱乐，但要取得高分需要相当的技巧和专注力。"},{"sentence":"Because bowling alleys provide a controlled environment, they are ideal venues for social gatherings regardless of weather conditions.","translation":"由于保龄球馆提供受控的环境，无论天气如何，它们都是社交聚会的理想场所。"},{"sentence":"When employees participate in bowling leagues, they often develop stronger interpersonal bonds, which can enhance workplace collaboration.","translation":"当员工参加保龄球联赛时，他们通常会建立更牢固的人际关系，这可以加强职场协作。"},{"sentence":"The growing popularity of bowling among young professionals has led to the emergence of upscale alleys that combine the sport with fine dining.","translation":"保龄球在年轻专业人士中日益流行，催生了将这项运动与精致餐饮相结合的高档球馆。"},{"sentence":"Researchers suggest that regular bowling can improve balance and coordination in older adults, thereby reducing the risk of falls.","translation":"研究人员认为，定期打保龄球可以改善老年人的平衡和协调能力，从而降低跌倒的风险。"}]},"dash":{"examples":[{"sentence":"Although the 100-meter dash is a short event, it demands explosive power and precise technique.","translation":"虽然100米短跑是一项短距离赛事，但它需要爆发力和精确的技术。"},{"sentence":"Because a sudden dash of rain soaked the equipment, the field experiment had to be rescheduled.","translation":"因为一阵突如其来的暴雨淋湿了设备，野外实验不得不重新安排。"},{"sentence":"When she received the rejection letter, a dash of disappointment crossed her face before she composed herself.","translation":"当她收到拒绝信时，一丝失望掠过她的脸庞，随后她便镇定下来。"},{"sentence":"The author used a dash to emphasize the appositive, which clarified the complex historical reference.","translation":"作者使用破折号来强调同位语，从而澄清了复杂的历史指涉。"},{"sentence":"With a final dash of creativity, the architect transformed the ordinary building into a landmark that attracted tourists.","translation":"凭借最后一点创造力的迸发，建筑师将这座普通的建筑变成了一座吸引游客的地标。"}]},"mill":{"examples":[{"sentence":"The old textile mill, which was once the town's economic backbone, now houses a technology incubator that fosters startups.","translation":"那座曾经是小镇经济支柱的旧纺织厂，如今容纳了一个培育初创企业的科技孵化器。"},{"sentence":"Steel produced at the local mill was essential for constructing the region's infrastructure, thereby boosting economic growth.","translation":"当地钢厂生产的钢铁对于建设该地区的基础设施至关重要，从而促进了经济增长。"},{"sentence":"Historians argue that the invention of the water mill revolutionized medieval industry because it mechanized grain processing.","translation":"历史学家认为，水磨的发明彻底改变了中世纪的工业，因为它使谷物加工机械化。"},{"sentence":"The paper mill implemented a closed-loop water system to reduce environmental impact, which set a precedent for sustainable manufacturing.","translation":"这家造纸厂实施了闭环水系统以减少对环境的影响，这为可持续制造树立了先例。"},{"sentence":"Rumors began to mill through the office after the unexpected resignation of the director, despite management's attempts to control the narrative.","translation":"主任意外辞职后，谣言开始在办公室里流传，尽管管理层试图控制舆论。"}]},"flourish":{"examples":[{"sentence":"Small businesses often flourish when they receive targeted government support.","translation":"小企业在获得有针对性的政府支持时往往会蓬勃发展。"},{"sentence":"Although the region faces harsh winters, its cultural traditions continue to flourish.","translation":"尽管该地区面临严冬，但其文化传统仍然繁荣不息。"},{"sentence":"Innovation tends to flourish in environments that encourage open collaboration.","translation":"在鼓励开放合作的环境中，创新往往会蓬勃发展。"},{"sentence":"Because the soil was enriched with organic matter, the crops began to flourish.","translation":"由于土壤富含有机质，庄稼开始茁壮成长。"},{"sentence":"A society can only flourish when its citizens enjoy equal access to education.","translation":"只有当公民享有平等的教育机会时，社会才能繁荣发展。"}]},"box":{"examples":[{"sentence":"Although the box appeared sturdy, its contents were damaged during transit.","translation":"尽管箱子看起来很结实，但里面的物品在运输过程中还是损坏了。"},{"sentence":"Because the box was too heavy to carry alone, she asked for assistance.","translation":"因为箱子太重，她一个人搬不动，所以请求帮助。"},{"sentence":"The wooden box, which had been in the attic for decades, contained valuable antiques.","translation":"那个在阁楼里放了几十年的木箱里装有珍贵的古董。"},{"sentence":"When you finish packing the box, please label it clearly to avoid confusion.","translation":"当你装完箱子后，请清楚地贴上标签，以免混淆。"},{"sentence":"He placed the fragile items in a padded box to ensure they would not break.","translation":"他把易碎物品放在有衬垫的盒子里，以确保它们不会破碎。"}]},"module":{"examples":[{"sentence":"Although the training module was designed for beginners, it also offers advanced insights that benefit experienced professionals.","translation":"尽管该培训模块是为初学者设计的，但它也提供了对经验丰富的专业人士有益的深入见解。"},{"sentence":"The spacecraft's service module, which provides essential power and propulsion, must function flawlessly throughout the mission.","translation":"航天器的服务舱提供必要的动力和推进力，必须在整个任务期间完美运行。"},{"sentence":"Because students must complete the core module before selecting electives, careful planning is required to ensure timely graduation.","translation":"由于学生必须完成核心模块才能选择选修课，因此需要仔细规划以确保按时毕业。"},{"sentence":"The software's reporting module generates detailed analytics, thereby enabling managers to make data-driven strategic decisions.","translation":"该软件的报告模块生成详细的分析数据，从而使管理者能够做出数据驱动的战略决策。"},{"sentence":"When a single faulty module is replaced, the modular design ensures that the entire system continues to operate without disruption.","translation":"当更换单个故障模块时，模块化设计确保整个系统继续运行而不中断。"}]},"suffice":{"examples":[{"sentence":"A brief summary will suffice to convey the main findings, provided that the key data points are clearly highlighted.","translation":"只要关键数据点被清晰突出，一个简短的摘要就足以传达主要发现。"},{"sentence":"Although basic computer skills suffice for routine tasks, more complex projects demand specialized technical knowledge.","translation":"尽管基本的计算机技能足以应对常规任务，但更复杂的项目需要专门的技术知识。"},{"sentence":"While a single example may suffice to illustrate the concept, multiple cases provide more robust evidence that strengthens the argument.","translation":"虽然一个例子可能足以说明概念，但多个案例能提供更有力的证据，从而加强论点。"},{"sentence":"In many contexts, informal communication can suffice to build trust, because it fosters a sense of openness and approachability.","translation":"在许多情况下，非正式沟通足以建立信任，因为它培养了一种开放和亲切感。"},{"sentence":"A modest budget can suffice to launch a pilot project if resources are allocated strategically, thereby maximizing the impact of limited funds.","translation":"如果资源得到战略性分配，适度的预算足以启动一个试点项目，从而最大化有限资金的影响。"}]},"pleasant":{"examples":[{"sentence":"A pleasant working environment, which is characterized by mutual respect and open communication, significantly enhances employee productivity.","translation":"一个以相互尊重和开放沟通为特征的愉快工作环境，能显著提高员工的生产力。"},{"sentence":"Although the journey was long, the pleasant conversation with fellow travelers made the time pass quickly, thereby reducing the fatigue of travel.","translation":"尽管旅途漫长，但与同行旅客的愉快交谈让时间过得很快，从而减轻了旅行的疲劳。"},{"sentence":"The garden's pleasant fragrance, which comes from a variety of blooming flowers, attracts numerous visitors each spring.","translation":"花园里宜人的芬芳来自各种盛开的花朵，每年春天都吸引众多游客。"},{"sentence":"Researchers found that exposure to pleasant natural scenery can reduce stress, because it promotes relaxation and mental restoration.","translation":"研究人员发现，接触宜人的自然风景可以减轻压力，因为它促进放松和心理恢复。"},{"sentence":"A pleasant demeanor, when combined with professional competence, often leads to more successful client interactions, thereby enhancing business relationships.","translation":"令人愉快的举止，当与专业能力相结合时，往往能带来更成功的客户互动，从而加强业务关系。"}]},"naval":{"examples":[{"sentence":"Although naval power is often associated with military strength, it also plays a crucial role in protecting international trade routes.","translation":"尽管海军力量常与军事实力联系在一起，但它在保护国际贸易航线方面也起着至关重要的作用。"},{"sentence":"The country expanded its naval presence in the region to ensure the security of its maritime borders.","translation":"该国扩大了在该地区的海军存在，以确保其海上边界的安全。"},{"sentence":"Because naval technology has advanced rapidly, modern warships are equipped with sophisticated radar and missile systems.","translation":"由于海军技术迅速发展，现代战舰配备了先进的雷达和导弹系统。"},{"sentence":"Naval historians argue that the battle of Midway was a turning point, which shifted the balance of power in the Pacific.","translation":"海军历史学家认为，中途岛战役是一个转折点，它改变了太平洋地区的力量平衡。"},{"sentence":"While naval exercises can demonstrate a nation's defensive capabilities, they may also be perceived as provocative by neighboring states.","translation":"虽然海军演习可以展示一个国家的防御能力，但也可能被邻国视为挑衅。"}]},"obedient":{"examples":[{"sentence":"In traditional societies, children were often expected to be obedient to their parents without question, which reinforced hierarchical family structures.","translation":"在传统社会中，孩子们常常被期望无条件地顺从父母，这强化了等级制的家庭结构。"},{"sentence":"A well-trained dog is not only obedient but also capable of assisting people with disabilities in daily tasks.","translation":"一只训练有素的狗不仅服从指令，还能协助残疾人完成日常任务。"},{"sentence":"While an obedient workforce may ensure short-term efficiency, it can stifle innovation and critical thinking.","translation":"虽然顺从的员工队伍可能确保短期效率，但它会扼杀创新和批判性思维。"},{"sentence":"The new policy requires all employees to be obedient to the revised safety protocols, because non-compliance could lead to serious accidents.","translation":"新政策要求所有员工遵守修订后的安全规程，因为不遵守可能导致严重事故。"},{"sentence":"Because the software was designed to be obedient to user commands, it gained popularity among those with limited technical skills.","translation":"由于该软件被设计为服从用户指令，它在技术能力有限的人群中广受欢迎。"}]},"sigh":{"examples":[{"sentence":"When the final exam was canceled, the students let out a collective sigh of relief, which echoed through the hallway.","translation":"当期末考试被取消时，学生们集体松了一口气，叹息声在走廊里回荡。"},{"sentence":"The announcement of the funding cut was met with a resigned sigh from the research team, because they had anticipated the decision.","translation":"研究团队听到资金削减的宣布后，发出了无奈的叹息，因为他们已经预料到了这个决定。"},{"sentence":"With a deep sigh, the negotiator acknowledged that reaching a consensus would require more time than anticipated.","translation":"谈判者深深地叹了口气，承认达成共识需要比预期更多的时间。"},{"sentence":"A sigh of disappointment spread through the audience when the keynote speaker failed to address the core issue, which many had hoped to hear about.","translation":"当主旨演讲者未能触及核心问题时，失望的叹息在观众中蔓延开来，许多人原本希望听到相关内容。"},{"sentence":"He breathed a sigh of contentment after finishing the last chapter of his dissertation, because it marked the end of years of hard work.","translation":"他写完论文的最后一章后，满足地舒了一口气，因为这标志着多年努力的结束。"}]},"inhabit":{"examples":[{"sentence":"Although the region is known for its extreme temperatures, several resilient species inhabit its arid plains.","translation":"尽管该地区以极端气温著称，仍有几种适应力强的物种栖息在其干旱的平原上。"},{"sentence":"The ancient ruins, which have stood for over two thousand years, now inhabit a landscape transformed by modern agriculture.","translation":"那些屹立了两千多年的古代遗址，如今坐落于被现代农业改变的地貌之中。"},{"sentence":"Because the cave system remains largely unexplored, scientists believe that unknown organisms may inhabit its deepest chambers.","translation":"由于该洞穴系统大部分尚未探索，科学家认为未知生物可能栖息在其最深的洞室中。"},{"sentence":"While urban expansion threatens natural habitats, many bird species continue to inhabit city parks and green spaces.","translation":"虽然城市扩张威胁着自然栖息地，许多鸟类仍继续栖息在城市公园和绿地中。"},{"sentence":"The cultural values that inhabit a society often shape its legal framework, thereby influencing individual behavior.","translation":"一个社会所蕴含的文化价值观往往塑造其法律框架，从而影响个人行为。"}]},"thick":{"examples":[{"sentence":"Because the walls were constructed with thick stone blocks, the building remained cool even during the hottest summer days.","translation":"由于墙壁是用厚石块砌成的，即使在最炎热的夏日，建筑物内也保持凉爽。"},{"sentence":"The report, which included a thick appendix of statistical data, provided comprehensive evidence for the policy change.","translation":"这份包含厚厚统计数据附录的报告，为政策变更提供了全面的证据。"},{"sentence":"Although the sauce appeared too thick at first, adding a small amount of water restored its desired consistency.","translation":"虽然酱汁起初显得太浓稠，加入少量水后恢复了理想的稠度。"},{"sentence":"The thick fog that often blankets the valley in early morning can delay flights, thereby disrupting travel schedules.","translation":"清晨常笼罩山谷的浓雾可能导致航班延误，从而打乱旅行计划。"},{"sentence":"When the hikers entered the thick underbrush, they had to use their machetes to clear a path through the dense vegetation.","translation":"当徒步者进入茂密的灌木丛时，他们不得不用砍刀在浓密的植被中开辟道路。"}]},"pollution":{"examples":[{"sentence":"Although industrial pollution has declined in developed nations, it remains a critical issue in emerging economies.","translation":"尽管发达国家的工业污染有所下降，但在新兴经济体中它仍然是一个关键问题。"},{"sentence":"Because agricultural runoff contributes to water pollution, farmers are encouraged to adopt sustainable practices.","translation":"由于农业径流导致水污染，农民被鼓励采用可持续的做法。"},{"sentence":"The government introduced a carbon tax, which aims to reduce air pollution by discouraging fossil fuel consumption.","translation":"政府引入了碳税，旨在通过抑制化石燃料消耗来减少空气污染。"},{"sentence":"While urbanization brings economic benefits, it often leads to increased noise pollution that affects residents' well-being.","translation":"虽然城市化带来经济利益，但它往往导致噪音污染增加，影响居民的福祉。"},{"sentence":"Unless stricter regulations are enforced, plastic pollution will continue to threaten marine biodiversity.","translation":"除非执行更严格的法规，否则塑料污染将继续威胁海洋生物多样性。"}]},"manual":{"examples":[{"sentence":"Because the assembly process is complex, the company provides a detailed manual to guide new employees.","translation":"由于装配过程复杂，公司提供了一本详细的手册来指导新员工。"},{"sentence":"Although digital tools are prevalent, a well-written manual remains essential for troubleshooting technical issues.","translation":"尽管数字工具很普遍，但一本编写良好的手册对于解决技术问题仍然至关重要。"},{"sentence":"The technician consulted the repair manual, which contained diagrams that simplified the diagnostic procedure.","translation":"技术员查阅了维修手册，其中包含简化诊断程序的图表。"},{"sentence":"To reduce errors, the laboratory replaced manual data entry with an automated system that ensures accuracy.","translation":"为了减少错误，实验室用确保准确性的自动化系统取代了手动数据输入。"},{"sentence":"While manual labor can be physically demanding, it often provides a sense of accomplishment that desk jobs lack.","translation":"虽然体力劳动可能对体力要求很高，但它往往提供一种案头工作所缺乏的成就感。"}]},"staple":{"examples":[{"sentence":"Although rice is a staple food in many Asian countries, its cultivation requires substantial water resources, which can strain local supplies.","translation":"尽管大米是许多亚洲国家的主食，但其种植需要大量水资源，这可能会给当地供应带来压力。"},{"sentence":"Because wheat serves as a staple crop in this region, farmers rely on stable weather patterns to ensure a successful harvest.","translation":"由于小麦是该地区的主要作物，农民依赖稳定的天气模式来确保丰收。"},{"sentence":"While digital media have transformed communication, television remains a staple of family entertainment, thereby preserving shared viewing experiences.","translation":"尽管数字媒体改变了通信方式，电视仍然是家庭娱乐的主要形式，从而保留了共同的观看体验。"},{"sentence":"The library's collection includes staple works of Western philosophy, which students are encouraged to read during their first year to build a strong foundation.","translation":"图书馆的馆藏包括西方哲学的主要著作，鼓励学生在第一年阅读这些作品以打下坚实基础。"},{"sentence":"Nutritionists recommend that staple foods be complemented with a variety of vegetables and proteins, rather than being consumed in isolation, to ensure a balanced diet.","translation":"营养学家建议主食应搭配多种蔬菜和蛋白质，而不是单独食用，以确保均衡饮食。"}]},"petrol":{"examples":[{"sentence":"Because the cost of petrol continues to rise, many commuters are switching to public transportation, thereby reducing both expenses and emissions.","translation":"由于汽油价格持续上涨，许多通勤者正在改乘公共交通，从而减少了开支和排放。"},{"sentence":"Although electric vehicles are gaining popularity, petrol engines still dominate the market, which is largely due to the extensive refueling infrastructure.","translation":"尽管电动汽车越来越受欢迎，汽油发动机仍然主导市场，这在很大程度上归功于广泛的加油基础设施。"},{"sentence":"Governments are imposing higher taxes on petrol, not only to curb carbon emissions but also to fund renewable energy research.","translation":"各国政府正在对汽油征收更高的税，不仅是为了遏制碳排放，也是为了资助可再生能源研究。"},{"sentence":"While petrol is a non-renewable resource, its depletion poses a serious challenge, unless alternative fuels are developed and adopted rapidly.","translation":"尽管汽油是一种不可再生资源，其枯竭构成严重挑战，除非快速开发和采用替代燃料。"},{"sentence":"The development of more efficient petrol engines has reduced fuel consumption, yet the environmental impact remains a pressing concern that requires global cooperation.","translation":"更高效汽油发动机的研发降低了燃料消耗，但环境影响仍然是一个需要全球合作的紧迫问题。"}]},"experience":{"examples":[{"sentence":"Although theoretical knowledge is important, practical experience often proves decisive in solving real-world problems.","translation":"尽管理论知识很重要，但实践经验在解决实际问题时往往起决定性作用。"},{"sentence":"Because she had extensive experience in crisis management, the team relied on her guidance during the emergency.","translation":"因为她在危机管理方面经验丰富，团队在紧急情况下依赖她的指导。"},{"sentence":"While internships provide valuable work experience, they also help students build professional networks that can benefit their future careers.","translation":"虽然实习提供了宝贵的工作经验，但它们也帮助学生建立职业网络，这对他们未来的职业生涯有益。"},{"sentence":"The researcher's firsthand experience in the field, which included years of data collection, lent credibility to her findings.","translation":"这位研究人员在实地的一手经验，包括多年的数据收集，为她的发现增添了可信度。"},{"sentence":"Through immersive travel, one can gain cultural experience that textbooks alone cannot provide, thereby fostering a more global perspective.","translation":"通过沉浸式旅行，人们可以获得仅靠教科书无法提供的文化体验，从而培养更全球化的视野。"}]},"multiply":{"examples":[{"sentence":"When environmental conditions are favorable, certain bacteria can multiply exponentially, leading to rapid contamination.","translation":"当环境条件有利时，某些细菌会呈指数级繁殖，导致快速污染。"},{"sentence":"To calculate the area of a rectangle, you must multiply its length by its width, which is a fundamental geometric principle.","translation":"要计算矩形的面积，你必须用长乘以宽，这是一个基本的几何原理。"},{"sentence":"If left unchecked, misinformation on social media can multiply quickly, undermining public trust in reliable sources.","translation":"如果不加制止，社交媒体上的错误信息会迅速倍增，破坏公众对可靠来源的信任。"},{"sentence":"Because the invasive plant species had no natural predators, it began to multiply and threaten the native ecosystem.","translation":"由于这种入侵植物没有天敌，它开始大量繁殖并威胁到本地生态系统。"},{"sentence":"By adopting efficient farming techniques, communities can multiply their crop yields, thereby improving food security.","translation":"通过采用高效的农业技术，社区可以成倍增加作物产量，从而改善粮食安全。"}]},"tile":{"examples":[{"sentence":"The kitchen renovation was completed once the workers installed the ceramic tile backsplash, which added both durability and visual appeal.","translation":"厨房翻新在工人安装了陶瓷瓷砖后挡板后完成，这既增加了耐用性又提升了视觉吸引力。"},{"sentence":"Because the bathroom floor tile had cracked under constant moisture, the landlord decided to replace it with a more water-resistant material.","translation":"由于浴室地砖在持续潮湿下开裂，房东决定用更防水的材料替换它。"},{"sentence":"The architect specified a matte-finish tile for the lobby walls, so that the space would feel warmer and less institutional.","translation":"建筑师为大厅墙壁指定了哑光饰面瓷砖，以便空间感觉更温暖而不那么机构化。"},{"sentence":"Although the mosaic tile pattern was labor-intensive to install, it created a stunning focal point that justified the extra effort.","translation":"尽管马赛克瓷砖图案安装起来劳动密集，但它创造了一个令人惊叹的焦点，证明了额外努力的合理性。"},{"sentence":"When selecting a roof tile, homeowners must consider not only aesthetic preferences but also the material's resistance to extreme weather.","translation":"在选择屋顶瓦片时，房主不仅要考虑审美偏好，还要考虑材料对极端天气的抵抗力。"}]},"earth":{"examples":[{"sentence":"The satellite imagery revealed that vast stretches of earth in the region had been degraded by unsustainable farming practices.","translation":"卫星图像显示，该地区大片土地因不可持续的耕作方式而退化。"},{"sentence":"Although the earth beneath the construction site appeared stable, engineers conducted additional tests to rule out hidden cavities.","translation":"尽管建筑工地下的泥土看似稳定，工程师们还是进行了额外测试以排除隐藏的空洞。"},{"sentence":"Because the earth absorbs and releases heat more slowly than the air, ground-source heat pumps can achieve remarkable energy efficiency.","translation":"由于泥土比空气吸收和释放热量更慢，地源热泵可以实现显著的能源效率。"},{"sentence":"The gardener enriched the depleted earth with organic compost, which gradually restored its fertility and improved drainage.","translation":"园丁用有机堆肥丰富了贫瘠的泥土，这逐渐恢复了其肥力并改善了排水。"},{"sentence":"In many ancient cultures, the earth was revered as a maternal figure, a belief that fostered a deep respect for the natural world.","translation":"在许多古代文化中，地球被尊崇为母亲形象，这种信仰培养了对自然界的深深敬意。"}]},"accompany":{"examples":[{"sentence":"Although the CEO was unable to attend, she sent a senior manager to accompany the delegation during the factory tour.","translation":"尽管首席执行官无法出席，她派了一位高级经理在工厂参观期间陪同代表团。"},{"sentence":"The new trade agreement will accompany a series of tariff reductions, which are expected to boost bilateral commerce significantly.","translation":"新的贸易协定将伴随一系列关税削减，这预计将显著促进双边贸易。"},{"sentence":"Because the elderly patient required constant monitoring, a nurse was assigned to accompany her throughout the night.","translation":"由于这位老年病人需要持续监护，一名护士被指派整夜陪伴她。"},{"sentence":"The pianist agreed to accompany the choir during the charity concert, thereby enhancing the overall musical performance.","translation":"钢琴家同意在慈善音乐会上为合唱团伴奏，从而提升了整体音乐表演。"},{"sentence":"When submitting your application, you must accompany it with a personal statement that clearly outlines your research interests.","translation":"提交申请时，你必须附上一份个人陈述，清楚地概述你的研究兴趣。"}]},"satire":{"examples":[{"sentence":"Although satire often employs humor, its primary aim is to critique societal flaws rather than merely entertain.","translation":"虽然讽刺作品常常运用幽默，但其主要目的是批判社会缺陷，而不仅仅是娱乐。"},{"sentence":"Because satire exaggerates reality, it can reveal hidden truths that straightforward commentary might overlook.","translation":"由于讽刺作品夸大现实，它能揭示直白评论可能忽略的隐藏真相。"},{"sentence":"When writers use satire to address political corruption, they risk censorship in regimes that suppress dissent.","translation":"当作家用讽刺作品揭露政治腐败时，他们在压制异议的政权中面临审查风险。"},{"sentence":"The film's satire of consumer culture resonated globally, which demonstrates the universal appeal of this genre.","translation":"这部电影对消费文化的讽刺在全球引起共鸣，这表明了这一体裁的普遍吸引力。"},{"sentence":"While satire can be misunderstood as mere mockery, it often serves as a catalyst for social change.","translation":"虽然讽刺作品可能被误解为单纯的嘲弄，但它常常成为社会变革的催化剂。"}]},"locomotive":{"examples":[{"sentence":"Although the steam locomotive is now obsolete, it remains a powerful symbol of the Industrial Revolution.","translation":"尽管蒸汽机车现已过时，但它仍然是工业革命的有力象征。"},{"sentence":"The new electric locomotive, which uses regenerative braking, can significantly reduce energy consumption on long-haul routes.","translation":"这种新型电力机车采用再生制动，可以显著降低长途线路的能耗。"},{"sentence":"Because the locomotive is the primary source of pulling power, its maintenance schedule must be strictly followed to avoid breakdowns.","translation":"由于机车是主要的牵引动力来源，必须严格遵守其维护计划以避免故障。"},{"sentence":"When a locomotive engineer detects an anomaly in the engine, they must immediately report it to the control center to ensure safety.","translation":"当机车司机发现发动机异常时，必须立即向控制中心报告以确保安全。"},{"sentence":"The museum's restored locomotive attracts thousands of visitors each year, thereby boosting the local tourism industry.","translation":"博物馆修复的机车每年吸引成千上万的游客，从而促进了当地旅游业的发展。"}]}}};
